// A small JavaScript lexer sufficient for evaluating grammar files.

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Ident(String),
    Keyword(String),
    Num(f64),
    Str(String),
    Template(Vec<String>, Vec<String>, Vec<Vec<Token>>), // cooked, raw, expression tokens
    Regex(String, String),
    Punct(&'static str),
    Eof,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Token {
    pub tok: Tok,
    pub nl_before: bool,
    pub line: u32,
    pub col: u32,
    pub pos: usize,
}

const KEYWORDS: &[&str] = &[
    "var", "let", "const", "function", "return", "if", "else", "for", "while", "do", "break",
    "continue", "new", "delete", "typeof", "instanceof", "in", "of", "this", "null", "true",
    "false", "throw", "try", "catch", "finally", "switch", "case", "default", "void", "class",
    "extends", "super", "import", "export", "yield", "async", "await", "static", "get", "set",
];

// Keywords that are allowed to be used as identifiers in most positions.
pub const CONTEXTUAL: &[&str] = &["of", "get", "set", "async", "await", "static", "yield", "let"];

const PUNCTS: &[&str] = &[
    ">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=", "=>", "==",
    "!=", "<=", ">=", "&&", "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=",
    "|=", "^=", "<<", ">>", "**", "{", "}", "(", ")", "[", "]", ";", ",", "<", ">", "+", "-",
    "*", "/", "%", "&", "|", "^", "!", "~", "?", ":", "=", ".", "@", "#",
];

pub struct Lexer<'a> {
    src: &'a [char],
    pos: usize,
    line: u32,
    col: u32,
    base_line: u32,
}

pub type LexResult<T> = Result<T, (String, u32, u32)>;

fn is_id_start(c: char) -> bool {
    c == '$' || c == '_' || c.is_alphabetic()
}
fn is_id_part(c: char) -> bool {
    c == '$' || c == '_' || c.is_alphanumeric() || c == '\u{200c}' || c == '\u{200d}'
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [char]) -> Self {
        Lexer { src, pos: 0, line: 1, col: 1, base_line: 0 }
    }

    fn peek(&self, off: usize) -> Option<char> {
        self.src.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.src.get(self.pos).copied()?;
        self.pos += 1;
        if c == '\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        Some(c)
    }

    fn err<T>(&self, msg: &str) -> LexResult<T> {
        Err((msg.to_string(), self.line + self.base_line, self.col))
    }

    pub fn tokenize(&mut self) -> LexResult<Vec<Token>> {
        let mut toks: Vec<Token> = Vec::new();
        // handle shebang
        if self.peek(0) == Some('#') && self.peek(1) == Some('!') {
            while let Some(c) = self.peek(0) {
                if c == '\n' {
                    break;
                }
                self.bump();
            }
        }
        loop {
            let nl = self.skip_ws()?;
            let line = self.line;
            let col = self.col;
            let pos = self.pos;
            let c = match self.peek(0) {
                None => {
                    toks.push(Token { tok: Tok::Eof, nl_before: true, line, col, pos });
                    break;
                }
                Some(c) => c,
            };
            let tok = if is_id_start(c) || c == '\\' {
                let mut s = String::new();
                while let Some(c) = self.peek(0) {
                    if is_id_part(c) {
                        s.push(c);
                        self.bump();
                    } else {
                        break;
                    }
                }
                if KEYWORDS.contains(&s.as_str()) {
                    Tok::Keyword(s)
                } else {
                    Tok::Ident(s)
                }
            } else if c.is_ascii_digit() || (c == '.' && self.peek(1).map_or(false, |d| d.is_ascii_digit())) {
                self.lex_number()?
            } else if c == '"' || c == '\'' {
                self.lex_string(c)?
            } else if c == '`' {
                self.lex_template()?
            } else if c == '/' && regex_allowed(toks.last()) {
                self.lex_regex()?
            } else {
                let mut found = None;
                for p in PUNCTS {
                    let pc: Vec<char> = p.chars().collect();
                    if self.src.len() >= self.pos + pc.len() && self.src[self.pos..self.pos + pc.len()] == pc[..] {
                        // `?.` followed by digit is conditional
                        if *p == "?." && self.peek(2).map_or(false, |d| d.is_ascii_digit()) {
                            continue;
                        }
                        found = Some(*p);
                        break;
                    }
                }
                match found {
                    Some(p) => {
                        for _ in 0..p.chars().count() {
                            self.bump();
                        }
                        Tok::Punct(p)
                    }
                    None => return self.err(&format!("unexpected character '{}'", c)),
                }
            };
            toks.push(Token { tok, nl_before: nl, line: line + self.base_line, col, pos });
        }
        Ok(toks)
    }

    fn skip_ws(&mut self) -> LexResult<bool> {
        let mut nl = false;
        loop {
            match self.peek(0) {
                Some('\n') | Some('\r') | Some('\u{2028}') | Some('\u{2029}') => {
                    nl = true;
                    self.bump();
                }
                Some(c) if c.is_whitespace() || c == '\u{feff}' => {
                    self.bump();
                }
                Some('/') if self.peek(1) == Some('/') => {
                    while let Some(c) = self.peek(0) {
                        if c == '\n' {
                            break;
                        }
                        self.bump();
                    }
                }
                Some('/') if self.peek(1) == Some('*') => {
                    self.bump();
                    self.bump();
                    loop {
                        match self.peek(0) {
                            None => return self.err("unexpected end of comment"),
                            Some('*') if self.peek(1) == Some('/') => {
                                self.bump();
                                self.bump();
                                break;
                            }
                            Some(c) => {
                                if c == '\n' {
                                    nl = true;
                                }
                                self.bump();
                            }
                        }
                    }
                }
                _ => break,
            }
        }
        Ok(nl)
    }

    fn lex_number(&mut self) -> LexResult<Tok> {
        let start = self.pos;
        if self.peek(0) == Some('0') {
            let radix = match self.peek(1) {
                Some('x') | Some('X') => 16,
                Some('o') | Some('O') => 8,
                Some('b') | Some('B') => 2,
                _ => 0,
            };
            if radix != 0 {
                self.bump();
                self.bump();
                let mut v: f64 = 0.0;
                while let Some(c) = self.peek(0) {
                    if c == '_' {
                        self.bump();
                        continue;
                    }
                    match c.to_digit(radix) {
                        Some(d) => {
                            v = v * radix as f64 + d as f64;
                            self.bump();
                        }
                        None => break,
                    }
                }
                if self.peek(0) == Some('n') {
                    self.bump();
                }
                return Ok(Tok::Num(v));
            }
        }
        let mut s = String::new();
        while let Some(c) = self.peek(0) {
            if c.is_ascii_digit() || c == '_' {
                if c != '_' {
                    s.push(c);
                }
                self.bump();
            } else {
                break;
            }
        }
        if self.peek(0) == Some('.') {
            s.push('.');
            self.bump();
            while let Some(c) = self.peek(0) {
                if c.is_ascii_digit() || c == '_' {
                    if c != '_' {
                        s.push(c);
                    }
                    self.bump();
                } else {
                    break;
                }
            }
        }
        if matches!(self.peek(0), Some('e') | Some('E')) {
            let save = (self.pos, self.line, self.col);
            let mut e = String::from("e");
            self.bump();
            if matches!(self.peek(0), Some('+') | Some('-')) {
                e.push(self.bump().unwrap());
            }
            if self.peek(0).map_or(false, |c| c.is_ascii_digit()) {
                while let Some(c) = self.peek(0) {
                    if c.is_ascii_digit() {
                        e.push(c);
                        self.bump();
                    } else {
                        break;
                    }
                }
                s.push_str(&e);
            } else {
                self.pos = save.0;
                self.line = save.1;
                self.col = save.2;
            }
        }
        if self.peek(0) == Some('n') {
            self.bump();
        }
        let _ = start;
        let s2 = if s.starts_with('.') { format!("0{}", s) } else { s.clone() };
        let s2 = if s2.ends_with('.') { format!("{}0", s2) } else { s2 };
        match s2.parse::<f64>() {
            Ok(v) => Ok(Tok::Num(v)),
            Err(_) => self.err("invalid number"),
        }
    }

    fn lex_escape(&mut self, out: &mut String) -> LexResult<()> {
        // assumes backslash consumed
        let c = match self.bump() {
            None => return self.err("unexpected end of string"),
            Some(c) => c,
        };
        match c {
            'n' => out.push('\n'),
            't' => out.push('\t'),
            'r' => out.push('\r'),
            'b' => out.push('\u{8}'),
            'f' => out.push('\u{c}'),
            'v' => out.push('\u{b}'),
            '0' if !self.peek(0).map_or(false, |c| c.is_ascii_digit()) => out.push('\0'),
            'x' => {
                let mut v = 0u32;
                for _ in 0..2 {
                    let d = self.bump().and_then(|c| c.to_digit(16));
                    match d {
                        Some(d) => v = v * 16 + d,
                        None => return self.err("malformed escape sequence in string literal"),
                    }
                }
                out.push(char::from_u32(v).unwrap_or('\u{fffd}'));
            }
            'u' => {
                let v = self.lex_unicode_escape()?;
                // handle surrogate pairs
                if (0xD800..0xDC00).contains(&v) && self.peek(0) == Some('\\') && self.peek(1) == Some('u') {
                    let save = (self.pos, self.line, self.col);
                    self.bump();
                    self.bump();
                    let lo = self.lex_unicode_escape()?;
                    if (0xDC00..0xE000).contains(&lo) {
                        let cp = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                        out.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                        return Ok(());
                    } else {
                        self.pos = save.0;
                        self.line = save.1;
                        self.col = save.2;
                    }
                }
                out.push(char::from_u32(v).unwrap_or('\u{fffd}'));
            }
            '\r' => {
                if self.peek(0) == Some('\n') {
                    self.bump();
                }
            }
            '\n' | '\u{2028}' | '\u{2029}' => {}
            c if c.is_ascii_digit() => {
                // legacy octal
                let mut v = c.to_digit(8).unwrap_or(0);
                for _ in 0..2 {
                    match self.peek(0).and_then(|c| c.to_digit(8)) {
                        Some(d) if v * 8 + d < 256 => {
                            v = v * 8 + d;
                            self.bump();
                        }
                        _ => break,
                    }
                }
                out.push(char::from_u32(v).unwrap());
            }
            c => out.push(c),
        }
        Ok(())
    }

    fn lex_unicode_escape(&mut self) -> LexResult<u32> {
        if self.peek(0) == Some('{') {
            self.bump();
            let mut v = 0u32;
            loop {
                match self.bump() {
                    Some('}') => break,
                    Some(c) if c.is_ascii_hexdigit() => v = v * 16 + c.to_digit(16).unwrap(),
                    _ => return self.err("malformed escape sequence in string literal"),
                }
            }
            Ok(v)
        } else {
            let mut v = 0u32;
            for _ in 0..4 {
                match self.bump().and_then(|c| c.to_digit(16)) {
                    Some(d) => v = v * 16 + d,
                    None => return self.err("malformed escape sequence in string literal"),
                }
            }
            Ok(v)
        }
    }

    fn lex_string(&mut self, q: char) -> LexResult<Tok> {
        self.bump();
        let mut s = String::new();
        loop {
            match self.peek(0) {
                None | Some('\n') => return self.err("unexpected end of string"),
                Some(c) if c == q => {
                    self.bump();
                    break;
                }
                Some('\\') => {
                    self.bump();
                    self.lex_escape(&mut s)?;
                }
                Some(c) => {
                    s.push(c);
                    self.bump();
                }
            }
        }
        Ok(Tok::Str(s))
    }

    fn lex_template(&mut self) -> LexResult<Tok> {
        self.bump();
        let mut cooked = Vec::new();
        let mut raws = Vec::new();
        let mut exprs = Vec::new();
        let mut cur = String::new();
        let mut raw = String::new();
        loop {
            match self.peek(0) {
                None => return self.err("unexpected end of string"),
                Some('`') => {
                    self.bump();
                    cooked.push(std::mem::take(&mut cur));
                    raws.push(std::mem::take(&mut raw));
                    break;
                }
                Some('\\') => {
                    let start = self.pos;
                    self.bump();
                    self.lex_escape(&mut cur)?;
                    for i in start..self.pos {
                        raw.push(self.src[i]);
                    }
                }
                Some('$') if self.peek(1) == Some('{') => {
                    self.bump();
                    self.bump();
                    cooked.push(std::mem::take(&mut cur));
                    raws.push(std::mem::take(&mut raw));
                    // find the matching close brace by lexing tokens
                    let start = self.pos;
                    let start_line = self.line;
                    let start_col = self.col;
                    // lex the expression tokens with a sub-lexer up to the matching '}'
                    let mut depth = 0i32;
                    let mut sub = Lexer { src: self.src, pos: start, line: start_line, col: start_col, base_line: self.base_line };
                    let mut toks: Vec<Token> = Vec::new();
                    loop {
                        let nl = sub.skip_ws()?;
                        let line = sub.line;
                        let col = sub.col;
                        let pos = sub.pos;
                        let c = match sub.peek(0) {
                            None => return self.err("unexpected end of template"),
                            Some(c) => c,
                        };
                        if c == '}' && depth == 0 {
                            sub.bump();
                            break;
                        }
                        // lex one token using the sub lexer
                        let tok = sub.lex_one(toks.last())?;
                        if let Tok::Punct(p) = &tok {
                            if *p == "{" {
                                depth += 1;
                            } else if *p == "}" {
                                depth -= 1;
                            }
                        }
                        toks.push(Token { tok, nl_before: nl, line, col, pos });
                    }
                    toks.push(Token { tok: Tok::Eof, nl_before: true, line: sub.line, col: sub.col, pos: sub.pos });
                    self.pos = sub.pos;
                    self.line = sub.line;
                    self.col = sub.col;
                    exprs.push(toks);
                }
                Some(c) => {
                    if c == '\r' {
                        self.bump();
                        if self.peek(0) == Some('\n') {
                            self.bump();
                        }
                        cur.push('\n');
                        raw.push('\n');
                        continue;
                    }
                    cur.push(c);
                    raw.push(c);
                    self.bump();
                }
            }
        }
        Ok(Tok::Template(cooked, raws, exprs))
    }

    fn lex_one(&mut self, prev: Option<&Token>) -> LexResult<Tok> {
        let c = self.peek(0).unwrap();
        if is_id_start(c) {
            let mut s = String::new();
            while let Some(c) = self.peek(0) {
                if is_id_part(c) {
                    s.push(c);
                    self.bump();
                } else {
                    break;
                }
            }
            return Ok(if KEYWORDS.contains(&s.as_str()) { Tok::Keyword(s) } else { Tok::Ident(s) });
        }
        if c.is_ascii_digit() || (c == '.' && self.peek(1).map_or(false, |d| d.is_ascii_digit())) {
            return self.lex_number();
        }
        if c == '"' || c == '\'' {
            return self.lex_string(c);
        }
        if c == '`' {
            return self.lex_template();
        }
        if c == '/' && regex_allowed(prev) {
            return self.lex_regex();
        }
        for p in PUNCTS {
            let pc: Vec<char> = p.chars().collect();
            if self.src.len() >= self.pos + pc.len() && self.src[self.pos..self.pos + pc.len()] == pc[..] {
                for _ in 0..pc.len() {
                    self.bump();
                }
                return Ok(Tok::Punct(p));
            }
        }
        self.err(&format!("unexpected character '{}'", c))
    }

    fn lex_regex(&mut self) -> LexResult<Tok> {
        self.bump();
        let mut s = String::new();
        let mut in_class = false;
        loop {
            match self.peek(0) {
                None | Some('\n') => return self.err("unexpected end of regexp"),
                Some('\\') => {
                    s.push('\\');
                    self.bump();
                    match self.bump() {
                        None => return self.err("unexpected end of regexp"),
                        Some(c) => s.push(c),
                    }
                }
                Some('[') => {
                    in_class = true;
                    s.push('[');
                    self.bump();
                }
                Some(']') => {
                    in_class = false;
                    s.push(']');
                    self.bump();
                }
                Some('/') if !in_class => {
                    self.bump();
                    break;
                }
                Some(c) => {
                    s.push(c);
                    self.bump();
                }
            }
        }
        let mut flags = String::new();
        while let Some(c) = self.peek(0) {
            if is_id_part(c) {
                flags.push(c);
                self.bump();
            } else {
                break;
            }
        }
        Ok(Tok::Regex(s, flags))
    }
}

fn regex_allowed(prev: Option<&Token>) -> bool {
    match prev {
        None => true,
        Some(t) => match &t.tok {
            Tok::Ident(_) | Tok::Num(_) | Tok::Str(_) | Tok::Template(..) | Tok::Regex(..) => false,
            Tok::Keyword(k) => !matches!(k.as_str(), "this" | "super" | "null" | "true" | "false"),
            Tok::Punct(p) => !matches!(*p, ")" | "]" | "}" | "++" | "--"),
            Tok::Eof => true,
        },
    }
}
