    Num(f64),
    Str(Rc<str>),
    Obj(Obj),
}

pub type Obj = Rc<RefCell<ObjData>>;

pub type NativeFn = Rc<dyn Fn(&mut super::interp::Interp, Value, Vec<Value>) -> Result<Value, Ctl>>;

pub enum Func {
    Closure { def: Rc<FuncDef>, env: Env, this_val: Option<Value>, home: Option<Obj> },
    Native { name: Rc<str>, f: NativeFn, ctor: bool },
    Bound { target: Value, this: Value, args: Vec<Value> },
}

pub enum Kind {
    Ordinary,
    Array(Vec<Value>),
    Function(Func),
    RegExp(Rc<str>, Rc<str>),
    Error,
    RuleBuilder(Option<Rc<std::collections::HashSet<String>>>),
    Map(Vec<(Value, Value)>),
    Set(Vec<Value>),
    Boxed(Value),
}

pub struct ObjData {
    pub kind: Kind,
    pub props: IndexMap<Rc<str>, Value>,
    pub getters: Option<HashMap<Rc<str>, Value>>,
    pub proto: Option<Obj>,
    pub class_name: Option<Rc<str>>,
}

impl ObjData {
    pub fn new(kind: Kind) -> Self {
        ObjData { kind, props: IndexMap::new(), getters: None, proto: None, class_name: None }
    }
}

pub fn new_obj(kind: Kind) -> Value {
    Value::Obj(Rc::new(RefCell::new(ObjData::new(kind))))
}

pub enum Ctl {
    Throw(Value),
    Return(Value),
    Break(Option<Rc<str>>),
    Continue(Option<Rc<str>>),
}

pub type R<T> = Result<T, Ctl>;

pub struct Scope {
    pub vars: HashMap<Rc<str>, (Value, bool)>, // value, is_const
    pub parent: Option<Env>,
    pub is_function: bool,
    pub this_val: Option<Value>,
}

pub type Env = Rc<RefCell<Scope>>;

pub fn new_scope(parent: Option<Env>, is_function: bool) -> Env {
    Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent, is_function, this_val: None }))
}

impl Value {
    pub fn str(s: &str) -> Value {
        Value::Str(Rc::from(s))
    }
    pub fn is_undef(&self) -> bool {
        matches!(self, Value::Undef)
    }
    pub fn is_nullish(&self) -> bool {
        matches!(self, Value::Undef | Value::Null)
    }
    pub fn truthy(&self) -> bool {
        match self {
            Value::Undef | Value::Null => false,
            Value::Bool(b) => *b,
            Value::Num(n) => !(*n == 0.0 || n.is_nan()),
            Value::Str(s) => !s.is_empty(),
            Value::Obj(_) => true,
        }
    }
    pub fn as_obj(&self) -> Option<&Obj> {
        match self {
            Value::Obj(o) => Some(o),
            _ => None,
        }
    }
    pub fn is_array(&self) -> bool {
        match self {
            Value::Obj(o) => matches!(o.borrow().kind, Kind::Array(_)),
            _ => false,
        }
    }
    pub fn is_function(&self) -> bool {
        match self {
            Value::Obj(o) => matches!(o.borrow().kind, Kind::Function(_)),
            _ => false,
        }
    }
    pub fn is_regexp(&self) -> bool {
        match self {
            Value::Obj(o) => matches!(o.borrow().kind, Kind::RegExp(..)),
            _ => false,
        }
    }
    pub fn array_items(&self) -> Option<Vec<Value>> {
        match self {
            Value::Obj(o) => match &o.borrow().kind {
                Kind::Array(v) => Some(v.clone()),
                _ => None,
            },
            _ => None,
        }
    }
}

pub fn same_obj(a: &Obj, b: &Obj) -> bool {
    Rc::ptr_eq(a, b)
}
