use super::ast::*;
use super::value::*;
use indexmap::IndexMap;
use std::cell::RefCell;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::rc::Rc;

pub struct Frame {
    pub name: Rc<str>,
    pub file: Rc<str>,
    pub line: u32,
    pub col: u32,
}

pub struct Interp {
    pub global: Env,
    pub object_proto: Obj,
    pub function_proto: Obj,
    pub array_proto: Obj,
    pub error_proto: Obj,
    pub error_ctors: HashMap<&'static str, Value>,
    pub method_cache: HashMap<(&'static str, Rc<str>), Value>,
    pub stack: Vec<Frame>,
    pub cur_file: Rc<str>,
    pub cur_line: u32,
    pub cur_col: u32,
    pub module_cache: HashMap<PathBuf, Value>,
    pub base_dir: PathBuf,
    pub stderr_log: Vec<String>,
    pub depth: usize,
}

pub fn num_to_string(n: f64) -> String {
    if n.is_nan() {
        return "NaN".into();
    }
    if n.is_infinite() {
        return if n > 0.0 { "Infinity".into() } else { "-Infinity".into() };
    }
    if n == 0.0 {
        return "0".into();
    }
    if n < 0.0 {
        return format!("-{}", num_to_string(-n));
    }
    // shortest round-trip digits
    let e = format!("{:e}", n);
    let (mant, exp) = e.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let k = digits.len() as i32;
    let nexp = exp + 1; // position of decimal point
    if k <= nexp && nexp <= 21 {
        let mut s = digits.clone();
        for _ in 0..(nexp - k) {
            s.push('0');
        }
        s
    } else if 0 < nexp && nexp <= 21 {
        format!("{}.{}", &digits[..nexp as usize], &digits[nexp as usize..])
    } else if -6 < nexp && nexp <= 0 {
        let mut s = String::from("0.");
        for _ in 0..(-nexp) {
            s.push('0');
        }
        s.push_str(&digits);
        s
    } else {
        let e2 = nexp - 1;
        let sign = if e2 >= 0 { "+" } else { "-" };
        if k == 1 {
            format!("{}e{}{}", digits, sign, e2.abs())
        } else {
            format!("{}.{}e{}{}", &digits[..1], &digits[1..], sign, e2.abs())
        }
    }
}

fn rcs(s: &str) -> Rc<str> {
    Rc::from(s)
}

pub fn throw_error(interp: &mut Interp, kind: &'static str, msg: &str) -> Ctl {
    Ctl::Throw(interp.make_error(kind, msg))
}

macro_rules! native {
    ($interp:expr, $name:expr, $f:expr) => {
        $interp.native_fn($name, Rc::new($f))
    };
}

impl Interp {
    pub fn new(base_dir: PathBuf) -> Interp {
        let object_proto = Rc::new(RefCell::new(ObjData::new(Kind::Ordinary)));
        let mk = |k: Kind, p: &Obj| {
            let mut d = ObjData::new(k);
            d.proto = Some(p.clone());
            Rc::new(RefCell::new(d))
        };
        let function_proto = mk(Kind::Ordinary, &object_proto);
        let array_proto = mk(Kind::Ordinary, &object_proto);
        let error_proto = mk(Kind::Ordinary, &object_proto);
        let global = new_scope(None, true);
        let mut it = Interp {
            global,
            object_proto,
            function_proto,
            array_proto,
            error_proto,
            error_ctors: HashMap::new(),
            method_cache: HashMap::new(),
            stack: Vec::new(),
            cur_file: rcs("grammar.js"),
            cur_line: 1,
            cur_col: 1,
            module_cache: HashMap::new(),
            base_dir,
            stderr_log: Vec::new(),
            depth: 0,
        };
        super::builtins::install(&mut it);
        it
    }

    pub fn native_fn(&mut self, name: &str, f: NativeFn) -> Value {
        let mut d = ObjData::new(Kind::Function(Func::Native { name: rcs(name), f, ctor: false }));
        d.proto = Some(self.function_proto.clone());
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn native_ctor(&mut self, name: &str, f: NativeFn) -> Value {
        let mut d = ObjData::new(Kind::Function(Func::Native { name: rcs(name), f, ctor: true }));
        d.proto = Some(self.function_proto.clone());
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn new_object(&self) -> Value {
        let mut d = ObjData::new(Kind::Ordinary);
        d.proto = Some(self.object_proto.clone());
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn new_array(&self, items: Vec<Value>) -> Value {
        let mut d = ObjData::new(Kind::Array(items));
        d.proto = Some(self.array_proto.clone());
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn new_regexp(&self, src: &str, flags: &str) -> Value {
        let mut d = ObjData::new(Kind::RegExp(rcs(src), rcs(flags)));
        d.proto = Some(self.object_proto.clone());
        d.props.insert(rcs("lastIndex"), Value::Num(0.0));
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn stack_string(&self) -> String {
        let mut s = String::new();
        // innermost first
        let mut line = self.cur_line;
        let mut col = self.cur_col;
        for f in self.stack.iter().rev() {
            s.push_str(&format!("    at {} ({}:{}:{})\n", f.name, f.file, line, col));
            line = f.line;
            col = f.col;
        }
        s.push_str(&format!("    at <anonymous> ({}:{}:{})\n", self.cur_file_for_bottom(), line, col));
        s
    }

    fn cur_file_for_bottom(&self) -> Rc<str> {
        self.stack.first().map(|f| f.file.clone()).unwrap_or(self.cur_file.clone())
    }

    pub fn make_error(&mut self, kind: &'static str, msg: &str) -> Value {
        let proto = match self.error_ctors.get(kind).cloned() {
            Some(c) => self.get(&c, "prototype").ok().and_then(|p| p.as_obj().cloned()),
            None => None,
        };
        let mut d = ObjData::new(Kind::Error);
        d.proto = Some(proto.unwrap_or(self.error_proto.clone()));
        d.props.insert(rcs("message"), Value::str(msg));
        let st = self.stack_string();
        d.props.insert(rcs("stack"), Value::str(&st));
        d.class_name = Some(rcs(kind));
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn type_error(&mut self, msg: &str) -> Ctl {
        throw_error(self, "TypeError", msg)
    }

    // ---------- conversions ----------
    pub fn to_string(&mut self, v: &Value) -> R<Rc<str>> {
        Ok(match v {
            Value::Undef => rcs("undefined"),
            Value::Null => rcs("null"),
            Value::Bool(b) => rcs(if *b { "true" } else { "false" }),
            Value::Num(n) => rcs(&num_to_string(*n)),
            Value::Str(s) => s.clone(),
            Value::Obj(o) => {
                // check for toString method
                let ts = self.get(v, "toString")?;
                if ts.is_function() {
                    let is_default = {
                        if let Value::Obj(f) = &ts {
                            matches!(&f.borrow().kind, Kind::Function(Func::Native { name, .. }) if &**name == "__default_toString")
                        } else {
                            false
                        }
                    };
                    if !is_default {
                        let r = self.call(&ts, v.clone(), vec![])?;
                        if !matches!(r, Value::Obj(_)) {
                            return self.to_string(&r);
                        }
                    }
                }
                let _ = o;
                rcs(&self.default_to_string(v)?)
            }
        })
    }

    pub fn default_to_string(&mut self, v: &Value) -> R<String> {
        let o = match v {
            Value::Obj(o) => o.clone(),
            _ => return Ok(self.to_string(v)?.to_string()),
        };
        let kind_info = {
            let b = o.borrow();
            match &b.kind {
                Kind::Array(items) => Some(items.clone()),
                _ => None,
            }
        };
        if let Some(items) = kind_info {
            let mut parts = Vec::new();
            for it in items {
                if it.is_nullish() {
                    parts.push(String::new());
                } else {
                    parts.push(self.to_string(&it)?.to_string());
                }
            }
            return Ok(parts.join(","));
        }
        let b = o.borrow();
        Ok(match &b.kind {
            Kind::RegExp(s, f) => format!("/{}/{}", s, f),
            Kind::Function(Func::Closure { def, .. }) => {
                format!("function {}() {{ [code] }}", def.name.as_deref().unwrap_or(""))
            }
            Kind::Function(Func::Native { name, .. }) => format!("function {}() {{\n    [native code]\n}}", name),
            Kind::Function(_) => "function () {\n    [native code]\n}".to_string(),
            Kind::Error => {
                drop(b);
                let name = self.get(v, "name")?;
                let msg = self.get(v, "message")?;
                let name = if name.is_undef() { rcs("Error") } else { self.to_string(&name)? };
                let msg = if msg.is_undef() { rcs("") } else { self.to_string(&msg)? };
                if msg.is_empty() {
                    name.to_string()
                } else if name.is_empty() {
                    msg.to_string()
                } else {
                    format!("{}: {}", name, msg)
                }
            }
            Kind::Boxed(inner) => {
                let inner = inner.clone();
                drop(b);
                self.to_string(&inner)?.to_string()
            }
            _ => "[object Object]".to_string(),
        })
    }

    pub fn to_number(&mut self, v: &Value) -> R<f64> {
        Ok(match v {
            Value::Undef => f64::NAN,
            Value::Null => 0.0,
            Value::Bool(b) => {
                if *b {
                    1.0
                } else {
                    0.0
                }
            }
            Value::Num(n) => *n,
            Value::Str(s) => str_to_num(s),
            Value::Obj(_) => {
                let p = self.to_primitive(v)?;
                self.to_number(&p)?
            }
        })
    }

    pub fn to_primitive(&mut self, v: &Value) -> R<Value> {
        match v {
            Value::Obj(o) => {
                if let Kind::Boxed(inner) = &o.borrow().kind {
                    return Ok(inner.clone());
                }
                let vo = self.get(v, "valueOf")?;
                if vo.is_function() {
                    let r = self.call(&vo, v.clone(), vec![])?;
                    if !matches!(r, Value::Obj(_)) {
                        return Ok(r);
                    }
                }
                Ok(Value::Str(self.to_string(v)?))
            }
            _ => Ok(v.clone()),
        }
    }

    pub fn typeof_(&self, v: &Value) -> &'static str {
        match v {
            Value::Undef => "undefined",
            Value::Null => "object",
            Value::Bool(_) => "boolean",
            Value::Num(_) => "number",
            Value::Str(_) => "string",
            Value::Obj(o) => {
                if matches!(o.borrow().kind, Kind::Function(_)) {
                    "function"
                } else {
                    "object"
                }
            }
        }
    }

    pub fn strict_eq(&self, a: &Value, b: &Value) -> bool {
        match (a, b) {
            (Value::Undef, Value::Undef) | (Value::Null, Value::Null) => true,
            (Value::Bool(x), Value::Bool(y)) => x == y,
            (Value::Num(x), Value::Num(y)) => x == y,
            (Value::Str(x), Value::Str(y)) => x == y,
            (Value::Obj(x), Value::Obj(y)) => Rc::ptr_eq(x, y),
            _ => false,
        }
    }

    pub fn same_value_zero(&self, a: &Value, b: &Value) -> bool {
        match (a, b) {
            (Value::Num(x), Value::Num(y)) if x.is_nan() && y.is_nan() => true,
            _ => self.strict_eq(a, b),
        }
    }

    pub fn loose_eq(&mut self, a: &Value, b: &Value) -> R<bool> {
        Ok(match (a, b) {
            (Value::Undef | Value::Null, Value::Undef | Value::Null) => true,
            (Value::Undef | Value::Null, _) | (_, Value::Undef | Value::Null) => false,
            (Value::Num(_), Value::Str(_)) | (Value::Str(_), Value::Num(_)) => self.to_number(a)? == self.to_number(b)?,
            (Value::Bool(_), _) => {
                let n = Value::Num(self.to_number(a)?);
                self.loose_eq(&n, b)?
            }
            (_, Value::Bool(_)) => {
                let n = Value::Num(self.to_number(b)?);
                self.loose_eq(a, &n)?
            }
            (Value::Obj(_), Value::Obj(_)) => self.strict_eq(a, b),
            (Value::Obj(_), _) => {
                let p = self.to_primitive(a)?;
                self.loose_eq(&p, b)?
            }
            (_, Value::Obj(_)) => {
                let p = self.to_primitive(b)?;
                self.loose_eq(a, &p)?
            }
            _ => self.strict_eq(a, b),
        })
    }

    pub fn to_key(&mut self, v: &Value) -> R<Rc<str>> {
        match v {
            Value::Str(s) => Ok(s.clone()),
            Value::Num(n) => Ok(rcs(&num_to_string(*n))),
            _ => self.to_string(v),
        }
    }

    // ---------- property access ----------
    pub fn get(&mut self, target: &Value, key: &str) -> R<Value> {
        match target {
            Value::Undef | Value::Null => {
                let msg = format!("cannot read property '{}' of {}", key, if target.is_undef() { "undefined" } else { "null" });
                Err(self.type_error(&msg))
            }
            Value::Str(s) => {
                if key == "length" {
                    return Ok(Value::Num(s.encode_utf16().count() as f64));
                }
                if let Ok(i) = key.parse::<usize>() {
                    let u: Vec<u16> = s.encode_utf16().collect();
                    if i < u.len() {
                        return Ok(Value::str(&String::from_utf16_lossy(&u[i..i + 1])));
                    }
                    return Ok(Value::Undef);
                }
                Ok(super::builtins::string_method(self, key).unwrap_or(Value::Undef))
            }
            Value::Num(_) => Ok(super::builtins::number_method(self, key).unwrap_or(Value::Undef)),
            Value::Bool(_) => Ok(super::builtins::bool_method(self, key).unwrap_or(Value::Undef)),
            Value::Obj(o) => self.get_obj(o, key, target),
        }
    }

    pub fn get_obj(&mut self, o: &Obj, key: &str, this: &Value) -> R<Value> {
        // special kinds
        {
            let b = o.borrow();
            match &b.kind {
                Kind::Array(items) => {
                    if key == "length" {
                        return Ok(Value::Num(items.len() as f64));
                    }
                    if let Ok(i) = key.parse::<usize>() {
                        return Ok(items.get(i).cloned().unwrap_or(Value::Undef));
                    }
                }
                Kind::RuleBuilder(rules) => {
                    let rules = rules.clone();
                    drop(b);
                    return super::dsl::rule_builder_get(self, rules, key);
                }
                Kind::RegExp(src, flags) => match key {
                    "source" => return Ok(Value::Str(src.clone())),
                    "flags" => return Ok(Value::Str(flags.clone())),
                    "global" => return Ok(Value::Bool(flags.contains('g'))),
                    "ignoreCase" => return Ok(Value::Bool(flags.contains('i'))),
                    "multiline" => return Ok(Value::Bool(flags.contains('m'))),
                    "unicode" => return Ok(Value::Bool(flags.contains('u'))),
                    "sticky" => return Ok(Value::Bool(flags.contains('y'))),
                    "dotAll" => return Ok(Value::Bool(flags.contains('s'))),
                    _ => {}
                },
                Kind::Map(m) if key == "size" => return Ok(Value::Num(m.len() as f64)),
                Kind::Set(m) if key == "size" => return Ok(Value::Num(m.len() as f64)),
                Kind::Error if key == "name" && !b.props.contains_key("name") => {
                    // fall through to proto lookup
                }
                Kind::Function(f) => {
                    if !b.props.contains_key(key) {
                        match key {
                            "name" => {
                                return Ok(Value::str(&match f {
                                    Func::Closure { def, .. } => def.name.as_deref().unwrap_or("").to_string(),
                                    Func::Native { name, .. } => name.to_string(),
                                    Func::Bound { .. } => "bound".to_string(),
                                }))
                            }
                            "length" => {
                                return Ok(Value::Num(match f {
                                    Func::Closure { def, .. } => def.params.iter().take_while(|p| p.default.is_none() && !p.rest).count() as f64,
                                    _ => 0.0,
                                }))
                            }
                            "prototype" => {
                                if let Func::Closure { def, .. } = f {
                                    if !def.is_arrow {
                                        drop(b);
                                        let p = self.new_object();
                                        if let Value::Obj(po) = &p {
                                            po.borrow_mut().props.insert(rcs("constructor"), this.clone());
                                        }
                                        o.borrow_mut().props.insert(rcs("prototype"), p.clone());
                                        return Ok(p);
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                }
                _ => {}
            }
        }
        // own props / getters / proto chain
        let mut cur = Some(o.clone());
        while let Some(c) = cur {
            let (v, getter, next) = {
                let b = c.borrow();
                let v = b.props.get(key).cloned();
                let g = b.getters.as_ref().and_then(|g| g.get(key).cloned());
                (v, g, b.proto.clone())
            };
            if let Some(g) = getter {
                return self.call(&g, this.clone(), vec![]);
            }
            if let Some(v) = v {
                return Ok(v);
            }
            cur = next;
        }
        Ok(Value::Undef)
    }

    pub fn set(&mut self, target: &Value, key: &str, val: Value) -> R<()> {
        match target {
            Value::Obj(o) => {
                let mut b = o.borrow_mut();
                if let Kind::Array(items) = &mut b.kind {
                    if key == "length" {
                        drop(b);
                        let n = self.to_number(&val)? as usize;
                        if let Kind::Array(items) = &mut o.borrow_mut().kind {
                            items.resize(n, Value::Undef);
                        }
                        return Ok(());
                    }
                    if let Ok(i) = key.parse::<usize>() {
                        if i >= items.len() {
                            items.resize(i + 1, Value::Undef);
                        }
                        items[i] = val;
                        return Ok(());
                    }
                }
                if b.class_name.as_deref() == Some("__frozen") {
                    return Ok(());
                }
                // setter?
                let setter = b.getters.as_ref().and_then(|g| g.get(&*format!("set {}", key)).cloned());
                if let Some(s) = setter {
                    drop(b);
                    self.call(&s, target.clone(), vec![val])?;
                    return Ok(());
                }
                b.props.insert(rcs(key), val);
                Ok(())
            }
            Value::Undef | Value::Null => {
                let msg = format!("cannot set property '{}' of {}", key, if target.is_undef() { "undefined" } else { "null" });
                Err(self.type_error(&msg))
            }
            _ => Ok(()),
        }
    }

    // ---------- calling ----------
    pub fn call(&mut self, f: &Value, this: Value, args: Vec<Value>) -> R<Value> {
        let fo = match f {
            Value::Obj(o) => o.clone(),
            _ => {
                let s = self.describe(f);
                return Err(self.type_error(&format!("{} is not a function", s)));
            }
        };
        enum C {
            Closure(Rc<FuncDef>, Env, Option<Value>, Option<Obj>),
            Native(NativeFn, Rc<str>),
            Bound(Value, Value, Vec<Value>),
        }
        let c = {
            let b = fo.borrow();
            match &b.kind {
                Kind::Function(Func::Closure { def, env, this_val, home }) => C::Closure(def.clone(), env.clone(), this_val.clone(), home.clone()),
                Kind::Function(Func::Native { f, name, .. }) => C::Native(f.clone(), name.clone()),
                Kind::Function(Func::Bound { target, this, args }) => C::Bound(target.clone(), this.clone(), args.clone()),
                _ => {
                    drop(b);
                    let s = self.describe(f);
                    return Err(self.type_error(&format!("{} is not a function", s)));
                }
            }
        };
        self.depth += 1;
        if self.depth > 2000 {
            self.depth -= 1;
            return Err(throw_error(self, "RangeError", "Maximum call stack size exceeded"));
        }
        let r = match c {
            C::Native(nf, name) => {
                self.stack.push(Frame { name: name.clone(), file: rcs("native"), line: self.cur_line, col: self.cur_col });
                let saved = (self.cur_line, self.cur_col);
                let r = nf(self, this, args);
                self.stack.pop();
                self.cur_line = saved.0;
                self.cur_col = saved.1;
                r
            }
            C::Bound(t, th, mut bargs) => {
                bargs.extend(args);
                self.call(&t, th, bargs)
            }
            C::Closure(def, env, this_val, _home) => {
                let fname: Rc<str> = def.name.clone().unwrap_or_else(|| rcs("<anonymous>"));
                self.stack.push(Frame { name: fname, file: self.cur_file.clone(), line: self.cur_line, col: self.cur_col });
                let saved = (self.cur_line, self.cur_col);
                let r = self.call_closure(&def, env, if def.is_arrow { this_val } else { Some(this) }, args, &fo);
                self.stack.pop();
                self.cur_line = saved.0;
                self.cur_col = saved.1;
                r
            }
        };
        self.depth -= 1;
        r
    }

    fn call_closure(&mut self, def: &Rc<FuncDef>, env: Env, this: Option<Value>, args: Vec<Value>, fo: &Obj) -> R<Value> {
        let scope = new_scope(Some(env), !def.is_arrow);
        if !def.is_arrow {
            scope.borrow_mut().this_val = Some(this.unwrap_or(Value::Undef));
            let argsv = self.new_array(args.clone());
            scope.borrow_mut().vars.insert(rcs("arguments"), (argsv, false));
        }
        let _ = fo;
        for (i, p) in def.params.iter().enumerate() {
            let v = if p.rest {
                self.new_array(args.get(i..).map(|s| s.to_vec()).unwrap_or_default())
            } else {
                let mut v = args.get(i).cloned().unwrap_or(Value::Undef);
                if v.is_undef() {
                    if let Some(d) = &p.default {
                        v = self.eval(d, &scope)?;
                    }
                }
                v
            };
            self.bind_pattern(&p.pat, v, &scope, VarKind::Let, true)?;
        }
        match &def.body {
            FuncBody::Expr(e) => self.eval(e, &scope),
            FuncBody::Block(stmts) => {
                self.hoist(stmts, &scope)?;
                match self.exec_stmts(stmts, &scope) {
                    Ok(()) => Ok(Value::Undef),
                    Err(Ctl::Return(v)) => Ok(v),
                    Err(e) => Err(e),
                }
            }
        }
    }

    pub fn construct(&mut self, f: &Value, args: Vec<Value>) -> R<Value> {
        let fo = match f {
            Value::Obj(o) => o.clone(),
            _ => {
                let s = self.describe(f);
                return Err(self.type_error(&format!("{} is not a constructor", s)));
            }
        };
        let is_native = matches!(&fo.borrow().kind, Kind::Function(Func::Native { .. }));
        if is_native {
            // native constructors handle `new` themselves when this is Undef marker
            return self.call(f, Value::Null, args);
        }
        let is_class = fo.borrow().class_name.as_deref() == Some("__class");
        let proto = self.get(f, "prototype")?;
        let obj = self.new_object();
        if let (Value::Obj(o), Value::Obj(p)) = (&obj, &proto) {
            o.borrow_mut().proto = Some(p.clone());
        }
        if is_class {
            // initialize fields of the class chain
            self.init_class_fields(f, &obj)?;
        }
        let r = self.call(f, obj.clone(), args)?;
        if let Value::Obj(_) = r {
            Ok(r)
        } else {
            Ok(obj)
        }
    }

    fn init_class_fields(&mut self, f: &Value, obj: &Value) -> R<()> {
        let fields = self.get(f, "__fields")?;
        if let Some(items) = fields.array_items() {
            for it in items {
                let k = self.get(&it, "0")?;
                let init = self.get(&it, "1")?;
                let k = self.to_key(&k)?;
                let v = if init.is_function() { self.call(&init, obj.clone(), vec![])? } else { Value::Undef };
                self.set(obj, &k, v)?;
            }
        }
        Ok(())
    }

    pub fn describe(&mut self, v: &Value) -> String {
        match v {
            Value::Undef => "undefined".into(),
            Value::Null => "null".into(),
            Value::Str(s) => format!("\"{}\"", s),
            Value::Obj(_) => "not a function".into(),
            _ => self.to_string(v).map(|s| s.to_string()).unwrap_or_default(),
        }
    }

    pub fn instance_of(&mut self, v: &Value, ctor: &Value) -> R<bool> {
        let proto = self.get(ctor, "prototype")?;
        let p = match proto {
            Value::Obj(p) => p,
            _ => return Ok(false),
        };
        let mut cur = match v {
            Value::Obj(o) => o.borrow().proto.clone(),
            _ => return Ok(false),
        };
        while let Some(c) = cur {
            if Rc::ptr_eq(&c, &p) {
                return Ok(true);
            }
            cur = c.borrow().proto.clone();
        }
        Ok(false)
    }

    // ---------- scopes ----------
    pub fn lookup(&mut self, name: &str, env: &Env) -> R<Value> {
        let mut cur = Some(env.clone());
        while let Some(e) = cur {
            if let Some((v, _)) = e.borrow().vars.get(name) {
                return Ok(v.clone());
            }
            cur = e.borrow().parent.clone();
        }
        Err(throw_error(self, "ReferenceError", &format!("'{}' is not defined", name)))
    }

    fn lookup_opt(&self, name: &str, env: &Env) -> Option<Value> {
        let mut cur = Some(env.clone());
        while let Some(e) = cur {
            if let Some((v, _)) = e.borrow().vars.get(name) {
                return Some(v.clone());
            }
            cur = e.borrow().parent.clone();
        }
        None
    }

    fn assign_var(&mut self, name: &str, v: Value, env: &Env) -> R<()> {
        let mut cur = Some(env.clone());
        while let Some(e) = cur {
            {
                let mut b = e.borrow_mut();
                if let Some(slot) = b.vars.get_mut(name) {
                    if slot.1 {
                        drop(b);
                        return Err(self.type_error("invalid assignment to const variable"));
                    }
                    slot.0 = v;
                    return Ok(());
                }
            }
            cur = e.borrow().parent.clone();
        }
        // implicit global
        self.global.borrow_mut().vars.insert(rcs(name), (v, false));
        Ok(())
    }

    fn this_value(&self, env: &Env) -> Value {
        let mut cur = Some(env.clone());
        while let Some(e) = cur {
            if let Some(t) = &e.borrow().this_val {
                return t.clone();
            }
            cur = e.borrow().parent.clone();
        }
        Value::Undef
    }

    fn function_scope(&self, env: &Env) -> Env {
        let mut cur = env.clone();
        loop {
            let next = {
                let b = cur.borrow();
                if b.is_function {
                    return cur.clone();
                }
                b.parent.clone()
            };
            match next {
                Some(n) => cur = n,
                None => return cur,
            }
        }
    }

    pub fn bind_pattern(&mut self, pat: &Pattern, v: Value, env: &Env, kind: VarKind, declare: bool) -> R<()> {
        match pat {
            Pattern::Ident(name) => {
                if declare {
                    let target = if kind == VarKind::Var { self.function_scope(env) } else { env.clone() };
                    target.borrow_mut().vars.insert(name.clone(), (v, kind == VarKind::Const));
                    Ok(())
                } else {
                    self.assign_var(name, v, env)
                }
            }
            Pattern::Expr(e) => self.assign_to_expr(e, v, env),
            Pattern::Array(elems, rest) => {
                let items = self.iterate(&v)?;
                for (i, el) in elems.iter().enumerate() {
                    if let Some((p, d)) = el {
                        let mut x = items.get(i).cloned().unwrap_or(Value::Undef);
                        if x.is_undef() {
                            if let Some(d) = d {
                                x = self.eval(d, env)?;
                            }
                        }
                        self.bind_pattern(p, x, env, kind, declare)?;
                    }
                }
                if let Some(r) = rest {
                    let rv = self.new_array(items.get(elems.len()..).map(|s| s.to_vec()).unwrap_or_default());
                    self.bind_pattern(r, rv, env, kind, declare)?;
                }
                Ok(())
            }
            Pattern::Object(props, rest) => {
                if v.is_nullish() {
                    return Err(self.type_error("cannot destructure undefined"));
                }
                let mut used = Vec::new();
                for (k, p, d) in props {
                    let key = match k {
                        PropKey::Static(s) => s.clone(),
                        PropKey::Computed(e) => {
                            let kv = self.eval(e, env)?;
                            self.to_key(&kv)?
                        }
                    };
                    let mut x = self.get(&v, &key)?;
                    if x.is_undef() {
                        if let Some(d) = d {
                            x = self.eval(d, env)?;
                        }
                    }
                    used.push(key);
                    self.bind_pattern(p, x, env, kind, declare)?;
                }
                if let Some(r) = rest {
                    let out = self.new_object();
                    for k in self.own_keys(&v) {
                        if !used.contains(&k) {
                            let x = self.get(&v, &k)?;
                            self.set(&out, &k, x)?;
                        }
                    }
                    self.bind_pattern(r, out, env, kind, declare)?;
                }
                Ok(())
            }
        }
    }

    pub fn own_keys(&self, v: &Value) -> Vec<Rc<str>> {
        match v {
            Value::Obj(o) => {
                let b = o.borrow();
                let mut keys: Vec<Rc<str>> = Vec::new();
                if let Kind::Array(items) = &b.kind {
                    for i in 0..items.len() {
                        keys.push(rcs(&i.to_string()));
                    }
                }
                // integer keys first in ascending order
                let mut ints: Vec<(u64, Rc<str>)> = Vec::new();
                let mut strs: Vec<Rc<str>> = Vec::new();
                for k in b.props.keys() {
                    if let Kind::Function(_) = b.kind {
                        if &**k == "__fields" {
                            continue;
                        }
                    }
                    if is_array_index(k) {
                        ints.push((k.parse().unwrap(), k.clone()));
                    } else {
                        strs.push(k.clone());
                    }
                }
                ints.sort_by_key(|x| x.0);
                keys.extend(ints.into_iter().map(|x| x.1));
                keys.extend(strs);
                if let Some(g) = &b.getters {
                    for k in g.keys() {
                        if !k.starts_with("set ") && !keys.contains(k) {
                            keys.push(k.clone());
                        }
                    }
                }
                keys
            }
            Value::Str(s) => (0..s.encode_utf16().count()).map(|i| rcs(&i.to_string())).collect(),
            _ => vec![],
        }
    }

    pub fn iterate(&mut self, v: &Value) -> R<Vec<Value>> {
        match v {
            Value::Str(s) => Ok(s.chars().map(|c| Value::str(&c.to_string())).collect()),
            Value::Obj(o) => {
                let b = o.borrow();
                match &b.kind {
                    Kind::Array(items) => Ok(items.clone()),
                    Kind::Set(items) => Ok(items.clone()),
                    Kind::Map(items) => {
                        let items = items.clone();
                        drop(b);
                        Ok(items.into_iter().map(|(k, v)| self.new_array(vec![k, v])).collect())
                    }
                    _ => {
                        drop(b);
                        // iterator protocol via next()
                        let next = self.get(v, "next")?;
                        if next.is_function() {
                            let mut out = Vec::new();
                            loop {
                                let r = self.call(&next, v.clone(), vec![])?;
                                if self.get(&r, "done")?.truthy() {
                                    break;
                                }
                                out.push(self.get(&r, "value")?);
                            }
                            return Ok(out);
                        }
                        Err(self.type_error("value is not iterable"))
                    }
                }
            }
            _ => Err(self.type_error("value is not iterable")),
        }
    }

    fn assign_to_expr(&mut self, e: &Expr, v: Value, env: &Env) -> R<()> {
        match e {
            Expr::Ident(n, _) => self.assign_var(n, v, env),
            Expr::Member(obj, name, _, _) => {
                let o = self.eval(obj, env)?;
                self.set(&o, name, v)
            }
            Expr::Index(obj, idx, _, _) => {
                let o = self.eval(obj, env)?;
                let k = self.eval(idx, env)?;
                let k = self.to_key(&k)?;
                self.set(&o, &k, v)
            }
            _ => Err(throw_error(self, "SyntaxError", "invalid assignment target")),
        }
    }

    // ---------- statements ----------
    pub fn hoist(&mut self, stmts: &[Stmt], env: &Env) -> R<()> {
        for s in stmts {
            match s {
                Stmt::Func(def) => {
                    let f = self.make_closure(def, env);
                    env.borrow_mut().vars.insert(def.name.clone().unwrap(), (f, false));
                }
                Stmt::ExportDecl(inner) => {
                    if let Stmt::Func(def) = &**inner {
                        let f = self.make_closure(def, env);
                        env.borrow_mut().vars.insert(def.name.clone().unwrap(), (f, false));
                    }
                }
                Stmt::Var(VarKind::Var, decls) => {
                    let fs = self.function_scope(env);
                    for (p, _) in decls {
                        if let Pattern::Ident(n) = p {
                            if !fs.borrow().vars.contains_key(n) {
                                fs.borrow_mut().vars.insert(n.clone(), (Value::Undef, false));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        Ok(())
    }

    pub fn exec_stmts(&mut self, stmts: &[Stmt], env: &Env) -> R<()> {
        for s in stmts {
            self.exec(s, env)?;
        }
        Ok(())
    }

    pub fn make_closure(&mut self, def: &Rc<FuncDef>, env: &Env) -> Value {
        let this_val = if def.is_arrow { Some(self.this_value(env)) } else { None };
        let mut d = ObjData::new(Kind::Function(Func::Closure { def: def.clone(), env: env.clone(), this_val, home: None }));
        d.proto = Some(self.function_proto.clone());
        Value::Obj(Rc::new(RefCell::new(d)))
    }

    pub fn exec(&mut self, s: &Stmt, env: &Env) -> R<()> {
        match s {
            Stmt::Empty => Ok(()),
            Stmt::Expr(e) => {
                self.eval(e, env)?;
                Ok(())
            }
            Stmt::Var(kind, decls) => {
                for (p, init) in decls {
                    let v = match init {
                        Some(e) => {
                            let v = self.eval(e, env)?;
                            // name anonymous functions
                            if let (Pattern::Ident(n), Value::Obj(o)) = (p, &v) {
                                name_function(o, n);
                            }
                            v
                        }
                        None => {
                            if *kind == VarKind::Var {
                                if let Pattern::Ident(n) = p {
                                    if self.lookup_opt(n, env).is_some() {
                                        continue;
                                    }
                                }
                            }
                            Value::Undef
                        }
                    };
                    self.bind_pattern(p, v, env, *kind, true)?;
                }
                Ok(())
            }
            Stmt::Func(_) => Ok(()),
            Stmt::Class(name, e) => {
                let v = self.eval(e, env)?;
                env.borrow_mut().vars.insert(name.clone(), (v, false));
                Ok(())
            }
            Stmt::Return(e) => {
                let v = match e {
                    Some(e) => self.eval(e, env)?,
                    None => Value::Undef,
                };
                Err(Ctl::Return(v))
            }
            Stmt::If(c, a, b) => {
                if self.eval(c, env)?.truthy() {
                    self.exec_scoped(a, env)
                } else if let Some(b) = b {
                    self.exec_scoped(b, env)
                } else {
                    Ok(())
                }
            }
            Stmt::Block(stmts) => {
                let scope = new_scope(Some(env.clone()), false);
                self.hoist(stmts, &scope)?;
                self.exec_stmts(stmts, &scope)
            }
            Stmt::While(c, body) => {
                while self.eval(c, env)?.truthy() {
                    match self.exec_scoped(body, env) {
                        Ok(()) => {}
                        Err(Ctl::Break(None)) => break,
                        Err(Ctl::Continue(None)) => continue,
                        Err(e) => return Err(e),
                    }
                }
                Ok(())
            }
            Stmt::DoWhile(body, c) => {
                loop {
                    match self.exec_scoped(body, env) {
                        Ok(()) => {}
                        Err(Ctl::Break(None)) => break,
                        Err(Ctl::Continue(None)) => {}
                        Err(e) => return Err(e),
                    }
                    if !self.eval(c, env)?.truthy() {
                        break;
                    }
                }
                Ok(())
            }
            Stmt::For(init, test, update, body) => {
                let loop_env = new_scope(Some(env.clone()), false);
                let mut let_names: Vec<Rc<str>> = Vec::new();
                match init {
                    Some(ForInit::Var(k, decls)) => {
                        self.exec(&Stmt::Var(*k, decls.clone()), &loop_env)?;
                        if *k != VarKind::Var {
                            for (p, _) in decls {
                                collect_names(p, &mut let_names);
                            }
                        }
                    }
                    Some(ForInit::Expr(e)) => {
                        self.eval(e, &loop_env)?;
                    }
                    None => {}
                }
                loop {
                    if let Some(t) = test {
                        if !self.eval(t, &loop_env)?.truthy() {
                            break;
                        }
                    }
                    // per-iteration environment copy
                    let iter_env = new_scope(Some(loop_env.clone()), false);
                    for n in &let_names {
                        let v = loop_env.borrow().vars.get(n).cloned();
                        if let Some(v) = v {
                            iter_env.borrow_mut().vars.insert(n.clone(), v);
                        }
                    }
                    let r = self.exec_scoped(body, &iter_env);
                    for n in &let_names {
                        let v = iter_env.borrow().vars.get(n).cloned();
                        if let Some(v) = v {
                            loop_env.borrow_mut().vars.insert(n.clone(), v);
                        }
                    }
                    match r {
                        Ok(()) => {}
                        Err(Ctl::Break(None)) => break,
                        Err(Ctl::Continue(None)) => {}
                        Err(e) => return Err(e),
                    }
                    if let Some(u) = update {
                        self.eval(u, &loop_env)?;
                    }
                }
                Ok(())
            }
            Stmt::ForIn(init, right, body, of) => {
                let rv = self.eval(right, env)?;
                let items: Vec<Value> = if *of {
                    self.iterate(&rv)?
                } else {
                    let mut keys = self.own_keys(&rv);
                    // include inherited enumerable keys from prototypes of plain objects
                    if let Value::Obj(o) = &rv {
                        let mut p = o.borrow().proto.clone();
                        while let Some(pp) = p {
                            if Rc::ptr_eq(&pp, &self.object_proto) || Rc::ptr_eq(&pp, &self.array_proto) || Rc::ptr_eq(&pp, &self.function_proto) {
                                break;
                            }
                            for k in pp.borrow().props.keys() {
                                if !keys.contains(k) && &**k != "constructor" {
                                    keys.push(k.clone());
                                }
                            }
                            p = pp.borrow().proto.clone();
                        }
                    }
                    keys.into_iter().map(Value::Str).collect()
                };
                for it in items {
                    let iter_env = new_scope(Some(env.clone()), false);
                    match init {
                        ForInit::Var(k, decls) => {
                            self.bind_pattern(&decls[0].0, it, &iter_env, *k, true)?;
                        }
                        ForInit::Expr(e) => {
                            let p = expr_to_pattern_rt(e);
                            self.bind_pattern(&p, it, &iter_env, VarKind::Let, false)?;
                        }
                    }
                    match self.exec_scoped(body, &iter_env) {
                        Ok(()) => {}
                        Err(Ctl::Break(None)) => break,
                        Err(Ctl::Continue(None)) => {}
                        Err(e) => return Err(e),
                    }
                }
                Ok(())
            }
            Stmt::Break(l) => Err(Ctl::Break(l.clone())),
            Stmt::Continue(l) => Err(Ctl::Continue(l.clone())),
            Stmt::Throw(e, pos) => {
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                let v = self.eval(e, env)?;
                Err(Ctl::Throw(v))
            }
            Stmt::Try(body, handler, finalizer) => {
                let scope = new_scope(Some(env.clone()), false);
                self.hoist(body, &scope)?;
                let saved_stack = self.stack.len();
                let saved_depth = self.depth;
                let mut r = self.exec_stmts(body, &scope);
                if let Err(Ctl::Throw(exc)) = &r {
                    self.stack.truncate(saved_stack);
                    self.depth = saved_depth;
                    if let Some((param, hbody)) = handler {
                        let hs = new_scope(Some(env.clone()), false);
                        if let Some(p) = param {
                            self.bind_pattern(p, exc.clone(), &hs, VarKind::Let, true)?;
                        }
                        self.hoist(hbody, &hs)?;
                        r = self.exec_stmts(hbody, &hs);
                    }
                }
                if let Some(f) = finalizer {
                    let fs = new_scope(Some(env.clone()), false);
                    self.hoist(f, &fs)?;
                    self.exec_stmts(f, &fs)?;
                }
                r
            }
            Stmt::Switch(d, cases) => {
                let dv = self.eval(d, env)?;
                let scope = new_scope(Some(env.clone()), false);
                let mut matched = None;
                for (i, (t, _)) in cases.iter().enumerate() {
                    if let Some(t) = t {
                        let tv = self.eval(t, &scope)?;
                        if self.strict_eq(&dv, &tv) {
                            matched = Some(i);
                            break;
                        }
                    }
                }
                if matched.is_none() {
                    matched = cases.iter().position(|(t, _)| t.is_none());
                }
                if let Some(start) = matched {
                    for (_, body) in &cases[start..] {
                        match self.exec_stmts(body, &scope) {
                            Ok(()) => {}
                            Err(Ctl::Break(None)) => return Ok(()),
                            Err(e) => return Err(e),
                        }
                    }
                }
                Ok(())
            }
            Stmt::Labeled(label, body) => match self.exec(body, env) {
                Err(Ctl::Break(Some(l))) if &l == label => Ok(()),
                Err(Ctl::Continue(Some(l))) if &l == label => Ok(()),
                r => r,
            },
            Stmt::ExportDefault(e) => {
                let v = self.eval(e, env)?;
                env.borrow_mut().vars.insert(rcs("__export_default"), (v, false));
                Ok(())
            }
            Stmt::ExportDecl(inner) => {
                self.exec(inner, env)?;
                let mut names = Vec::new();
                match &**inner {
                    Stmt::Var(_, decls) => {
                        for (p, _) in decls {
                            collect_names(p, &mut names);
                        }
                    }
                    Stmt::Func(def) => names.push(def.name.clone().unwrap()),
                    Stmt::Class(n, _) => names.push(n.clone()),
                    _ => {}
                }
                let exports = self.lookup_opt("__exports", env);
                if let Some(ex) = exports {
                    for n in names {
                        let v = self.lookup(&n, env)?;
                        self.set(&ex, &n, v)?;
                    }
                }
                Ok(())
            }
            Stmt::ExportNamed(names, from) => {
                let exports = self.lookup_opt("__exports", env);
                let src = match from {
                    Some(f) => Some(self.require(f)?),
                    None => None,
                };
                if let Some(ex) = exports {
                    for (local, exported) in names {
                        let v = match &src {
                            Some(m) => self.get(m, local)?,
                            None => self.lookup(local, env)?,
                        };
                        if &**exported == "default" {
                            env.borrow_mut().vars.insert(rcs("__export_default"), (v.clone(), false));
                        }
                        self.set(&ex, exported, v)?;
                    }
                }
                Ok(())
            }
            Stmt::Import(default, ns, named, src) => {
                let m = self.require(src)?;
                if let Some(d) = default {
                    let dv = self.get(&m, "default")?;
                    let dv = if dv.is_undef() { m.clone() } else { dv };
                    env.borrow_mut().vars.insert(d.clone(), (dv, true));
                }
                if let Some(n) = ns {
                    env.borrow_mut().vars.insert(n.clone(), (m.clone(), true));
                }
                for (imp, local) in named {
                    let v = self.get(&m, imp)?;
                    env.borrow_mut().vars.insert(local.clone(), (v, true));
                }
                Ok(())
            }
        }
    }

    fn exec_scoped(&mut self, s: &Stmt, env: &Env) -> R<()> {
        match s {
            Stmt::Var(VarKind::Let, _) | Stmt::Var(VarKind::Const, _) => {
                let scope = new_scope(Some(env.clone()), false);
                self.exec(s, &scope)
            }
            _ => self.exec(s, env),
        }
    }

    // ---------- expressions ----------
    pub fn eval(&mut self, e: &Expr, env: &Env) -> R<Value> {
        match e {
            Expr::Num(n) => Ok(Value::Num(*n)),
            Expr::Str(s) => Ok(Value::Str(s.clone())),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Null => Ok(Value::Null),
            Expr::This => Ok(self.this_value(env)),
            Expr::Template(quasis, exprs) => {
                let mut s = String::new();
                for (i, q) in quasis.iter().enumerate() {
                    s.push_str(q);
                    if let Some(e) = exprs.get(i) {
                        let v = self.eval(e, env)?;
                        s.push_str(&self.to_string(&v)?);
                    }
                }
                Ok(Value::str(&s))
            }
            Expr::Tagged(tag, cooked, raw, exprs) => {
                let (f, this) = self.eval_callee(tag, env)?;
                let strings = self.new_array(cooked.iter().map(|s| Value::Str(s.clone())).collect());
                let raws = self.new_array(raw.iter().map(|s| Value::Str(s.clone())).collect());
                if let Value::Obj(o) = &strings {
                    o.borrow_mut().props.insert(rcs("raw"), raws);
                }
                let mut args = vec![strings];
                for e in exprs {
                    args.push(self.eval(e, env)?);
                }
                self.call(&f, this, args)
            }
            Expr::Regex(s, f) => Ok(self.new_regexp(s, f)),
            Expr::Ident(name, pos) => {
                if &**name == "undefined" {
                    if let Some(v) = self.lookup_opt(name, env) {
                        return Ok(v);
                    }
                    return Ok(Value::Undef);
                }
                match self.lookup_opt(name, env) {
                    Some(v) => Ok(v),
                    None => {
                        self.cur_line = pos.line;
                        self.cur_col = pos.col;
                        Err(throw_error(self, "ReferenceError", &format!("'{}' is not defined", name)))
                    }
                }
            }
            Expr::Array(elems) => {
                let mut out = Vec::new();
                for el in elems {
                    match el {
                        None => out.push(Value::Undef),
                        Some(Expr::Spread(inner)) => {
                            let v = self.eval(inner, env)?;
                            out.extend(self.iterate(&v)?);
                        }
                        Some(e) => out.push(self.eval(e, env)?),
                    }
                }
                Ok(self.new_array(out))
            }
            Expr::Spread(_) => Err(throw_error(self, "SyntaxError", "unexpected spread")),
            Expr::Object(props) => {
                let obj = self.new_object();
                for p in props {
                    match p {
                        PropDef::KeyValue(k, v) => {
                            let key = self.prop_key(k, env)?;
                            let val = self.eval(v, env)?;
                            if let Value::Obj(o) = &val {
                                if matches!(v, Expr::Function(_) | Expr::Class(..)) {
                                    name_function(o, &key);
                                }
                            }
                            if let Value::Obj(o) = &obj {
                                o.borrow_mut().props.insert(key, val);
                            }
                        }
                        PropDef::Shorthand(n) => {
                            let val = self.lookup(n, env)?;
                            if let Value::Obj(o) = &obj {
                                o.borrow_mut().props.insert(n.clone(), val);
                            }
                        }
                        PropDef::Spread(e) => {
                            let src = self.eval(e, env)?;
                            if !src.is_nullish() {
                                for k in self.own_keys(&src) {
                                    let v = self.get(&src, &k)?;
                                    if let Value::Obj(o) = &obj {
                                        o.borrow_mut().props.insert(k, v);
                                    }
                                }
                            }
                        }
                        PropDef::Getter(k, f) | PropDef::Setter(k, f) => {
                            let key = self.prop_key(k, env)?;
                            let fv = self.make_closure(f, env);
                            let is_set = matches!(p, PropDef::Setter(..));
                            if let Value::Obj(o) = &obj {
                                let mut b = o.borrow_mut();
                                let g = b.getters.get_or_insert_with(HashMap::new);
                                if is_set {
                                    g.insert(rcs(&format!("set {}", key)), fv);
                                } else {
                                    g.insert(key, fv);
                                }
                            }
                        }
                    }
                }
                Ok(obj)
            }
            Expr::Function(def) => Ok(self.make_closure(def, env)),
            Expr::Class(name, sup, members) => self.eval_class(name, sup, members, env),
            Expr::Unary(op, inner) => {
                if *op == "typeof" {
                    if let Expr::Ident(n, _) = &**inner {
                        if self.lookup_opt(n, env).is_none() {
                            return Ok(Value::str("undefined"));
                        }
                    }
                    let v = self.eval(inner, env)?;
                    return Ok(Value::str(self.typeof_(&v)));
                }
                if *op == "delete" {
                    match &**inner {
                        Expr::Member(o, name, _, _) => {
                            let ov = self.eval(o, env)?;
                            if let Value::Obj(o) = ov {
                                o.borrow_mut().props.shift_remove(&**name);
                            }
                        }
                        Expr::Index(o, idx, _, _) => {
                            let ov = self.eval(o, env)?;
                            let k = self.eval(idx, env)?;
                            let k = self.to_key(&k)?;
                            if let Value::Obj(o) = ov {
                                let mut b = o.borrow_mut();
                                if let Kind::Array(items) = &mut b.kind {
                                    if let Ok(i) = k.parse::<usize>() {
                                        if i < items.len() {
                                            items[i] = Value::Undef;
                                        }
                                    }
                                }
                                b.props.shift_remove(&*k);
                            }
                        }
                        _ => {}
                    }
                    return Ok(Value::Bool(true));
                }
                let v = self.eval(inner, env)?;
                Ok(match *op {
                    "!" => Value::Bool(!v.truthy()),
                    "-" => Value::Num(-self.to_number(&v)?),
                    "+" => Value::Num(self.to_number(&v)?),
                    "~" => Value::Num(!(to_int32(self.to_number(&v)?)) as f64),
                    "void" => Value::Undef,
                    _ => Value::Undef,
                })
            }
            Expr::Update(op, prefix, target) => {
                let old = self.eval(target, env)?;
                let n = self.to_number(&old)?;
                let nv = if *op == "++" { n + 1.0 } else { n - 1.0 };
                self.assign_to_expr(target, Value::Num(nv), env)?;
                Ok(Value::Num(if *prefix { nv } else { n }))
            }
            Expr::Binary(op, l, r) => {
                let lv = self.eval(l, env)?;
                let rv = self.eval(r, env)?;
                self.binary(op, &lv, &rv)
            }
            Expr::Logical(op, l, r) => {
                let lv = self.eval(l, env)?;
                match *op {
                    "&&" => {
                        if lv.truthy() {
                            self.eval(r, env)
                        } else {
                            Ok(lv)
                        }
                    }
                    "||" => {
                        if lv.truthy() {
                            Ok(lv)
                        } else {
                            self.eval(r, env)
                        }
                    }
                    _ => {
                        if lv.is_nullish() {
                            self.eval(r, env)
                        } else {
                            Ok(lv)
                        }
                    }
                }
            }
            Expr::Cond(c, a, b) => {
                if self.eval(c, env)?.truthy() {
                    self.eval(a, env)
                } else {
                    self.eval(b, env)
                }
            }
            Expr::Assign(op, target, value) => {
                if *op == "=" {
                    let v = self.eval(value, env)?;
                    if let (Pattern::Ident(n), Value::Obj(o)) = (&**target, &v) {
                        if matches!(&**value, Expr::Function(_)) {
                            name_function(o, n);
                        }
                    }
                    self.bind_pattern(target, v.clone(), env, VarKind::Let, false)?;
                    return Ok(v);
                }
                let te = match &**target {
                    Pattern::Expr(e) => e.clone(),
                    Pattern::Ident(n) => Box::new(Expr::Ident(n.clone(), Pos { line: 0, col: 0 })),
                    _ => return Err(throw_error(self, "SyntaxError", "invalid assignment")),
                };
                let old = self.eval(&te, env)?;
                let nv = match *op {
                    "&&" => {
                        if !old.truthy() {
                            return Ok(old);
                        }
                        self.eval(value, env)?
                    }
                    "||" => {
                        if old.truthy() {
                            return Ok(old);
                        }
                        self.eval(value, env)?
                    }
                    "??" => {
                        if !old.is_nullish() {
                            return Ok(old);
                        }
                        self.eval(value, env)?
                    }
                    _ => {
                        let rv = self.eval(value, env)?;
                        self.binary(op, &old, &rv)?
                    }
                };
                self.assign_to_expr(&te, nv.clone(), env)?;
                Ok(nv)
            }
            Expr::Seq(es) => {
                let mut last = Value::Undef;
                for e in es {
                    last = self.eval(e, env)?;
                }
                Ok(last)
            }
            Expr::Member(obj, name, optional, pos) => {
                let o = self.eval(obj, env)?;
                if *optional && o.is_nullish() {
                    return Ok(Value::Undef);
                }
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                self.get(&o, name)
            }
            Expr::Index(obj, idx, optional, pos) => {
                let o = self.eval(obj, env)?;
                if *optional && o.is_nullish() {
                    return Ok(Value::Undef);
                }
                let k = self.eval(idx, env)?;
                let k = self.to_key(&k)?;
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                self.get(&o, &k)
            }
            Expr::Call(callee, args, optional, pos) => {
                let (f, this) = self.eval_callee(callee, env)?;
                if *optional && f.is_nullish() {
                    return Ok(Value::Undef);
                }
                let argv = self.eval_args(args, env)?;
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                if !f.is_function() {
                    let name = callee_name(callee);
                    return Err(self.type_error(&format!("{} is not a function", name)));
                }
                self.call(&f, this, argv)
            }
            Expr::New(callee, args, pos) => {
                let f = self.eval(callee, env)?;
                let argv = self.eval_args(args, env)?;
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                if !f.is_function() {
                    let name = callee_name(callee);
                    return Err(self.type_error(&format!("{} is not a constructor", name)));
                }
                self.construct(&f, argv)
            }
        }
    }

    fn prop_key(&mut self, k: &PropKey, env: &Env) -> R<Rc<str>> {
        match k {
            PropKey::Static(s) => Ok(s.clone()),
            PropKey::Computed(e) => {
                let v = self.eval(e, env)?;
                self.to_key(&v)
            }
        }
    }

    fn eval_args(&mut self, args: &[Expr], env: &Env) -> R<Vec<Value>> {
        let mut out = Vec::new();
        for a in args {
            if let Expr::Spread(inner) = a {
                let v = self.eval(inner, env)?;
                out.extend(self.iterate(&v)?);
            } else {
                out.push(self.eval(a, env)?);
            }
        }
        Ok(out)
    }

    fn eval_callee(&mut self, callee: &Expr, env: &Env) -> R<(Value, Value)> {
        match callee {
            Expr::Member(obj, name, optional, pos) => {
                let o = self.eval(obj, env)?;
                if *optional && o.is_nullish() {
                    return Ok((Value::Undef, Value::Undef));
                }
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                if let Expr::Ident(n, _) = &**obj {
                    if &**n == "super" {
                        let this = self.this_value(env);
                        let f = self.get(&o, name)?;
                        return Ok((f, this));
                    }
                }
                let f = self.get(&o, name)?;
                Ok((f, o))
            }
            Expr::Index(obj, idx, optional, pos) => {
                let o = self.eval(obj, env)?;
                if *optional && o.is_nullish() {
                    return Ok((Value::Undef, Value::Undef));
                }
                let k = self.eval(idx, env)?;
                let k = self.to_key(&k)?;
                self.cur_line = pos.line;
                self.cur_col = pos.col;
                let f = self.get(&o, &k)?;
                Ok((f, o))
            }
            Expr::Ident(n, _) if &**n == "super" => {
                let f = self.lookup(n, env)?;
                let this = self.this_value(env);
                Ok((f, this))
            }
            _ => Ok((self.eval(callee, env)?, Value::Undef)),
        }
    }

    fn eval_class(&mut self, name: &Option<Rc<str>>, sup: &Option<Box<Expr>>, members: &[(bool, PropKey, ClassMember)], env: &Env) -> R<Value> {
        let super_v = match sup {
            Some(s) => Some(self.eval(s, env)?),
            None => None,
        };
        let cenv = new_scope(Some(env.clone()), false);
        // constructor
        let mut ctor_def = None;
        for (st, k, m) in members {
            if let (false, PropKey::Static(n), ClassMember::Method(f)) = (st, k, m) {
                if &**n == "constructor" {
                    ctor_def = Some(f.clone());
                }
            }
        }
        let ctor_def = match ctor_def {
            Some(d) => Rc::new(FuncDef { name: name.clone(), ..(*d).clone() }),
            None => {
                // default constructor: calls super(...args)
                let body = if super_v.is_some() {
                    vec![Stmt::Expr(Expr::Call(
                        Box::new(Expr::Ident(rcs("super"), Pos { line: 0, col: 0 })),
                        vec![Expr::Spread(Box::new(Expr::Ident(rcs("arguments"), Pos { line: 0, col: 0 })))],
                        false,
                        Pos { line: 0, col: 0 },
                    ))]
                } else {
                    vec![]
                };
                Rc::new(FuncDef { name: name.clone(), params: vec![], body: FuncBody::Block(body), is_arrow: false, line: 0, col: 0 })
            }
        };
        let ctor = self.make_closure(&ctor_def, &cenv);
        let proto = self.new_object();
        if let Value::Obj(co) = &ctor {
            co.borrow_mut().class_name = Some(rcs("__class"));
            co.borrow_mut().props.insert(rcs("prototype"), proto.clone());
        }
        if let Value::Obj(po) = &proto {
            po.borrow_mut().props.insert(rcs("constructor"), ctor.clone());
        }
        if let Some(sv) = &super_v {
            let sp = self.get(sv, "prototype")?;
            if let (Value::Obj(po), Value::Obj(spo)) = (&proto, &sp) {
                po.borrow_mut().proto = Some(spo.clone());
            }
            if let (Value::Obj(co), Value::Obj(so)) = (&ctor, sv) {
                co.borrow_mut().proto = Some(so.clone());
            }
            // super binding: calling super(...) initializes this via parent constructor
            let sv2 = sv.clone();
            let superf = native!(self, "super", move |it: &mut Interp, this: Value, args: Vec<Value>| {
                let is_native = matches!(&sv2.as_obj().unwrap().borrow().kind, Kind::Function(Func::Native { .. }));
                if is_native {
                    let r = it.call(&sv2, Value::Null, args)?;
                    // copy props
                    for k in it.own_keys(&r) {
                        let v = it.get(&r, &k)?;
                        it.set(&this, &k, v)?;
                    }
                    return Ok(Value::Undef);
                }
                it.init_class_fields(&sv2, &this)?;
                it.call(&sv2, this, args)?;
                Ok(Value::Undef)
            });
            // `super.method` access: make super an object whose props come from parent prototype
            if let Value::Obj(so) = &superf {
                if let Value::Obj(spo) = &sp {
                    so.borrow_mut().proto = Some(spo.clone());
                }
            }
            cenv.borrow_mut().vars.insert(rcs("super"), (superf, true));
        }
        let mut fields = Vec::new();
        for (st, k, m) in members {
            let key = self.prop_key(k, &cenv)?;
            let target = if *st { ctor.clone() } else { proto.clone() };
            match m {
                ClassMember::Method(f) => {
                    if !*st && &*key == "constructor" {
                        continue;
                    }
                    let fv = self.make_closure(f, &cenv);
                    if let Value::Obj(t) = &target {
                        t.borrow_mut().props.insert(key, fv);
                    }
                }
                ClassMember::Getter(f) | ClassMember::Setter(f) => {
                    let fv = self.make_closure(f, &cenv);
                    let is_set = matches!(m, ClassMember::Setter(_));
                    if let Value::Obj(t) = &target {
                        let mut b = t.borrow_mut();
                        let g = b.getters.get_or_insert_with(HashMap::new);
                        if is_set {
                            g.insert(rcs(&format!("set {}", key)), fv);
                        } else {
                            g.insert(key, fv);
                        }
                    }
                }
                ClassMember::Field(init) => {
                    if *st {
                        let v = match init {
                            Some(e) => self.eval(e, &cenv)?,
                            None => Value::Undef,
                        };
                        self.set(&ctor, &key, v)?;
                    } else {
                        let initf = match init {
                            Some(e) => {
                                let def = Rc::new(FuncDef { name: None, params: vec![], body: FuncBody::Expr(Box::new(e.clone())), is_arrow: false, line: 0, col: 0 });
                                self.make_closure(&def, &cenv)
                            }
                            None => Value::Undef,
                        };
                        fields.push(self.new_array(vec![Value::Str(key), initf]));
                    }
                }
            }
        }
        let fa = self.new_array(fields);
        if let Value::Obj(co) = &ctor {
            co.borrow_mut().props.insert(rcs("__fields"), fa);
        }
        if let Some(n) = name {
            cenv.borrow_mut().vars.insert(n.clone(), (ctor.clone(), true));
        }
        Ok(ctor)
    }

    pub fn binary(&mut self, op: &str, l: &Value, r: &Value) -> R<Value> {
        Ok(match op {
            "+" => {
                let lp = self.to_primitive(l)?;
                let rp = self.to_primitive(r)?;
                if matches!(lp, Value::Str(_)) || matches!(rp, Value::Str(_)) {
                    let a = self.to_string(&lp)?;
                    let b = self.to_string(&rp)?;
                    let mut s = String::with_capacity(a.len() + b.len());
                    s.push_str(&a);
                    s.push_str(&b);
                    Value::str(&s)
                } else {
                    Value::Num(self.to_number(&lp)? + self.to_number(&rp)?)
                }
            }
            "-" => Value::Num(self.to_number(l)? - self.to_number(r)?),
            "*" => Value::Num(self.to_number(l)? * self.to_number(r)?),
            "/" => Value::Num(self.to_number(l)? / self.to_number(r)?),
            "%" => Value::Num(self.to_number(l)? % self.to_number(r)?),
            "**" => Value::Num(self.to_number(l)?.powf(self.to_number(r)?)),
            "==" => Value::Bool(self.loose_eq(l, r)?),
            "!=" => Value::Bool(!self.loose_eq(l, r)?),
            "===" => Value::Bool(self.strict_eq(l, r)),
            "!==" => Value::Bool(!self.strict_eq(l, r)),
            "<" | ">" | "<=" | ">=" => {
                let lp = self.to_primitive(l)?;
                let rp = self.to_primitive(r)?;
                if let (Value::Str(a), Value::Str(b)) = (&lp, &rp) {
                    let a16: Vec<u16> = a.encode_utf16().collect();
                    let b16: Vec<u16> = b.encode_utf16().collect();
                    Value::Bool(match op {
                        "<" => a16 < b16,
                        ">" => a16 > b16,
                        "<=" => a16 <= b16,
                        _ => a16 >= b16,
                    })
                } else {
                    let a = self.to_number(&lp)?;
                    let b = self.to_number(&rp)?;
                    Value::Bool(match op {
                        "<" => a < b,
                        ">" => a > b,
                        "<=" => a <= b,
                        _ => a >= b,
                    })
                }
            }
            "&" => Value::Num((to_int32(self.to_number(l)?) & to_int32(self.to_number(r)?)) as f64),
            "|" => Value::Num((to_int32(self.to_number(l)?) | to_int32(self.to_number(r)?)) as f64),
            "^" => Value::Num((to_int32(self.to_number(l)?) ^ to_int32(self.to_number(r)?)) as f64),
            "<<" => Value::Num((to_int32(self.to_number(l)?).wrapping_shl(to_int32(self.to_number(r)?) as u32 & 31)) as f64),
            ">>" => Value::Num((to_int32(self.to_number(l)?) >> (to_int32(self.to_number(r)?) as u32 & 31)) as f64),
            ">>>" => Value::Num(((to_int32(self.to_number(l)?) as u32) >> (to_int32(self.to_number(r)?) as u32 & 31)) as f64),
            "instanceof" => Value::Bool(self.instance_of(l, r)?),
            "in" => {
                let k = self.to_key(l)?;
                match r {
                    Value::Obj(o) => {
                        let b = o.borrow();
                        let has = match &b.kind {
                            Kind::Array(items) => k.parse::<usize>().map_or(false, |i| i < items.len()) || &*k == "length",
                            Kind::RuleBuilder(Some(rules)) => rules.contains(&*k),
                            _ => false,
                        };
                        if has || b.props.contains_key(&*k) {
                            Value::Bool(true)
                        } else {
                            drop(b);
                            let v = self.get(r, &k)?;
                            Value::Bool(!v.is_undef())
                        }
                    }
                    _ => return Err(self.type_error("invalid 'in' operand")),
                }
            }
            _ => Value::Undef,
        })
    }

    // ---------- modules ----------
    pub fn require(&mut self, spec: &str) -> R<Value> {
        let path = match self.resolve_module(spec) {
            Some(p) => p,
            None => {
                return Err(throw_error(self, "ReferenceError", &format!("could not load module '{}'", spec)));
            }
        };
        if let Some(v) = self.module_cache.get(&path) {
            return Ok(v.clone());
        }
        let src = match std::fs::read_to_string(&path) {
            Ok(s) => s,
            Err(_) => return Err(throw_error(self, "ReferenceError", &format!("could not load module '{}'", spec))),
        };
        if path.extension().map_or(false, |e| e == "json") {
            let v = super::builtins::json_parse(self, &src)?;
            self.module_cache.insert(path, v.clone());
            return Ok(v);
        }
        let saved_dir = self.base_dir.clone();
        let saved_file = self.cur_file.clone();
        self.base_dir = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        let fname = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
        self.cur_file = rcs(&fname);
        let r = self.eval_module_source(&src, &fname);
        self.base_dir = saved_dir;
        self.cur_file = saved_file;
        let v = r?;
        self.module_cache.insert(path, v.clone());
        Ok(v)
    }

    fn resolve_module(&self, spec: &str) -> Option<PathBuf> {
        let try_file = |p: &Path| -> Option<PathBuf> {
            if p.is_file() {
                return Some(p.to_path_buf());
            }
            for ext in ["js", "cjs", "mjs", "json"] {
                let q = PathBuf::from(format!("{}.{}", p.display(), ext));
                if q.is_file() {
                    return Some(q);
                }
            }
            if p.is_dir() {
                let pj = p.join("package.json");
                if let Ok(s) = std::fs::read_to_string(&pj) {
                    if let Ok(v) = serde_json::from_str::<serde_json::Value>(&s) {
                        if let Some(m) = v.get("main").and_then(|m| m.as_str()) {
                            let q = p.join(m);
                            if q.is_file() {
                                return Some(q);
                            }
                            for ext in ["js", "cjs", "mjs"] {
                                let q2 = PathBuf::from(format!("{}.{}", q.display(), ext));
                                if q2.is_file() {
                                    return Some(q2);
                                }
                            }
                        }
                    }
                }
                for f in ["index.js", "index.cjs", "index.mjs", "index.json"] {
                    let q = p.join(f);
                    if q.is_file() {
                        return Some(q);
                    }
                }
            }
            None
        };
        if spec.starts_with("./") || spec.starts_with("../") || spec.starts_with('/') || spec == "." || spec == ".." {
            let p = self.base_dir.join(spec);
            return try_file(&p);
        }
        // node_modules lookup
        let mut dir = Some(self.base_dir.clone());
        while let Some(d) = dir {
            let p = d.join("node_modules").join(spec);
            if let Some(f) = try_file(&p) {
                return Some(f);
            }
            dir = d.parent().map(|p| p.to_path_buf());
        }
        None
    }

    pub fn eval_module_source(&mut self, src: &str, fname: &str) -> R<Value> {
        let chars: Vec<char> = src.chars().collect();
        let toks = match super::lexer::Lexer::new(&chars).tokenize() {
            Ok(t) => t,
            Err((msg, line, col)) => {
                self.cur_line = line;
                self.cur_col = col;
                let mut e = self.make_error("SyntaxError", &msg);
                set_syntax_stack(&mut e, fname, line, col);
                return Err(Ctl::Throw(e));
            }
        };
        let stmts = match super::parser::Parser::new(toks).parse_program() {
            Ok(s) => s,
            Err((msg, line, col)) => {
                self.cur_line = line;
                self.cur_col = col;
                let mut e = self.make_error("SyntaxError", &msg);
                set_syntax_stack(&mut e, fname, line, col);
                return Err(Ctl::Throw(e));
            }
        };
        let env = new_scope(Some(self.global.clone()), true);
        let module = self.new_object();
        let exports = self.new_object();
        self.set(&module, "exports", exports.clone())?;
        env.borrow_mut().vars.insert(rcs("module"), (module.clone(), false));
        env.borrow_mut().vars.insert(rcs("exports"), (exports.clone(), false));
        env.borrow_mut().vars.insert(rcs("__exports"), (exports.clone(), false));
        env.borrow_mut().this_val = Some(Value::Undef);
        let dir = self.base_dir.to_string_lossy().to_string();
        env.borrow_mut().vars.insert(rcs("__dirname"), (Value::str(&dir), false));
        env.borrow_mut().vars.insert(rcs("__filename"), (Value::str(&format!("{}/{}", dir, fname)), false));
        self.hoist(&stmts, &env)?;
        let saved_line = self.cur_line;
        for s in &stmts {
            self.exec(s, &env)?;
        }
        self.cur_line = saved_line;
        let def = env.borrow().vars.get("__export_default").map(|v| v.0.clone());
        let mexports = self.get(&module, "exports")?;
        if let Some(d) = def {
            // ES module: namespace object with default
            if let Value::Obj(o) = &mexports {
                o.borrow_mut().props.insert(rcs("default"), d.clone());
            }
            return Ok(mexports);
        }
        Ok(mexports)
    }
}

fn set_syntax_stack(e: &mut Value, fname: &str, line: u32, col: u32) {
    if let Value::Obj(o) = e {
        o.borrow_mut().props.insert(rcs("stack"), Value::str(&format!("    at {}:{}:{}\n", fname, line, col)));
    }
}

pub fn is_array_index(k: &str) -> bool {
    !k.is_empty() && k.len() < 10 && k.bytes().all(|b| b.is_ascii_digit()) && (k == "0" || !k.starts_with('0'))
}

pub fn name_function(o: &Obj, name: &str) {
    let mut b = o.borrow_mut();
    if let Kind::Function(Func::Closure { def, .. }) = &mut b.kind {
        if def.name.is_none() {
            let mut d = (**def).clone();
            d.name = Some(rcs(name));
            *def = Rc::new(d);
        }
    }
}

fn collect_names(p: &Pattern, out: &mut Vec<Rc<str>>) {
    match p {
        Pattern::Ident(n) => out.push(n.clone()),
        Pattern::Array(elems, rest) => {
            for e in elems.iter().flatten() {
                collect_names(&e.0, out);
            }
            if let Some(r) = rest {
                collect_names(r, out);
            }
        }
        Pattern::Object(props, rest) => {
            for (_, p, _) in props {
                collect_names(p, out);
            }
            if let Some(r) = rest {
                collect_names(r, out);
            }
        }
        Pattern::Expr(_) => {}
    }
}

fn expr_to_pattern_rt(e: &Expr) -> Pattern {
    match e {
        Expr::Ident(n, _) => Pattern::Ident(n.clone()),
        _ => Pattern::Expr(Box::new(e.clone())),
    }
}

fn callee_name(e: &Expr) -> String {
    match e {
        Expr::Ident(n, _) => n.to_string(),
        Expr::Member(_, n, _, _) => n.to_string(),
        _ => "value".to_string(),
    }
}

pub fn to_int32(n: f64) -> i32 {
    if n.is_nan() || n.is_infinite() {
        return 0;
    }
    let m = n.trunc() % 4294967296.0;
    let m = if m < 0.0 { m + 4294967296.0 } else { m };
    (m as u64 as u32) as i32
}

pub fn str_to_num(s: &str) -> f64 {
    let t = s.trim();
    if t.is_empty() {
        return 0.0;
    }
    if let Some(h) = t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        return i64::from_str_radix(h, 16).map(|v| v as f64).unwrap_or(f64::NAN);
    }
    if let Some(h) = t.strip_prefix("0b").or_else(|| t.strip_prefix("0B")) {
        return i64::from_str_radix(h, 2).map(|v| v as f64).unwrap_or(f64::NAN);
    }
    if let Some(h) = t.strip_prefix("0o").or_else(|| t.strip_prefix("0O")) {
        return i64::from_str_radix(h, 8).map(|v| v as f64).unwrap_or(f64::NAN);
    }
    match t {
        "Infinity" | "+Infinity" => return f64::INFINITY,
        "-Infinity" => return f64::NEG_INFINITY,
        _ => {}
    }
    if t.chars().all(|c| c.is_ascii_digit() || matches!(c, '.' | 'e' | 'E' | '+' | '-')) {
        t.parse::<f64>().unwrap_or(f64::NAN)
    } else {
        f64::NAN
    }
}

