        Ok(Value::Num(if n > 0.0 { 1.0 } else if n < 0.0 { -1.0 } else { n }))
    });
    def(it, &math, "sqrt", |it, _, a| Ok(Value::Num(it.to_number(&arg(&a, 0))?.sqrt())));
    def(it, &math, "log", |it, _, a| Ok(Value::Num(it.to_number(&arg(&a, 0))?.ln())));
    def(it, &math, "log2", |it, _, a| Ok(Value::Num(it.to_number(&arg(&a, 0))?.log2())));
    def(it, &math, "log10", |it, _, a| Ok(Value::Num(it.to_number(&arg(&a, 0))?.log10())));
    def(it, &math, "pow", |it, _, a| {
        let x = it.to_number(&arg(&a, 0))?;
        let y = it.to_number(&arg(&a, 1))?;
        Ok(Value::Num(x.powf(y)))
    });
    def(it, &math, "random", |_, _, _| Ok(Value::Num(0.5)));
    def(it, &math, "max", |it, _, a| {
        let mut m = f64::NEG_INFINITY;
        for x in &a {
            let n = it.to_number(x)?;
            if n.is_nan() {
                return Ok(Value::Num(f64::NAN));
            }
            if n > m {
                m = n;
            }
        }
        Ok(Value::Num(m))
    });
    def(it, &math, "min", |it, _, a| {
        let mut m = f64::INFINITY;
        for x in &a {
            let n = it.to_number(x)?;
            if n.is_nan() {
                return Ok(Value::Num(f64::NAN));
            }
            if n < m {
                m = n;
            }
        }
        Ok(Value::Num(m))
    });
    global(it, "Math", math);

    // JSON
    let json = it.new_object();
    def(it, &json, "stringify", |it, _, a| {
        let v = arg(&a, 0);
        let indent = match arg(&a, 2) {
            Value::Num(n) => " ".repeat(n.max(0.0).min(10.0) as usize),
            Value::Str(s) => s.to_string(),
            _ => String::new(),
        };
        let mut out = String::new();
        let ok = json_stringify(it, &v, &indent, "", &mut out)?;
        if !ok {
            return Ok(Value::Undef);
        }
        Ok(Value::str(&out))
    });
    def(it, &json, "parse", |it, _, a| {
        let s = it.to_string(&arg(&a, 0))?;
        json_parse(it, &s)
    });
    global(it, "JSON", json);

    // RegExp
    let regexp = it.native_ctor("RegExp", Rc::new(|it: &mut Interp, _, args| {
        let p = arg(&args, 0);
        let (src, mut flags) = match &p {
            Value::Obj(o) => match &o.borrow().kind {
                Kind::RegExp(s, f) => (s.to_string(), f.to_string()),
                _ => (String::new(), String::new()),
            },
            _ => (String::new(), String::new()),
        };
        let src = if p.is_regexp() {
            src
        } else if p.is_undef() {
            "(?:)".to_string()
        } else {
            let s = it.to_string(&p)?.to_string();
            escape_regex_source(&s)
        };
        let f = arg(&args, 1);
        if !f.is_undef() {
            flags = it.to_string(&f)?.to_string();
        }
        Ok(it.new_regexp(&src, &flags))
    }));
    let rp = it.new_object();
    def(it, &rp, "test", |it, this, a| {
        let s = it.to_string(&arg(&a, 0))?;
        let re = compile_regex(it, &this)?;
        Ok(Value::Bool(re.is_match(&s)))
    });
    def(it, &rp, "exec", |it, this, a| {
        let s = it.to_string(&arg(&a, 0))?;
        let re = compile_regex(it, &this)?;
        Ok(match re.captures(&s) {
            Some(c) => match_result(it, &c, &s),
            None => Value::Null,
        })
    });
    def(it, &rp, "toString", |it, this, _| Ok(Value::str(&it.default_to_string(&this)?)));
    setp(&regexp, "prototype", rp.clone());
    setp(&rp, "constructor", regexp.clone());
    global(it, "RegExp", regexp);

    // Map / Set
    let map = it.native_ctor("Map", Rc::new(|it: &mut Interp, _, args| {
        let mut items = Vec::new();
        let init = arg(&args, 0);
        if !init.is_nullish() {
            for e in it.iterate(&init)? {
                let k = it.get(&e, "0")?;
                let v = it.get(&e, "1")?;
                items.push((k, v));
            }
        }
        let mp = it.lookup("Map", &it.global.clone())?;
        let proto = it.get(&mp, "prototype")?;
        let mut d = ObjData::new(Kind::Map(Vec::new()));
        d.proto = proto.as_obj().cloned();
        let o = Value::Obj(Rc::new(RefCell::new(d)));
        for (k, v) in items {
            map_set(it, &o, k, v);
        }
        Ok(o)
    }));
    let mproto = it.new_object();
    def(it, &mproto, "get", |it, this, a| Ok(map_get(it, &this, &arg(&a, 0)).unwrap_or(Value::Undef)));
    def(it, &mproto, "has", |it, this, a| Ok(Value::Bool(map_get(it, &this, &arg(&a, 0)).is_some())));
    def(it, &mproto, "set", |it, this, a| {
        map_set(it, &this, arg(&a, 0), arg(&a, 1));
        Ok(this)
    });
    def(it, &mproto, "delete", |it, this, a| {
        let k = arg(&a, 0);
        if let Value::Obj(o) = &this {
            if let Kind::Map(items) = &mut o.borrow_mut().kind {
                if let Some(i) = items.iter().position(|(x, _)| it.same_value_zero(x, &k)) {
                    items.remove(i);
                    return Ok(Value::Bool(true));
                }
            }
        }
        Ok(Value::Bool(false))
    });
    def(it, &mproto, "keys", |it, this, _| {
        let v = match &this {
            Value::Obj(o) => match &o.borrow().kind {
                Kind::Map(items) => items.iter().map(|x| x.0.clone()).collect(),
                _ => vec![],
            },
            _ => vec![],
        };
        Ok(it.new_array(v))
    });
    def(it, &mproto, "values", |it, this, _| {
        let v = match &this {
            Value::Obj(o) => match &o.borrow().kind {
                Kind::Map(items) => items.iter().map(|x| x.1.clone()).collect(),
                _ => vec![],
            },
            _ => vec![],
        };
        Ok(it.new_array(v))
    });
    def(it, &mproto, "entries", |it, this, _| {
        let v = it.iterate(&this)?;
        Ok(it.new_array(v))
    });
    def(it, &mproto, "forEach", |it, this, a| {
        let f = arg(&a, 0);
        let items = match &this {
            Value::Obj(o) => match &o.borrow().kind {
                Kind::Map(items) => items.clone(),
                _ => vec![],
            },
            _ => vec![],
        };
        for (k, v) in items {
            it.call(&f, Value::Undef, vec![v, k, this.clone()])?;
        }
        Ok(Value::Undef)
    });
    setp(&map, "prototype", mproto);
    global(it, "Map", map);
    let set = it.native_ctor("Set", Rc::new(|it: &mut Interp, _, args| {
        let init = arg(&args, 0);
        let sp = it.lookup("Set", &it.global.clone())?;
        let proto = it.get(&sp, "prototype")?;
        let mut d = ObjData::new(Kind::Set(Vec::new()));
        d.proto = proto.as_obj().cloned();
        let o = Value::Obj(Rc::new(RefCell::new(d)));
        if !init.is_nullish() {
            for e in it.iterate(&init)? {
                set_add(it, &o, e);
            }
        }
        Ok(o)
    }));
    let sproto = it.new_object();
    def(it, &sproto, "add", |it, this, a| {
        set_add(it, &this, arg(&a, 0));
        Ok(this)
    });
    def(it, &sproto, "has", |it, this, a| {
        let k = arg(&a, 0);
        if let Value::Obj(o) = &this {
            if let Kind::Set(items) = &o.borrow().kind {
                return Ok(Value::Bool(items.iter().any(|x| it.same_value_zero(x, &k))));
            }
        }
        Ok(Value::Bool(false))
    });
    def(it, &sproto, "delete", |it, this, a| {
        let k = arg(&a, 0);
        if let Value::Obj(o) = &this {
            if let Kind::Set(items) = &mut o.borrow_mut().kind {
                if let Some(i) = items.iter().position(|x| it.same_value_zero(x, &k)) {
                    items.remove(i);
                    return Ok(Value::Bool(true));
                }
            }
        }
        Ok(Value::Bool(false))
    });
    def(it, &sproto, "values", |it, this, _| {
        let v = it.iterate(&this)?;
        Ok(it.new_array(v))
    });
    def(it, &sproto, "keys", |it, this, _| {
        let v = it.iterate(&this)?;
        Ok(it.new_array(v))
    });
    def(it, &sproto, "forEach", |it, this, a| {
        let f = arg(&a, 0);
        for v in it.iterate(&this)? {
            it.call(&f, Value::Undef, vec![v.clone(), v, this.clone()])?;
        }
        Ok(Value::Undef)
    });
    setp(&set, "prototype", sproto);
    global(it, "Set", set);

    // Symbol (minimal)
    let symbol = it.native_fn("Symbol", Rc::new(|it: &mut Interp, _, args| {
        let d = arg(&args, 0);
        let s = if d.is_undef() { String::new() } else { it.to_string(&d)?.to_string() };
        Ok(Value::str(&format!("@@symbol:{}", s)))
    }));
    setp(&symbol, "iterator", Value::str("@@iterator"));
    global(it, "Symbol", symbol);

    // console
    let console = it.new_object();
    def(it, &console, "log", console_log);
    def(it, &console, "info", console_log);
    def(it, &console, "debug", console_log);
    def(it, &console, "warn", console_warn);
    def(it, &console, "error", console_error);
    global(it, "console", console);

    // process
    let process = it.new_object();
    let envo = it.new_object();
    for (k, v) in std::env::vars() {
        setp(&envo, &k, Value::str(&v));
    }
    setp(&process, "env", envo);
    let argv = it.new_array(vec![]);
    setp(&process, "argv", argv);
    setp(&process, "platform", Value::str("linux"));
    def(it, &process, "cwd", |_, _, _| Ok(Value::str(&std::env::current_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_default())));
    global(it, "process", process);

    let req = mkfn(it, "require", |it, _, args| {
        let s = it.to_string(&arg(&args, 0))?;
        it.require(&s)
    });
    global(it, "require", req);

    let g = it.new_object();
    global(it, "globalThis", g);

    super::dsl::install(it);
}

fn console_fmt(it: &mut Interp, args: &[Value]) -> R<String> {
    let mut parts = Vec::new();
    for a in args {
        parts.push(inspect(it, a, true)?);
    }
    Ok(parts.join(" "))
}

fn inspect(it: &mut Interp, v: &Value, top: bool) -> R<String> {
    match v {
        Value::Str(s) => Ok(if top { s.to_string() } else { format!("\"{}\"", s) }),
        Value::Obj(o) => {
            let items = match &o.borrow().kind {
                Kind::Array(items) => Some(items.clone()),
                _ => None,
            };
            if let Some(items) = items {
                let mut parts = Vec::new();
                for x in &items {
                    parts.push(inspect(it, x, false)?);
                }
                if parts.is_empty() {
                    return Ok("[  ]".to_string());
                }
                return Ok(format!("[ {} ]", parts.join(", ")));
            }
            Ok(it.to_string(v)?.to_string())
        }
        _ => Ok(it.to_string(v)?.to_string()),
    }
}

fn console_log(it: &mut Interp, _: Value, args: Vec<Value>) -> R<Value> {
    let s = console_fmt(it, &args)?;
    eprintln!("{}", s);
    Ok(Value::Undef)
}

fn console_warn(it: &mut Interp, _: Value, args: Vec<Value>) -> R<Value> {
    let s = console_fmt(it, &args)?;
    eprintln!("\x1b[33mWarning:\x1b[0m {}", s);
    Ok(Value::Undef)
}

fn console_error(it: &mut Interp, _: Value, args: Vec<Value>) -> R<Value> {
    let s = console_fmt(it, &args)?;
    eprintln!("\x1b[31mError:\x1b[0m {}", s);
    Ok(Value::Undef)
}

fn has_own(v: &Value, k: &str) -> bool {
    match v {
        Value::Obj(o) => {
            let b = o.borrow();
            if let Kind::Array(items) = &b.kind {
                if let Ok(i) = k.parse::<usize>() {
                    return i < items.len();
                }
                if k == "length" {
                    return true;
                }
            }
            b.props.contains_key(k) || b.getters.as_ref().map_or(false, |g| g.contains_key(k))
        }
        _ => false,
    }
}

fn map_get(it: &Interp, m: &Value, k: &Value) -> Option<Value> {
    if let Value::Obj(o) = m {
        if let Kind::Map(items) = &o.borrow().kind {
            return items.iter().find(|(x, _)| it.same_value_zero(x, k)).map(|x| x.1.clone());
        }
    }
    None
}

fn map_set(it: &Interp, m: &Value, k: Value, v: Value) {
    if let Value::Obj(o) = m {
        if let Kind::Map(items) = &mut o.borrow_mut().kind {
            if let Some(e) = items.iter_mut().find(|(x, _)| it.same_value_zero(x, &k)) {
                e.1 = v;
            } else {
                items.push((k, v));
            }
        }
    }
}

fn set_add(it: &Interp, m: &Value, k: Value) {
    if let Value::Obj(o) = m {
        if let Kind::Set(items) = &mut o.borrow_mut().kind {
            if !items.iter().any(|x| it.same_value_zero(x, &k)) {
                items.push(k);
            }
        }
    }
}

fn parse_int(it: &mut Interp, _: Value, args: Vec<Value>) -> R<Value> {
    let s = it.to_string(&arg(&args, 0))?;
    let mut radix = match arg(&args, 1) {
        Value::Undef => 10,
        r => it.to_number(&r)? as u32,
    };
    let mut t = s.trim();
    let mut neg = false;
    if let Some(r) = t.strip_prefix('-') {
        neg = true;
        t = r;
    } else if let Some(r) = t.strip_prefix('+') {
        t = r;
    }
    if radix == 0 {
        radix = 10;
    }
    if (radix == 16 || arg(&args, 1).is_undef()) && (t.starts_with("0x") || t.starts_with("0X")) {
        t = &t[2..];
        radix = 16;
    }
    let mut v: f64 = 0.0;
    let mut any = false;
    for c in t.chars() {
        match c.to_digit(radix) {
            Some(d) => {
                v = v * radix as f64 + d as f64;
                any = true;
            }
            None => break,
        }
    }
    if !any {
        return Ok(Value::Num(f64::NAN));
    }
    Ok(Value::Num(if neg { -v } else { v }))
}

fn parse_float(it: &mut Interp, _: Value, args: Vec<Value>) -> R<Value> {
    let s = it.to_string(&arg(&args, 0))?;
    let t = s.trim();
    let mut end = 0;
    let b = t.as_bytes();
    let mut seen_dot = false;
    let mut seen_e = false;
    while end < b.len() {
        let c = b[end];
        if c.is_ascii_digit() || (end == 0 && (c == b'-' || c == b'+')) {
        } else if c == b'.' && !seen_dot && !seen_e {
            seen_dot = true;
        } else if (c == b'e' || c == b'E') && !seen_e && end > 0 {
            seen_e = true;
        } else if (c == b'-' || c == b'+') && seen_e && (b[end - 1] == b'e' || b[end - 1] == b'E') {
        } else {
            break;
        }
        end += 1;
    }
    if t.starts_with("Infinity") {
        return Ok(Value::Num(f64::INFINITY));
    }
    let mut sub = &t[..end];
    while !sub.is_empty() && sub.parse::<f64>().is_err() {
        sub = &sub[..sub.len() - 1];
    }
    Ok(Value::Num(sub.parse::<f64>().unwrap_or(f64::NAN)))
}

pub fn escape_regex_source(s: &str) -> String {
    if s.is_empty() {
        return "(?:)".to_string();
    }
    let mut out = String::new();
    let mut in_class = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' => {
                out.push('\\');
                if let Some(n) = chars.next() {
                    out.push(n);
                }
            }
            '[' => {
                in_class = true;
                out.push(c);
            }
            ']' => {
                in_class = false;
                out.push(c);
            }
            '/' if !in_class => out.push_str("\\/"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c => out.push(c),
        }
    }
    out
}

pub fn js_regex_to_rust(src: &str, flags: &str) -> String {
    let mut out = String::new();
    if flags.contains('i') {
        out.push_str("(?i)");
    }
    if flags.contains('m') {
        out.push_str("(?m)");
    }
    if flags.contains('s') {
        out.push_str("(?s)");
    }
    let chars: Vec<char> = src.chars().collect();
    let mut i = 0;
    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            let n = chars[i + 1];
            match n {
                'd' | 'D' | 'w' | 'W' | 's' | 'S' | 'b' | 'B' | 'n' | 'r' | 't' | 'f' | 'v' | '\\' | '.' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '^' | '$' | '-' => {
                    out.push('\\');
                    out.push(n);
                }
                '/' => out.push('/'),
                'u' if i + 2 < chars.len() && chars[i + 2] == '{' => {
                    out.push_str("\\x");
                    i += 2;
                    while i < chars.len() && chars[i] != '}' {
                        out.push(chars[i]);
                        i += 1;
                    }
                    out.push('}');
                }
                'u' => {
                    out.push_str("\\x{");
                    for k in 0..4 {
                        if let Some(h) = chars.get(i + 2 + k) {
                            out.push(*h);
                        }
                    }
                    out.push('}');
                    i += 4;
                }
                'x' => {
                    out.push_str("\\x");
                }
                'p' | 'P' => {
                    out.push('\\');
                    out.push(n);
                }
                c2 if c2.is_ascii_alphanumeric() => {
                    out.push('\\');
                    out.push(c2);
                }
                c2 => {
                    out.push_str(&regex::escape(&c2.to_string()));
                }
            }
            i += 2;
            continue;
        }
        if c == '[' {
            in_class = true;
            out.push(c);
            if chars.get(i + 1) == Some(&'^') {
                out.push('^');
                i += 1;
            }
            if chars.get(i + 1) == Some(&']') {
                out.push_str("\\]");
                i += 1;
            }
        } else if c == ']' {
            in_class = false;
            out.push(c);
        } else if in_class && c == '[' {
            out.push_str("\\[");
        } else if in_class && (c == '&' || c == '~') {
            out.push('\\');
            out.push(c);
        } else {
            out.push(c);
        }
        i += 1;
    }
    out
}

pub fn compile_regex(it: &mut Interp, re: &Value) -> R<regex::Regex> {
    let (src, flags) = match re {
        Value::Obj(o) => match &o.borrow().kind {
            Kind::RegExp(s, f) => (s.to_string(), f.to_string()),
            _ => (String::new(), String::new()),
        },
        _ => {
            let s = it.to_string(re)?;
            (regex::escape(&s), String::new())
        }
    };
    let rs = js_regex_to_rust(&src, &flags);
    regex::Regex::new(&rs).map_err(|e| throw_error(it, "SyntaxError", &format!("invalid regular expression: {}", e)))
}

fn regex_flags(re: &Value) -> String {
    match re {
        Value::Obj(o) => match &o.borrow().kind {
            Kind::RegExp(_, f) => f.to_string(),
            _ => String::new(),
        },
        _ => String::new(),
    }
}

fn match_result(it: &mut Interp, c: &regex::Captures, s: &str) -> Value {
    let mut items = Vec::new();
    for g in c.iter() {
        items.push(match g {
            Some(m) => Value::str(m.as_str()),
            None => Value::Undef,
        });
    }
    let arr = it.new_array(items);
    let idx = c.get(0).map(|m| s[..m.start()].encode_utf16().count()).unwrap_or(0);
    if let Value::Obj(o) = &arr {
        o.borrow_mut().props.insert(rcs("index"), Value::Num(idx as f64));
        o.borrow_mut().props.insert(rcs("input"), Value::str(s));
    }
    arr
}

pub fn string_method(it: &mut Interp, name: &str) -> Option<Value> {
    let key = ("string", rcs(name));
    if let Some(v) = it.method_cache.get(&key) {
        return Some(v.clone());
    }
    let f: F = match name {
        "charAt" => |it, this, a| {
            let s = it.to_string(&this)?;
            let i = it.to_number(&arg(&a, 0))?;
            let i = if i.is_nan() { 0 } else { i as i64 };
            let u: Vec<u16> = s.encode_utf16().collect();
            if i < 0 || i as usize >= u.len() {
                return Ok(Value::str(""));
            }
            Ok(Value::str(&String::from_utf16_lossy(&u[i as usize..i as usize + 1])))
        },
        "charCodeAt" => |it, this, a| {
            let s = it.to_string(&this)?;
            let i = it.to_number(&arg(&a, 0))?;
            let i = if i.is_nan() { 0 } else { i as i64 };
            let u: Vec<u16> = s.encode_utf16().collect();
            if i < 0 || i as usize >= u.len() {
                return Ok(Value::Num(f64::NAN));
            }
            Ok(Value::Num(u[i as usize] as f64))
        },
        "codePointAt" => |it, this, a| {
            let s = it.to_string(&this)?;
            let i = it.to_number(&arg(&a, 0))?;
            let i = if i.is_nan() { 0 } else { i as usize };
            let u: Vec<u16> = s.encode_utf16().collect();
            if i >= u.len() {
                return Ok(Value::Undef);
            }
            let c = char::decode_utf16(u[i..].iter().cloned()).next().unwrap();
            Ok(Value::Num(match c {
                Ok(c) => c as u32 as f64,
                Err(e) => e.unpaired_surrogate() as f64,
            }))
        },
        "at" => |it, this, a| {
            let s = it.to_string(&this)?;
            let u: Vec<u16> = s.encode_utf16().collect();
            let mut i = it.to_number(&arg(&a, 0))? as i64;
            if i < 0 {
                i += u.len() as i64;
            }
            if i < 0 || i as usize >= u.len() {
                return Ok(Value::Undef);
            }
            Ok(Value::str(&String::from_utf16_lossy(&u[i as usize..i as usize + 1])))
        },
        "indexOf" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_string(&arg(&a, 0))?;
            let from = match arg(&a, 1) {
                Value::Undef => 0,
                v => it.to_number(&v)?.max(0.0) as usize,
            };
            let u: Vec<u16> = s.encode_utf16().collect();
            let nu: Vec<u16> = n.encode_utf16().collect();
            Ok(Value::Num(find_u16(&u, &nu, from).map(|x| x as f64).unwrap_or(-1.0)))
        },
        "lastIndexOf" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_string(&arg(&a, 0))?;
            let u: Vec<u16> = s.encode_utf16().collect();
            let nu: Vec<u16> = n.encode_utf16().collect();
            let mut r = -1.0;
            if nu.len() <= u.len() {
                for i in (0..=u.len() - nu.len()).rev() {
                    if u[i..i + nu.len()] == nu[..] {
                        r = i as f64;
                        break;
                    }
                }
            }
            Ok(Value::Num(r))
        },
        "includes" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_string(&arg(&a, 0))?;
            Ok(Value::Bool(s.contains(&*n)))
        },
        "startsWith" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_string(&arg(&a, 0))?;
            let from = match arg(&a, 1) {
                Value::Undef => 0,
                v => it.to_number(&v)? as usize,
            };
            let u: Vec<u16> = s.encode_utf16().collect();
            let nu: Vec<u16> = n.encode_utf16().collect();
            Ok(Value::Bool(from <= u.len() && u[from..].starts_with(&nu)))
        },
        "endsWith" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_string(&arg(&a, 0))?;
            Ok(Value::Bool(s.ends_with(&*n)))
        },
        "slice" => |it, this, a| {
            let s = it.to_string(&this)?;
            let u: Vec<u16> = s.encode_utf16().collect();
            let (st, en) = slice_range(it, &a, u.len())?;
            Ok(Value::str(&String::from_utf16_lossy(&u[st..en.max(st)])))
        },
        "substring" => |it, this, a| {
            let s = it.to_string(&this)?;
            let u: Vec<u16> = s.encode_utf16().collect();
            let len = u.len() as f64;
            let st = it.to_number(&arg(&a, 0))?;
            let st = if st.is_nan() { 0.0 } else { st.max(0.0).min(len) };
            let en = match arg(&a, 1) {
                Value::Undef => len,
                v => {
                    let e = it.to_number(&v)?;
                    if e.is_nan() {
                        0.0
                    } else {
                        e.max(0.0).min(len)
                    }
                }
            };
            let (x, y) = if st < en { (st, en) } else { (en, st) };
            Ok(Value::str(&String::from_utf16_lossy(&u[x as usize..y as usize])))
        },
        "substr" => |it, this, a| {
            let s = it.to_string(&this)?;
            let u: Vec<u16> = s.encode_utf16().collect();
            let len = u.len() as i64;
            let mut st = it.to_number(&arg(&a, 0))? as i64;
            if st < 0 {
                st = (len + st).max(0);
            }
            let st = st.min(len);
            let l = match arg(&a, 1) {
                Value::Undef => len - st,
                v => (it.to_number(&v)? as i64).max(0).min(len - st),
            };
            Ok(Value::str(&String::from_utf16_lossy(&u[st as usize..(st + l) as usize])))
        },
        "toUpperCase" | "toLocaleUpperCase" => |it, this, _| Ok(Value::str(&it.to_string(&this)?.to_uppercase())),
        "toLowerCase" | "toLocaleLowerCase" => |it, this, _| Ok(Value::str(&it.to_string(&this)?.to_lowercase())),
        "trim" => |it, this, _| Ok(Value::str(it.to_string(&this)?.trim())),
        "trimStart" | "trimLeft" => |it, this, _| Ok(Value::str(it.to_string(&this)?.trim_start())),
        "trimEnd" | "trimRight" => |it, this, _| Ok(Value::str(it.to_string(&this)?.trim_end())),
        "toString" | "valueOf" => |it, this, _| Ok(Value::Str(it.to_string(&this)?)),
        "repeat" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_number(&arg(&a, 0))?;
            if n < 0.0 || n.is_infinite() {
                return Err(throw_error(it, "RangeError", "invalid repeat count"));
            }
            Ok(Value::str(&s.repeat(n as usize)))
        },
        "padStart" | "padEnd" => |it, this, a| {
            let s = it.to_string(&this)?;
            let n = it.to_number(&arg(&a, 0))? as usize;
            let pad = match arg(&a, 1) {
                Value::Undef => " ".to_string(),
                v => it.to_string(&v)?.to_string(),
            };
            let len = s.encode_utf16().count();
            if n <= len || pad.is_empty() {
                return Ok(Value::Str(s));
            }
            let mut p = String::new();
            while p.chars().count() < n - len {
                p.push_str(&pad);
            }
            let p: String = p.chars().take(n - len).collect();
            // determine which by checking the function name is impossible here; use a marker
            Ok(Value::str(&format!("{}\u{0}{}", p, s)))
        },
        "concat" => |it, this, a| {
            let mut s = it.to_string(&this)?.to_string();
            for x in &a {
                s.push_str(&it.to_string(x)?);
            }
            Ok(Value::str(&s))
        },
        "split" => |it, this, a| {
            let s = it.to_string(&this)?;
            let sep = arg(&a, 0);
            let limit = match arg(&a, 1) {
                Value::Undef => usize::MAX,
                v => it.to_number(&v)? as usize,
            };
            let parts: Vec<Value> = if sep.is_undef() {
                vec![Value::Str(s.clone())]
            } else if sep.is_regexp() {
                let re = compile_regex(it, &sep)?;
                let mut out = Vec::new();
                let mut last = 0;
                for c in re.captures_iter(&s) {
                    let m = c.get(0).unwrap();
                    if m.end() == 0 && m.start() == 0 {
                        continue;
                    }
                    if m.start() == m.end() && m.start() >= s.len() {
                        break;
                    }
                    out.push(Value::str(&s[last..m.start()]));
                    for g in c.iter().skip(1) {
                        out.push(g.map(|g| Value::str(g.as_str())).unwrap_or(Value::Undef));
                    }
                    last = m.end();
                }
                out.push(Value::str(&s[last..]));
                out
            } else {
                let sep = it.to_string(&sep)?;
                if sep.is_empty() {
                    s.chars().map(|c| Value::str(&c.to_string())).collect()
                } else {
                    s.split(&*sep).map(Value::str).collect()
                }
            };
            Ok(it.new_array(parts.into_iter().take(limit).collect()))
        },
        "replace" => |it, this, a| string_replace(it, this, a, false),
        "replaceAll" => |it, this, a| string_replace(it, this, a, true),
        "match" => |it, this, a| {
            let s = it.to_string(&this)?;
            let re_v = arg(&a, 0);
            let re_v = if re_v.is_regexp() {
                re_v
            } else {
                let src = it.to_string(&re_v)?;
                it.new_regexp(&src, "")
            };
            let re = compile_regex(it, &re_v)?;
            if regex_flags(&re_v).contains('g') {
                let ms: Vec<Value> = re.find_iter(&s).map(|m| Value::str(m.as_str())).collect();
                if ms.is_empty() {
                    return Ok(Value::Null);
                }
                return Ok(it.new_array(ms));
            }
            Ok(match re.captures(&s) {
                Some(c) => match_result(it, &c, &s),
                None => Value::Null,
            })
        },
        "matchAll" => |it, this, a| {
            let s = it.to_string(&this)?;
            let re = compile_regex(it, &arg(&a, 0))?;
            let caps: Vec<_> = re.captures_iter(&s).collect();
            let mut out = Vec::new();
            for c in caps {
                out.push(match_result(it, &c, &s));
            }
            Ok(it.new_array(out))
        },
        "search" => |it, this, a| {
            let s = it.to_string(&this)?;
            let re = compile_regex(it, &arg(&a, 0))?;
            Ok(Value::Num(re.find(&s).map(|m| s[..m.start()].encode_utf16().count() as f64).unwrap_or(-1.0)))
        },
        "normalize" => |it, this, _| Ok(Value::Str(it.to_string(&this)?)),
        "localeCompare" => |it, this, a| {
            let s = it.to_string(&this)?;
            let o = it.to_string(&arg(&a, 0))?;
            Ok(Value::Num(match s.cmp(&o) {
                std::cmp::Ordering::Less => -1.0,
                std::cmp::Ordering::Equal => 0.0,
                std::cmp::Ordering::Greater => 1.0,
            }))
        },
        _ => return None,
    };
    let v = if name == "padStart" || name == "padEnd" {
        let is_start = name == "padStart";
        it.native_fn(name, Rc::new(move |it: &mut Interp, this: Value, a: Vec<Value>| {
            let r = f(it, this, a)?;
            if let Value::Str(s) = &r {
                if let Some((p, s2)) = s.split_once('\u{0}') {
                    return Ok(Value::str(&if is_start { format!("{}{}", p, s2) } else { format!("{}{}", s2, p) }));
                }
            }
            Ok(r)
        }))
    } else {
        mkfn(it, name, f)
    };
    it.method_cache.insert(key, v.clone());
    Some(v)
}

fn find_u16(h: &[u16], n: &[u16], from: usize) -> Option<usize> {
    if n.is_empty() {
        return Some(from.min(h.len()));
    }
    if n.len() > h.len() {
        return None;
    }
    (from..=h.len() - n.len()).find(|&i| h[i..i + n.len()] == n[..])
}

fn slice_range(it: &mut Interp, a: &[Value], len: usize) -> R<(usize, usize)> {
    let l = len as f64;
    let norm = |x: f64| -> usize {
        if x.is_nan() {
            0
        } else if x < 0.0 {
            (l + x).max(0.0) as usize
        } else {
            x.min(l) as usize
        }
    };
    let st = match arg(a, 0) {
        Value::Undef => 0,
        v => norm(it.to_number(&v)?),
    };
    let en = match arg(a, 1) {
        Value::Undef => len,
        v => norm(it.to_number(&v)?),
    };
    Ok((st, en))
}

fn expand_replacement(rep: &str, caps: &regex::Captures, s: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = rep.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '$' && i + 1 < chars.len() {
            let n = chars[i + 1];
            if n == '$' {
                out.push('$');
                i += 2;
                continue;
            }
            if n == '&' {
                out.push_str(caps.get(0).map(|m| m.as_str()).unwrap_or(""));
                i += 2;
                continue;
            }
            if n == '`' {
                out.push_str(&s[..caps.get(0).unwrap().start()]);
                i += 2;
                continue;
            }
            if n == '\'' {
                out.push_str(&s[caps.get(0).unwrap().end()..]);
                i += 2;
                continue;
            }
            if n.is_ascii_digit() {
                let mut num = n.to_digit(10).unwrap() as usize;
                let mut adv = 2;
                if i + 2 < chars.len() && chars[i + 2].is_ascii_digit() {
                    let two = num * 10 + chars[i + 2].to_digit(10).unwrap() as usize;
                    if two < caps.len() {
                        num = two;
                        adv = 3;
                    }
                }
                if num > 0 && num < caps.len() {
                    out.push_str(caps.get(num).map(|m| m.as_str()).unwrap_or(""));
                    i += adv;
                    continue;
                }
            }
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

fn string_replace(it: &mut Interp, this: Value, a: Vec<Value>, all: bool) -> R<Value> {
    let s = it.to_string(&this)?;
    let pat = arg(&a, 0);
    let rep = arg(&a, 1);
    let (re, global) = if pat.is_regexp() {
        (compile_regex(it, &pat)?, regex_flags(&pat).contains('g') || all)
    } else {
        let p = it.to_string(&pat)?;
        (regex::Regex::new(&regex::escape(&p)).unwrap(), all)
    };
    let mut out = String::new();
    let mut last = 0;
    let caps_list: Vec<regex::Captures> = if global { re.captures_iter(&s).collect() } else { re.captures(&s).into_iter().collect() };
    for c in caps_list {
        let m = c.get(0).unwrap();
        out.push_str(&s[last..m.start()]);
        if rep.is_function() {
            let mut args = Vec::new();
            for g in c.iter() {
                args.push(g.map(|g| Value::str(g.as_str())).unwrap_or(Value::Undef));
            }
            args.push(Value::Num(s[..m.start()].encode_utf16().count() as f64));
            args.push(Value::Str(s.clone()));
            let r = it.call(&rep, Value::Undef, args)?;
            out.push_str(&it.to_string(&r)?);
        } else {
            let r = it.to_string(&rep)?;
            out.push_str(&expand_replacement(&r, &c, &s));
        }
        last = m.end();
    }
    out.push_str(&s[last..]);
    Ok(Value::str(&out))
}

pub fn number_method(it: &mut Interp, name: &str) -> Option<Value> {
    let key = ("number", rcs(name));
    if let Some(v) = it.method_cache.get(&key) {
        return Some(v.clone());
    }
    let f: F = match name {
        "toString" => |it, this, a| {
            let n = it.to_number(&this)?;
            let radix = match arg(&a, 0) {
                Value::Undef => 10,
                v => it.to_number(&v)? as u32,
            };
            if radix == 10 || !n.is_finite() {
                return Ok(Value::str(&num_to_string(n)));
            }
            let neg = n < 0.0;
            let mut x = n.abs().trunc() as u64;
            let mut digits = Vec::new();
            if x == 0 {
                digits.push('0');
            }
            while x > 0 {
                digits.push(std::char::from_digit((x % radix as u64) as u32, radix).unwrap());
                x /= radix as u64;
            }
            if neg {
                digits.push('-');
            }
            digits.reverse();
            Ok(Value::str(&digits.into_iter().collect::<String>()))
        },
        "toFixed" => |it, this, a| {
            let n = it.to_number(&this)?;
            let d = match arg(&a, 0) {
                Value::Undef => 0,
                v => it.to_number(&v)? as usize,
            };
            Ok(Value::str(&format!("{:.*}", d, n)))
        },
        "valueOf" => |it, this, _| Ok(Value::Num(it.to_number(&this)?)),
        _ => return None,
    };
    let v = mkfn(it, name, f);
    it.method_cache.insert(key, v.clone());
    Some(v)
}

pub fn bool_method(it: &mut Interp, name: &str) -> Option<Value> {
    let f: F = match name {
        "toString" => |it, this, _| Ok(Value::Str(it.to_string(&this)?)),
        "valueOf" => |_, this, _| Ok(this),
        _ => return None,
    };
    Some(mkfn(it, name, f))
}

fn this_items(it: &mut Interp, this: &Value) -> R<Vec<Value>> {
    match this.array_items() {
        Some(v) => Ok(v),
        None => {
            let len = it.get(this, "length")?;
            let n = it.to_number(&len)?;
            let n = if n.is_nan() { 0 } else { n as usize };
            let mut v = Vec::new();
            for i in 0..n {
                v.push(it.get(this, &i.to_string())?);
            }
            Ok(v)
        }
    }
}

fn with_items<T>(this: &Value, f: impl FnOnce(&mut Vec<Value>) -> T) -> Option<T> {
    if let Value::Obj(o) = this {
        if let Kind::Array(items) = &mut o.borrow_mut().kind {
            return Some(f(items));
        }
    }
    None
}

fn install_array_methods(it: &mut Interp, ap: &Value) {
    def(it, ap, "push", |_, this, a| {
        let n = with_items(&this, |items| {
            items.extend(a);
            items.len()
        });
        Ok(Value::Num(n.unwrap_or(0) as f64))
    });
    def(it, ap, "pop", |_, this, _| Ok(with_items(&this, |items| items.pop()).flatten().unwrap_or(Value::Undef)));
    def(it, ap, "shift", |_, this, _| {
        Ok(with_items(&this, |items| if items.is_empty() { None } else { Some(items.remove(0)) }).flatten().unwrap_or(Value::Undef))
    });
    def(it, ap, "unshift", |_, this, a| {
        let n = with_items(&this, |items| {
            for (i, x) in a.into_iter().enumerate() {
                items.insert(i, x);
            }
            items.len()
        });
        Ok(Value::Num(n.unwrap_or(0) as f64))
    });
    def(it, ap, "slice", |it, this, a| {
        let items = this_items(it, &this)?;
        let (st, en) = slice_range(it, &a, items.len())?;
        Ok(it.new_array(if st < en { items[st..en].to_vec() } else { vec![] }))
    });
    def(it, ap, "splice", |it, this, a| {
        let items = this_items(it, &this)?;
        let len = items.len();
        let st = match arg(&a, 0) {
            Value::Undef => 0,
            v => {
                let x = it.to_number(&v)?;
                if x < 0.0 {
                    (len as f64 + x).max(0.0) as usize
                } else {
                    (x as usize).min(len)
                }
            }
        };
        let dc = if a.len() < 2 { len - st } else { (it.to_number(&a[1])?.max(0.0) as usize).min(len - st) };
        let ins: Vec<Value> = a.iter().skip(2).cloned().collect();
        let removed = with_items(&this, |items| items.splice(st..st + dc, ins).collect::<Vec<_>>()).unwrap_or_default();
        Ok(it.new_array(removed))
    });
    def(it, ap, "concat", |it, this, a| {
        let mut items = this_items(it, &this)?;
        for x in a {
            match x.array_items() {
                Some(v) => items.extend(v),
                None => items.push(x),
            }
        }
        Ok(it.new_array(items))
    });
    def(it, ap, "join", |it, this, a| {
        let items = this_items(it, &this)?;
        let sep = match arg(&a, 0) {
            Value::Undef => rcs(","),
            v => it.to_string(&v)?,
        };
        let mut parts = Vec::new();
        for x in items {
            parts.push(if x.is_nullish() { String::new() } else { it.to_string(&x)?.to_string() });
        }
        Ok(Value::str(&parts.join(&sep)))
    });
    def(it, ap, "toString", |it, this, _| Ok(Value::str(&it.default_to_string(&this)?)));
    def(it, ap, "map", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        let mut out = Vec::new();
        for (i, x) in items.into_iter().enumerate() {
            out.push(it.call(&f, arg(&a, 1), vec![x, Value::Num(i as f64), this.clone()])?);
        }
        Ok(it.new_array(out))
    });
    def(it, ap, "flatMap", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        let mut out = Vec::new();
        for (i, x) in items.into_iter().enumerate() {
            let r = it.call(&f, arg(&a, 1), vec![x, Value::Num(i as f64), this.clone()])?;
            match r.array_items() {
                Some(v) => out.extend(v),
                None => out.push(r),
            }
        }
        Ok(it.new_array(out))
    });
    def(it, ap, "filter", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        let mut out = Vec::new();
        for (i, x) in items.into_iter().enumerate() {
            if it.call(&f, arg(&a, 1), vec![x.clone(), Value::Num(i as f64), this.clone()])?.truthy() {
                out.push(x);
            }
        }
        Ok(it.new_array(out))
    });
    def(it, ap, "forEach", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        for (i, x) in items.into_iter().enumerate() {
            it.call(&f, arg(&a, 1), vec![x, Value::Num(i as f64), this.clone()])?;
        }
        Ok(Value::Undef)
    });
    def(it, ap, "reduce", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        let mut iter = items.into_iter().enumerate();
        let mut acc = if a.len() >= 2 {
            a[1].clone()
        } else {
            match iter.next() {
                Some((_, x)) => x,
                None => return Err(it.type_error("empty array")),
            }
        };
        for (i, x) in iter {
            acc = it.call(&f, Value::Undef, vec![acc, x, Value::Num(i as f64), this.clone()])?;
        }
        Ok(acc)
    });
    def(it, ap, "reduceRight", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        let mut iter = items.into_iter().enumerate().rev();
        let mut acc = if a.len() >= 2 {
            a[1].clone()
        } else {
            match iter.next() {
                Some((_, x)) => x,
                None => return Err(it.type_error("empty array")),
            }
        };
        for (i, x) in iter {
            acc = it.call(&f, Value::Undef, vec![acc, x, Value::Num(i as f64), this.clone()])?;
        }
        Ok(acc)
    });
    def(it, ap, "find", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        for (i, x) in items.into_iter().enumerate() {
            if it.call(&f, Value::Undef, vec![x.clone(), Value::Num(i as f64), this.clone()])?.truthy() {
                return Ok(x);
            }
        }
        Ok(Value::Undef)
    });
    def(it, ap, "findLast", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        for (i, x) in items.into_iter().enumerate().rev() {
            if it.call(&f, Value::Undef, vec![x.clone(), Value::Num(i as f64), this.clone()])?.truthy() {
                return Ok(x);
            }
        }
        Ok(Value::Undef)
    });
    def(it, ap, "findIndex", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        for (i, x) in items.into_iter().enumerate() {
            if it.call(&f, Value::Undef, vec![x, Value::Num(i as f64), this.clone()])?.truthy() {
                return Ok(Value::Num(i as f64));
            }
        }
        Ok(Value::Num(-1.0))
    });
    def(it, ap, "some", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        for (i, x) in items.into_iter().enumerate() {
            if it.call(&f, Value::Undef, vec![x, Value::Num(i as f64), this.clone()])?.truthy() {
                return Ok(Value::Bool(true));
            }
        }
        Ok(Value::Bool(false))
    });
    def(it, ap, "every", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        for (i, x) in items.into_iter().enumerate() {
            if !it.call(&f, Value::Undef, vec![x, Value::Num(i as f64), this.clone()])?.truthy() {
                return Ok(Value::Bool(false));
            }
        }
        Ok(Value::Bool(true))
    });
    def(it, ap, "includes", |it, this, a| {
        let items = this_items(it, &this)?;
        let x = arg(&a, 0);
        Ok(Value::Bool(items.iter().any(|y| it.same_value_zero(y, &x))))
    });
    def(it, ap, "indexOf", |it, this, a| {
        let items = this_items(it, &this)?;
        let x = arg(&a, 0);
        Ok(Value::Num(items.iter().position(|y| it.strict_eq(y, &x)).map(|i| i as f64).unwrap_or(-1.0)))
    });
    def(it, ap, "lastIndexOf", |it, this, a| {
        let items = this_items(it, &this)?;
        let x = arg(&a, 0);
        Ok(Value::Num(items.iter().rposition(|y| it.strict_eq(y, &x)).map(|i| i as f64).unwrap_or(-1.0)))
    });
