        let depth = match arg(&a, 0) {
            Value::Undef => 1,
            v => it.to_number(&v)? as i32,
        };
        fn flat(items: Vec<Value>, depth: i32, out: &mut Vec<Value>) {
            for x in items {
                match x.array_items() {
                    Some(v) if depth > 0 => flat(v, depth - 1, out),
                    _ => out.push(x),
                }
            }
        }
        let mut out = Vec::new();
        flat(items, depth, &mut out);
        Ok(it.new_array(out))
    });
    def(it, ap, "reverse", |_, this, _| {
        with_items(&this, |items| items.reverse());
        Ok(this)
    });
    def(it, ap, "fill", |it, this, a| {
        let v = arg(&a, 0);
        let len = this_items(it, &this)?.len();
        let st = match arg(&a, 1) {
            Value::Undef => 0,
            x => (it.to_number(&x)? as usize).min(len),
        };
        let en = match arg(&a, 2) {
            Value::Undef => len,
            x => (it.to_number(&x)? as usize).min(len),
        };
        with_items(&this, |items| {
            for i in st..en {
                items[i] = v.clone();
            }
        });
        Ok(this)
    });
    def(it, ap, "at", |it, this, a| {
        let items = this_items(it, &this)?;
        let mut i = it.to_number(&arg(&a, 0))? as i64;
        if i < 0 {
            i += items.len() as i64;
        }
        Ok(if i < 0 { Value::Undef } else { items.get(i as usize).cloned().unwrap_or(Value::Undef) })
    });
    def(it, ap, "keys", |it, this, _| {
        let n = this_items(it, &this)?.len();
        Ok(it.new_array((0..n).map(|i| Value::Num(i as f64)).collect()))
    });
    def(it, ap, "values", |it, this, _| {
        let items = this_items(it, &this)?;
        Ok(it.new_array(items))
    });
    def(it, ap, "entries", |it, this, _| {
        let items = this_items(it, &this)?;
        let mut out = Vec::new();
        for (i, x) in items.into_iter().enumerate() {
            out.push(it.new_array(vec![Value::Num(i as f64), x]));
        }
        Ok(it.new_array(out))
    });
    def(it, ap, "sort", |it, this, a| {
        let items = this_items(it, &this)?;
        let f = arg(&a, 0);
        // stable merge sort with fallible comparator
        let mut v = items;
        let mut err = None;
        let n = v.len();
        let mut width = 1;
        while width < n && err.is_none() {
            let mut out = Vec::with_capacity(n);
            let mut i = 0;
            while i < n {
                let mid = (i + width).min(n);
                let end = (i + 2 * width).min(n);
                let (mut l, mut r) = (i, mid);
                while l < mid && r < end {
                    let c = if f.is_function() {
                        match it.call(&f, Value::Undef, vec![v[r].clone(), v[l].clone()]) {
                            Ok(x) => it.to_number(&x).unwrap_or(0.0) < 0.0,
                            Err(e) => {
                                err = Some(e);
                                false
                            }
                        }
                    } else {
                        let a = it.to_string(&v[r]).map(|s| s.to_string()).unwrap_or_default();
                        let b = it.to_string(&v[l]).map(|s| s.to_string()).unwrap_or_default();
                        a.encode_utf16().collect::<Vec<_>>() < b.encode_utf16().collect::<Vec<_>>()
                    };
                    if c {
                        out.push(v[r].clone());
                        r += 1;
                    } else {
                        out.push(v[l].clone());
                        l += 1;
                    }
                }
                out.extend_from_slice(&v[l..mid]);
                out.extend_from_slice(&v[r..end]);
                i += 2 * width;
            }
            v = out;
            width *= 2;
        }
        if let Some(e) = err {
            return Err(e);
        }
        with_items(&this, |items| *items = v);
        Ok(this)
    });
}

// ---------- JSON ----------
pub fn json_quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn json_stringify(it: &mut Interp, v: &Value, indent: &str, cur: &str, out: &mut String) -> R<bool> {
    match v {
        Value::Undef => return Ok(false),
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Num(n) => {
            if n.is_finite() {
                out.push_str(&num_to_string(*n))
            } else {
                out.push_str("null")
            }
        }
        Value::Str(s) => out.push_str(&json_quote(s)),
        Value::Obj(o) => {
            if o.borrow().kind_is_function() {
                return Ok(false);
            }
            let tj = it.get(v, "toJSON")?;
            if tj.is_function() {
                let r = it.call(&tj, v.clone(), vec![])?;
                return json_stringify(it, &r, indent, cur, out);
            }
            if let Kind::RegExp(..) = o.borrow().kind {
                out.push_str("{}");
                return Ok(true);
            }
            let inner = format!("{}{}", cur, indent);
            if let Some(items) = v.array_items() {
                if items.is_empty() {
                    out.push_str("[]");
                    return Ok(true);
                }
                out.push('[');
                for (i, x) in items.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    if !indent.is_empty() {
                        out.push('\n');
                        out.push_str(&inner);
                    }
                    if !json_stringify(it, x, indent, &inner, out)? {
                        out.push_str("null");
                    }
                }
                if !indent.is_empty() {
                    out.push('\n');
                    out.push_str(cur);
                }
                out.push(']');
                return Ok(true);
            }
            let keys = it.own_keys(v);
            out.push('{');
            let mut first = true;
            for k in keys {
                let x = it.get(v, &k)?;
                let mut tmp = String::new();
                if !json_stringify(it, &x, indent, &inner, &mut tmp)? {
                    continue;
                }
                if !first {
                    out.push(',');
                }
                first = false;
                if !indent.is_empty() {
                    out.push('\n');
                    out.push_str(&inner);
                }
                out.push_str(&json_quote(&k));
                out.push(':');
                if !indent.is_empty() {
                    out.push(' ');
                }
                out.push_str(&tmp);
            }
            if !first && !indent.is_empty() {
                out.push('\n');
                out.push_str(cur);
            }
            out.push('}');
        }
    }
    Ok(true)
}

impl ObjData {
    pub fn kind_is_function(&self) -> bool {
        matches!(self.kind, Kind::Function(_))
    }
}

pub fn json_parse(it: &mut Interp, s: &str) -> R<Value> {
    let v: serde_json::Value = match serde_json::from_str(s) {
        Ok(v) => v,
        Err(e) => return Err(throw_error(it, "SyntaxError", &format!("JSON.parse: {}", e))),
    };
    Ok(from_serde(it, &v))
}

pub fn from_serde(it: &mut Interp, v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::Null,
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => Value::Num(n.as_f64().unwrap_or(0.0)),
        serde_json::Value::String(s) => Value::str(s),
        serde_json::Value::Array(a) => {
            let items = a.iter().map(|x| from_serde(it, x)).collect();
            it.new_array(items)
        }
        serde_json::Value::Object(m) => {
            let o = it.new_object();
            for (k, x) in m {
                let xv = from_serde(it, x);
                setp(&o, k, xv);
            }
            o
        }
    }
}
