use super::interp::*;
use super::value::*;
use std::cell::RefCell;
use std::rc::Rc;

fn rcs(s: &str) -> Rc<str> {
    Rc::from(s)
}

fn arg(args: &[Value], i: usize) -> Value {
    args.get(i).cloned().unwrap_or(Value::Undef)
}

type F = fn(&mut Interp, Value, Vec<Value>) -> R<Value>;

fn mkfn(it: &mut Interp, name: &str, f: F) -> Value {
    it.native_fn(name, Rc::new(f))
}

fn def(it: &mut Interp, target: &Value, name: &str, f: F) {
    let fv = mkfn(it, name, f);
    if let Value::Obj(o) = target {
        o.borrow_mut().props.insert(rcs(name), fv);
    }
}

fn setp(target: &Value, name: &str, v: Value) {
    if let Value::Obj(o) = target {
        o.borrow_mut().props.insert(rcs(name), v);
    }
}

fn global(it: &mut Interp, name: &str, v: Value) {
    it.global.borrow_mut().vars.insert(rcs(name), (v, false));
}

pub fn install(it: &mut Interp) {
    let op = Value::Obj(it.object_proto.clone());
    // Object.prototype
    def(it, &op, "hasOwnProperty", |it, this, args| {
        let k = it.to_key(&arg(&args, 0))?;
        Ok(Value::Bool(has_own(&this, &k)))
    });
    def(it, &op, "__default_toString", |it, this, _| Ok(Value::str(&it.default_to_string(&this)?)));
    let ts = it.native_fn("__default_toString", Rc::new(|it: &mut Interp, this: Value, _| Ok(Value::str(&it.default_to_string(&this)?))));
    setp(&op, "toString", ts);
    if let Value::Obj(o) = &op {
        o.borrow_mut().props.shift_remove("__default_toString");
    }
    def(it, &op, "valueOf", |_, this, _| Ok(this));
    def(it, &op, "isPrototypeOf", |_, this, args| {
        let mut cur = match &arg(&args, 0) {
            Value::Obj(o) => o.borrow().proto.clone(),
            _ => None,
        };
        while let Some(c) = cur {
            if let Value::Obj(t) = &this {
                if Rc::ptr_eq(&c, t) {
