        it.call(&this, t, rest)
    });
    def(it, &fp, "apply", |it, this, args| {
        let t = arg(&args, 0);
        let a = arg(&args, 1);
        let rest = if a.is_nullish() { vec![] } else { it.iterate(&a)? };
        it.call(&this, t, rest)
