    def(it, &ep, "toString", |it, this, _| Ok(Value::str(&it.default_to_string(&this)?)));
    for name in ["Error", "TypeError", "ReferenceError", "SyntaxError", "RangeError", "EvalError", "URIError"] {
        let proto = if name == "Error" {
