        } else {
            let p = it.new_object();
            if let (Value::Obj(po), Value::Obj(e)) = (&p, &ep) {
                po.borrow_mut().proto = Some(e.clone());
            }
            setp(&p, "name", Value::str(name));
            p
        };
        let pname: &'static str = name;
        let proto2 = proto.clone();
        let ctor = it.native_ctor(
            name,
            Rc::new(move |it: &mut Interp, this: Value, args: Vec<Value>| {
                let msg = arg(&args, 0);
                let msg = if msg.is_undef() { String::new() } else { it.to_string(&msg)?.to_string() };
                let e = it.make_error(pname, &msg);
                if let (Value::Obj(eo), Value::Obj(p)) = (&e, &proto2) {
                    eo.borrow_mut().proto = Some(p.clone());
                }
                if msg.is_empty() {
                    if let Value::Obj(eo) = &e {
                        eo.borrow_mut().props.shift_remove("message");
                    }
                }
                // subclass construction: copy onto this
                if let Value::Obj(_) = &this {
                    if !matches!(this, Value::Null) {
                        // when called as super() from class, the caller copies props
                    }
                }
                let opts = arg(&args, 1);
                if let Value::Obj(_) = &opts {
                    let c = it.get(&opts, "cause")?;
                    if !c.is_undef() {
                        it.set(&e, "cause", c)?;
                    }
                }
                Ok(e)
            }),
        );
        setp(&ctor, "prototype", proto.clone());
        setp(&proto, "constructor", ctor.clone());
        it.error_ctors.insert(pname, ctor.clone());
