    def(it, &object, "seal", |_, _, args| Ok(arg(&args, 0)));
    def(it, &object, "preventExtensions", |_, _, args| Ok(arg(&args, 0)));
    def(it, &object, "isFrozen", |_, _, _| Ok(Value::Bool(false)));
    def(it, &object, "create", |it, _, args| {
        let p = arg(&args, 0);
        let o = it.new_object();
        if let Value::Obj(oo) = &o {
            oo.borrow_mut().proto = p.as_obj().cloned();
        }
