    setp(&array, "prototype", ap.clone());
    setp(&ap, "constructor", array.clone());
    def(it, &array, "isArray", |_, _, args| Ok(Value::Bool(arg(&args, 0).is_array())));
    def(it, &array, "of", |it, _, args| Ok(it.new_array(args)));
    def(it, &array, "from", |it, _, args| {
        let src = arg(&args, 0);
        let items = match &src {
