                let len = it.get(&src, "length")?;
                if len.is_undef() {
                    it.iterate(&src)?
                } else {
                    let n = it.to_number(&len)? as usize;
                    let mut v = Vec::new();
                    for i in 0..n {
                        v.push(it.get(&src, &i.to_string())?);
                    }
                    v
                }
            }
            _ => it.iterate(&src)?,
        };
        let f = arg(&args, 1);
