// Native implementation of the tree-sitter grammar DSL.
use super::interp::*;
use super::value::*;
use std::collections::HashSet;
use std::rc::Rc;

fn rcs(s: &str) -> Rc<str> {
    Rc::from(s)
}

fn arg(args: &[Value], i: usize) -> Value {
    args.get(i).cloned().unwrap_or(Value::Undef)
}

const DSL_NAMES: &[&str] = &[
    "grammar", "seq", "choice", "repeat", "repeat1", "optional", "prec", "prec.left", "prec.right",
    "prec.dynamic", "token", "token.immediate", "alias", "field", "blank", "sym", "reserved",
];

pub fn is_dsl_name(n: &str) -> bool {
    DSL_NAMES.contains(&n)
}

pub fn make_obj(it: &mut Interp, props: Vec<(&str, Value)>) -> Value {
    let o = it.new_object();
    if let Value::Obj(oo) = &o {
        let mut b = oo.borrow_mut();
        for (k, v) in props {
            b.props.insert(rcs(k), v);
        }
    }
    o
}

fn is_error_obj(v: &Value) -> bool {
    match v {
        Value::Obj(o) => matches!(o.borrow().kind, Kind::Error),
        _ => false,
    }
}

fn is_reference_error(it: &mut Interp, v: &Value) -> bool {
    if !is_error_obj(v) {
        return false;
    }
    if let Some(c) = it.error_ctors.get("ReferenceError").cloned() {
        return it.instance_of(v, &c).unwrap_or(false);
    }
    false
}

/// normalize(value) from the DSL. `frames` describes the DSL call frames above the current JS frame.
pub fn normalize(it: &mut Interp, v: &Value, frames: &[(&str, u32, u32)]) -> R<Value> {
    match v {
        Value::Undef => {
            let mut fr = vec![("normalize", 197, 15)];
            fr.extend_from_slice(frames);
            Err(Ctl::Throw(it.error_with_frames("Error", "Undefined symbol", &fr)))
        }
        Value::Str(s) => Ok(make_obj(it, vec![("type", Value::str("STRING")), ("value", Value::Str(s.clone()))])),
        Value::Obj(o) => {
            let re = match &o.borrow().kind {
                Kind::RegExp(src, flags) => Some((src.clone(), flags.clone())),
                _ => None,
            };
            if let Some((src, flags)) = re {
                let mut props = vec![("type", Value::str("PATTERN")), ("value", Value::Str(src))];
                if !flags.is_empty() {
                    props.push(("flags", Value::Str(flags)));
                }
                return Ok(make_obj(it, props));
            }
            if is_reference_error(it, v) {
                return Err(Ctl::Throw(v.clone()));
            }
            let t = it.get(v, "type")?;
            if let Value::Str(_) = t {
                return Ok(v.clone());
            }
            invalid_rule(it, v, frames)
        }
        _ => invalid_rule(it, v, frames),
    }
}

fn invalid_rule(it: &mut Interp, v: &Value, frames: &[(&str, u32, u32)]) -> R<Value> {
    let s = it.to_string(v)?;
    let mut fr = vec![("normalize", 225, 19)];
    fr.extend_from_slice(frames);
    Err(Ctl::Throw(it.error_with_frames("TypeError", &format!("Invalid rule: {}", s), &fr)))
}

fn check_arguments(it: &mut Interp, args: &[Value], rule_count: usize, caller: &str, suffix: &str, arg_type: &str) -> R<()> {
    if rule_count > 1 {
        let msg = format!(
            "The `{}` function only takes one {} argument{}.\nYou passed in multiple {}s. Did you mean to call `seq`?\n",
            caller, arg_type, suffix, arg_type
        );
        let _ = args;
        return Err(Ctl::Throw(it.make_error("Error", &msg)));
    }
    Ok(())
}

fn check_precedence(it: &mut Interp, v: &Value, frames: &[(&str, u32, u32)]) -> R<()> {
    if v.is_nullish() {
        let mut fr = vec![("checkPrecedence", 515, 15)];
        fr.extend_from_slice(frames);
        return Err(Ctl::Throw(it.error_with_frames("Error", "Missing precedence value", &fr)));
    }
    Ok(())
}

fn map_normalize(it: &mut Interp, items: &[Value], frames: &[(&str, u32, u32)]) -> R<Vec<Value>> {
    let mut fr = vec![("map", 0, 0)];
    fr.extend_from_slice(frames);
    let mut out = Vec::new();
    for x in items {
        out.push(normalize(it, x, &fr)?);
    }
    Ok(out)
}

pub fn sym(it: &mut Interp, name: &str) -> Value {
    make_obj(it, vec![("type", Value::str("SYMBOL")), ("name", Value::str(name))])
}

pub fn rule_builder_get(it: &mut Interp, rules: Option<Rc<HashSet<String>>>, key: &str) -> R<Value> {
    let symbol = sym(it, key);
    match rules {
        None => Ok(symbol),
        Some(r) => {
            if r.contains(key) {
                Ok(symbol)
            } else {
                let e = it.error_with_frames("ReferenceError", &format!("Undefined symbol '{}'", key), &[("get", 238, 27)]);
                it.set(&e, "symbol", symbol)?;
                Ok(e)
            }
        }
    }
}

fn rule_builder(it: &mut Interp, rules: Option<Rc<HashSet<String>>>) -> Value {
    let mut d = ObjData::new(Kind::RuleBuilder(rules));
    d.proto = Some(it.object_proto.clone());
    Value::Obj(Rc::new(std::cell::RefCell::new(d)))
}

fn def(it: &mut Interp, target: Option<&Value>, name: &str, f: NativeFn) -> Value {
    let fv = it.native_fn(name, f);
    match target {
        Some(t) => {
            let short = name.rsplit('.').next().unwrap();
            if let Value::Obj(o) = t {
                o.borrow_mut().props.insert(rcs(short), fv.clone());
            }
        }
        None => {
            it.global.borrow_mut().vars.insert(rcs(name), (fv.clone(), false));
        }
    }
    fv
}

pub fn install(it: &mut Interp) {
    def(it, None, "alias", Rc::new(|it: &mut Interp, _, args| {
        let rule = arg(&args, 0);
        let value = arg(&args, 1);
        let content = normalize(it, &rule, &[("alias", 4, 24)])?;
        let mk = |it: &mut Interp, named: bool, v: Value| make_obj(it, vec![("type", Value::str("ALIAS")), ("content", content.clone()), ("named", Value::Bool(named)), ("value", v)]);
        match &value {
            Value::Str(s) => return Ok(mk(it, false, Value::Str(s.clone()))),
            Value::Obj(_) => {
                if is_reference_error(it, &value) {
                    let symbol = it.get(&value, "symbol")?;
                    let name = it.get(&symbol, "name")?;
                    return Ok(mk(it, true, name));
                }
                if !is_error_obj(&value) && !value.is_regexp() && !value.is_array() && !value.is_function() {
                    let t = it.get(&value, "type")?;
                    if let Value::Str(t) = t {
                        if &*t == "SYMBOL" {
                            let name = it.get(&value, "name")?;
                            return Ok(mk(it, true, name));
                        }
                    }
                }
            }
            _ => {}
        }
        let vs = match &value {
            Value::Undef => "undefined".to_string(),
            _ => it.to_string(&value)?.to_string(),
        };
        Err(Ctl::Throw(it.error_with_frames("Error", &format!("Invalid alias value {}", vs), &[("alias", 27, 13)])))
    }));
    def(it, None, "blank", Rc::new(|it: &mut Interp, _, _| Ok(make_obj(it, vec![("type", Value::str("BLANK"))]))));
    def(it, None, "field", Rc::new(|it: &mut Interp, _, args| {
        let name = arg(&args, 0);
        let content = normalize(it, &arg(&args, 1), &[("field", 40, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("FIELD")), ("name", name), ("content", content)]))
    }));
    def(it, None, "choice", Rc::new(|it: &mut Interp, _, args| {
        let members = map_normalize(it, &args, &[("choice", 47, 27)])?;
        let arr = it.new_array(members);
        Ok(make_obj(it, vec![("type", Value::str("CHOICE")), ("members", arr)]))
    }));
    def(it, None, "optional", Rc::new(|it: &mut Interp, _, args| {
        check_arguments(it, &args, args.len(), "optional", "", "rule")?;
        let blank = make_obj(it, vec![("type", Value::str("BLANK"))]);
        let members = map_normalize(it, &[arg(&args, 0), blank], &[("choice", 47, 27), ("optional", 53, 24)])?;
        let arr = it.new_array(members);
        Ok(make_obj(it, vec![("type", Value::str("CHOICE")), ("members", arr)]))
    }));
    let prec = def(it, None, "prec", Rc::new(|it: &mut Interp, _, args| {
        let number = arg(&args, 0);
        let rule = arg(&args, 1);
        check_precedence(it, &number, &[("prec", 57, 19)])?;
        check_arguments(it, &args, args.len().saturating_sub(1), "prec", " and a precedence argument", "rule")?;
        let content = normalize(it, &rule, &[("prec", 69, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("PREC")), ("value", number), ("content", content)]))
    }));
    for (name, ty, suffix) in [
        ("prec.left", "PREC_LEFT", " and an optional precedence argument"),
        ("prec.right", "PREC_RIGHT", " and an optional precedence argument"),
    ] {
        def(it, Some(&prec), name, Rc::new(move |it: &mut Interp, _, args| {
            let mut number = arg(&args, 0);
            let mut rule = arg(&args, 1);
            if rule.is_undef() && args.len() < 2 {
                rule = number;
                number = Value::Num(0.0);
            }
            check_precedence(it, &number, &[])?;
            check_arguments(it, &args, args.len().saturating_sub(1), name, suffix, "rule")?;
            let content = normalize(it, &rule, &[])?;
            Ok(make_obj(it, vec![("type", Value::str(ty)), ("value", number), ("content", content)]))
        }));
    }
    def(it, Some(&prec), "prec.dynamic", Rc::new(|it: &mut Interp, _, args| {
        let number = arg(&args, 0);
        let rule = arg(&args, 1);
        check_precedence(it, &number, &[])?;
        check_arguments(it, &args, args.len().saturating_sub(1), "prec.dynamic", " and a precedence argument", "rule")?;
        let content = normalize(it, &rule, &[])?;
        Ok(make_obj(it, vec![("type", Value::str("PREC_DYNAMIC")), ("value", number), ("content", content)]))
    }));
    def(it, None, "repeat", Rc::new(|it: &mut Interp, _, args| {
        check_arguments(it, &args, args.len(), "repeat", "", "rule")?;
        let content = normalize(it, &arg(&args, 0), &[("repeat", 138, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("REPEAT")), ("content", content)]))
    }));
    def(it, None, "repeat1", Rc::new(|it: &mut Interp, _, args| {
        check_arguments(it, &args, args.len(), "repeat1", "", "rule")?;
        let content = normalize(it, &arg(&args, 0), &[("repeat1", 146, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("REPEAT1")), ("content", content)]))
    }));
    def(it, None, "seq", Rc::new(|it: &mut Interp, _, args| {
        let members = map_normalize(it, &args, &[("seq", 153, 27)])?;
        let arr = it.new_array(members);
        Ok(make_obj(it, vec![("type", Value::str("SEQ")), ("members", arr)]))
    }));
    def(it, None, "sym", Rc::new(|it: &mut Interp, _, args| {
        let n = arg(&args, 0);
        Ok(make_obj(it, vec![("type", Value::str("SYMBOL")), ("name", n)]))
    }));
    def(it, None, "reserved", Rc::new(|it: &mut Interp, _, args| {
        let ws = arg(&args, 0);
        if !matches!(ws, Value::Str(_)) {
            let s = it.to_string(&ws)?;
            return Err(Ctl::Throw(it.error_with_frames("Error", &format!("Invalid reserved word set name: {}", s), &[("reserved", 166, 58)])));
        }
        let content = normalize(it, &arg(&args, 1), &[("reserved", 170, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("RESERVED")), ("content", content), ("context_name", ws)]))
    }));
    let token = def(it, None, "token", Rc::new(|it: &mut Interp, _, args| {
        check_arguments(it, &args, args.len(), "token", "", "literal")?;
        let content = normalize(it, &arg(&args, 0), &[("token", 183, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("TOKEN")), ("content", content)]))
    }));
    def(it, Some(&token), "token.immediate", Rc::new(|it: &mut Interp, _, args| {
        check_arguments(it, &args, args.len(), "token.immediate", "", "literal")?;
        let content = normalize(it, &arg(&args, 0), &[])?;
        Ok(make_obj(it, vec![("type", Value::str("IMMEDIATE_TOKEN")), ("content", content)]))
    }));
    def(it, None, "grammar", Rc::new(grammar_fn));
}

fn dsl_err(it: &mut Interp, msg: &str, line: u32, col: u32) -> Ctl {
    Ctl::Throw(it.error_with_frames("Error", msg, &[("grammar", line, col)]))
}

fn call_with_frames(it: &mut Interp, f: &Value, this: Value, args: Vec<Value>, line: u32, col: u32) -> R<Value> {
    it.push_dsl("grammar", line, col);
    it.push_native("call");
    let r = it.call(f, this, args);
    it.stack.pop();
    it.stack.pop();
    r
}

fn grammar_fn(it: &mut Interp, _this: Value, args: Vec<Value>) -> R<Value> {
    let mut base = arg(&args, 0);
    let mut options = arg(&args, 1);
    let mut inherits = Value::Undef;
    if options.is_undef() {
        options = base;
        let ex = make_obj(it, vec![("type", Value::str("PATTERN")), ("value", Value::str("\\s"))]);
        let extras = it.new_array(vec![ex]);
        let rules = it.new_object();
        let conflicts = it.new_array(vec![]);
        let externals = it.new_array(vec![]);
        let inline = it.new_array(vec![]);
        let supertypes = it.new_array(vec![]);
        let precedences = it.new_array(vec![]);
        let reserved = it.new_object();
        base = make_obj(
            it,
            vec![
                ("name", Value::Null),
                ("rules", rules),
                ("extras", extras),
                ("conflicts", conflicts),
                ("externals", externals),
                ("inline", inline),
                ("supertypes", supertypes),
                ("precedences", precedences),
                ("reserved", reserved),
            ],
        );
    } else {
        base = it.get(&base, "grammar")?;
        inherits = it.get(&base, "name")?;
    }

    // externals
    let mut externals = it.get(&base, "externals")?;
    let opt_ext = it.get(&options, "externals")?;
    if opt_ext.truthy() {
        if !opt_ext.is_function() {
            return Err(dsl_err(it, "Grammar's 'externals' property must be a function.", 270, 17));
        }
        let rb = rule_builder(it, None);
        let r = call_with_frames(it, &opt_ext, rb.clone(), vec![rb, externals.clone()], 274, 50)?;
        let items = match r.array_items() {
            Some(v) => v,
            None => return Err(dsl_err(it, "Grammar's 'externals' property must return an array of rules.", 277, 17)),
        };
        let v = map_normalize(it, &items, &[("grammar", 280, 35)])?;
        externals = it.new_array(v);
    }

    // rule map
    let mut rule_names: HashSet<String> = HashSet::new();
    let opt_rules = it.get(&options, "rules")?;
    for k in it.own_keys(&opt_rules) {
        rule_names.insert(k.to_string());
    }
    let base_rules = it.get(&base, "rules")?;
    for k in it.own_keys(&base_rules) {
        rule_names.insert(k.to_string());
    }
    for e in it.iterate(&externals)? {
        if let Ok(Value::Str(n)) = it.get(&e, "name") {
            rule_names.insert(n.to_string());
        }
    }
    let rb = rule_builder(it, Some(Rc::new(rule_names)));

    let name = it.get(&options, "name")?;
    let name_s = match &name {
        Value::Str(s) => s.clone(),
        _ => return Err(dsl_err(it, "Grammar's 'name' property must be a string.", 300, 15)),
    };
    {
        let ok = {
            let mut ch = name_s.chars();
            match ch.next() {
                Some(c) if c.is_ascii_alphabetic() || c == '_' => ch.all(|c| c.is_ascii_alphanumeric() || c == '_'),
                _ => false,
            }
        };
        if !ok {
            return Err(dsl_err(it, "Grammar's 'name' property must not start with a digit and cannot contain non-word characters.", 304, 15));
        }
    }

    // rules
    let rules = it.new_object();
    for k in it.own_keys(&base_rules) {
        let v = it.get(&base_rules, &k)?;
        it.set(&rules, &k, v)?;
    }
    if opt_rules.truthy() {
        if !matches!(opt_rules, Value::Obj(_)) {
            return Err(dsl_err(it, "Grammar's 'rules' property must be an object.", 318, 17));
        }
        for k in it.own_keys(&opt_rules) {
            let f = it.get(&opt_rules, &k)?;
            if !f.is_function() {
                return Err(dsl_err(it, &format!("Grammar rules must all be functions. '{}' rule is not.", k), 324, 19));
            }
            let prev = it.get(&base_rules, &k)?;
            let r = call_with_frames(it, &f, rb.clone(), vec![rb.clone(), prev], 326, 32)?;
            if r.is_undef() {
                return Err(dsl_err(it, &format!("Rule '{}' returned undefined.", k), 328, 19));
            }
            let n = normalize(it, &r, &[("grammar", 330, 35)])?;
            it.set(&rules, &k, n)?;
        }
    }

    // reserved
    let reserved = it.new_object();
    let base_reserved = it.get(&base, "reserved")?;
    if !base_reserved.is_nullish() {
        for k in it.own_keys(&base_reserved) {
            let v = it.get(&base_reserved, &k)?;
            it.set(&reserved, &k, v)?;
        }
    }
    let opt_reserved = it.get(&options, "reserved")?;
    if opt_reserved.truthy() {
        if !matches!(opt_reserved, Value::Obj(_)) || opt_reserved.is_function() {
            return Err(dsl_err(it, "Grammar's 'reserved' property must be an object.", 337, 17));
        }
        for k in it.own_keys(&opt_reserved) {
            let f = it.get(&opt_reserved, &k)?;
            if !f.is_function() {
                return Err(dsl_err(it, &format!("Grammar reserved word sets must all be functions. '{}' is not.", k), 343, 19));
            }
            let prev = if base_reserved.is_nullish() { Value::Undef } else { it.get(&base_reserved, &k)? };
            let r = call_with_frames(it, &f, rb.clone(), vec![rb.clone(), prev], 346, 53)?;
            let items = match r.array_items() {
                Some(v) => v,
                None => {
                    return Err(dsl_err(it, &format!("Grammar's reserved word set functions must all return arrays of rules. '{}' does not.", k), 349, 19))
                }
            };
            let v = map_normalize(it, &items, &[("grammar", 352, 50)])?;
            let arr = it.new_array(v);
            it.set(&reserved, &k, arr)?;
        }
    }

    // extras
    let base_extras = it.get(&base, "extras")?;
    let mut extras = it.new_array(base_extras.array_items().unwrap_or_default());
    let opt_extras = it.get(&options, "extras")?;
    if opt_extras.truthy() {
        if !opt_extras.is_function() {
            return Err(dsl_err(it, "Grammar's 'extras' property must be a function.", 359, 17));
        }
        let r = call_with_frames(it, &opt_extras, rb.clone(), vec![rb.clone(), base_extras.clone()], 363, 13)?;
        let items = match r.array_items() {
            Some(v) => v,
            None => return Err(dsl_err(it, "Grammar's 'extras' function must return an array.", 366, 17)),
        };
        let v = map_normalize(it, &items, &[("grammar", 369, 27)])?;
        extras = it.new_array(v);
    }

    // word
    let mut word = it.get(&base, "word")?;
    let opt_word = it.get(&options, "word")?;
    if opt_word.truthy() {
        if !opt_word.is_function() {
            return Err(dsl_err(it, "Grammar's 'word' property must be a function.", 372, 17));
        }
        let r = call_with_frames(it, &opt_word, rb.clone(), vec![rb.clone()], 374, 30)?;
        word = it.get(&r, "name")?;
        match &word {
            Value::Str(s) => {
                if &**s == "ReferenceError" {
                    return Err(dsl_err(it, "Grammar's 'word' property must be a valid rule name.", 380, 17));
                }
            }
            _ => return Err(dsl_err(it, "Grammar's 'word' property must be a named rule.", 376, 17)),
        }
    }

    // conflicts
    let mut conflicts = it.get(&base, "conflicts")?;
    let opt_conflicts = it.get(&options, "conflicts")?;
    if opt_conflicts.truthy() {
        if !opt_conflicts.is_function() {
            return Err(dsl_err(it, "Grammar's 'conflicts' property must be a function.", 387, 17));
        }
        let mut base_conf = Vec::new();
        for c in it.iterate(&conflicts)? {
            let mut syms = Vec::new();
            for n in it.iterate(&c)? {
                let ns = it.to_string(&n)?;
                syms.push(sym(it, &ns));
            }
            base_conf.push(it.new_array(syms));
        }
        let bc = it.new_array(base_conf);
        let r = call_with_frames(it, &opt_conflicts, rb.clone(), vec![rb.clone(), bc], 391, 50)?;
        let items = match r.array_items() {
            Some(v) => v,
            None => return Err(dsl_err(it, "Grammar's conflicts must be an array of arrays of rules.", 394, 17)),
        };
        let mut out = Vec::new();
        for set in items {
            let syms = match set.array_items() {
                Some(v) => v,
                None => {
                    return Err(Ctl::Throw(it.error_with_frames(
                        "Error",
                        "Grammar's conflicts must be an array of arrays of rules.",
                        &[("<anonymous>", 399, 19), ("map", 0, 0), ("grammar", 397, 35)],
                    )))
                }
            };
            let mut names = Vec::new();
            for s in syms {
                let n = normalize(it, &s, &[("<anonymous>", 402, 40), ("map", 0, 0), ("<anonymous>", 402, 25), ("map", 0, 0), ("grammar", 397, 35)])?;
                names.push(it.get(&n, "name")?);
            }
            out.push(it.new_array(names));
        }
        conflicts = it.new_array(out);
    }

    // inline
    let mut inline = it.get(&base, "inline")?;
    let opt_inline = it.get(&options, "inline")?;
    if opt_inline.truthy() {
        if !opt_inline.is_function() {
            return Err(dsl_err(it, "Grammar's 'inline' property must be a function.", 409, 17));
        }
        let mut base_inl = Vec::new();
        for n in it.iterate(&inline)? {
            let ns = it.to_string(&n)?;
            base_inl.push(sym(it, &ns));
        }
        let bi = it.new_array(base_inl);
        let r = call_with_frames(it, &opt_inline, rb.clone(), vec![rb.clone(), bi], 413, 45)?;
        let items = match r.array_items() {
            Some(v) => v,
            None => return Err(dsl_err(it, "Grammar's inline must be an array of rules.", 416, 17)),
        };
        let mut names: Vec<Value> = Vec::new();
        let mut all_names: Vec<Value> = Vec::new();
        for s in &items {
            all_names.push(it.get(s, "name")?);
        }
        for (i, s) in items.iter().enumerate() {
            let n = all_names[i].clone();
            let first = all_names.iter().position(|x| it.strict_eq(x, &n)).unwrap();
            if first != i {
                let ns = it.to_string(&n)?;
                eprintln!("Warning: duplicate inline rule '{}'", ns);
                continue;
            }
            if let Value::Str(ns) = &n {
                if &**ns == "ReferenceError" {
                    let symbol = it.get(s, "symbol")?;
                    let sn = it.get(&symbol, "name")?;
                    let sn = it.to_string(&sn)?;
                    eprintln!("Warning: inline rule '{}' is not defined.", sn);
                    continue;
                }
            }
            names.push(n);
        }
        inline = it.new_array(names);
    }

    // supertypes
    let mut supertypes = it.get(&base, "supertypes")?;
    let opt_super = it.get(&options, "supertypes")?;
    if opt_super.truthy() {
        if !opt_super.is_function() {
            return Err(dsl_err(it, "Grammar's 'supertypes' property must be a function.", 435, 17));
        }
        let mut base_sup = Vec::new();
        for n in it.iterate(&supertypes)? {
            let ns = it.to_string(&n)?;
            base_sup.push(sym(it, &ns));
        }
        let bs = it.new_array(base_sup);
        let r = call_with_frames(it, &opt_super, rb.clone(), vec![rb.clone(), bs], 439, 52)?;
        let items = match r.array_items() {
            Some(v) => v,
            None => return Err(dsl_err(it, "Grammar's supertypes must be an array of rules.", 442, 17)),
        };
        let mut names = Vec::new();
        for s in items {
            let n = it.get(&s, "name")?;
            if let Value::Str(ns) = &n {
                if &**ns == "ReferenceError" {
                    let symbol = it.get(&s, "symbol")?;
                    let sn = it.get(&symbol, "name")?;
                    let sn = it.to_string(&sn)?;
                    return Err(Ctl::Throw(it.error_with_frames(
                        "Error",
                        &format!("Supertype rule `{}` is not defined.", sn),
                        &[("<anonymous>", 447, 19), ("map", 0, 0), ("grammar", 445, 37)],
                    )));
                }
            }
            names.push(n);
        }
        supertypes = it.new_array(names);
    }

    // precedences
    let mut precedences = it.get(&base, "precedences")?;
    let opt_prec = it.get(&options, "precedences")?;
    if opt_prec.truthy() {
        if !opt_prec.is_function() {
            return Err(dsl_err(it, "Grammar's 'precedences' property must be a function.", 456, 17));
        }
        let r = call_with_frames(it, &opt_prec, rb.clone(), vec![rb.clone(), precedences.clone()], 458, 44)?;
        let items = match r.array_items() {
            Some(v) => v,
            None => return Err(dsl_err(it, "Grammar's precedences must be an array of arrays of rules.", 460, 17)),
        };
        let mut out = Vec::new();
        for list in items {
            let l = match list.array_items() {
                Some(v) => v,
                None => {
                    return Err(Ctl::Throw(it.error_with_frames(
                        "Error",
                        "Grammar's precedences must be an array of arrays of rules.",
                        &[("<anonymous>", 464, 19), ("map", 0, 0), ("grammar", 462, 35)],
                    )))
                }
            };
            let v = map_normalize(it, &l, &[("<anonymous>", 466, 23), ("map", 0, 0), ("grammar", 462, 35)])?;
            out.push(it.new_array(v));
        }
        precedences = it.new_array(out);
    }

    if it.own_keys(&rules).is_empty() {
        return Err(dsl_err(it, "Grammar must have at least one rule.", 471, 15));
    }

    let g = make_obj(
        it,
        vec![
            ("name", name),
            ("inherits", inherits),
            ("word", word),
            ("rules", rules),
            ("extras", extras),
            ("conflicts", conflicts),
            ("precedences", precedences),
            ("externals", externals),
            ("inline", inline),
            ("supertypes", supertypes),
            ("reserved", reserved),
        ],
    );
    Ok(make_obj(it, vec![("grammar", g)]))
}
