/// Evaluate a grammar.js file and return the JSON text that the grammar produces
/// (as JSON.stringify(..., null, 2) of the grammar object with a "$schema" key).
pub fn load_grammar_js(path: &Path) -> Result<String, String> {
    let src = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
    let dir = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    let dir = if dir.as_os_str().is_empty() { std::path::PathBuf::from(".") } else { dir };
