// Native implementation of the tree-sitter grammar DSL.
use super::interp::*;
use super::value::*;
use std::collections::HashSet;
use std::rc::Rc;

fn rcs(s: &str) -> Rc<str> {
    Rc::from(s)
}

fn arg(args: &[Value], i: usize) -> Value {
    args.get(i).cloned().unwrap_or(Value::Undef)
}

const DSL_NAMES: &[&str] = &[
    "grammar", "seq", "choice", "repeat", "repeat1", "optional", "prec", "prec.left", "prec.right",
    "prec.dynamic", "token", "token.immediate", "alias", "field", "blank", "sym", "reserved",
];

pub fn is_dsl_name(n: &str) -> bool {
    DSL_NAMES.contains(&n)
}

pub fn make_obj(it: &mut Interp, props: Vec<(&str, Value)>) -> Value {
    let o = it.new_object();
    if let Value::Obj(oo) = &o {
        let mut b = oo.borrow_mut();
        for (k, v) in props {
            b.props.insert(rcs(k), v);
        }
    }
    o
}

fn is_error_obj(v: &Value) -> bool {
    match v {
        Value::Obj(o) => matches!(o.borrow().kind, Kind::Error),
        _ => false,
    }
}

fn is_reference_error(it: &mut Interp, v: &Value) -> bool {
    if !is_error_obj(v) {
        return false;
    }
    if let Some(c) = it.error_ctors.get("ReferenceError").cloned() {
        return it.instance_of(v, &c).unwrap_or(false);
    }
    false
}

/// normalize(value) from the DSL. `frames` describes the DSL call frames above the current JS frame.
pub fn normalize(it: &mut Interp, v: &Value, frames: &[(&str, u32, u32)]) -> R<Value> {
    match v {
        Value::Undef => {
            let mut fr = vec![("normalize", 197, 15)];
            fr.extend_from_slice(frames);
            Err(Ctl::Throw(it.error_with_frames("Error", "Undefined symbol", &fr)))
        }
        Value::Str(s) => Ok(make_obj(it, vec![("type", Value::str("STRING")), ("value", Value::Str(s.clone()))])),
        Value::Obj(o) => {
            let re = match &o.borrow().kind {
                Kind::RegExp(src, flags) => Some((src.clone(), flags.clone())),
                _ => None,
            };
            if let Some((src, flags)) = re {
                let mut props = vec![("type", Value::str("PATTERN")), ("value", Value::Str(src))];
                if !flags.is_empty() {
                    props.push(("flags", Value::Str(flags)));
                }
                return Ok(make_obj(it, props));
            }
            if is_reference_error(it, v) {
                return Err(Ctl::Throw(v.clone()));
            }
            let t = it.get(v, "type")?;
            if let Value::Str(_) = t {
                return Ok(v.clone());
            }
            invalid_rule(it, v, frames)
        }
        _ => invalid_rule(it, v, frames),
    }
}

fn invalid_rule(it: &mut Interp, v: &Value, frames: &[(&str, u32, u32)]) -> R<Value> {
    let s = it.to_string(v)?;
    let mut fr = vec![("normalize", 225, 19)];
    fr.extend_from_slice(frames);
    Err(Ctl::Throw(it.error_with_frames("TypeError", &format!("Invalid rule: {}", s), &fr)))
}

fn check_arguments(it: &mut Interp, args: &[Value], rule_count: usize, caller: &str, suffix: &str, arg_type: &str) -> R<()> {
    if rule_count > 1 {
        let msg = format!(
            "The `{}` function only takes one {} argument{}.\nYou passed in multiple {}s. Did you mean to call `seq`?\n",
            caller, arg_type, suffix, arg_type
        );
        let _ = args;
        return Err(Ctl::Throw(it.make_error("Error", &msg)));
    }
    Ok(())
}

fn check_precedence(it: &mut Interp, v: &Value, frames: &[(&str, u32, u32)]) -> R<()> {
    if v.is_nullish() {
        let mut fr = vec![("checkPrecedence", 515, 15)];
        fr.extend_from_slice(frames);
        return Err(Ctl::Throw(it.error_with_frames("Error", "Missing precedence value", &fr)));
    }
    Ok(())
}

fn map_normalize(it: &mut Interp, items: &[Value], frames: &[(&str, u32, u32)]) -> R<Vec<Value>> {
    let mut fr = vec![("map", 0, 0)];
    fr.extend_from_slice(frames);
    let mut out = Vec::new();
    for x in items {
        out.push(normalize(it, x, &fr)?);
    }
    Ok(out)
}

pub fn sym(it: &mut Interp, name: &str) -> Value {
    make_obj(it, vec![("type", Value::str("SYMBOL")), ("name", Value::str(name))])
}

pub fn rule_builder_get(it: &mut Interp, rules: Option<Rc<HashSet<String>>>, key: &str) -> R<Value> {
    let symbol = sym(it, key);
    match rules {
        None => Ok(symbol),
        Some(r) => {
            if r.contains(key) {
                Ok(symbol)
            } else {
                let e = it.error_with_frames("ReferenceError", &format!("Undefined symbol '{}'", key), &[("get", 238, 27)]);
                it.set(&e, "symbol", symbol)?;
                Ok(e)
            }
        }
    }
}

fn rule_builder(it: &mut Interp, rules: Option<Rc<HashSet<String>>>) -> Value {
    let mut d = ObjData::new(Kind::RuleBuilder(rules));
    d.proto = Some(it.object_proto.clone());
    Value::Obj(Rc::new(std::cell::RefCell::new(d)))
}

fn def(it: &mut Interp, target: Option<&Value>, name: &str, f: NativeFn) -> Value {
    let fv = it.native_fn(name, f);
    match target {
        Some(t) => {
            let short = name.rsplit('.').next().unwrap();
            if let Value::Obj(o) = t {
                o.borrow_mut().props.insert(rcs(short), fv.clone());
            }
        }
        None => {
            it.global.borrow_mut().vars.insert(rcs(name), (fv.clone(), false));
        }
    }
    fv
}

pub fn install(it: &mut Interp) {
    def(it, None, "alias", Rc::new(|it: &mut Interp, _, args| {
        let rule = arg(&args, 0);
        let value = arg(&args, 1);
        let content = normalize(it, &rule, &[("alias", 4, 24)])?;
        let mk = |it: &mut Interp, named: bool, v: Value| make_obj(it, vec![("type", Value::str("ALIAS")), ("content", content.clone()), ("named", Value::Bool(named)), ("value", v)]);
        match &value {
            Value::Str(s) => return Ok(mk(it, false, Value::Str(s.clone()))),
            Value::Obj(_) => {
                if is_reference_error(it, &value) {
                    let symbol = it.get(&value, "symbol")?;
                    let name = it.get(&symbol, "name")?;
                    return Ok(mk(it, true, name));
                }
                if !is_error_obj(&value) && !value.is_regexp() && !value.is_array() && !value.is_function() {
                    let t = it.get(&value, "type")?;
                    if let Value::Str(t) = t {
                        if &*t == "SYMBOL" {
                            let name = it.get(&value, "name")?;
                            return Ok(mk(it, true, name));
                        }
                    }
                }
            }
            _ => {}
        }
        let vs = match &value {
            Value::Undef => "undefined".to_string(),
            _ => it.to_string(&value)?.to_string(),
        };
        Err(Ctl::Throw(it.error_with_frames("Error", &format!("Invalid alias value {}", vs), &[("alias", 27, 13)])))
    }));
    def(it, None, "blank", Rc::new(|it: &mut Interp, _, _| Ok(make_obj(it, vec![("type", Value::str("BLANK"))]))));
    def(it, None, "field", Rc::new(|it: &mut Interp, _, args| {
        let name = arg(&args, 0);
        let content = normalize(it, &arg(&args, 1), &[("field", 40, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("FIELD")), ("name", name), ("content", content)]))
    }));
    def(it, None, "choice", Rc::new(|it: &mut Interp, _, args| {
        let members = map_normalize(it, &args, &[("choice", 47, 27)])?;
        let arr = it.new_array(members);
        Ok(make_obj(it, vec![("type", Value::str("CHOICE")), ("members", arr)]))
    }));
