        let number = arg(&args, 0);
        let rule = arg(&args, 1);
        check_precedence(it, &number, &[("prec", 57, 19)])?;
        check_arguments(it, &args, args.len().saturating_sub(1), "prec", " and a precedence argument", "rule")?;
        let content = normalize(it, &rule, &[("prec", 69, 24)])?;
        Ok(make_obj(it, vec![("type", Value::str("PREC")), ("value", number), ("content", content)]))
    }));
    for (name, ty, suffix) in [
        ("prec.left", "PREC_LEFT", " and an optional precedence argument"),
        ("prec.right", "PREC_RIGHT", " and an optional precedence argument"),
    ] {
        def(it, Some(&prec), name, Rc::new(move |it: &mut Interp, _, args| {
            let mut number = arg(&args, 0);
            let mut rule = arg(&args, 1);
            if rule.is_undef() && args.len() < 2 {
                rule = number;
                number = Value::Num(0.0);
            }
            check_precedence(it, &number, &[])?;
            check_arguments(it, &args, args.len().saturating_sub(1), name, suffix, "rule")?;
            let content = normalize(it, &rule, &[])?;
            Ok(make_obj(it, vec![("type", Value::str(ty)), ("value", number), ("content", content)]))
        }));
    }
    def(it, Some(&prec), "prec.dynamic", Rc::new(|it: &mut Interp, _, args| {
        let number = arg(&args, 0);
        let rule = arg(&args, 1);
        check_precedence(it, &number, &[])?;
        check_arguments(it, &args, args.len().saturating_sub(1), "prec.dynamic", " and a precedence argument", "rule")?;
        let content = normalize(it, &rule, &[])?;
        Ok(make_obj(it, vec![("type", Value::str("PREC_DYNAMIC")), ("value", number), ("content", content)]))
    }));
