pub mod ast;
pub mod builtins;
pub mod dsl;
pub mod interp;
pub mod lexer;
pub mod parser;
pub mod value;

use std::path::Path;
use value::*;

/// Evaluate a grammar.js file and return the JSON text that the grammar produces
/// (as JSON.stringify(..., null, 2) of the grammar object with a "$schema" key).
pub fn load_grammar_js(path: &Path) -> Result<String, String> {
    let src = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
    let dir = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    let dir = if dir.as_os_str().is_empty() { std::path::PathBuf::from(".") } else { dir };
    let mut it = interp::Interp::new(dir);
    let fname = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| "grammar.js".into());
    it.cur_file = std::rc::Rc::from(fname.as_str());
    let r = it.eval_module_source(&src, &fname);
    let exports = match r {
        Ok(v) => v,
        Err(Ctl::Throw(e)) => return Err(format_exception(&mut it, &e)),
        Err(_) => return Err("QuickJS error: Expected a JS exception".into()),
    };
    // default export or module.exports
    let def = it.get(&exports, "default").unwrap_or(Value::Undef);
    let g = if def.is_undef() { exports } else { def };
    let inner = match &g {
        Value::Obj(_) => it.get(&g, "grammar").unwrap_or(Value::Undef),
        _ => Value::Undef,
    };
    let obj = it.new_object();
    let _ = it.set(&obj, "$schema", Value::str("https://tree-sitter.github.io/tree-sitter/assets/schemas/grammar.schema.json"));
    if let Value::Obj(_) = &inner {
        for k in it.own_keys(&inner) {
            let v = it.get(&inner, &k).unwrap_or(Value::Undef);
            let _ = it.set(&obj, &k, v);
        }
    }
    let mut out = String::new();
    match builtins::json_stringify(&mut it, &obj, "  ", "", &mut out) {
        Ok(_) => Ok(out),
        Err(Ctl::Throw(e)) => Err(format_exception(&mut it, &e)),
        Err(_) => Err("QuickJS error: Expected a JS exception".into()),
    }
}

fn format_exception(it: &mut interp::Interp, e: &Value) -> String {
    if let Value::Obj(o) = e {
        if matches!(o.borrow().kind, Kind::Error) {
            let msg = it.get(e, "message").unwrap_or(Value::Undef);
            let msg = if msg.is_undef() { String::new() } else { it.to_string(&msg).map(|s| s.to_string()).unwrap_or_default() };
            let stack = it.get(e, "stack").unwrap_or(Value::Undef);
            let stack = if stack.is_undef() { String::new() } else { it.to_string(&stack).map(|s| s.to_string()).unwrap_or_default() };
            let name = it.get(e, "name").unwrap_or(Value::Undef);
            let name = it.to_string(&name).map(|s| s.to_string()).unwrap_or_default();
            return format!("QuickJS error: Message: {}\nStack: {}\nType: {}", msg, stack, name);
        }
    }
    "QuickJS error: Expected a JS exception".to_string()
}
