        for (i, range) in set.ranges().enumerate() {
            if i > 0 {
                write!(f, ", ")?;
            }
            write!(f, "{:?}", range.start())?;
            if range.end() != range.start() {
                write!(f, "-{:?}", range.end())?;
            }
        }
