    }

    /// Produces a `CharacterSet` containing every character that is in _exactly one_ of `self` or `other`, but is not present in both sets.
    pub fn symmetric_difference(mut self, mut other: Self) -> Self {
        self.remove_intersection(&mut other);
        self.add(&other)
