{"command":"cat > /workspace/src/generate/parse_grammar.rs <<'EOF'
use super::grammar_json::{GrammarJSON, PrecedenceValueJSON, RuleJSON};
use super::grammars::{InputGrammar, PrecedenceEntry, ReservedWordContext, Variable, VariableType};
use super::rules::{Precedence, Rule};
use anyhow::{anyhow, Result};
use std::collections::HashSet;

fn rule_from_json(rule: &RuleJSON) -> Result<Rule> {
    Ok(match rule {
        RuleJSON::ALIAS { content, value, named } => {
            if value.is_empty() {
                return Err(anyhow!("Rules in the `alias` function cannot be empty"));
            }
            Rule::alias(rule_from_json(content)?, value.clone(), *named)
        }
        RuleJSON::BLANK => Rule::Blank,
        RuleJSON::STRING { value } => Rule::String(value.clone()),
        RuleJSON::PATTERN { value, flags } => Rule::Pattern(
            value.clone(),
            flags.as_ref().map_or(String::new(), |f| f.matches(|c| c != 'u').collect()),
        ),
        RuleJSON::SYMBOL { name } => Rule::NamedSymbol(name.clone()),
        RuleJSON::CHOICE { members } => Rule::choice(members.iter().map(rule_from_json).collect::<Result<_>>()?),
        RuleJSON::FIELD { content, name } => Rule::field(name.clone(), rule_from_json(content)?),
        RuleJSON::SEQ { members } => Rule::seq(members.iter().map(rule_from_json).collect::<Result<_>>()?),
        RuleJSON::REPEAT1 { content } => Rule::repeat(rule_from_json(content)?),
        RuleJSON::REPEAT { content } => Rule::choice(vec![Rule::repeat(rule_from_json(content)?), Rule::Blank]),
        RuleJSON::PREC { value, content } => Rule::prec(prec_value(value), rule_from_json(content)?),
        RuleJSON::PREC_LEFT { value, content } => Rule::prec_left(prec_value(value), rule_from_json(content)?),
        RuleJSON::PREC_RIGHT { value, content } => Rule::prec_right(prec_value(value), rule_from_json(content)?),
        RuleJSON::PREC_DYNAMIC { value, content } => Rule::prec_dynamic(*value, rule_from_json(content)?),
        RuleJSON::TOKEN { content } => Rule::token(rule_from_json(content)?),
        RuleJSON::IMMEDIATE_TOKEN { content } => Rule::immediate_token(rule_from_json(content)?),
        RuleJSON::RESERVED { context_name, content } => Rule::Reserved { rule: Box::new(rule_from_json(content)?), context_name: context_name.clone() },
    })
}

fn prec_value(v: &PrecedenceValueJSON) -> Precedence {
    match v {
        PrecedenceValueJSON::Integer(i) => Precedence::Integer(*i),
        PrecedenceValueJSON::Name(s) => Precedence::Name(s.clone()),
    }
}

fn collect_symbol_names(rule: &RuleJSON, out: &mut Vec<String>) {
    match rule {
        RuleJSON::SYMBOL { name } => out.push(name.clone()),
        RuleJSON::ALIAS { content, .. }
        | RuleJSON::FIELD { content, .. }
        | RuleJSON::REPEAT { content }
        | RuleJSON::REPEAT1 { content }
        | RuleJSON::PREC { content, .. }
        | RuleJSON::PREC_LEFT { content, .. }
        | RuleJSON::PREC_RIGHT { content, .. }
        | RuleJSON::PREC_DYNAMIC { content, .. }
        | RuleJSON::TOKEN { content }
        | RuleJSON::IMMEDIATE_TOKEN { content }
        | RuleJSON::RESERVED { content, .. } => collect_symbol_names(content, out),
        RuleJSON::CHOICE { members } | RuleJSON::SEQ { members } => {
            for m in members {
                collect_symbol_names(m, out);
            }
        }
        _ => {}
    }
}

pub fn parse_grammar(grammar_json: &GrammarJSON) -> Result<InputGrammar> {
    // Determine which rules are reachable.
    let mut reachable: HashSet<String> = HashSet::new();
    let mut queue: Vec<String> = Vec::new();
    if let Some((first, _)) = grammar_json.rules.first() {
        queue.push(first.clone());
    }
    for extra in &grammar_json.extras {
        collect_symbol_names(extra, &mut queue);
    }
    for ext in &grammar_json.externals {
        collect_symbol_names(ext, &mut queue);
    }
    if let Some(w) = &grammar_json.word {
        queue.push(w.clone());
    }
    for words in grammar_json.reserved.values() {
        for w in words {
            collect_symbol_names(w, &mut queue);
        }
    }
    while let Some(name) = queue.pop() {
        if reachable.contains(&name) {
            continue;
        }
        if let Some(rule) = grammar_json.rules.get(&name) {
            reachable.insert(name.clone());
            collect_symbol_names(rule, &mut queue);
        }
    }

    let mut variables = Vec::new();
    for (name, value) in &grammar_json.rules {
        if !reachable.contains(name) {
            continue;
        }
        variables.push(Variable { name: name.clone(), kind: VariableType::Named, rule: rule_from_json(value)? });
    }

    let mut precedence_orderings = Vec::with_capacity(grammar_json.precedences.len());
    for list in &grammar_json.precedences {
        let mut ordering = Vec::with_capacity(list.len());
        for entry in list {
            ordering.push(match entry {
                RuleJSON::STRING { value } => PrecedenceEntry::Name(value.clone()),
                RuleJSON::SYMBOL { name } => PrecedenceEntry::Symbol(name.clone()),
                _ => {
                    return Err(anyhow!("Invalid rule in precedences array. Only strings and symbols are allowed"));
                }
            });
        }
        precedence_orderings.push(ordering);
    }

    let extra_symbols = grammar_json.extras.iter().map(rule_from_json).collect::<Result<Vec<_>>>()?;
    let external_tokens = grammar_json.externals.iter().map(rule_from_json).collect::<Result<Vec<_>>>()?;

    let mut reserved_words = Vec::new();
    for (name, words) in &grammar_json.reserved {
        let mut rws = Vec::new();
        for w in words {
            rws.push(rule_from_json(w)?);
        }
        reserved_words.push(ReservedWordContext { name: name.clone(), reserved_words: rws });
    }

    Ok(InputGrammar {
        name: grammar_json.name.clone(),
        word_token: grammar_json.word.clone(),
        expected_conflicts: grammar_json.conflicts.clone(),
        supertype_symbols: grammar_json.supertypes.clone(),
        variables_to_inline: grammar_json.inline.clone(),
        precedence_orderings,
        variables,
        extra_symbols,
        external_tokens,
        reserved_words,
    })
}
