struct Interner<'a> {
    grammar: &'a InputGrammar,
}

impl Interner<'_> {
    fn intern_rule(&self, rule: &Rule, name: Option<&str>) -> Result<Rule> {
        match rule {
            Rule::Choice(elements) => {
                self.check_single(elements, name)?;
                let mut result = Vec::with_capacity(elements.len());
                for element in elements {
                    result.push(self.intern_rule(element, name)?);
                }
                Ok(Rule::Choice(result))
            }
            Rule::Seq(elements) => {
                self.check_single(elements, name)?;
                let mut result = Vec::with_capacity(elements.len());
                for element in elements {
                    result.push(self.intern_rule(element, name)?);
                }
                Ok(Rule::Seq(result))
            }
            Rule::Repeat(content) => Ok(Rule::Repeat(Box::new(self.intern_rule(content, name)?))),
            Rule::Metadata { rule, params } => Ok(Rule::Metadata { rule: Box::new(self.intern_rule(rule, name)?), params: params.clone() }),
            Rule::Reserved { rule, context_name } => Ok(Rule::Reserved { rule: Box::new(self.intern_rule(rule, name)?), context_name: context_name.clone() }),
            Rule::NamedSymbol(name) => self.intern_name(name).map_or_else(|| Err(anyhow!("Undefined symbol `{}`", name)), |symbol| Ok(Rule::Symbol(symbol))),
            _ => Ok(rule.clone()),
        }
    }

    fn intern_name(&self, symbol: &str) -> Option<Symbol> {
        for (i, variable) in self.grammar.variables.iter().enumerate() {
            if variable.name == symbol {
                return Some(Symbol::non_terminal(i));
            }
        }

        for (i, external_token) in self.grammar.external_tokens.iter().enumerate() {
            if let Rule::NamedSymbol(name) = external_token {
                if name == symbol {
                    return Some(Symbol::external(i));
                }
            }
        }

        None
    }

    // Check if the rule is a single-element choice or sequence.
    fn check_single(&self, elements: &[Rule], name: Option<&str>) -> Result<()> {
        if elements.len() == 1 && matches!(elements[0], Rule::String(_) | Rule::Pattern(_, _)) {
            if let Some(name) = name {
                let _ = name;
            }
        }
        Ok(())
    }
}

pub fn variable_type_for_name(name: &str) -> VariableType {
    if name.starts_with('_') {
        VariableType::Hidden
    } else {
        VariableType::Named
    }
}
