{"command":"cat > /workspace/src/generate/prepare_grammar/extract_tokens.rs <<'EOF'
use super::{ExtractedLexicalGrammar, ExtractedSyntaxGrammar, InternedGrammar};
use crate::generate::grammars::{ExternalToken, ReservedWordContext, Variable, VariableType};
use crate::generate::rules::{MetadataParams, Rule, Symbol, SymbolType};
use anyhow::{anyhow, Result};
use std::collections::HashMap;

pub fn extract_tokens(mut grammar: InternedGrammar) -> Result<(ExtractedSyntaxGrammar, ExtractedLexicalGrammar)> {
    let mut extractor = TokenExtractor {
        current_variable_name: String::new(),
        current_variable_token_count: 0,
        is_first_rule: false,
        extracted_variables: Vec::new(),
        extracted_usage_counts: Vec::new(),
    };

    // The word token is extracted first, so that it receives the lowest token index.
    let word_index = grammar.word_token.and_then(|w| if w.is_non_terminal() { Some(w.index) } else { None });
    if let Some(wi) = word_index {
        if wi > 0 {
            let variable = &mut grammar.variables[wi];
            extractor.extract_tokens_in_variable(variable)?;
        }
    }
    for (i, variable) in grammar.variables.iter_mut().enumerate() {
        if Some(i) == word_index && i > 0 {
            continue;
        }
        extractor.is_first_rule = i == 0;
        extractor.extract_tokens_in_variable(variable)?;
    }

    for variable in &mut grammar.external_tokens {
        extractor.extract_tokens_in_variable(variable)?;
    }

    let mut lexical_variables = Vec::with_capacity(extractor.extracted_variables.len());
    for variable in extractor.extracted_variables {
        lexical_variables.push(variable);
    }

    // If a variable's entire rule is just a single token, and that token is used only
    // once, then replace the variable with that token.
    let mut symbol_replacer = SymbolReplacer { replacements: HashMap::new() };
    let mut variables = Vec::with_capacity(grammar.variables.len());
    for (i, variable) in grammar.variables.into_iter().enumerate() {
        if let Rule::Symbol(Symbol { kind: SymbolType::Terminal, index }) = variable.rule {
            if i > 0 && extractor.extracted_usage_counts[index] == 1 {
                let lexical_variable = &mut lexical_variables[index];
                if lexical_variable.kind == VariableType::Auxiliary || variable.kind != VariableType::Hidden {
                    lexical_variable.kind = variable.kind;
                    lexical_variable.name = variable.name;
                    symbol_replacer.replacements.insert(i, index);
                    continue;
                }
            }
        }
        variables.push(variable);
    }

    for variable in &mut variables {
        variable.rule = symbol_replacer.replace_symbols_in_rule(&variable.rule);
    }

    let expected_conflicts = grammar
        .expected_conflicts
        .into_iter()
        .map(|conflict| {
            let mut result: Vec<_> = conflict.iter().map(|symbol| symbol_replacer.replace_symbol(*symbol)).collect();
            result.sort_unstable();
            result.dedup();
            result
        })
        .collect();

    let supertype_symbols = grammar.supertype_symbols.into_iter().map(|symbol| symbol_replacer.replace_symbol(symbol)).collect();

    let variables_to_inline = grammar.variables_to_inline.into_iter().map(|symbol| symbol_replacer.replace_symbol(symbol)).collect();

    let mut separators = Vec::new();
    let mut extra_symbols = Vec::new();
    for rule in grammar.extra_symbols {
        if let Rule::Symbol(symbol) = rule {
            extra_symbols.push(symbol_replacer.replace_symbol(symbol));
        } else if let Some(index) = lexical_variables.iter().position(|v| v.rule == rule) {
            extra_symbols.push(Symbol::terminal(index));
        } else {
            separators.push(rule);
        }
    }

    let mut external_tokens = Vec::new();
    for external_token in grammar.external_tokens {
        let rule = symbol_replacer.replace_symbols_in_rule(&external_token.rule);
        if let Rule::Symbol(symbol) = rule {
            if symbol.is_non_terminal() {
                return Err(anyhow!(
                    "Rule '{}' cannot be used as both an external token and a non-terminal rule",
                    &variables[symbol.index].name,
                ));
            }

            if symbol.is_external() {
                external_tokens.push(ExternalToken { name: external_token.name, kind: external_token.kind, corresponding_internal_token: None });
            } else {
                external_tokens.push(ExternalToken {
                    name: lexical_variables[symbol.index].name.clone(),
                    kind: external_token.kind,
                    corresponding_internal_token: Some(symbol),
                });
            }
        } else {
            return Err(anyhow!("Non-symbol rules cannot be used as external tokens"));
        }
    }

    let word_token = if let Some(token) = grammar.word_token {
        let token = symbol_replacer.replace_symbol(token);
        if token.is_non_terminal() {
            let word_token_variable = &variables[token.index];
            let conflicting_symbol_name = variables
                .iter()
                .enumerate()
                .find(|(i, v)| *i != token.index && v.rule == word_token_variable.rule)
                .map(|(_, v)| v.name.clone());
            let mut msg = format!("Non-terminal symbol '{}' cannot be used as the word token", word_token_variable.name);
            if let Some(n) = conflicting_symbol_name {
                msg.push_str(&format!(", because its rule is duplicated in '{}'", n));
            }
            msg.push('\n');
            return Err(anyhow!(msg));
        }
        Some(token)
    } else {
        None
    };

    let mut reserved_word_contexts = Vec::with_capacity(grammar.reserved_word_sets.len());
    for reserved_word_context in grammar.reserved_word_sets {
        let mut reserved_words = Vec::with_capacity(reserved_word_context.reserved_words.len());
        for reserved_rule in reserved_word_context.reserved_words {
            if let Rule::Symbol(symbol) = reserved_rule {
                reserved_words.push(symbol_replacer.replace_symbol(symbol));
            } else if let Some(index) = lexical_variables.iter().position(|v| v.rule == reserved_rule) {
                reserved_words.push(Symbol::terminal(index));
            } else {
                let token_name = match &reserved_rule {
                    Rule::String(s) => s.clone(),
                    Rule::Pattern(p, _) => p.clone(),
                    _ => "unknown".to_string(),
                };
                return Err(anyhow!("Reserved word '{}' must be a token", token_name));
            }
        }
        reserved_word_contexts.push(ReservedWordContext { name: reserved_word_context.name, reserved_words });
    }

    Ok((
        ExtractedSyntaxGrammar {
            variables,
            expected_conflicts,
            extra_symbols,
            variables_to_inline,
            supertype_symbols,
            external_tokens,
            word_token,
            precedence_orderings: grammar.precedence_orderings,
            reserved_word_sets: reserved_word_contexts,
        },
        ExtractedLexicalGrammar { variables: lexical_variables, separators },
    ))
}

struct TokenExtractor {
    current_variable_name: String,
    current_variable_token_count: usize,
    is_first_rule: bool,
    extracted_variables: Vec<Variable>,
    extracted_usage_counts: Vec<usize>,
}

struct SymbolReplacer {
    replacements: HashMap<usize, usize>,
}

impl TokenExtractor {
    fn extract_tokens_in_variable(&mut self, variable: &mut Variable) -> Result<()> {
        self.current_variable_name.clear();
        self.current_variable_name.push_str(&variable.name);
        self.current_variable_token_count = 0;
        let mut rule = Rule::Blank;
        std::mem::swap(&mut rule, &mut variable.rule);
        variable.rule = self.extract_tokens_in_rule(&rule)?;
        Ok(())
    }

    fn extract_tokens_in_rule(&mut self, input: &Rule) -> Result<Rule> {
        match input {
            Rule::String(name) => Ok(self.extract_token(input, Some(name))?.into()),
            Rule::Pattern(..) => Ok(self.extract_token(input, None)?.into()),
            Rule::Metadata { params, rule } => {
                if params.is_token {
                    let mut params = params.clone();
                    params.is_token = false;

                    let string_value = if let Rule::String(value) = rule.as_ref() { Some(value) } else { None };

                    let rule_to_extract = if params == MetadataParams::default() { rule.as_ref() } else { input };

                    Ok(self.extract_token(rule_to_extract, string_value)?.into())
                } else {
                    Ok(Rule::Metadata { params: params.clone(), rule: Box::new(self.extract_tokens_in_rule(rule)?) })
                }
            }
            Rule::Repeat(content) => Ok(Rule::Repeat(Box::new(self.extract_tokens_in_rule(content)?))),
            Rule::Seq(elements) => Ok(Rule::Seq(elements.iter().map(|e| self.extract_tokens_in_rule(e)).collect::<Result<Vec<_>>>()?)),
            Rule::Choice(elements) => Ok(Rule::Choice(elements.iter().map(|e| self.extract_tokens_in_rule(e)).collect::<Result<Vec<_>>>()?)),
            Rule::Reserved { rule, context_name } => Ok(Rule::Reserved { rule: Box::new(self.extract_tokens_in_rule(rule)?), context_name: context_name.clone() }),
            _ => Ok(input.clone()),
        }
    }

    fn extract_token(&mut self, rule: &Rule, string_value: Option<&String>) -> Result<Symbol> {
        for (i, variable) in self.extracted_variables.iter_mut().enumerate() {
            if variable.rule == *rule {
                self.extracted_usage_counts[i] += 1;
                return Ok(Symbol::terminal(i));
            }
        }

        let index = self.extracted_variables.len();
        let variable = if let Some(string_value) = string_value {
            if string_value.is_empty() && !self.is_first_rule {
                return Err(anyhow!(
                    "The rule `{}` contains an empty string.\n\nTree-sitter does not support syntactic rules that contain an empty string\nunless they are used only as the grammar's start rule.\n",
                    self.current_variable_name
                ));
            }
            Variable { name: string_value.clone(), kind: VariableType::Anonymous, rule: rule.clone() }
        } else {
            self.current_variable_token_count += 1;
            Variable {
                name: format!("{}_token{}", self.current_variable_name, self.current_variable_token_count),
                kind: VariableType::Auxiliary,
                rule: rule.clone(),
            }
        };

        self.extracted_variables.push(variable);
        self.extracted_usage_counts.push(1);
        Ok(Symbol::terminal(index))
    }
}

impl SymbolReplacer {
    fn replace_symbols_in_rule(&self, rule: &Rule) -> Rule {
        match rule {
            Rule::Symbol(symbol) => self.replace_symbol(*symbol).into(),
            Rule::Choice(elements) => Rule::Choice(elements.iter().map(|e| self.replace_symbols_in_rule(e)).collect()),
            Rule::Seq(elements) => Rule::Seq(elements.iter().map(|e| self.replace_symbols_in_rule(e)).collect()),
            Rule::Repeat(content) => Rule::Repeat(Box::new(self.replace_symbols_in_rule(content))),
            Rule::Metadata { rule, params } => Rule::Metadata { params: params.clone(), rule: Box::new(self.replace_symbols_in_rule(rule)) },
            Rule::Reserved { rule, context_name } => Rule::Reserved { rule: Box::new(self.replace_symbols_in_rule(rule)), context_name: context_name.clone() },
            _ => rule.clone(),
        }
    }

    fn replace_symbol(&self, symbol: Symbol) -> Symbol {
        if !symbol.is_non_terminal() {
            return symbol;
        }

        if let Some(replacement) = self.replacements.get(&symbol.index) {
            return Symbol::terminal(*replacement);
        }

        let mut adjusted_index = symbol.index;
        for replaced_index in self.replacements.keys() {
            if *replaced_index < symbol.index {
                adjusted_index -= 1;
            }
        }

        Symbol::non_terminal(adjusted_index)
    }
}
