                                if last_inserted_step.precedence.is_none() {
                                    last_inserted_step.precedence = removed_step.precedence;
                                }
                                if last_inserted_step.associativity.is_none() {
                                    last_inserted_step.associativity = removed_step.associativity;
                                }
                            }
                            if p.dynamic_precedence.abs() > production.dynamic_precedence.abs() {
                                production.dynamic_precedence = p.dynamic_precedence;
                            }
                            production
                        }),
                    );

                    continue;
                }
            }
            i += 1;
        }

        // Store all the computed productions.
        let result = productions_to_add
            .into_iter()
            .map(|production| {
                self.productions.iter().position(|p| *p == production).unwrap_or_else(|| {
                    self.productions.push(production);
                    self.productions.len() - 1
                })
            })
            .collect();

        // Cache these productions based on the original production step.
        self.production_indices_by_step_id.entry(step_id).or_insert(result)
    }

    fn production_for_id<'a>(&'a self, id: ProductionStepId, grammar: &'a SyntaxGrammar) -> &'a Production {
        id.variable_index.map_or_else(|| &self.productions[id.production_index], |variable_index| &grammar.variables[variable_index].productions[id.production_index])
    }

    fn production_step_for_id<'a>(&'a self, id: ProductionStepId, grammar: &'a SyntaxGrammar) -> Option<&'a ProductionStep> {
        self.production_for_id(id, grammar).steps.get(id.step_index)
    }
}

pub fn process_inlines(grammar: &SyntaxGrammar, lexical_grammar: &LexicalGrammar) -> Result<InlinedProductionMap> {
    for symbol in &grammar.variables_to_inline {
        match symbol.kind {
            SymbolType::External => {
                return Err(anyhow!("Token `{}` cannot be inlined", grammar.external_tokens[symbol.index].name));
            }
            SymbolType::Terminal => {
                return Err(anyhow!("Token `{}` cannot be inlined", lexical_grammar.variables[symbol.index].name));
            }
            SymbolType::NonTerminal if symbol.index == 0 => {
                return Err(anyhow!("Rule `{}` cannot be inlined because it is the first rule", grammar.variables[symbol.index].name));
            }
            _ => {}
        }
    }

    Ok(InlinedProductionMapBuilder { productions: Vec::new(), production_indices_by_step_id: HashMap::new() }.build(grammar))
}
