pub use intern_symbols::variable_type_for_name;

/// Transform an input grammar into separate components that are ready
/// for parse table construction.
pub fn prepare_grammar(input_grammar: &InputGrammar) -> Result<(SyntaxGrammar, LexicalGrammar, InlinedProductionMap, AliasMap)> {
    validate_precedences(input_grammar)?;
    validate_reserved_words(input_grammar)?;

    let interned_grammar = intern_symbols::intern_symbols(input_grammar)?;
    let (syntax_grammar, lexical_grammar) = extract_tokens::extract_tokens(interned_grammar)?;
    let syntax_grammar = expand_repeats::expand_repeats(syntax_grammar);
    let mut syntax_grammar = flatten_grammar::flatten_grammar(syntax_grammar)?;
    let lexical_grammar = expand_tokens::expand_tokens(lexical_grammar)?;
    let default_aliases = extract_default_aliases::extract_default_aliases(&mut syntax_grammar, &lexical_grammar);
    let inlines = process_inlines::process_inlines(&syntax_grammar, &lexical_grammar)?;
    Ok((syntax_grammar, lexical_grammar, inlines, default_aliases))
}

fn validate_reserved_words(grammar: &InputGrammar) -> Result<()> {
    let _ = grammar;
    Ok(())
}

/// Check that all of the named precedences used in the grammar are declared
/// within the `precedences` lists, and also that there are no conflicting
/// precedence orderings declared in those lists.
fn validate_precedences(grammar: &InputGrammar) -> Result<()> {
    // Check that no rule contains a named precedence that is not present in
    // any of the `precedences` lists.
    fn validate(rule_name: &str, rule: &Rule, names: &HashSet<&String>) -> Result<()> {
        match rule {
            Rule::Repeat(rule) => validate(rule_name, rule, names),
            Rule::Seq(elements) | Rule::Choice(elements) => elements.iter().try_for_each(|e| validate(rule_name, e, names)),
            Rule::Metadata { rule, params } => {
                if let Precedence::Name(n) = &params.precedence {
                    if !names.contains(n) {
                        return Err(anyhow!("Undeclared precedence '{}' in rule '{}'", n, rule_name));
                    }
                }
                validate(rule_name, rule, names)?;
                Ok(())
            }
            Rule::Reserved { rule, .. } => validate(rule_name, rule, names),
            _ => Ok(()),
        }
    }

    // For any two precedence names `a` and `b`, if `a` comes before `b`
    // in some list, then it cannot come *after* `b` in any list.
    let mut pairs = HashMap::new();
    for list in &grammar.precedence_orderings {
        for (i, mut entry1) in list.iter().enumerate() {
            for mut entry2 in list.iter().skip(i + 1) {
                if entry2 == entry1 {
                    continue;
                }
                let mut ordering = std::cmp::Ordering::Greater;
                if entry1 > entry2 {
                    ordering = std::cmp::Ordering::Less;
                    std::mem::swap(&mut entry1, &mut entry2);
                }
                match pairs.entry((entry1, entry2)) {
                    hash_map::Entry::Vacant(e) => {
                        e.insert(ordering);
                    }
                    hash_map::Entry::Occupied(e) => {
                        if e.get() != &ordering {
                            return Err(anyhow!(
                                "Conflicting orderings for precedences {} and {}",
                                entry_display(entry1),
                                entry_display(entry2)
                            ));
                        }
                    }
                }
            }
        }
    }

    let precedence_names = grammar
        .precedence_orderings
        .iter()
        .flat_map(|l| l.iter())
        .filter_map(|p| if let PrecedenceEntry::Name(n) = p { Some(n) } else { None })
        .collect::<HashSet<&String>>();
    for variable in &grammar.variables {
        validate(&variable.name, &variable.rule, &precedence_names)?;
    }

    Ok(())
}

fn entry_display(e: &PrecedenceEntry) -> String {
    match e {
        PrecedenceEntry::Name(n) => format!("'{}'", n),
        PrecedenceEntry::Symbol(s) => format!("$.{}", s),
    }
}

impl PartialOrd for PrecedenceEntry {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for PrecedenceEntry {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        let a = match self {
            PrecedenceEntry::Name(n) => (0, n),
            PrecedenceEntry::Symbol(n) => (1, n),
        };
        let b = match other {
            PrecedenceEntry::Name(n) => (0, n),
            PrecedenceEntry::Symbol(n) => (1, n),
        };
        a.cmp(&b)
    }
}
