}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NodeInfoJSON {
    pub kind: String,
    pub named: bool,
    pub root: bool,
    pub extra: bool,
    pub fields: Option<BTreeMap<String, FieldInfoJSON>>,
    pub children: Option<FieldInfoJSON>,
    pub subtypes: Option<Vec<NodeTypeJSON>>,
}

impl Default for FieldInfoJSON {
    fn default() -> Self {
        FieldInfoJSON { multiple: false, required: true, types: Vec::new() }
    }
}

impl Default for ChildQuantity {
    fn default() -> Self {
        Self::one()
    }
}

impl ChildQuantity {
    const fn zero() -> Self {
        Self { exists: false, required: false, multiple: false }
    }

    const fn one() -> Self {
        Self { exists: true, required: true, multiple: false }
    }

    fn append(&mut self, other: Self) {
        if other.exists {
            if self.exists || other.multiple {
                self.multiple = true;
            }
            if other.required {
                self.required = true;
            }
            self.exists = true;
        }
    }

    fn union(&mut self, other: Self) -> bool {
        let mut result = false;
        if !self.exists && other.exists {
            result = true;
            self.exists = true;
        }
        if self.required && !other.required {
            result = true;
            self.required = false;
        }
        if !self.multiple && other.multiple {
            result = true;
            self.multiple = true;
        }
        result
    }
}

fn extend_sorted<'a, T>(vec: &mut Vec<T>, values: impl IntoIterator<Item = &'a T>) -> bool
where
    T: 'a + Clone + Eq + Ord,
{
    values.into_iter().any(|value| {
        if let Err(i) = vec.binary_search(value) {
            vec.insert(i, value.clone());
            true
        } else {
            false
        }
    })
}

fn variable_type_for_child_type(child_type: &ChildType, syntax_grammar: &SyntaxGrammar, lexical_grammar: &LexicalGrammar) -> VariableType {
    match child_type {
        ChildType::Aliased(alias) => {
            if alias.is_named {
                VariableType::Named
            } else {
                VariableType::Anonymous
            }
        }
        ChildType::Normal(symbol) => {
            if syntax_grammar.supertype_symbols.contains(symbol) {
                VariableType::Named
            } else {
                match symbol.kind {
                    SymbolType::NonTerminal => syntax_grammar.variables[symbol.index].kind,
                    SymbolType::Terminal => lexical_grammar.variables[symbol.index].kind,
                    SymbolType::External => syntax_grammar.external_tokens[symbol.index].kind,
                    _ => VariableType::Hidden,
                }
            }
        }
    }
}

/// Compute a summary of the public-facing structure of each variable in the
/// grammar.
pub fn get_variable_info(syntax_grammar: &SyntaxGrammar, lexical_grammar: &LexicalGrammar, default_aliases: &AliasMap) -> Vec<VariableInfo> {
    let child_type_is_visible = |t: &ChildType| variable_type_for_child_type(t, syntax_grammar, lexical_grammar) >= VariableType::Anonymous;

    let child_type_is_named = |t: &ChildType| variable_type_for_child_type(t, syntax_grammar, lexical_grammar) == VariableType::Named;

    // Each variable's summary can depend on the summaries of other hidden variables,
    // and variables can have mutually recursive structure. So we compute the summaries
    // iteratively, in a loop that terminates only when no more changes are possible.
    let mut did_change = true;
    let mut all_initialized = false;
    let mut result = vec![VariableInfo::default(); syntax_grammar.variables.len()];
    while did_change {
        did_change = false;

        for (i, variable) in syntax_grammar.variables.iter().enumerate() {
            let mut variable_info = result[i].clone();

            // Examine each of the variable's productions. The variable's child types can be
            // immediately combined across all productions, but the child quantities must be
            // recorded separately for each production.
            for production in &variable.productions {
                let mut production_field_quantities = HashMap::new();
                let mut production_children_quantity = ChildQuantity::zero();
                let mut production_children_without_fields_quantity = ChildQuantity::zero();
                let mut production_has_uninitialized_invisible_children = false;

                if production.steps.len() > 1 {
                    variable_info.has_multi_step_production = true;
                }

                for step in &production.steps {
                    let child_symbol = step.symbol;
                    let child_type = if let Some(alias) = &step.alias {
                        ChildType::Aliased(alias.clone())
                    } else if let Some(alias) = default_aliases.get(&step.symbol) {
                        ChildType::Aliased(alias.clone())
                    } else {
                        ChildType::Normal(child_symbol)
                    };

                    let child_is_hidden = !child_type_is_visible(&child_type) && !syntax_grammar.supertype_symbols.contains(&child_symbol);

                    // Maintain the set of all child types for this variable, and the quantity of
                    // visible children in this production.
                    did_change |= extend_sorted(&mut variable_info.children.types, Some(&child_type));
                    if !child_is_hidden {
                        production_children_quantity.append(ChildQuantity::one());
                    }

                    // Maintain the set of child types associated with each field, and the quantity
                    // of children associated with each field in this production.
                    if let Some(field_name) = &step.field_name {
                        let field_info = variable_info.fields.entry(field_name.clone()).or_insert_with(FieldInfo::default);
                        did_change |= extend_sorted(&mut field_info.types, Some(&child_type));

                        let production_field_quantity = production_field_quantities.entry(field_name.clone()).or_insert_with(ChildQuantity::zero);

                        // Inherit the types and quantities of hidden children associated with fields.
                        if child_is_hidden && child_symbol.is_non_terminal() {
                            let child_variable_info = &result[child_symbol.index];
                            did_change |= extend_sorted(&mut field_info.types, &child_variable_info.children.types);
                            production_field_quantity.append(child_variable_info.children.quantity);
                        } else {
                            production_field_quantity.append(ChildQuantity::one());
                        }
                    }
                    // Maintain the set of named children without fields within this variable.
                    else if child_type_is_named(&child_type) {
                        production_children_without_fields_quantity.append(ChildQuantity::one());
                        did_change |= extend_sorted(&mut variable_info.children_without_fields.types, Some(&child_type));
                    }

                    // Inherit all child information from hidden children.
                    if child_is_hidden && child_symbol.is_non_terminal() {
                        let child_variable_info = &result[child_symbol.index];

                        // If a hidden child can have multiple children, then its parent node can
                        // appear to have multiple children.
                        if child_variable_info.has_multi_step_production {
                            variable_info.has_multi_step_production = true;
                        }

                        // If a hidden child has fields, then the parent node can appear to have
                        // those same fields.
                        for (field_name, child_field_info) in &child_variable_info.fields {
                            production_field_quantities.entry(field_name.clone()).or_insert_with(ChildQuantity::zero).append(child_field_info.quantity);
                            did_change |= extend_sorted(&mut variable_info.fields.entry(field_name.clone()).or_insert_with(FieldInfo::default).types, &child_field_info.types);
                        }

                        // If a hidden child has children, then the parent node can appear to have
                        // those same children.
                        production_children_quantity.append(child_variable_info.children.quantity);
                        did_change |= extend_sorted(&mut variable_info.children.types, &child_variable_info.children.types);

                        // If a hidden child can have named children without fields, then the parent
                        // node can appear to have those same children.
                        if step.field_name.is_none() {
                            let grandchildren_info = &child_variable_info.children_without_fields;
                            if !grandchildren_info.types.is_empty() {
                                production_children_without_fields_quantity.append(child_variable_info.children_without_fields.quantity);
                                did_change |= extend_sorted(&mut variable_info.children_without_fields.types, &child_variable_info.children_without_fields.types);
                            }
                        }
                    }

                    // Note whether or not this production contains children whose summaries
                    // have not yet been computed.
                    if child_symbol.index >= i && !all_initialized {
                        production_has_uninitialized_invisible_children = true;
                    }
                }

                // If this production's children all have had their summaries initialized,
                // then expand the quantity information with all of the possibilities introduced
                // by this production.
                if !production_has_uninitialized_invisible_children {
                    did_change |= variable_info.children.quantity.union(production_children_quantity);

                    did_change |= variable_info.children_without_fields.quantity.union(production_children_without_fields_quantity);

                    for (field_name, info) in &mut variable_info.fields {
                        did_change |= info.quantity.union(production_field_quantities.get(field_name).copied().unwrap_or_else(ChildQuantity::zero));
                    }
                }
            }

            result[i] = variable_info;
        }

        all_initialized = true;
    }

    for supertype_symbol in &syntax_grammar.supertype_symbols {
        result[supertype_symbol.index].has_multi_step_production = true;
    }

    // Update all of the node type lists to eliminate hidden nodes.
    for variable_info in &mut result {
        for field_info in variable_info.fields.values_mut() {
            field_info.types.retain(child_type_is_visible);
        }
        variable_info.fields.retain(|_, v| !v.types.is_empty());
        variable_info.children.types.retain(child_type_is_visible);
        variable_info.children_without_fields.types.retain(child_type_is_visible);
    }

    result
}

pub fn generate_node_types_json(
    syntax_grammar: &SyntaxGrammar,
    lexical_grammar: &LexicalGrammar,
    default_aliases: &AliasMap,
    variable_info: &[VariableInfo],
) -> Vec<NodeInfoJSON> {
    let mut node_types_json = BTreeMap::new();

    let child_type_to_node_type = |child_type: &ChildType| match child_type {
        ChildType::Aliased(alias) => NodeTypeJSON { kind: alias.value.clone(), named: alias.is_named },
        ChildType::Normal(symbol) => {
            if let Some(alias) = default_aliases.get(symbol) {
                NodeTypeJSON { kind: alias.value.clone(), named: alias.is_named }
            } else {
                match symbol.kind {
                    SymbolType::NonTerminal => {
                        let variable = &syntax_grammar.variables[symbol.index];
                        NodeTypeJSON { kind: variable.name.clone(), named: variable.kind != VariableType::Anonymous }
                    }
                    SymbolType::Terminal => {
                        let variable = &lexical_grammar.variables[symbol.index];
                        NodeTypeJSON { kind: variable.name.clone(), named: variable.kind != VariableType::Anonymous }
                    }
                    SymbolType::External => {
                        let variable = &syntax_grammar.external_tokens[symbol.index];
                        NodeTypeJSON { kind: variable.name.clone(), named: variable.kind != VariableType::Anonymous }
                    }
                    _ => panic!("Unexpected symbol type"),
                }
            }
        }
    };

    let populate_field_info_json = |json: &mut FieldInfoJSON, info: &FieldInfo| {
        if info.types.is_empty() {
            json.required = false;
        } else {
            json.multiple |= info.quantity.multiple;
            json.required &= info.quantity.required;
            json.types.extend(info.types.iter().map(child_type_to_node_type));
            json.types.sort_unstable();
            json.types.dedup();
        }
    };

    let mut aliases_by_symbol: HashMap<Symbol, Vec<Option<Alias>>> = HashMap::new();
    let mut add_alias = |map: &mut HashMap<Symbol, Vec<Option<Alias>>>, s: Symbol, a: Option<Alias>| {
        let e = map.entry(s).or_default();
        if !e.contains(&a) {
            e.push(a);
        }
    };
    for (symbol, alias) in default_aliases {
        add_alias(&mut aliases_by_symbol, *symbol, Some(alias.clone()));
    }
    for extra_symbol in &syntax_grammar.extra_symbols {
        if !default_aliases.contains_key(extra_symbol) {
            add_alias(&mut aliases_by_symbol, *extra_symbol, None);
        }
    }
    for variable in &syntax_grammar.variables {
        for production in &variable.productions {
            for step in &production.steps {
                add_alias(&mut aliases_by_symbol, step.symbol, step.alias.as_ref().or_else(|| default_aliases.get(&step.symbol)).cloned());
            }
        }
    }
    aliases_by_symbol.insert(Symbol::non_terminal(0), vec![None]);

    let mut extra_names = HashSet::new();
    for extra in &syntax_grammar.extra_symbols {
        let name = match default_aliases.get(extra) {
            Some(a) => a.value.clone(),
            None => match extra.kind {
                SymbolType::NonTerminal => syntax_grammar.variables[extra.index].name.clone(),
                SymbolType::Terminal => lexical_grammar.variables[extra.index].name.clone(),
                SymbolType::External => syntax_grammar.external_tokens[extra.index].name.clone(),
                _ => continue,
            },
        };
        extra_names.insert(name);
    }

    let mut subtype_map = Vec::new();
    for (i, info) in variable_info.iter().enumerate() {
        let symbol = Symbol::non_terminal(i);
        let variable = &syntax_grammar.variables[i];
        if syntax_grammar.supertype_symbols.contains(&symbol) {
            let node_type_json = node_types_json.entry(variable.name.clone()).or_insert_with(|| NodeInfoJSON {
                kind: variable.name.clone(),
                named: true,
                root: false,
                extra: extra_names.contains(&variable.name),
                fields: None,
                children: None,
                subtypes: None,
            });
            let mut subtypes = info.children.types.iter().map(child_type_to_node_type).collect::<Vec<_>>();
            subtypes.sort_unstable();
            subtypes.dedup();
            subtype_map.push((NodeTypeJSON { kind: node_type_json.kind.clone(), named: true }, subtypes.clone()));
            node_type_json.subtypes = Some(subtypes);
        } else if !syntax_grammar.variables_to_inline.contains(&symbol) {
            // If a rule is aliased under multiple names, then its information
            // contributes to multiple entries in the final JSON.
            let empty = Vec::new();
            let mut aliases: Vec<Option<Alias>> = aliases_by_symbol.get(&Symbol::non_terminal(i)).unwrap_or(&empty).clone();
            aliases.sort();
            for alias in &aliases {
                let kind;
                let is_named;
                if let Some(alias) = alias {
                    kind = &alias.value;
                    is_named = alias.is_named;
                } else if variable.kind >= VariableType::Anonymous {
                    kind = &variable.name;
                    is_named = variable.kind == VariableType::Named;
                } else {
                    continue;
                }

                // There may already be an entry with this name, because multiple
                // rules may be aliased with the same name.
                let mut node_type_existed = true;
                let node_type_json = node_types_json.entry(kind.clone()).or_insert_with(|| {
                    node_type_existed = false;
                    NodeInfoJSON {
                        kind: kind.clone(),
                        named: is_named,
                        root: i == 0,
                        extra: extra_names.contains(kind),
                        fields: Some(BTreeMap::new()),
                        children: None,
                        subtypes: None,
                    }
                });

                let fields_json = node_type_json.fields.get_or_insert_with(BTreeMap::new);
                let mut field_names: Vec<&String> = info.fields.keys().collect();
                field_names.sort();
                for new_field in field_names {
                    let field_info = &info.fields[new_field];
                    let field_json = fields_json.entry(new_field.clone()).or_insert_with(|| {
                        // If another rule is aliased with the same name, and does *not* have this
                        // field, then this field cannot be required.
                        let mut field_json = FieldInfoJSON::default();
                        if node_type_existed {
                            field_json.required = false;
                        }
                        field_json
                    });
                    populate_field_info_json(field_json, field_info);
                }

                // If another rule is aliased with the same name, any fields that aren't present in
                // this cannot be required.
                for (existing_field, field_json) in fields_json.iter_mut() {
                    if !info.fields.contains_key(existing_field) {
                        field_json.required = false;
                    }
                }

                populate_field_info_json(node_type_json.children.get_or_insert(FieldInfoJSON::default()), &info.children_without_fields);
            }
        }
    }

    // Sort the subtype map topologically so that subtypes are listed before their supertypes.
    let mut sorted_kinds = Vec::with_capacity(subtype_map.len());
    let mut top_sort = topological_sort(&subtype_map);
    sorted_kinds.append(&mut top_sort);
    subtype_map.sort_by(|a, b| {
        let a_idx = sorted_kinds.iter().position(|n| n == &a.0).unwrap_or(usize::MAX);
        let b_idx = sorted_kinds.iter().position(|n| n == &b.0).unwrap_or(usize::MAX);
        a_idx.cmp(&b_idx)
    });

    for node_type_json in node_types_json.values_mut() {
        if node_type_json.children.as_ref().is_some_and(|c| c.types.is_empty()) {
            node_type_json.children = None;
        }

        if let Some(children) = &mut node_type_json.children {
            process_supertypes(children, &subtype_map);
        }
        if let Some(fields) = &mut node_type_json.fields {
            for field_info in fields.values_mut() {
                process_supertypes(field_info, &subtype_map);
            }
        }
    }

    let mut anonymous_node_types = Vec::new();

    let empty = Vec::new();
    let mut token_entries: Vec<(String, VariableType)> = Vec::new();
    for (i, variable) in lexical_grammar.variables.iter().enumerate() {
        for alias in aliases_by_symbol.get(&Symbol::terminal(i)).unwrap_or(&empty) {
            token_entries.push(match alias {
                Some(alias) => (alias.value.clone(), if alias.is_named { VariableType::Named } else { VariableType::Anonymous }),
                None => (variable.name.clone(), variable.kind),
            });
        }
    }
    for (i, token) in syntax_grammar.external_tokens.iter().enumerate() {
        // Don't output anything for external tokens that are not used anywhere.
        let aliases = aliases_by_symbol.get(&Symbol::external(i));
        if let Some(aliases) = aliases {
            for alias in aliases {
                token_entries.push(match alias {
                    Some(alias) => (alias.value.clone(), if alias.is_named { VariableType::Named } else { VariableType::Anonymous }),
                    None => (token.name.clone(), token.kind),
                });
            }
        }
    }

    for (name, kind) in token_entries {
        match kind {
            VariableType::Named => {
                let node_type_json = node_types_json.entry(name.clone()).or_insert(NodeInfoJSON {
                    kind: name.clone(),
                    named: true,
                    root: false,
                    extra: extra_names.contains(&name),
                    fields: None,
                    children: None,
                    subtypes: None,
                });
                if let Some(children) = &mut node_type_json.children {
                    children.required = false;
                }
                if let Some(fields) = &mut node_type_json.fields {
                    for field in fields.values_mut() {
                        field.required = false;
                    }
                }
            }
            VariableType::Anonymous => anonymous_node_types.push(NodeInfoJSON {
                kind: name.clone(),
                named: false,
                root: false,
                extra: extra_names.contains(&name),
                fields: None,
                children: None,
                subtypes: None,
            }),
            _ => {}
        }
    }

    let mut result = node_types_json.into_values().collect::<Vec<_>>();
    result.extend(anonymous_node_types);
    result.sort_unstable_by(|a, b| {
        b.subtypes
            .is_some()
            .cmp(&a.subtypes.is_some())
            .then_with(|| {
                let a_is_leaf = a.fields.is_none();
                let b_is_leaf = b.fields.is_none();
                a_is_leaf.cmp(&b_is_leaf)
            })
            .then_with(|| a.kind.cmp(&b.kind))
            .then_with(|| b.named.cmp(&a.named))
    });
    result.dedup();
    result
}

fn topological_sort(subtype_map: &[(NodeTypeJSON, Vec<NodeTypeJSON>)]) -> Vec<NodeTypeJSON> {
    let mut result = Vec::new();
    let mut visited = HashSet::new();
    fn visit(
        n: &NodeTypeJSON,
        map: &[(NodeTypeJSON, Vec<NodeTypeJSON>)],
        visited: &mut HashSet<NodeTypeJSON>,
        result: &mut Vec<NodeTypeJSON>,
    ) {
        if !visited.insert(n.clone()) {
            return;
        }
        if let Some((_, subs)) = map.iter().find(|(s, _)| s == n) {
            for s in subs {
                visit(s, map, visited, result);
            }
        }
        result.push(n.clone());
    }
    for (n, _) in subtype_map {
        visit(n, subtype_map, &mut visited, &mut result);
    }
    result
}

fn process_supertypes(info: &mut FieldInfoJSON, subtype_map: &[(NodeTypeJSON, Vec<NodeTypeJSON>)]) {
    for (supertype, subtypes) in subtype_map {
        if info.types.contains(supertype) {
            info.types.retain(|t| !subtypes.contains(t));
        }
    }
}

fn node_type_value(t: &NodeTypeJSON) -> Value {
    json!({"type": t.kind, "named": t.named})
}

fn field_value(f: &FieldInfoJSON) -> Value {
    let mut m = Map::new();
    m.insert("multiple".into(), Value::Bool(f.multiple));
    m.insert("required".into(), Value::Bool(f.required));
    m.insert("types".into(), Value::Array(f.types.iter().map(node_type_value).collect()));
    Value::Object(m)
}

pub fn node_types_to_json(nodes: &[NodeInfoJSON]) -> String {
    let mut arr = Vec::new();
    for n in nodes {
        let mut m = Map::new();
        m.insert("type".into(), Value::String(n.kind.clone()));
        m.insert("named".into(), Value::Bool(n.named));
        if n.root {
            m.insert("root".into(), Value::Bool(true));
        }
        if n.extra {
            m.insert("extra".into(), Value::Bool(true));
        }
        if let Some(fields) = &n.fields {
            let mut fm = Map::new();
            for (k, v) in fields {
                fm.insert(k.clone(), field_value(v));
            }
            m.insert("fields".into(), Value::Object(fm));
        }
        if let Some(c) = &n.children {
            m.insert("children".into(), field_value(c));
        }
        if let Some(s) = &n.subtypes {
            m.insert("subtypes".into(), Value::Array(s.iter().map(node_type_value).collect()));
        }
        arr.push(Value::Object(m));
    }
    serde_json::to_string_pretty(&Value::Array(arr)).unwrap()
}
