                    Some(p) => p,
                    None => {
                        follow_set_info_by_non_terminal.push((variable_index, FollowSetInfo { lookaheads: TokenSet::new(), reserved_lookaheads: ReservedWordSetId::default(), propagates_lookaheads: false }));
