                    }
                };
                let existing_info = &mut follow_set_info_by_non_terminal[pos].1;

                let did_add_follow_set_info;
                if propagates_lookaheads {
                    did_add_follow_set_info = !existing_info.propagates_lookaheads;
                    existing_info.propagates_lookaheads = true;
                } else {
                    let a = existing_info.lookaheads.insert_all(&lookaheads);
                    let mut b = false;
                    if reserved_lookaheads > existing_info.reserved_lookaheads {
                        existing_info.reserved_lookaheads = reserved_lookaheads;
                        b = true;
                    }
                    did_add_follow_set_info = a || b;
                }

                // Each production of this non-terminal may itself begin with non-terminals.
                // Add each of those non-terminals as entries to process.
                if did_add_follow_set_info {
                    for production in &syntax_grammar.variables[variable_index].productions {
                        if let Some(symbol) = production.first_symbol() {
                            if symbol.is_non_terminal() {
                                if production.steps.len() == 1 {
                                    entries_to_process.push((symbol.index, lookaheads.clone(), reserved_lookaheads, propagates_lookaheads));
                                } else {
                                    entries_to_process.push((
