                                        result.first_sets[&production.steps[1].symbol].clone(),
                                        result.reserved_first_sets.get(&production.steps[1].symbol).copied().unwrap_or(NO_RESERVED_WORDS),
                                        false,
                                    ));
                                }
                            }
                        }
                    }
                }
            }

