use super::rules::{AliasMap, Symbol, SymbolType, TokenSet};
use super::tables::{LexTable, ParseAction, ParseTable, ParseTableEntry};
use anyhow::Result;
use std::collections::HashMap;

pub struct Tables {
    pub parse_table: ParseTable,
    pub main_lex_table: LexTable,
    pub keyword_lex_table: LexTable,
    pub word_token: Option<Symbol>,
    pub unused_conflicts: Vec<Vec<Symbol>>,
