use std::fmt::Write;
use std::mem::swap;

const SMALL_STATE_THRESHOLD: usize = 64;
pub const ABI_VERSION_WITH_RESERVED_WORDS: usize = 15;

macro_rules! add {
    ($this: tt, $($arg: tt)*) => {{
