use crate::generate;
use anyhow::{anyhow, Context, Result};
use std::path::{Path, PathBuf};

pub struct GenerateOptions {
    pub grammar_path: Option<String>,
    pub abi: Option<String>,
    pub no_parser: bool,
    pub output: Option<String>,
    pub js_runtime: String,
    pub disable_optimizations: bool,
    pub json_summary: bool,
    pub report_states_for_rule: Option<String>,
    pub log: bool,
}

pub const LATEST_ABI: usize = 15;
pub const MIN_ABI: usize = 14;

pub fn warn(msg: &str) {
    eprintln!("\x1b[33mWarning:\x1b[0m {}", msg);
}

/// Load the JSON text for a grammar (from grammar.js or grammar.json).
pub fn load_grammar_json_text(grammar_path: &Path, js_runtime: &str, arg_given: bool) -> Result<String> {
    let ext = grammar_path.extension().and_then(|e| e.to_str()).unwrap_or("");
    if grammar_path.is_dir() || (ext != "js" && ext != "json") {
        if !grammar_path.exists() && arg_given {
            // falls through to a load error below
        } else {
            return Err(anyhow!("Path to a grammar file with `.js` or `.json` extension is required"));
        }
    }
    if ext == "json" {
        return std::fs::read_to_string(grammar_path).map_err(|e| anyhow!("Failed to read grammar file {} -- {}", grammar_path.display(), e));
    }
    if !grammar_path.is_file() {
        let shown = if arg_given { grammar_path.join("grammar.js") } else { grammar_path.to_path_buf() };
        let err = std::io::Error::from(std::io::ErrorKind::NotFound);
        return Err(anyhow!("Failed to load grammar.js -- {} ({})", io_error_string(&err), shown.display()));
    }
    if js_runtime != "native" {
        // Check that the runtime exists.
        let found = if js_runtime.contains('/') {
            Path::new(js_runtime).is_file()
        } else {
            std::env::var_os("PATH").map_or(false, |p| std::env::split_paths(&p).any(|d| d.join(js_runtime).is_file()))
        };
        if !found {
            let err = std::io::Error::from(std::io::ErrorKind::NotFound);
            return Err(anyhow!("Failed to load grammar.js -- Failed to run `{}` -- {}", js_runtime, io_error_string(&err)));
        }
    }
    crate::js::load_grammar_js(grammar_path).map_err(|e| anyhow!("Failed to load grammar.js -- {}", e))
}

pub fn io_error_string(e: &std::io::Error) -> String {
    match e.kind() {
        std::io::ErrorKind::NotFound => "No such file or directory (os error 2)".to_string(),
        std::io::ErrorKind::PermissionDenied => "Permission denied (os error 13)".to_string(),
        _ => e.to_string(),
    }
}

pub fn run(opts: GenerateOptions) -> Result<()> {
    let cwd = std::env::current_dir()?;
    let arg_given = opts.grammar_path.is_some();
    let grammar_path = match &opts.grammar_path {
        Some(p) => PathBuf::from(p),
        None => cwd.join("grammar.js"),
    };

    // Determine ABI version
    let mut abi = LATEST_ABI;
    if let Some(a) = &opts.abi {
        if a == "latest" {
            abi = LATEST_ABI;
        } else {
            match a.parse::<usize>() {
                Ok(v) => abi = v,
                Err(e) => {
                    eprintln!("\nthread 'main' ({}) panicked at crates/cli/src/main.rs:940:41:\ninvalid abi version flag: {:?}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", std::process::id(), e);
                    std::process::exit(101);
                }
            }
        }
    }
    if abi < MIN_ABI {
        return Err(anyhow!("This version of Tree-sitter can only generate parsers with ABI version {} - {}, not {}", MIN_ABI, LATEST_ABI, abi))
            .context("Error when generating parser");
    }

    let output_dir = match &opts.output {
        Some(o) => PathBuf::from(o),
        None => cwd.join("src"),
    };

    let ts_json_path = cwd.join("tree-sitter.json");
    let mut metadata = None;
    if ts_json_path.exists() {
        let cfg = crate::ts_json::parse_file(&ts_json_path).context("Error when generating parser")?;
        if abi > LATEST_ABI {
            return Err(anyhow!("This version of Tree-sitter can only generate parsers with ABI version {} - {}, not {}", MIN_ABI, LATEST_ABI, abi))
                .context("Error when generating parser");
        }
        let v = semver::Version::parse(&cfg.metadata.version).ok();
        metadata = Some(match v {
            Some(v) => generate::render::Metadata { major_version: v.major as u8, minor_version: v.minor as u8, patch_version: v.patch as u8 },
            None => generate::render::Metadata { major_version: 0, minor_version: 0, patch_version: 0 },
        });
    } else if abi >= 15 {
        warn(&format!(
            "No `tree-sitter.json` file found in your grammar, this file is required to generate with ABI {}. Using ABI version 14 instead.\nThis file can be set up with `tree-sitter init`. For more information, see https://tree-sitter.github.io/tree-sitter/cli/init.",
            abi
        ));
        abi = 14;
    }

    std::fs::create_dir_all(&output_dir).ok();

    let result = (|| -> Result<()> {
        let json_text = load_grammar_json_text(&grammar_path, &opts.js_runtime, arg_given)?;
        let g = generate::grammar_json::parse_grammar_json(&json_text).map_err(|e| anyhow!(e))?;
        let is_js = grammar_path.extension().map_or(false, |e| e == "js");
        if is_js {
            std::fs::write(output_dir.join("grammar.json"), generate::grammar_json::write_grammar_json(&g))?;
        } else if grammar_path.file_name().map_or(true, |n| n != "grammar.json") {
            std::fs::write(output_dir.join("grammar.json"), &json_text)?;
        }
        let files = generate::generate_from_grammar_json(&g, abi, opts.no_parser, metadata, !opts.disable_optimizations)?;
        for w in &files.warnings {
            warn(w);
        }
        std::fs::write(output_dir.join("node-types.json"), &files.node_types_json)?;
        if let Some(c) = &files.parser_c {
            std::fs::write(output_dir.join("parser.c"), c)?;
            let header_dir = output_dir.join("tree_sitter");
            std::fs::create_dir_all(&header_dir)?;
            std::fs::write(header_dir.join("alloc.h"), generate::ALLOC_HEADER)?;
            std::fs::write(header_dir.join("array.h"), generate::ARRAY_HEADER)?;
            std::fs::write(header_dir.join("parser.h"), generate::PARSER_HEADER)?;
        }
        let _ = (&opts.report_states_for_rule, opts.log, opts.json_summary);
        Ok(())
    })();
    result.context("Error when generating parser")
}
