pub struct TableEntry {
    pub actions: Vec<ParseAction>,
    pub is_reusable: bool,
}

pub struct LookaheadIterator<'a> {
    lang: &'a Language,
    table_index: usize,
    is_small: bool,
    group_end: usize,
    group_value: u16,
    state: TSStateId,
    symbol: u16,
}

impl Language {
    pub fn new(raw: *const RawLanguage) -> Language {
        Language { raw }
    }

    fn r(&self) -> &RawLanguage {
        unsafe { &*self.raw }
    }

    pub fn abi_version(&self) -> u32 {
        self.r().abi_version
    }

    pub fn symbol_count(&self) -> u32 {
        self.r().symbol_count + self.r().alias_count
    }

    pub fn token_count(&self) -> u32 {
        self.r().token_count
    }

    pub fn state_count(&self) -> u32 {
        self.r().state_count
    }

    pub fn field_count(&self) -> u32 {
        self.r().field_count
    }

    pub fn external_token_count(&self) -> u32 {
        self.r().external_token_count
    }

    pub fn name(&self) -> Option<String> {
        let r = self.r();
        if r.abi_version >= 15 && !r.name.is_null() {
            unsafe { Some(CStr::from_ptr(r.name).to_string_lossy().to_string()) }
        } else {
            None
        }
    }

    pub fn symbol_name(&self, symbol: TSSymbol) -> &'static str {
        if symbol == TS_BUILTIN_SYM_ERROR {
            return "ERROR";
        }
        if symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            return "_ERROR";
        }
        let r = self.r();
        if (symbol as u32) < r.symbol_count + r.alias_count {
            unsafe {
                let p = *r.symbol_names.add(symbol as usize);
                if p.is_null() {
                    return "";
                }
                let s = CStr::from_ptr(p);
                std::str::from_utf8_unchecked(s.to_bytes())
            }
        } else {
            ""
        }
    }

    pub fn symbol_metadata(&self, symbol: TSSymbol) -> TSSymbolMetadata {
        if symbol == TS_BUILTIN_SYM_ERROR {
            return TSSymbolMetadata { visible: true, named: true, supertype: false };
        }
        if symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            return TSSymbolMetadata { visible: false, named: false, supertype: false };
        }
        let r = self.r();
        if (symbol as u32) < r.symbol_count + r.alias_count {
            unsafe { *r.symbol_metadata.add(symbol as usize) }
        } else {
            TSSymbolMetadata { visible: false, named: false, supertype: false }
        }
    }

    pub fn public_symbol(&self, symbol: TSSymbol) -> TSSymbol {
        if symbol == TS_BUILTIN_SYM_ERROR {
            return symbol;
        }
        let r = self.r();
        if (symbol as u32) < r.symbol_count + r.alias_count {
            unsafe { *r.public_symbol_map.add(symbol as usize) }
        } else {
            symbol
        }
    }

    pub fn field_name(&self, id: TSFieldId) -> Option<&'static str> {
        let r = self.r();
        if id == 0 || id as u32 > r.field_count || r.field_names.is_null() {
            return None;
        }
        unsafe {
            let p = *r.field_names.add(id as usize);
            if p.is_null() {
                return None;
            }
            Some(std::str::from_utf8_unchecked(CStr::from_ptr(p).to_bytes()))
        }
    }

    pub fn field_id_for_name(&self, name: &str) -> Option<TSFieldId> {
        for i in 1..=self.field_count() as u16 {
            if self.field_name(i) == Some(name) {
                return Some(i);
            }
        }
        None
    }

    pub fn symbol_for_name(&self, name: &str, named: bool) -> Option<TSSymbol> {
        if name == "ERROR" {
            return Some(TS_BUILTIN_SYM_ERROR);
        }
        let count = self.symbol_count() as u16;
        for i in 0..count {
            let md = self.symbol_metadata(i);
            if (!md.visible && !md.supertype) || md.named != named {
                continue;
            }
            if self.symbol_name(i) == name {
                return Some(self.public_symbol(i));
            }
        }
        None
    }

    pub fn is_large_state(&self, state: TSStateId) -> bool {
        (state as u32) < self.r().large_state_count
    }

    /// Look up a value in the parse table: for terminals an action index, for nonterminals a state
    pub fn lookup(&self, state: TSStateId, symbol: TSSymbol) -> u16 {
        let r = self.r();
        if (state as u32) >= r.large_state_count {
            unsafe {
                let index = *r.small_parse_table_map.add(state as usize - r.large_state_count as usize) as usize;
                let mut data = r.small_parse_table.add(index);
                let group_count = *data;
                data = data.add(1);
                for _ in 0..group_count {
                    let section_value = *data;
                    data = data.add(1);
                    let symbol_count = *data;
                    data = data.add(1);
                    for _ in 0..symbol_count {
                        if *data == symbol {
                            return section_value;
                        }
                        data = data.add(1);
                    }
                }
                0
            }
        } else {
            unsafe { *r.parse_table.add(state as usize * r.symbol_count as usize + symbol as usize) }
        }
    }

    pub fn parse_action_entry(&self, index: u16) -> (u8, bool) {
        unsafe {
            let e = &*self.r().parse_actions.add(index as usize);
            (e.bytes[0], e.bytes[1] != 0)
        }
    }

    pub fn parse_action(&self, index: usize) -> ParseAction {
        unsafe {
            let e = &*self.r().parse_actions.add(index);
            let b = e.bytes;
            match b[0] {
                0 => {
                    // shift: type(u8) pad(u8) state(u16) extra(bool) repetition(bool)
                    let state = u16::from_ne_bytes([b[2], b[3]]);
                    ParseAction::Shift { state, extra: b[4] != 0, repetition: b[5] != 0 }
                }
                1 => {
                    // reduce: type(u8) child_count(u8) symbol(u16) dynamic_precedence(i16) production_id(u16)
                    let child_count = b[1];
                    let symbol = u16::from_ne_bytes([b[2], b[3]]);
                    let dp = i16::from_ne_bytes([b[4], b[5]]);
                    let pid = u16::from_ne_bytes([b[6], b[7]]);
                    ParseAction::Reduce { symbol, child_count, dynamic_precedence: dp, production_id: pid }
                }
                2 => ParseAction::Accept,
                _ => ParseAction::Recover,
            }
        }
    }

    pub fn table_entry(&self, state: TSStateId, symbol: TSSymbol) -> TableEntry {
        if symbol == TS_BUILTIN_SYM_ERROR || symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            return TableEntry { actions: vec![], is_reusable: false };
        }
        let action_index = self.lookup(state, symbol);
        let (count, reusable) = self.parse_action_entry(action_index);
        let mut actions = Vec::with_capacity(count as usize);
        for i in 0..count as usize {
            actions.push(self.parse_action(action_index as usize + 1 + i));
        }
        TableEntry { actions, is_reusable: reusable }
    }

    pub fn actions(&self, state: TSStateId, symbol: TSSymbol) -> Vec<ParseAction> {
        self.table_entry(state, symbol).actions
    }

    pub fn has_actions(&self, state: TSStateId, symbol: TSSymbol) -> bool {
        let action_index = self.lookup(state, symbol);
        self.parse_action_entry(action_index).0 > 0
    }

    pub fn has_reduce_action(&self, state: TSStateId, symbol: TSSymbol) -> bool {
        let e = self.table_entry(state, symbol);
        e.actions.len() > 0 && matches!(e.actions[0], ParseAction::Reduce { .. })
    }

    pub fn next_state(&self, state: TSStateId, symbol: TSSymbol) -> TSStateId {
        if symbol == TS_BUILTIN_SYM_ERROR || symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            return 0;
        }
        let r = self.r();
        if (symbol as u32) < r.token_count {
            let actions = self.actions(state, symbol);
            if let Some(ParseAction::Shift { state: s, extra, .. }) = actions.last() {
                if *extra {
                    return state;
                }
                return *s;
            }
            0
        } else {
            self.lookup(state, symbol)
        }
    }

    pub fn lex_mode(&self, state: TSStateId) -> LexMode {
        let r = self.r();
        unsafe {
            if r.abi_version >= 15 {
                let p = (r.lex_modes as *const u16).add(state as usize * 3);
                LexMode { lex_state: *p, external_lex_state: *p.add(1), reserved_word_set_id: *p.add(2) }
            } else {
                let p = (r.lex_modes as *const u16).add(state as usize * 2);
                LexMode { lex_state: *p, external_lex_state: *p.add(1), reserved_word_set_id: 0 }
            }
        }
    }

    pub fn is_reserved_word(&self, state: TSStateId, symbol: TSSymbol) -> bool {
        let r = self.r();
        if r.abi_version < 15 || r.reserved_words.is_null() {
            return false;
        }
        let lm = self.lex_mode(state);
        if lm.reserved_word_set_id == 0 {
            return false;
        }
        let size = r.max_reserved_word_set_size as usize;
        unsafe {
            let start = r.reserved_words.add(lm.reserved_word_set_id as usize * size);
            for i in 0..size {
                let s = *start.add(i);
                if s == symbol {
                    return true;
                }
                if s == 0 {
                    break;
                }
            }
        }
        false
    }

    pub fn lex_fn(&self) -> Option<unsafe extern "C" fn(*mut TSLexer, TSStateId) -> bool> {
        self.r().lex_fn
    }

    pub fn keyword_lex_fn(&self) -> Option<unsafe extern "C" fn(*mut TSLexer, TSStateId) -> bool> {
        self.r().keyword_lex_fn
    }

    pub fn keyword_capture_token(&self) -> TSSymbol {
        self.r().keyword_capture_token
    }

    pub fn external_scanner(&self) -> &ExternalScanner {
        &self.r().external_scanner
    }

    pub fn enabled_external_tokens(&self, external_lex_state: u16) -> *const bool {
        let r = self.r();
        if external_lex_state == 0 || r.external_scanner.states.is_null() {
            std::ptr::null()
        } else {
            unsafe { r.external_scanner.states.add(r.external_token_count as usize * external_lex_state as usize) }
        }
    }

    pub fn external_symbol(&self, index: TSSymbol) -> TSSymbol {
        unsafe { *self.r().external_scanner.symbol_map.add(index as usize) }
    }

    pub fn alias_sequence(&self, production_id: u16) -> Option<&[TSSymbol]> {
        let r = self.r();
        if production_id == 0 || r.alias_sequences.is_null() {
            return None;
        }
        unsafe { Some(std::slice::from_raw_parts(r.alias_sequences.add(production_id as usize * r.max_alias_sequence_length as usize), r.max_alias_sequence_length as usize)) }
    }

    pub fn alias_at(&self, production_id: u16, child_index: usize) -> TSSymbol {
        let r = self.r();
        if production_id == 0 || r.alias_sequences.is_null() || child_index >= r.max_alias_sequence_length as usize {
            return 0;
        }
        unsafe { *r.alias_sequences.add(production_id as usize * r.max_alias_sequence_length as usize + child_index) }
    }

    pub fn max_alias_sequence_length(&self) -> usize {
        self.r().max_alias_sequence_length as usize
    }

    pub fn field_map(&self, production_id: u16) -> &[TSFieldMapEntry] {
        let r = self.r();
        if r.field_count == 0 || r.field_map_slices.is_null() {
            return &[];
        }
        unsafe {
            let slice = *r.field_map_slices.add(production_id as usize);
            std::slice::from_raw_parts(r.field_map_entries.add(slice.index as usize), slice.length as usize)
        }
    }

    /// The list of symbols that a given non-terminal can be aliased to (from alias_map).
    pub fn aliases_for_symbol(&self, original: TSSymbol) -> Vec<TSSymbol> {
        let r = self.r();
        let mut result = vec![original];
        if r.alias_map.is_null() {
            return result;
        }
        unsafe {
            let mut idx = 0usize;
            loop {
                let symbol = *r.alias_map.add(idx);
                if symbol == 0 || symbol > original {
                    break;
                }
                let count = *r.alias_map.add(idx + 1) as usize;
                if symbol == original {
                    result.clear();
                    for i in 0..count {
                        result.push(*r.alias_map.add(idx + 2 + i));
                    }
                    break;
                }
                idx += 2 + count;
            }
        }
        result
    }

    pub fn primary_state(&self, state: TSStateId) -> TSStateId {
        let r = self.r();
        if r.primary_state_ids.is_null() {
            return state;
        }
        unsafe { *r.primary_state_ids.add(state as usize) }
    }

    pub fn supertypes(&self) -> Vec<TSSymbol> {
        let r = self.r();
        if r.abi_version < 15 || r.supertype_symbols.is_null() {
            return vec![];
        }
        unsafe { std::slice::from_raw_parts(r.supertype_symbols, r.supertype_count as usize).to_vec() }
    }

    pub fn subtypes(&self, supertype: TSSymbol) -> Vec<TSSymbol> {
        let r = self.r();
        if r.abi_version < 15 || r.supertype_map_slices.is_null() {
            return vec![];
        }
        unsafe {
            let slice = *r.supertype_map_slices.add(supertype as usize);
            std::slice::from_raw_parts(r.supertype_map_entries.add(slice.index as usize), slice.length as usize).to_vec()
        }
    }

    pub fn lookahead_iterator(&self, state: TSStateId) -> LookaheadIterator<'_> {
        let r = self.r();
        let is_small = (state as u32) >= r.large_state_count;
        let table_index = if is_small {
            unsafe { *r.small_parse_table_map.add(state as usize - r.large_state_count as usize) as usize }
        } else {
            0
        };
        LookaheadIterator { lang: self, table_index, is_small, group_end: 0, group_value: 0, state, symbol: 0 }
    }

    /// All (symbol, value) pairs for a state where value != 0
    pub fn state_entries(&self, state: TSStateId) -> Vec<(TSSymbol, u16)> {
        let r = self.r();
        let mut out = Vec::new();
        if (state as u32) >= r.large_state_count {
            unsafe {
                let index = *r.small_parse_table_map.add(state as usize - r.large_state_count as usize) as usize;
                let mut data = r.small_parse_table.add(index);
                let group_count = *data;
                data = data.add(1);
                for _ in 0..group_count {
                    let section_value = *data;
                    data = data.add(1);
                    let symbol_count = *data;
                    data = data.add(1);
                    for _ in 0..symbol_count {
                        out.push((*data, section_value));
                        data = data.add(1);
                    }
                }
            }
            out.sort_by_key(|e| e.0);
        } else {
            for s in 0..r.symbol_count as u16 {
                let v = self.lookup(state, s);
                if v != 0 {
                    out.push((s, v));
                }
            }
        }
        out
    }
}

impl Iterator for LookaheadIterator<'_> {
    type Item = TSSymbol;
    fn next(&mut self) -> Option<TSSymbol> {
        let _ = (self.table_index, self.is_small, self.group_end, self.group_value);
        let r = self.lang.r();
        while (self.symbol as u32) < r.symbol_count {
            let s = self.symbol;
            self.symbol += 1;
            if self.lang.lookup(self.state, s) != 0 {
                return Some(s);
            }
        }
        None
    }
}

// ---------- dynamic loading ----------

pub struct LoadedLibrary {
    pub handle: *mut c_void,
}

unsafe impl Send for LoadedLibrary {}
unsafe impl Sync for LoadedLibrary {}

pub fn load_language_from_library(path: &std::path::Path, function_name: &str) -> Result<Language, String> {
    use std::ffi::CString;
    let cpath = CString::new(path.to_string_lossy().as_bytes()).unwrap();
    unsafe {
        let handle = libc::dlopen(cpath.as_ptr(), libc::RTLD_NOW);
        if handle.is_null() {
            let err = libc::dlerror();
            let msg = if err.is_null() { String::from("unknown error") } else { CStr::from_ptr(err).to_string_lossy().to_string() };
            return Err(msg);
        }
        let fname = CString::new(function_name).unwrap();
        let sym = libc::dlsym(handle, fname.as_ptr());
        if sym.is_null() {
            let err = libc::dlerror();
            let msg = if err.is_null() { String::from("undefined symbol") } else { CStr::from_ptr(err).to_string_lossy().to_string() };
            return Err(msg);
        }
        let f: extern "C" fn() -> *const RawLanguage = std::mem::transmute(sym);
        let raw = f();
        // leak the handle intentionally
        Ok(Language::new(raw))
    }
}
