pub const ERROR_STATE: TSStateId = 0;
pub const ERROR_COST_PER_RECOVERY: u32 = 500;
pub const ERROR_COST_PER_MISSING_TREE: u32 = 110;
pub const ERROR_COST_PER_SKIPPED_TREE: u32 = 100;
pub const ERROR_COST_PER_SKIPPED_LINE: u32 = 30;
pub const ERROR_COST_PER_SKIPPED_CHAR: u32 = 1;
pub const TS_TREE_STATE_NONE: TSStateId = u16::MAX;

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Point {
    pub row: u32,
    pub column: u32,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Length {
    pub bytes: u32,
    pub extent: Point,
}

impl Length {
    pub fn zero() -> Length {
        Length::default()
    }
    pub fn add(self, b: Length) -> Length {
        let mut r = Length { bytes: self.bytes + b.bytes, extent: Point::default() };
        if b.extent.row > 0 {
            r.extent.row = self.extent.row + b.extent.row;
            r.extent.column = b.extent.column;
        } else {
            r.extent.row = self.extent.row;
            r.extent.column = self.extent.column + b.extent.column;
        }
        r
    }
    pub fn sub(self, b: Length) -> Length {
        let mut r = Length { bytes: self.bytes.wrapping_sub(b.bytes), extent: Point::default() };
        if self.extent.row > b.extent.row {
            r.extent.row = self.extent.row - b.extent.row;
            r.extent.column = self.extent.column;
        } else {
            r.extent.row = 0;
            r.extent.column = self.extent.column.wrapping_sub(b.extent.column);
        }
        r
    }
}

#[derive(Clone, Debug)]
pub struct SubtreeData {
    pub symbol: TSSymbol,
    pub parse_state: TSStateId,
    pub padding: Length,
    pub size: Length,
    pub lookahead_bytes: u32,
    pub error_cost: u32,
    pub children: Vec<Subtree>,
    pub visible: bool,
    pub named: bool,
    pub extra: bool,
    pub fragile_left: bool,
    pub fragile_right: bool,
    pub has_external_tokens: bool,
    pub has_external_scanner_state_change: bool,
    pub depends_on_column: bool,
    pub is_missing: bool,
    pub is_keyword: bool,
    pub visible_child_count: u32,
    pub named_child_count: u32,
    pub visible_descendant_count: u32,
    pub dynamic_precedence: i32,
    pub repeat_depth: u16,
    pub production_id: u16,
    pub first_leaf_symbol: TSSymbol,
    pub first_leaf_parse_state: TSStateId,
    pub external_scanner_state: Vec<u8>,
    pub lookahead_char: i32,
}

pub type Subtree = Rc<SubtreeData>;

impl SubtreeData {
    pub fn child_count(&self) -> usize {
        self.children.len()
    }
    pub fn total_size(&self) -> Length {
        self.padding.add(self.size)
    }
    pub fn total_bytes(&self) -> u32 {
        self.padding.bytes + self.size.bytes
    }
    pub fn error_cost(&self) -> u32 {
        if self.is_missing {
            ERROR_COST_PER_MISSING_TREE + ERROR_COST_PER_RECOVERY
        } else {
            self.error_cost
        }
    }
    pub fn is_error(&self) -> bool {
        self.symbol == TS_BUILTIN_SYM_ERROR
    }
    pub fn is_eof(&self) -> bool {
        self.symbol == TS_BUILTIN_SYM_END
    }
    pub fn leaf_symbol(&self) -> TSSymbol {
        if self.children.is_empty() {
            self.symbol
        } else {
            self.first_leaf_symbol
        }
    }
    pub fn leaf_parse_state(&self) -> TSStateId {
        if self.children.is_empty() {
            self.parse_state
        } else {
            self.first_leaf_parse_state
        }
    }
    pub fn visible_descendant_count(&self) -> u32 {
        if self.children.is_empty() {
            0
        } else {
            self.visible_descendant_count
        }
    }
    pub fn dynamic_precedence(&self) -> i32 {
        if self.children.is_empty() {
            0
        } else {
            self.dynamic_precedence
        }
    }
    pub fn repeat_depth(&self) -> u16 {
        if self.children.is_empty() {
            0
        } else {
            self.repeat_depth
        }
    }
}

pub fn new_leaf(
    language: &Language,
    symbol: TSSymbol,
    padding: Length,
    size: Length,
    lookahead_bytes: u32,
    parse_state: TSStateId,
    has_external_tokens: bool,
    depends_on_column: bool,
    is_keyword: bool,
) -> SubtreeData {
    let metadata = language.symbol_metadata(symbol);
    let extra = symbol == TS_BUILTIN_SYM_END;
    SubtreeData {
        symbol,
        parse_state,
        padding,
        size,
        lookahead_bytes,
        error_cost: 0,
        children: Vec::new(),
        visible: metadata.visible,
        named: metadata.named,
        extra,
        fragile_left: false,
        fragile_right: false,
        has_external_tokens,
        has_external_scanner_state_change: false,
        depends_on_column,
        is_missing: false,
        is_keyword,
        visible_child_count: 0,
        named_child_count: 0,
        visible_descendant_count: 0,
        dynamic_precedence: 0,
        repeat_depth: 0,
        production_id: 0,
        first_leaf_symbol: 0,
        first_leaf_parse_state: 0,
        external_scanner_state: Vec::new(),
        lookahead_char: 0,
    }
}

pub fn new_error(language: &Language, lookahead_char: i32, padding: Length, size: Length, bytes_scanned: u32, parse_state: TSStateId) -> Subtree {
    let mut data = new_leaf(language, TS_BUILTIN_SYM_ERROR, padding, size, bytes_scanned, parse_state, false, false, false);
    data.fragile_left = true;
    data.fragile_right = true;
    data.lookahead_char = lookahead_char;
    Rc::new(data)
}

pub fn new_missing_leaf(language: &Language, symbol: TSSymbol, padding: Length, lookahead_bytes: u32) -> Subtree {
    let mut data = new_leaf(language, symbol, padding, Length::zero(), lookahead_bytes, 0, false, false, false);
    data.is_missing = true;
    Rc::new(data)
}

pub fn set_symbol(data: &mut SubtreeData, symbol: TSSymbol, language: &Language) {
    let metadata = language.symbol_metadata(symbol);
    data.symbol = symbol;
    data.named = metadata.named;
    data.visible = metadata.visible;
}

pub fn new_node(symbol: TSSymbol, children: Vec<Subtree>, production_id: u16, language: &Language) -> SubtreeData {
    let metadata = language.symbol_metadata(symbol);
    let fragile = symbol == TS_BUILTIN_SYM_ERROR || symbol == TS_BUILTIN_SYM_ERROR_REPEAT;
    let mut data = SubtreeData {
        symbol,
        parse_state: 0,
        padding: Length::zero(),
        size: Length::zero(),
        lookahead_bytes: 0,
        error_cost: 0,
        children,
        visible: metadata.visible,
        named: metadata.named,
        extra: false,
        fragile_left: fragile,
        fragile_right: fragile,
        has_external_tokens: false,
        has_external_scanner_state_change: false,
        depends_on_column: false,
        is_missing: false,
        is_keyword: false,
        visible_child_count: 0,
        named_child_count: 0,
        visible_descendant_count: 0,
        dynamic_precedence: 0,
        repeat_depth: 0,
        production_id,
        first_leaf_symbol: 0,
        first_leaf_parse_state: 0,
        external_scanner_state: Vec::new(),
        lookahead_char: 0,
    };
    summarize_children(&mut data, language);
    data
