pub fn new_error_node(children: Vec<Subtree>, extra: bool, language: &Language) -> Subtree {
    let mut data = new_node(TS_BUILTIN_SYM_ERROR, children, 0, language);
    data.extra = extra;
    Rc::new(data)
}

pub fn summarize_children(data: &mut SubtreeData, language: &Language) {
    data.named_child_count = 0;
    data.visible_child_count = 0;
    data.error_cost = 0;
    data.repeat_depth = 0;
    data.visible_descendant_count = 0;
    data.has_external_tokens = false;
    data.depends_on_column = false;
    data.has_external_scanner_state_change = false;
    data.dynamic_precedence = 0;

    let mut structural_index = 0usize;
    let mut lookahead_end_byte: u32 = 0;
    let production_id = data.production_id;
    let has_alias_seq = production_id != 0;

    let n = data.children.len();
    for i in 0..n {
        let child = data.children[i].clone();
        if data.size.extent.row == 0 && child.depends_on_column {
            data.depends_on_column = true;
        }
        if child.has_external_scanner_state_change {
            data.has_external_scanner_state_change = true;
        }
        if i == 0 {
            data.padding = child.padding;
            data.size = child.size;
        } else {
            data.size = data.size.add(child.total_size());
        }

        let child_lookahead_end_byte = data.padding.bytes + data.size.bytes + child.lookahead_bytes;
        if child_lookahead_end_byte > lookahead_end_byte {
            lookahead_end_byte = child_lookahead_end_byte;
        }

        if child.symbol != TS_BUILTIN_SYM_ERROR_REPEAT {
            data.error_cost += child.error_cost();
        }

        let grandchild_count = child.children.len();
        if data.symbol == TS_BUILTIN_SYM_ERROR || data.symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            if !child.extra && !(child.is_error() && grandchild_count == 0) {
                if child.visible {
                    data.error_cost += ERROR_COST_PER_SKIPPED_TREE;
                } else if grandchild_count > 0 {
                    data.error_cost += ERROR_COST_PER_SKIPPED_TREE * child.visible_child_count;
                }
            }
        }

        data.dynamic_precedence += child.dynamic_precedence();
        data.visible_descendant_count += child.visible_descendant_count();

        let alias = if has_alias_seq && !child.extra { language.alias_at(production_id, structural_index) } else { 0 };
        if alias != 0 {
            data.visible_descendant_count += 1;
            data.visible_child_count += 1;
            if language.symbol_metadata(alias).named {
                data.named_child_count += 1;
            }
        } else if child.visible {
            data.visible_descendant_count += 1;
            data.visible_child_count += 1;
            if child.named {
                data.named_child_count += 1;
            }
        } else if grandchild_count > 0 {
            data.visible_child_count += child.visible_child_count;
            data.named_child_count += child.named_child_count;
        }

        if child.has_external_tokens {
            data.has_external_tokens = true;
        }

        if child.is_error() {
            data.fragile_left = true;
            data.fragile_right = true;
            data.parse_state = TS_TREE_STATE_NONE;
        }

        if !child.extra {
            structural_index += 1;
        }
    }

    data.lookahead_bytes = lookahead_end_byte.wrapping_sub(data.size.bytes).wrapping_sub(data.padding.bytes);

    if data.symbol == TS_BUILTIN_SYM_ERROR || data.symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
        data.error_cost += ERROR_COST_PER_RECOVERY + ERROR_COST_PER_SKIPPED_CHAR * data.size.bytes + ERROR_COST_PER_SKIPPED_LINE * data.size.extent.row;
    }

    if n > 0 {
        let first_child = data.children[0].clone();
        let last_child = data.children[n - 1].clone();
        data.first_leaf_symbol = first_child.leaf_symbol();
        data.first_leaf_parse_state = first_child.leaf_parse_state();
        if first_child.fragile_left {
            data.fragile_left = true;
        }
        if last_child.fragile_right {
            data.fragile_right = true;
        }
        if n >= 2 && !data.visible && !data.named && first_child.symbol == data.symbol {
            if first_child.repeat_depth() > last_child.repeat_depth() {
                data.repeat_depth = first_child.repeat_depth() + 1;
            } else {
                data.repeat_depth = last_child.repeat_depth() + 1;
            }
        }
    }
}

pub fn last_external_token(tree: &Subtree) -> Option<Subtree> {
    let mut tree = tree.clone();
    if !tree.has_external_tokens {
        return None;
    }
    while !tree.children.is_empty() {
        let mut found = None;
        for child in tree.children.iter().rev() {
            if child.has_external_tokens {
                found = Some(child.clone());
                break;
            }
        }
        match found {
            Some(c) => tree = c,
            None => break,
        }
    }
    Some(tree)
}

pub fn external_scanner_state_eq(a: &Option<Subtree>, b: &Option<Subtree>) -> bool {
    let sa: &[u8] = match a {
        Some(s) => &s.external_scanner_state,
        None => &[],
    };
    let sb: &[u8] = match b {
        Some(s) => &s.external_scanner_state,
        None => &[],
    };
    sa == sb
}

pub fn compare(left: &Subtree, right: &Subtree) -> i32 {
    let mut stack: Vec<(Subtree, Subtree)> = vec![(left.clone(), right.clone())];
    while let Some((left, right)) = stack.pop() {
        let mut result = 0;
        if left.symbol < right.symbol {
            result = -1;
        } else if right.symbol < left.symbol {
            result = 1;
        } else if left.children.len() < right.children.len() {
            result = -1;
        } else if right.children.len() < left.children.len() {
            result = 1;
        }
        if result != 0 {
            return result;
        }
        // Push children in reverse so that the first child is compared first (LIFO).
        let n = left.children.len();
        let mut pairs = Vec::with_capacity(n);
        for i in (0..n).rev() {
            pairs.push((left.children[i].clone(), right.children[i].clone()));
        }
        // The C implementation pushes children from last to first onto a stack, then pops,
        // so the first child pair is examined first.
        for p in pairs {
            stack.push(p);
        }
    }
    0
}

pub fn remove_trailing_extras(subtrees: &mut Vec<Subtree>) -> Vec<Subtree> {
    let mut destination = Vec::new();
    while let Some(last) = subtrees.last() {
        if last.extra {
            destination.push(subtrees.pop().unwrap());
        } else {
            break;
        }
    }
    destination.reverse();
    destination
}
