    pub status: StackStatus,
}

pub struct StackSlice {
    pub subtrees: Vec<Subtree>,
    pub version: StackVersion,
}

#[derive(Clone)]
struct StackIterator {
    node: NodeRef,
    subtrees: Vec<Subtree>,
    subtree_count: u32,
    is_pending: bool,
}

pub struct Stack {
    pub heads: Vec<StackHead>,
    base_node: NodeRef,
}

fn subtree_node_count(subtree: &Subtree) -> u32 {
    let mut count = subtree.visible_descendant_count();
    if subtree.visible {
        count += 1;
    }
    if subtree.symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
        count += 1;
    }
    count
}

fn subtree_is_equivalent(left: &Option<Subtree>, right: &Option<Subtree>) -> bool {
    match (left, right) {
        (None, None) => true,
        (Some(l), Some(r)) => {
            if Rc::ptr_eq(l, r) {
                return true;
            }
            if l.symbol != r.symbol {
                return false;
            }
            if l.error_cost() > 0 && r.error_cost() > 0 {
                return true;
            }
            l.padding.bytes == r.padding.bytes
                && l.size.bytes == r.size.bytes
                && l.children.len() == r.children.len()
                && l.extra == r.extra
                && external_scanner_state_eq(left, right)
        }
        _ => false,
    }
}

fn node_new(previous: Option<&NodeRef>, subtree: Option<Subtree>, is_pending: bool, state: TSStateId) -> NodeRef {
    let mut node = StackNode { state, position: Length::zero(), links: Vec::new(), error_cost: 0, node_count: 0, dynamic_precedence: 0 };
    if let Some(prev) = previous {
        let p = prev.borrow();
        node.position = p.position;
        node.error_cost = p.error_cost;
        node.dynamic_precedence = p.dynamic_precedence;
        node.node_count = p.node_count;
        if let Some(s) = &subtree {
            node.error_cost += s.error_cost();
            node.position = node.position.add(s.total_size());
            node.node_count += subtree_node_count(s);
            node.dynamic_precedence += s.dynamic_precedence();
        }
        drop(p);
        node.links.push(StackLink { node: prev.clone(), subtree, is_pending });
    }
    Rc::new(RefCell::new(node))
}

fn node_add_link(self_node: &NodeRef, link: StackLink) {
    if Rc::ptr_eq(&link.node, self_node) {
        return;
    }
    let link_count = self_node.borrow().links.len();
    for i in 0..link_count {
        let existing = self_node.borrow().links[i].clone();
        if subtree_is_equivalent(&existing.subtree, &link.subtree) {
            // In general, we preserve ambiguities until they are removed from the stack
            // during a pop operation where multiple paths lead to the same node. But in
            // the special case where two links directly connect the same pair of nodes,
            // we can safely remove the ambiguity ahead of time without changing behavior.
            if Rc::ptr_eq(&existing.node, &link.node) {
                let new_dp = link.subtree.as_ref().map_or(0, |s| s.dynamic_precedence());
                let old_dp = existing.subtree.as_ref().map_or(0, |s| s.dynamic_precedence());
                if new_dp > old_dp {
                    let ldp = link.node.borrow().dynamic_precedence;
                    let mut sn = self_node.borrow_mut();
                    sn.links[i].subtree = link.subtree.clone();
                    sn.dynamic_precedence = ldp + new_dp;
                }
                return;
            }

            // If the previous nodes are mergeable, merge them recursively.
            let (es, ep, ee) = {
                let e = existing.node.borrow();
                (e.state, e.position.bytes, e.error_cost)
            };
            let (ls, lp, le, l_links, l_dp) = {
                let l = link.node.borrow();
                (l.state, l.position.bytes, l.error_cost, l.links.clone(), l.dynamic_precedence)
            };
            if es == ls && ep == lp && ee == le {
                for l in l_links {
                    node_add_link(&existing.node, l);
                }
                let mut dynamic_precedence = l_dp;
                if let Some(s) = &link.subtree {
                    dynamic_precedence += s.dynamic_precedence();
                }
                let mut sn = self_node.borrow_mut();
                if dynamic_precedence > sn.dynamic_precedence {
                    sn.dynamic_precedence = dynamic_precedence;
                }
                return;
            }
        }
    }

    if link_count == MAX_LINK_COUNT {
        return;
    }

    let mut node_count = link.node.borrow().node_count;
    let mut dynamic_precedence = link.node.borrow().dynamic_precedence;
    if let Some(s) = &link.subtree {
        node_count += subtree_node_count(s);
        dynamic_precedence += s.dynamic_precedence();
    }
    let mut sn = self_node.borrow_mut();
    sn.links.push(link);
    if node_count > sn.node_count {
        sn.node_count = node_count;
    }
    if dynamic_precedence > sn.dynamic_precedence {
        sn.dynamic_precedence = dynamic_precedence;
    }
}

enum Callback<'a> {
    PopCount(u32),
    PopPending,
    PopError(&'a mut bool),
    PopAll,
    Summarize(&'a mut Vec<StackSummaryEntry>, u32),
}

const ACTION_NONE: u32 = 0;
const ACTION_POP: u32 = 1;
const ACTION_STOP: u32 = 2;

impl Stack {
    pub fn new() -> Stack {
        let base_node = node_new(None, None, false, 1);
        let mut s = Stack { heads: Vec::new(), base_node };
        s.clear();
        s
    }

    pub fn clear(&mut self) {
        self.heads.clear();
        self.heads.push(StackHead {
            node: self.base_node.clone(),
            summary: None,
            node_count_at_last_error: 0,
            last_external_token: None,
            lookahead_when_paused: None,
            status: StackStatus::Active,
        });
    }

    pub fn version_count(&self) -> usize {
        self.heads.len()
    }

    pub fn halted_version_count(&self) -> usize {
        self.heads.iter().filter(|h| h.status == StackStatus::Halted).count()
    }

    pub fn state(&self, version: StackVersion) -> TSStateId {
        self.heads[version].node.borrow().state
    }

    pub fn position(&self, version: StackVersion) -> Length {
        self.heads[version].node.borrow().position
    }

    pub fn last_external_token(&self, version: StackVersion) -> Option<Subtree> {
        self.heads[version].last_external_token.clone()
    }

    pub fn set_last_external_token(&mut self, version: StackVersion, token: Option<Subtree>) {
        self.heads[version].last_external_token = token;
    }

    pub fn error_cost(&self, version: StackVersion) -> u32 {
        let head = &self.heads[version];
        let node = head.node.borrow();
        let mut result = node.error_cost;
        if head.status == StackStatus::Paused || (node.state == ERROR_STATE && node.links.first().map_or(true, |l| l.subtree.is_none())) {
            result += ERROR_COST_PER_RECOVERY;
        }
        result
    }

    pub fn node_count_since_error(&mut self, version: StackVersion) -> u32 {
        let head = &mut self.heads[version];
        let nc = head.node.borrow().node_count;
        if nc < head.node_count_at_last_error {
            head.node_count_at_last_error = nc;
        }
        nc - head.node_count_at_last_error
    }

    pub fn dynamic_precedence(&self, version: StackVersion) -> i32 {
        self.heads[version].node.borrow().dynamic_precedence
    }

    pub fn push(&mut self, version: StackVersion, subtree: Option<Subtree>, pending: bool, state: TSStateId) {
        let head = &mut self.heads[version];
        let is_none = subtree.is_none();
        let new_node = node_new(Some(&head.node), subtree, pending, state);
        if is_none {
            head.node_count_at_last_error = new_node.borrow().node_count;
        }
        head.node = new_node;
    }

    fn add_version(&mut self, original_version: StackVersion, node: NodeRef) -> StackVersion {
        let head = StackHead {
            node,
            summary: None,
            node_count_at_last_error: self.heads[original_version].node_count_at_last_error,
            last_external_token: self.heads[original_version].last_external_token.clone(),
            lookahead_when_paused: None,
            status: StackStatus::Active,
        };
        self.heads.push(head);
        self.heads.len() - 1
    }

    fn add_slice(&mut self, slices: &mut Vec<StackSlice>, original_version: StackVersion, node: &NodeRef, subtrees: Vec<Subtree>) {
        for i in (0..slices.len()).rev() {
            let version = slices[i].version;
            if Rc::ptr_eq(&self.heads[version].node, node) {
                slices.insert(i + 1, StackSlice { subtrees, version });
                return;
            }
        }
        let version = self.add_version(original_version, node.clone());
        slices.push(StackSlice { subtrees, version });
    }

    fn iter(&mut self, version: StackVersion, mut callback: Callback, goal_subtree_count: i64) -> Vec<StackSlice> {
        let mut slices: Vec<StackSlice> = Vec::new();
        let mut iterators: Vec<StackIterator> = Vec::new();
        let head_node = self.heads[version].node.clone();
        let include_subtrees = goal_subtree_count >= 0;
        iterators.push(StackIterator { node: head_node, subtrees: Vec::new(), subtree_count: 0, is_pending: true });

        while !iterators.is_empty() {
            let mut i = 0;
            let mut size = iterators.len();
            while i < size {
                let node = iterators[i].node.clone();
                let action = match &mut callback {
                    Callback::PopCount(goal) => {
                        if iterators[i].subtree_count == *goal {
                            ACTION_POP | ACTION_STOP
                        } else {
                            ACTION_NONE
                        }
                    }
                    Callback::PopPending => {
                        if iterators[i].subtree_count >= 1 {
                            if iterators[i].is_pending {
                                ACTION_POP | ACTION_STOP
                            } else {
                                ACTION_STOP
                            }
                        } else {
                            ACTION_NONE
                        }
                    }
                    Callback::PopError(found_error) => {
                        if !iterators[i].subtrees.is_empty() {
                            if !**found_error && iterators[i].subtrees[0].is_error() {
                                **found_error = true;
                                ACTION_POP | ACTION_STOP
                            } else {
                                ACTION_STOP
                            }
                        } else {
                            ACTION_NONE
                        }
                    }
                    Callback::PopAll => {
                        if node.borrow().links.is_empty() {
                            ACTION_POP
                        } else {
                            ACTION_NONE
                        }
                    }
                    Callback::Summarize(summary, max_depth) => {
                        let state = node.borrow().state;
                        let depth = iterators[i].subtree_count;
                        if depth > *max_depth {
                            ACTION_STOP
                        } else {
                            let mut found = false;
                            for entry in summary.iter().rev() {
                                if entry.depth < depth {
                                    break;
                                }
                                if entry.depth == depth && entry.state == state {
                                    found = true;
                                    break;
                                }
                            }
                            if !found {
                                summary.push(StackSummaryEntry { position: node.borrow().position, depth, state });
                            }
                            ACTION_NONE
                        }
                    }
                };
                let should_pop = action & ACTION_POP != 0;
                let link_count = node.borrow().links.len();
                let should_stop = action & ACTION_STOP != 0 || link_count == 0;

                if should_pop {
                    let mut subtrees = iterators[i].subtrees.clone();
                    subtrees.reverse();
                    self.add_slice(&mut slices, version, &node, subtrees);
                }

                if should_stop {
                    iterators.remove(i);
                    size -= 1;
                    continue;
                }

                let links = node.borrow().links.clone();
                for j in 1..=link_count {
                    let link;
                    let idx;
                    if j == link_count {
                        link = links[0].clone();
                        idx = i;
                    } else {
                        if iterators.len() >= MAX_ITERATOR_COUNT {
                            continue;
                        }
                        link = links[j].clone();
                        let current = iterators[i].clone();
                        iterators.push(current);
                        idx = iterators.len() - 1;
                    }
                    let next_iterator = &mut iterators[idx];
                    next_iterator.node = link.node.clone();
                    if let Some(s) = &link.subtree {
                        if include_subtrees {
                            next_iterator.subtrees.push(s.clone());
                        }
                        if !s.extra {
                            next_iterator.subtree_count += 1;
                            if !link.is_pending {
                                next_iterator.is_pending = false;
                            }
                        }
                    } else {
                        next_iterator.subtree_count += 1;
                        next_iterator.is_pending = false;
                    }
                }
                i += 1;
            }
        }
        slices
    }

    pub fn pop_count(&mut self, version: StackVersion, count: u32) -> Vec<StackSlice> {
        self.iter(version, Callback::PopCount(count), count as i64)
    }

    pub fn pop_pending(&mut self, version: StackVersion) -> Vec<StackSlice> {
        let mut pop = self.iter(version, Callback::PopPending, 0);
        if !pop.is_empty() {
            let v = pop[0].version;
            self.renumber_version(v, version);
            pop[0].version = version;
        }
        pop
    }

    pub fn pop_error(&mut self, version: StackVersion) -> Vec<Subtree> {
        let links = self.heads[version].node.borrow().links.clone();
        for link in &links {
            if let Some(s) = &link.subtree {
                if s.is_error() {
                    let mut found_error = false;
                    let pop = self.iter(version, Callback::PopError(&mut found_error), 1);
                    if !pop.is_empty() {
                        let v = pop[0].version;
                        self.renumber_version(v, version);
                        return pop.into_iter().next().unwrap().subtrees;
                    }
                    break;
                }
            }
        }
        Vec::new()
    }

    pub fn pop_all(&mut self, version: StackVersion) -> Vec<StackSlice> {
        self.iter(version, Callback::PopAll, 0)
    }

    pub fn record_summary(&mut self, version: StackVersion, max_depth: u32) {
        let mut summary = Vec::new();
        self.iter(version, Callback::Summarize(&mut summary, max_depth), -1);
        self.heads[version].summary = Some(Rc::new(summary));
    }

    pub fn get_summary(&self, version: StackVersion) -> Option<Rc<Vec<StackSummaryEntry>>> {
        self.heads[version].summary.clone()
    }

    pub fn has_advanced_since_error(&self, version: StackVersion) -> bool {
        let head = &self.heads[version];
        let mut node = head.node.clone();
        if node.borrow().error_cost == 0 {
            return true;
        }
        loop {
            let next = {
                let n = node.borrow();
                if let Some(link) = n.links.first() {
                    if let Some(subtree) = &link.subtree {
                        if subtree.total_bytes() > 0 {
                            return true;
                        } else if n.node_count > head.node_count_at_last_error && subtree.error_cost() == 0 {
                            Some(link.node.clone())
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            match next {
                Some(n) => node = n,
                None => break,
            }
        }
        false
    }

    pub fn remove_version(&mut self, version: StackVersion) {
        self.heads.remove(version);
    }

    pub fn renumber_version(&mut self, v1: StackVersion, v2: StackVersion) {
        if v1 == v2 {
            return;
        }
        let mut source = self.heads[v1].clone();
        if self.heads[v2].summary.is_some() && source.summary.is_none() {
            source.summary = self.heads[v2].summary.take();
        }
        self.heads[v2] = source;
        self.heads.remove(v1);
    }

    pub fn swap_versions(&mut self, v1: StackVersion, v2: StackVersion) {
        self.heads.swap(v1, v2);
    }

    pub fn copy_version(&mut self, version: StackVersion) -> StackVersion {
        let mut head = self.heads[version].clone();
        head.summary = None;
        self.heads.push(head);
        self.heads.len() - 1
    }

    pub fn can_merge(&self, version1: StackVersion, version2: StackVersion) -> bool {
        let head1 = &self.heads[version1];
        let head2 = &self.heads[version2];
        let n1 = head1.node.borrow();
        let n2 = head2.node.borrow();
        head1.status == StackStatus::Active
            && head2.status == StackStatus::Active
            && n1.state == n2.state
            && n1.position.bytes == n2.position.bytes
            && n1.error_cost == n2.error_cost
            && external_scanner_state_eq(&head1.last_external_token, &head2.last_external_token)
    }

    pub fn merge(&mut self, version1: StackVersion, version2: StackVersion) -> bool {
        if !self.can_merge(version1, version2) {
            return false;
        }
        let node1 = self.heads[version1].node.clone();
        let links2 = self.heads[version2].node.borrow().links.clone();
        for link in links2 {
            node_add_link(&node1, link);
        }
        if node1.borrow().state == ERROR_STATE {
            self.heads[version1].node_count_at_last_error = node1.borrow().node_count;
        }
        self.remove_version(version2);
        true
    }

    pub fn halt(&mut self, version: StackVersion) {
        self.heads[version].status = StackStatus::Halted;
    }

    pub fn pause(&mut self, version: StackVersion, lookahead: Subtree) {
        let head = &mut self.heads[version];
        head.status = StackStatus::Paused;
        head.lookahead_when_paused = Some(lookahead);
        head.node_count_at_last_error = head.node.borrow().node_count;
    }

    pub fn is_active(&self, version: StackVersion) -> bool {
        self.heads[version].status == StackStatus::Active
    }

    pub fn is_halted(&self, version: StackVersion) -> bool {
        self.heads[version].status == StackStatus::Halted
    }

    pub fn is_paused(&self, version: StackVersion) -> bool {
        self.heads[version].status == StackStatus::Paused
    }

    pub fn resume(&mut self, version: StackVersion) -> Option<Subtree> {
        let head = &mut self.heads[version];
        head.status = StackStatus::Active;
        head.lookahead_when_paused.take()
    }
}
