const LENGTH_UNDEFINED: Length = Length { bytes: 0, extent: Point { row: 0, column: 1 } };

fn length_is_undefined(l: &Length) -> bool {
    l.bytes == 0 && l.extent.column != 0
}

fn decode_utf8(bytes: &[u8]) -> (i32, u32) {
    let b0 = bytes[0];
    if b0 < 0x80 {
        return (b0 as i32, 1);
    }
    let (len, init) = if b0 & 0xE0 == 0xC0 {
        (2, (b0 & 0x1F) as u32)
    } else if b0 & 0xF0 == 0xE0 {
        (3, (b0 & 0x0F) as u32)
    } else if b0 & 0xF8 == 0xF0 {
        (4, (b0 & 0x07) as u32)
    } else {
        return (TS_DECODE_ERROR, 1);
    };
    if bytes.len() < len {
        return (TS_DECODE_ERROR, 1);
    }
    let mut cp = init;
    for i in 1..len {
        let b = bytes[i];
        if b & 0xC0 != 0x80 {
            return (TS_DECODE_ERROR, i as u32);
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    // reject overlong / surrogates / out of range
    let valid = match len {
        2 => cp >= 0x80,
        3 => cp >= 0x800 && !(0xD800..0xE000).contains(&cp),
        _ => (0x10000..=0x10FFFF).contains(&cp),
    };
    if !valid {
        return (TS_DECODE_ERROR, 1);
    }
    (cp as i32, len as u32)
}

fn decode_utf16(bytes: &[u8], le: bool) -> (i32, u32) {
    if bytes.len() < 2 {
        return (TS_DECODE_ERROR, bytes.len() as u32);
    }
    let unit = |i: usize| -> u32 {
        if le {
            u16::from_le_bytes([bytes[i], bytes[i + 1]]) as u32
        } else {
            u16::from_be_bytes([bytes[i], bytes[i + 1]]) as u32
        }
    };
    let u0 = unit(0);
    if (0xD800..0xDC00).contains(&u0) {
        if bytes.len() >= 4 {
            let u1 = unit(2);
            if (0xDC00..0xE000).contains(&u1) {
                return ((0x10000 + ((u0 - 0xD800) << 10) + (u1 - 0xDC00)) as i32, 4);
            }
        }
        return (TS_DECODE_ERROR, 2);
    }
    if (0xDC00..0xE000).contains(&u0) {
        return (TS_DECODE_ERROR, 2);
    }
    (u0 as i32, 2)
}

extern "C" fn lexer_advance(this: *mut TSLexer, skip: bool) {
    let lexer = unsafe { &mut *(this as *mut Lexer) };
    if !lexer.chunk_valid {
        return;
    }
    lexer.do_advance(skip);
}

extern "C" fn lexer_mark_end(this: *mut TSLexer) {
    let lexer = unsafe { &mut *(this as *mut Lexer) };
    lexer.mark_end();
}

