    let lexer = unsafe { &*(this as *const Lexer) };
    if lexer.current_included_range_index < lexer.included_ranges.len() {
        let r = &lexer.included_ranges[lexer.current_included_range_index];
        lexer.current_position.bytes == r.start_byte
    } else {
        false
    }
}

extern "C" fn lexer_eof(this: *const TSLexer) -> bool {
    let lexer = unsafe { &*(this as *const Lexer) };
    lexer.is_eof()
}

impl Lexer {
    pub fn new(input: Vec<u8>, encoding: Encoding) -> Box<Lexer> {
        let mut l = Box::new(Lexer {
            data: TSLexer {
                lookahead: 0,
                result_symbol: 0,
                advance: lexer_advance,
                mark_end: lexer_mark_end,
                get_column: lexer_get_column,
                is_at_included_range_start: lexer_is_at_included_range_start,
                eof: lexer_eof,
                log: std::ptr::null(),
            },
            current_position: Length::zero(),
            token_start_position: Length::zero(),
            token_end_position: LENGTH_UNDEFINED,
            included_ranges: vec![Range { start_byte: 0, end_byte: u32::MAX, start_point: Point::default(), end_point: Point { row: u32::MAX, column: u32::MAX } }],
            current_included_range_index: 0,
            input,
            encoding,
            chunk_valid: false,
            lookahead_size: 0,
            did_get_column: false,
            column_valid: false,
            column_value: 0,
            logger: None,
        });
        l.goto_position(Length::zero());
        l
    }

    pub fn is_eof(&self) -> bool {
        self.current_included_range_index == self.included_ranges.len()
    }

    fn get_chunk(&mut self) {
        if (self.current_position.bytes as usize) < self.input.len() {
            self.chunk_valid = true;
        } else {
            self.current_included_range_index = self.included_ranges.len();
            self.chunk_valid = false;
        }
    }

    fn get_lookahead(&mut self) {
        let pos = self.current_position.bytes as usize;
        if pos >= self.input.len() {
            self.lookahead_size = 1;
            self.data.lookahead = 0;
            return;
        }
        let rest = &self.input[pos..];
        let (cp, size) = match self.encoding {
            Encoding::Utf8 => decode_utf8(rest),
            Encoding::Utf16LE => decode_utf16(rest, true),
            Encoding::Utf16BE => decode_utf16(rest, false),
        };
        self.data.lookahead = cp;
        self.lookahead_size = size.max(1);
    }

    fn do_advance(&mut self, skip: bool) {
