            if self.data.lookahead == '\n' as i32 {
                self.current_position.extent.row += 1;
                self.current_position.extent.column = 0;
            } else {
                self.current_position.extent.column += self.lookahead_size;
            }
            self.current_position.bytes += self.lookahead_size;
        }

        let mut has_range = true;
        loop {
            let idx = self.current_included_range_index;
            if idx >= self.included_ranges.len() {
                has_range = false;
                break;
            }
            let r = self.included_ranges[idx];
            if self.current_position.bytes >= r.end_byte || r.end_byte == r.start_byte {
                if self.current_included_range_index < self.included_ranges.len() {
                    self.current_included_range_index += 1;
