        if !self.is_eof() {
            let idx = self.current_included_range_index;
            if idx > 0 && self.current_position.bytes == self.included_ranges[idx].start_byte {
                let prev = self.included_ranges[idx - 1];
                self.token_end_position = Length { bytes: prev.end_byte, extent: prev.end_point };
                return;
            }
        }
        self.token_end_position = self.current_position;
    }

    pub fn get_column(&mut self) -> u32 {
        let goal_byte = self.current_position.bytes;
        self.did_get_column = true;
        if !self.column_valid {
            // Back up to the beginning of the line
            let start_of_col = Length {
                bytes: self.current_position.bytes - self.current_position.extent.column,
                extent: Point { row: self.current_position.extent.row, column: 0 },
            };
            let saved_lookahead = self.data.lookahead;
            let saved_size = self.lookahead_size;
            let saved_pos = self.current_position;
            let saved_idx = self.current_included_range_index;
            let saved_chunk = self.chunk_valid;
            self.goto_position(start_of_col);
            self.get_chunk();
            let mut result = 0;
            if !self.is_eof() {
                self.get_lookahead();
                while self.current_position.bytes < goal_byte && self.chunk_valid {
                    result += 1;
                    self.do_advance(false);
                    if self.is_eof() {
                        break;
                    }
                }
            }
            self.current_position = saved_pos;
            self.current_included_range_index = saved_idx;
            self.chunk_valid = saved_chunk;
            self.data.lookahead = saved_lookahead;
            self.lookahead_size = saved_size;
            self.column_value = result;
            self.column_valid = true;
        }
        self.column_value
    }

    pub fn goto_position(&mut self, position: Length) {
        self.current_position = position;
        let mut found = false;
        for i in 0..self.included_ranges.len() {
            let r = self.included_ranges[i];
            if r.end_byte > self.current_position.bytes && r.end_byte > r.start_byte {
                if r.start_byte >= self.current_position.bytes {
                    self.current_position = Length { bytes: r.start_byte, extent: r.start_point };
                }
                self.current_included_range_index = i;
                found = true;
                break;
            }
        }
        if found {
            self.chunk_valid = (self.current_position.bytes as usize) < self.input.len();
            self.lookahead_size = 0;
            self.data.lookahead = 0;
        } else {
            self.current_included_range_index = self.included_ranges.len();
            let last = *self.included_ranges.last().unwrap();
            self.current_position = Length { bytes: last.end_byte, extent: last.end_point };
            self.chunk_valid = false;
            self.lookahead_size = 1;
            self.data.lookahead = 0;
        }
    }

    pub fn reset(&mut self, position: Length) {
        if position.bytes != self.current_position.bytes {
            self.goto_position(position);
        }
    }

    pub fn start(&mut self) {
        self.token_start_position = self.current_position;
        self.token_end_position = LENGTH_UNDEFINED;
        self.data.result_symbol = 0;
        self.did_get_column = false;
        if !self.is_eof() {
            if !self.chunk_valid {
                self.get_chunk();
            }
            if self.lookahead_size == 0 && !self.is_eof() {
                self.get_lookahead();
            }
            if self.current_position.bytes == 0 && self.data.lookahead == 0xFEFF {
                lexer_advance(&mut self.data as *mut TSLexer, true);
            }
            if self.is_eof() {
                self.data.lookahead = 0;
                self.lookahead_size = 1;
            }
        }
        self.column_valid = false;
    }

    pub fn finish(&mut self, lookahead_end_byte: &mut u32) {
        if length_is_undefined(&self.token_end_position) {
            self.mark_end();
        }
        let mut current_lookahead_end_byte = self.current_position.bytes + 1;
        if self.data.lookahead == TS_DECODE_ERROR {
            current_lookahead_end_byte += 4;
        }
        if current_lookahead_end_byte > *lookahead_end_byte {
            *lookahead_end_byte = current_lookahead_end_byte;
        }
    }
}
