#![allow(dead_code)]
use super::language::TSLexer;
use super::subtree::{Length, Point};

pub const TS_DECODE_ERROR: i32 = -1;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Encoding {
    Utf8,
    Utf16LE,
    Utf16BE,
}

#[derive(Clone, Copy, Debug)]
pub struct Range {
    pub start_byte: u32,
    pub end_byte: u32,
    pub start_point: Point,
    pub end_point: Point,
}

#[repr(C)]
pub struct Lexer {
    pub data: TSLexer,
    pub current_position: Length,
    pub token_start_position: Length,
    pub token_end_position: Length,
    pub included_ranges: Vec<Range>,
    pub current_included_range_index: usize,
    pub input: Vec<u8>,
    pub encoding: Encoding,
    pub chunk_valid: bool,
    pub lookahead_size: u32,
    pub did_get_column: bool,
    pub column_valid: bool,
    pub column_value: u32,
    pub logger: Option<Box<dyn FnMut(&str)>>,
}

const LENGTH_UNDEFINED: Length = Length { bytes: 0, extent: Point { row: 0, column: 1 } };

fn length_is_undefined(l: &Length) -> bool {
    l.bytes == 0 && l.extent.column != 0
}

fn decode_utf8(bytes: &[u8]) -> (i32, u32) {
    let b0 = bytes[0];
    if b0 < 0x80 {
        return (b0 as i32, 1);
    }
    let (len, init) = if b0 & 0xE0 == 0xC0 {
        (2, (b0 & 0x1F) as u32)
    } else if b0 & 0xF0 == 0xE0 {
        (3, (b0 & 0x0F) as u32)
    } else if b0 & 0xF8 == 0xF0 {
        (4, (b0 & 0x07) as u32)
    } else {
        return (TS_DECODE_ERROR, 1);
    };
    if bytes.len() < len {
        return (TS_DECODE_ERROR, 1);
    }
    let mut cp = init;
    for i in 1..len {
        let b = bytes[i];
        if b & 0xC0 != 0x80 {
            return (TS_DECODE_ERROR, i as u32);
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    // reject overlong / surrogates / out of range
    let valid = match len {
        2 => cp >= 0x80,
        3 => cp >= 0x800 && !(0xD800..0xE000).contains(&cp),
        _ => (0x10000..=0x10FFFF).contains(&cp),
    };
    if !valid {
        return (TS_DECODE_ERROR, 1);
    }
    (cp as i32, len as u32)
}

fn decode_utf16(bytes: &[u8], le: bool) -> (i32, u32) {
    if bytes.len() < 2 {
        return (TS_DECODE_ERROR, bytes.len() as u32);
    }
    let unit = |i: usize| -> u32 {
        if le {
            u16::from_le_bytes([bytes[i], bytes[i + 1]]) as u32
        } else {
            u16::from_be_bytes([bytes[i], bytes[i + 1]]) as u32
        }
    };
    let u0 = unit(0);
    if (0xD800..0xDC00).contains(&u0) {
        if bytes.len() >= 4 {
            let u1 = unit(2);
            if (0xDC00..0xE000).contains(&u1) {
                return ((0x10000 + ((u0 - 0xD800) << 10) + (u1 - 0xDC00)) as i32, 4);
            }
        }
        return (TS_DECODE_ERROR, 2);
    }
    if (0xDC00..0xE000).contains(&u0) {
        return (TS_DECODE_ERROR, 2);
    }
    (u0 as i32, 2)
}

extern "C" fn lexer_advance(this: *mut TSLexer, skip: bool) {
    let lexer = unsafe { &mut *(this as *mut Lexer) };
    if !lexer.chunk_valid {
        return;
    }
    lexer.do_advance(skip);
}

extern "C" fn lexer_mark_end(this: *mut TSLexer) {
    let lexer = unsafe { &mut *(this as *mut Lexer) };
    lexer.mark_end();
}

extern "C" fn lexer_get_column(this: *mut TSLexer) -> u32 {
    let lexer = unsafe { &mut *(this as *mut Lexer) };
    lexer.get_column()
}

extern "C" fn lexer_is_at_included_range_start(this: *const TSLexer) -> bool {
    let lexer = unsafe { &*(this as *const Lexer) };
    if lexer.current_included_range_index < lexer.included_ranges.len() {
        let r = &lexer.included_ranges[lexer.current_included_range_index];
        lexer.current_position.bytes == r.start_byte
    } else {
        false
    }
}

extern "C" fn lexer_eof(this: *const TSLexer) -> bool {
    let lexer = unsafe { &*(this as *const Lexer) };
    lexer.is_eof()
}

impl Lexer {
    pub fn new(input: Vec<u8>, encoding: Encoding) -> Box<Lexer> {
        let mut l = Box::new(Lexer {
            data: TSLexer {
                lookahead: 0,
                result_symbol: 0,
                advance: lexer_advance,
                mark_end: lexer_mark_end,
                get_column: lexer_get_column,
                is_at_included_range_start: lexer_is_at_included_range_start,
                eof: lexer_eof,
                log: std::ptr::null(),
            },
            current_position: Length::zero(),
            token_start_position: Length::zero(),
            token_end_position: LENGTH_UNDEFINED,
            included_ranges: vec![Range { start_byte: 0, end_byte: u32::MAX, start_point: Point::default(), end_point: Point { row: u32::MAX, column: u32::MAX } }],
            current_included_range_index: 0,
            input,
            encoding,
            chunk_valid: false,
            lookahead_size: 0,
            did_get_column: false,
            column_valid: false,
            column_value: 0,
            logger: None,
        });
        l.goto_position(Length::zero());
        l
    }

    pub fn is_eof(&self) -> bool {
        self.current_included_range_index == self.included_ranges.len()
    }

    fn get_chunk(&mut self) {
        if (self.current_position.bytes as usize) < self.input.len() {
            self.chunk_valid = true;
        } else {
            self.current_included_range_index = self.included_ranges.len();
            self.chunk_valid = false;
        }
    }

    fn get_lookahead(&mut self) {
        let pos = self.current_position.bytes as usize;
        if pos >= self.input.len() {
            self.lookahead_size = 1;
            self.data.lookahead = 0;
            return;
        }
        let rest = &self.input[pos..];
        let (cp, size) = match self.encoding {
            Encoding::Utf8 => decode_utf8(rest),
            Encoding::Utf16LE => decode_utf16(rest, true),
            Encoding::Utf16BE => decode_utf16(rest, false),
        };
        self.data.lookahead = cp;
        self.lookahead_size = size.max(1);
    }

    fn do_advance(&mut self, skip: bool) {
        if self.lookahead_size > 0 {
            if self.data.lookahead == '\n' as i32 {
                self.current_position.extent.row += 1;
                self.current_position.extent.column = 0;
            } else {
                self.current_position.extent.column += self.lookahead_size;
            }
            self.current_position.bytes += self.lookahead_size;
        }

        let mut has_range = true;
        loop {
            let idx = self.current_included_range_index;
            if idx >= self.included_ranges.len() {
                has_range = false;
                break;
            }
            let r = self.included_ranges[idx];
            if self.current_position.bytes >= r.end_byte || r.end_byte == r.start_byte {
                if self.current_included_range_index < self.included_ranges.len() {
                    self.current_included_range_index += 1;
                }
                if self.current_included_range_index < self.included_ranges.len() {
                    let r2 = self.included_ranges[self.current_included_range_index];
                    self.current_position = Length { bytes: r2.start_byte, extent: r2.start_point };
                } else {
                    has_range = false;
                    break;
                }
            } else {
                break;
            }
        }

        if skip {
            self.token_start_position = self.current_position;
        }

        if has_range {
            if (self.current_position.bytes as usize) >= self.input.len() {
                self.get_chunk();
            }
            if self.chunk_valid || !self.is_eof() {
                self.get_lookahead();
            }
            if self.is_eof() {
                self.data.lookahead = 0;
                self.lookahead_size = 1;
            }
        } else {
            self.chunk_valid = false;
            self.data.lookahead = 0;
            self.lookahead_size = 1;
        }
    }

    pub fn mark_end(&mut self) {
        if !self.is_eof() {
            let idx = self.current_included_range_index;
            if idx > 0 && self.current_position.bytes == self.included_ranges[idx].start_byte {
                let prev = self.included_ranges[idx - 1];
                self.token_end_position = Length { bytes: prev.end_byte, extent: prev.end_point };
                return;
            }
        }
        self.token_end_position = self.current_position;
    }

    pub fn get_column(&mut self) -> u32 {
        let goal_byte = self.current_position.bytes;
        self.did_get_column = true;
        if !self.column_valid {
            // Back up to the beginning of the line
            let start_of_col = Length {
                bytes: self.current_position.bytes - self.current_position.extent.column,
                extent: Point { row: self.current_position.extent.row, column: 0 },
            };
            let saved_lookahead = self.data.lookahead;
            let saved_size = self.lookahead_size;
            let saved_pos = self.current_position;
            let saved_idx = self.current_included_range_index;
            let saved_chunk = self.chunk_valid;
            self.goto_position(start_of_col);
            self.get_chunk();
            let mut result = 0;
            if !self.is_eof() {
                self.get_lookahead();
                while self.current_position.bytes < goal_byte && self.chunk_valid {
                    result += 1;
                    self.do_advance(false);
                    if self.is_eof() {
                        break;
                    }
                }
            }
            self.current_position = saved_pos;
            self.current_included_range_index = saved_idx;
            self.chunk_valid = saved_chunk;
            self.data.lookahead = saved_lookahead;
            self.lookahead_size = saved_size;
            self.column_value = result;
            self.column_valid = true;
        }
        self.column_value
    }

    pub fn goto_position(&mut self, position: Length) {
        self.current_position = position;
        let mut found = false;
        for i in 0..self.included_ranges.len() {
            let r = self.included_ranges[i];
            if r.end_byte > self.current_position.bytes && r.end_byte > r.start_byte {
                if r.start_byte >= self.current_position.bytes {
                    self.current_position = Length { bytes: r.start_byte, extent: r.start_point };
                }
                self.current_included_range_index = i;
                found = true;
                break;
            }
        }
        if found {
            self.chunk_valid = (self.current_position.bytes as usize) < self.input.len();
            self.lookahead_size = 0;
            self.data.lookahead = 0;
        } else {
            self.current_included_range_index = self.included_ranges.len();
            let last = *self.included_ranges.last().unwrap();
            self.current_position = Length { bytes: last.end_byte, extent: last.end_point };
            self.chunk_valid = false;
            self.lookahead_size = 1;
            self.data.lookahead = 0;
        }
    }

    pub fn reset(&mut self, position: Length) {
        if position.bytes != self.current_position.bytes {
            self.goto_position(position);
        }
    }

    pub fn start(&mut self) {
        self.token_start_position = self.current_position;
        self.token_end_position = LENGTH_UNDEFINED;
        self.data.result_symbol = 0;
        self.did_get_column = false;
        if !self.is_eof() {
            if !self.chunk_valid {
                self.get_chunk();
            }
            if self.lookahead_size == 0 && !self.is_eof() {
                self.get_lookahead();
            }
            if self.current_position.bytes == 0 && self.data.lookahead == 0xFEFF {
                lexer_advance(&mut self.data as *mut TSLexer, true);
            }
            if self.is_eof() {
                self.data.lookahead = 0;
                self.lookahead_size = 1;
            }
        }
        self.column_valid = false;
    }

    pub fn finish(&mut self, lookahead_end_byte: &mut u32) {
        if length_is_undefined(&self.token_end_position) {
            self.mark_end();
        }
        let mut current_lookahead_end_byte = self.current_position.bytes + 1;
        if self.data.lookahead == TS_DECODE_ERROR {
            current_lookahead_end_byte += 4;
        }
        if current_lookahead_end_byte > *lookahead_end_byte {
            *lookahead_end_byte = current_lookahead_end_byte;
        }
    }
}
