#![allow(dead_code)]
use super::language::{Language, ParseAction, TSStateId, TSSymbol, TS_BUILTIN_SYM_END, TS_BUILTIN_SYM_ERROR, TS_BUILTIN_SYM_ERROR_REPEAT};
use super::lexer::{Encoding, Lexer};
use super::stack::{Stack, StackVersion, STACK_VERSION_NONE};
use super::subtree::*;
use std::ffi::c_void;
use std::rc::Rc;

const MAX_VERSION_COUNT: usize = 6;
const MAX_VERSION_COUNT_OVERFLOW: usize = 4;
const MAX_SUMMARY_DEPTH: u32 = 16;
const MAX_COST_DIFFERENCE: u32 = 18 * ERROR_COST_PER_SKIPPED_TREE;

#[derive(Clone, Copy, PartialEq, Eq)]
enum ErrorComparison {
    TakeLeft,
    PreferLeft,
    None,
    PreferRight,
    TakeRight,
}

#[derive(Clone, Copy)]
struct ErrorStatus {
    cost: u32,
    node_count: u32,
    dynamic_precedence: i32,
    is_in_error: bool,
}

struct TokenCache {
    token: Option<Subtree>,
    last_external_token: Option<Subtree>,
    byte_index: u32,
}

#[derive(Clone, Copy, PartialEq, Eq)]
struct ReduceAction {
    symbol: TSSymbol,
    count: u32,
    dynamic_precedence: i32,
    production_id: u16,
}

pub struct Parser {
    pub language: Language,
    lexer: Box<Lexer>,
    stack: Stack,
    finished_tree: Option<Subtree>,
    token_cache: TokenCache,
    accept_count: usize,
    has_error: bool,
    external_scanner_payload: *mut c_void,
    serialization_buffer: Vec<u8>,
    has_scanner_error: bool,
    pub logger: Option<Box<dyn FnMut(&str)>>,
    pub timeout_micros: u64,
    start_time: std::time::Instant,
    operation_count: u32,
    pub cancelled: bool,
}

impl Drop for Parser {
    fn drop(&mut self) {
        if !self.external_scanner_payload.is_null() {
            if let Some(destroy) = self.language.external_scanner().destroy {
                unsafe { destroy(self.external_scanner_payload) };
            }
        }
    }
}

macro_rules! log {
    ($self:expr, $($arg:tt)*) => {
        if let Some(l) = &mut $self.logger {
            let s = format!($($arg)*);
            l(&s);
        }
    };
}

impl Parser {
    pub fn new(language: Language, input: Vec<u8>, encoding: Encoding) -> Parser {
        let mut payload = std::ptr::null_mut();
        if let Some(create) = language.external_scanner().create {
            payload = unsafe { create() };
        }
        Parser {
            language,
            lexer: Lexer::new(input, encoding),
            stack: Stack::new(),
            finished_tree: None,
            token_cache: TokenCache { token: None, last_external_token: None, byte_index: 0 },
            accept_count: 0,
            has_error: false,
            external_scanner_payload: payload,
            serialization_buffer: vec![0u8; 1024],
            has_scanner_error: false,
            logger: None,
            timeout_micros: 0,
            start_time: std::time::Instant::now(),
            operation_count: 0,
            cancelled: false,
        }
    }

    fn sym_name(&self, symbol: TSSymbol) -> String {
        self.language.symbol_name(symbol).to_string()
    }

    // ---------------- external scanner ----------------
    fn external_scanner_serialize(&mut self) -> usize {
        if let Some(ser) = self.language.external_scanner().serialize {
            let len = unsafe { ser(self.external_scanner_payload, self.serialization_buffer.as_mut_ptr() as *mut i8) };
            len as usize
        } else {
            0
        }
    }

    fn external_scanner_deserialize(&mut self, external_token: &Option<Subtree>) {
        if let Some(de) = self.language.external_scanner().deserialize {
            match external_token {
                Some(t) => unsafe { de(self.external_scanner_payload, t.external_scanner_state.as_ptr() as *const i8, t.external_scanner_state.len() as u32) },
                None => unsafe { de(self.external_scanner_payload, std::ptr::null(), 0) },
            }
        }
    }

    fn external_scanner_scan(&mut self, external_lex_state: u16) -> bool {
        let valid = self.language.enabled_external_tokens(external_lex_state);
        if let Some(scan) = self.language.external_scanner().scan {
            unsafe { scan(self.external_scanner_payload, &mut self.lexer.data as *mut _, valid) }
        } else {
            false
        }
    }

    // ---------------- lexing ----------------
    fn lex(&mut self, version: StackVersion, parse_state: TSStateId) -> Option<Subtree> {
        let mut lex_mode = self.language.lex_mode(parse_state);
        if lex_mode.lex_state == u16::MAX {
            return None;
        }

        let start_position = self.stack.position(version);
        let external_token = self.stack.last_external_token(version);

        let mut found_external_token = false;
        let mut error_mode = parse_state == ERROR_STATE;
        let mut skipped_error = false;
        let mut called_get_column = false;
        let mut first_error_character: i32 = 0;
        let mut error_start_position = Length::zero();
        let mut error_end_position = Length::zero();
        let mut lookahead_end_byte: u32 = 0;
        let mut external_scanner_state_len = 0usize;
        let mut external_scanner_state_changed = false;
        self.lexer.reset(start_position);

        loop {
            let mut found_token;
            let current_position = self.lexer.current_position;

            if lex_mode.external_lex_state != 0 {
                log!(self, "lex_external state:{}, row:{}, column:{}", lex_mode.external_lex_state, current_position.extent.row, current_position.extent.column);
                self.lexer.start();
                self.external_scanner_deserialize(&external_token);
                found_token = self.external_scanner_scan(lex_mode.external_lex_state);
                self.lexer.finish(&mut lookahead_end_byte);

                if found_token {
                    external_scanner_state_len = self.external_scanner_serialize();
                    let prev: &[u8] = match &external_token {
                        Some(t) => &t.external_scanner_state,
                        None => &[],
                    };
                    external_scanner_state_changed = prev != &self.serialization_buffer[..external_scanner_state_len];

                    // Avoid infinite loops caused by the external scanner returning empty tokens.
                    if self.lexer.token_end_position.bytes <= current_position.bytes && !external_scanner_state_changed {
                        let symbol = self.language.external_symbol(self.lexer.data.result_symbol);
                        let next_parse_state = self.language.next_state(parse_state, symbol);
                        let token_is_extra = next_parse_state == parse_state;
                        if error_mode || !self.stack.has_advanced_since_error(version) || token_is_extra {
                            log!(self, "ignore_empty_external_token symbol:{}", self.sym_name(symbol));
                            found_token = false;
                        }
                    }
                }

                if found_token {
                    found_external_token = true;
                    called_get_column = self.lexer.did_get_column;
                    break;
                }

                self.lexer.reset(current_position);
            }

            log!(self, "lex_internal state:{}, row:{}, column:{}", lex_mode.lex_state, current_position.extent.row, current_position.extent.column);
            self.lexer.start();
            found_token = match self.language.lex_fn() {
                Some(f) => unsafe { f(&mut self.lexer.data as *mut _, lex_mode.lex_state) },
                None => false,
            };
            self.lexer.finish(&mut lookahead_end_byte);
            if found_token {
                break;
            }

            if !error_mode {
                error_mode = true;
                lex_mode = self.language.lex_mode(ERROR_STATE);
                self.lexer.reset(start_position);
                continue;
            }

            if !skipped_error {
                log!(self, "skip_unrecognized_character");
                skipped_error = true;
                error_start_position = self.lexer.token_start_position;
                error_end_position = self.lexer.token_start_position;
                first_error_character = self.lexer.data.lookahead;
            }

            if self.lexer.current_position.bytes == error_end_position.bytes {
                if self.lexer.is_eof() {
                    self.lexer.data.result_symbol = TS_BUILTIN_SYM_ERROR;
                    break;
                }
                let adv = self.lexer.data.advance;
                adv(&mut self.lexer.data as *mut _, false);
            }

            error_end_position = self.lexer.current_position;
        }

        let result;
        if skipped_error {
            let padding = error_start_position.sub(start_position);
            let size = error_end_position.sub(error_start_position);
            let lookahead_bytes = lookahead_end_byte - error_end_position.bytes;
            result = new_error(&self.language, first_error_character, padding, size, lookahead_bytes, parse_state);
        } else {
            let mut is_keyword = false;
            let mut symbol = self.lexer.data.result_symbol;
            let padding = self.lexer.token_start_position.sub(start_position);
            let size = self.lexer.token_end_position.sub(self.lexer.token_start_position);
            let lookahead_bytes = lookahead_end_byte - self.lexer.token_end_position.bytes;

            if found_external_token {
                symbol = self.language.external_symbol(symbol);
            } else if symbol == self.language.keyword_capture_token() && symbol != 0 {
                let end_byte = self.lexer.token_end_position.bytes;
                let tsp = self.lexer.token_start_position;
                self.lexer.reset(tsp);
                self.lexer.start();
                is_keyword = match self.language.keyword_lex_fn() {
                    Some(f) => unsafe { f(&mut self.lexer.data as *mut _, 0) },
                    None => false,
                };
                if is_keyword
                    && self.lexer.token_end_position.bytes == end_byte
                    && (self.language.has_actions(parse_state, self.lexer.data.result_symbol)
                        || self.language.is_reserved_word(parse_state, self.lexer.data.result_symbol))
                {
                    symbol = self.lexer.data.result_symbol;
                }
            }

            let mut data = new_leaf(&self.language, symbol, padding, size, lookahead_bytes, parse_state, found_external_token, called_get_column, is_keyword);
            if found_external_token {
                data.external_scanner_state = self.serialization_buffer[..external_scanner_state_len].to_vec();
                data.has_external_scanner_state_change = external_scanner_state_changed;
            }
            result = Rc::new(data);
        }

        log!(self, "lexed_lookahead sym:{}, size:{}", self.tree_name(&result), result.total_bytes());
        Some(result)
    }

    fn tree_name(&self, t: &Subtree) -> String {
        self.language.symbol_name(t.symbol).to_string()
    }

    fn get_cached_token(&mut self, state: TSStateId, position: u32, last_external_token: &Option<Subtree>) -> Option<Subtree> {
        if let Some(token) = &self.token_cache.token {
            if self.token_cache.byte_index == position && external_scanner_state_eq(&self.token_cache.last_external_token, last_external_token) {
                let token = token.clone();
                let entry = self.language.table_entry(state, token.symbol);
                if self.can_reuse_first_leaf(state, &token, entry.actions.len(), entry.is_reusable) {
                    return Some(token);
                }
            }
        }
        None
    }

    fn set_cached_token(&mut self, byte_index: u32, last_external_token: Option<Subtree>, token: Subtree) {
        self.token_cache.token = Some(token);
        self.token_cache.byte_index = byte_index;
        self.token_cache.last_external_token = last_external_token;
    }

    fn can_reuse_first_leaf(&self, state: TSStateId, tree: &Subtree, action_count: usize, is_reusable: bool) -> bool {
        let current_lex_mode = self.language.lex_mode(state);
        let leaf_symbol = tree.leaf_symbol();
        let leaf_state = tree.leaf_parse_state();
        let leaf_lex_mode = self.language.lex_mode(leaf_state);

        if current_lex_mode.lex_state == u16::MAX {
            return false;
        }

        if action_count > 0
            && leaf_lex_mode.lex_state == current_lex_mode.lex_state
            && leaf_lex_mode.external_lex_state == current_lex_mode.external_lex_state
            && leaf_lex_mode.reserved_word_set_id == current_lex_mode.reserved_word_set_id
            && (leaf_symbol != self.language.keyword_capture_token() || (!tree.is_keyword && tree.parse_state == state))
        {
            return true;
        }

        if tree.size.bytes == 0 && leaf_symbol != TS_BUILTIN_SYM_END {
            return false;
        }

        current_lex_mode.external_lex_state == 0 && is_reusable
    }

    // ---------------- stack operations ----------------
    fn shift(&mut self, version: StackVersion, state: TSStateId, lookahead: Subtree, extra: bool) {
        let is_leaf = lookahead.children.is_empty();
        let mut subtree_to_push = lookahead;
        if extra != subtree_to_push.extra && is_leaf {
            let mut d = (*subtree_to_push).clone();
            d.extra = extra;
            subtree_to_push = Rc::new(d);
        }
        let has_ext = subtree_to_push.has_external_tokens;
        self.stack.push(version, Some(subtree_to_push.clone()), !is_leaf, state);
        if has_ext {
            self.stack.set_last_external_token(version, last_external_token(&subtree_to_push));
        }
    }

    fn select_tree(&mut self, left: &Option<Subtree>, right: &Option<Subtree>) -> bool {
        let left = match left {
            None => return true,
            Some(l) => l,
        };
        let right = match right {
            None => return false,
            Some(r) => r,
        };
        if right.error_cost() < left.error_cost() {
            log!(self, "select_smaller_error symbol:{}, over_symbol:{}", self.tree_name(right), self.tree_name(left));
            return true;
        }
        if left.error_cost() < right.error_cost() {
            log!(self, "select_smaller_error symbol:{}, over_symbol:{}", self.tree_name(left), self.tree_name(right));
            return false;
        }
        if right.dynamic_precedence() > left.dynamic_precedence() {
            log!(self, "select_higher_precedence symbol:{}, prec:{}, over_symbol:{}, other_prec:{}", self.tree_name(right), right.dynamic_precedence(), self.tree_name(left), left.dynamic_precedence());
            return true;
        }
        if left.dynamic_precedence() > right.dynamic_precedence() {
            log!(self, "select_higher_precedence symbol:{}, prec:{}, over_symbol:{}, other_prec:{}", self.tree_name(left), left.dynamic_precedence(), self.tree_name(right), right.dynamic_precedence());
            return false;
        }
        if left.error_cost() > 0 {
            return true;
        }
        let comparison = compare(left, right);
        match comparison {
            -1 => {
                log!(self, "select_earlier symbol:{}, over_symbol:{}", self.tree_name(left), self.tree_name(right));
                false
            }
            1 => {
                log!(self, "select_earlier symbol:{}, over_symbol:{}", self.tree_name(right), self.tree_name(left));
                true
            }
            _ => {
                log!(self, "select_existing symbol:{}, over_symbol:{}", self.tree_name(left), self.tree_name(right));
                false
            }
        }
    }

    fn select_children(&mut self, left: &Subtree, children: &[Subtree]) -> bool {
        let scratch = Rc::new(new_node(left.symbol, children.to_vec(), 0, &self.language));
        self.select_tree(&Some(left.clone()), &Some(scratch))
    }

    fn reduce(&mut self, version: StackVersion, symbol: TSSymbol, count: u32, dynamic_precedence: i32, production_id: u16, is_fragile: bool, end_of_non_terminal_extra: bool) -> StackVersion {
        let initial_version_count = self.stack.version_count();

        let pop = self.stack.pop_count(version, count);
        let mut removed_version_count = 0usize;
        let halted_version_count = self.stack.halted_version_count();
        let pop_len = pop.len();
        let mut pop_iter: Vec<Option<super::stack::StackSlice>> = pop.into_iter().map(Some).collect();
        let mut i = 0;
        while i < pop_len {
            let slice = pop_iter[i].take().unwrap();
            let slice_version = slice.version - removed_version_count;

            if slice_version > MAX_VERSION_COUNT + MAX_VERSION_COUNT_OVERFLOW + halted_version_count {
                self.stack.remove_version(slice_version);
                removed_version_count += 1;
                while i + 1 < pop_len {
                    log!(self, "aborting reduce with too many versions");
                    let next_version = pop_iter[i + 1].as_ref().unwrap().version;
                    if next_version != slice.version {
                        break;
                    }
                    i += 1;
                }
                i += 1;
                continue;
            }

            let mut children = slice.subtrees;
            let mut trailing_extras = remove_trailing_extras(&mut children);

            let mut parent = new_node(symbol, children, production_id, &self.language);

            while i + 1 < pop_len {
                let next_version = pop_iter[i + 1].as_ref().unwrap().version;
                if next_version != slice.version {
                    break;
                }
                i += 1;
                let next_slice = pop_iter[i].take().unwrap();
                let mut next_slice_children = next_slice.subtrees;
                let trailing_extras2 = remove_trailing_extras(&mut next_slice_children);

                let parent_rc = Rc::new(parent.clone());
                if self.select_children(&parent_rc, &next_slice_children) {
                    trailing_extras = trailing_extras2;
                    parent = new_node(symbol, next_slice_children, production_id, &self.language);
                }
            }

            let state = self.stack.state(slice_version);
            let next_state = self.language.next_state(state, symbol);
            if end_of_non_terminal_extra && next_state == state {
                parent.extra = true;
            }
            if is_fragile || pop_len > 1 || initial_version_count > 1 {
                parent.fragile_left = true;
                parent.fragile_right = true;
                parent.parse_state = TS_TREE_STATE_NONE;
            } else {
                parent.parse_state = state;
            }
            parent.dynamic_precedence += dynamic_precedence;

            self.stack.push(slice_version, Some(Rc::new(parent)), false, next_state);
            for extra in trailing_extras {
                self.stack.push(slice_version, Some(extra), false, next_state);
            }

            for j in 0..slice_version {
                if j == version {
                    continue;
                }
                if self.stack.merge(j, slice_version) {
                    removed_version_count += 1;
                    break;
                }
            }
            i += 1;
        }

        if self.stack.version_count() > initial_version_count {
            initial_version_count
        } else {
            STACK_VERSION_NONE
        }
    }

    fn accept(&mut self, version: StackVersion, lookahead: Subtree) {
        self.stack.push(version, Some(lookahead), false, 1);

        let pop = self.stack.pop_all(version);
        let first_version = pop.first().map(|s| s.version);
        for slice in pop {
            let mut trees = slice.subtrees;
            let mut root: Option<Subtree> = None;
            let mut j = trees.len();
            while j > 0 {
                j -= 1;
                let tree = trees[j].clone();
                if !tree.extra {
                    let children = tree.children.clone();
                    trees.splice(j..j + 1, children);
                    root = Some(Rc::new(new_node(tree.symbol, trees.clone(), tree.production_id, &self.language)));
                    break;
                }
            }

            let root = match root {
                Some(r) => r,
                None => continue,
            };
            self.accept_count += 1;

            if self.finished_tree.is_some() {
                let ft = self.finished_tree.clone();
                if self.select_tree(&ft, &Some(root.clone())) {
                    self.finished_tree = Some(root);
                }
            } else {
                self.finished_tree = Some(root);
            }
        }

        if let Some(v) = first_version {
            self.stack.remove_version(v);
        }
        self.stack.halt(version);
    }

    fn do_all_potential_reductions(&mut self, starting_version: StackVersion, lookahead_symbol: TSSymbol) -> bool {
        let initial_version_count = self.stack.version_count();

        let mut can_shift_lookahead_symbol = false;
        let mut version = starting_version;
        let mut i: usize = 0;
        loop {
            let version_count = self.stack.version_count();
            if version >= version_count {
                break;
            }

            let mut merged = false;
            for j in initial_version_count..version {
                if self.stack.merge(j, version) {
                    merged = true;
                    break;
                }
            }
            if merged {
                i += 1;
                continue;
            }

            let state = self.stack.state(version);
            let mut has_shift_action = false;
            let mut reduce_actions: Vec<ReduceAction> = Vec::new();

            let (first_symbol, end_symbol) = if lookahead_symbol != 0 {
                (lookahead_symbol, lookahead_symbol + 1)
            } else {
                (1, self.language.token_count() as TSSymbol)
            };

            for symbol in first_symbol..end_symbol {
                let entry = self.language.table_entry(state, symbol);
                for action in entry.actions {
                    match action {
                        ParseAction::Shift { extra, repetition, .. } => {
                            if !extra && !repetition {
                                has_shift_action = true;
                            }
                        }
                        ParseAction::Recover => {
                            has_shift_action = true;
                        }
                        ParseAction::Reduce { symbol, child_count, dynamic_precedence, production_id } => {
                            if child_count > 0 {
                                let ra = ReduceAction { symbol, count: child_count as u32, dynamic_precedence: dynamic_precedence as i32, production_id };
                                if !reduce_actions.iter().any(|a| a.symbol == ra.symbol && a.count == ra.count) {
                                    reduce_actions.push(ra);
                                }
                            }
                        }
                        _ => {}
                    }
                }
            }

            let mut reduction_version = STACK_VERSION_NONE;
            for action in &reduce_actions {
                reduction_version = self.reduce(version, action.symbol, action.count, action.dynamic_precedence, action.production_id, true, false);
            }

            if has_shift_action {
                can_shift_lookahead_symbol = true;
            } else if reduction_version != STACK_VERSION_NONE && i < MAX_VERSION_COUNT {
                self.stack.renumber_version(reduction_version, version);
                i += 1;
                continue;
            } else if lookahead_symbol != 0 {
                self.stack.remove_version(version);
            }

            if version == starting_version {
                version = version_count;
            } else {
                version += 1;
            }
            i += 1;
        }

        can_shift_lookahead_symbol
    }

    fn version_status(&mut self, version: StackVersion) -> ErrorStatus {
        let mut cost = self.stack.error_cost(version);
        let is_paused = self.stack.is_paused(version);
        if is_paused {
            cost += ERROR_COST_PER_SKIPPED_TREE;
        }
        ErrorStatus {
            cost,
            node_count: self.stack.node_count_since_error(version),
            dynamic_precedence: self.stack.dynamic_precedence(version),
            is_in_error: is_paused || self.stack.state(version) == ERROR_STATE,
        }
    }

    fn compare_versions(a: ErrorStatus, b: ErrorStatus) -> ErrorComparison {
        if !a.is_in_error && b.is_in_error {
            if a.cost < b.cost {
                return ErrorComparison::TakeLeft;
            } else {
                return ErrorComparison::PreferLeft;
            }
        }

        if a.is_in_error && !b.is_in_error {
            if b.cost < a.cost {
                return ErrorComparison::TakeRight;
            } else {
                return ErrorComparison::PreferRight;
            }
        }

        if a.cost < b.cost {
            if (b.cost - a.cost) * (1 + a.node_count) > MAX_COST_DIFFERENCE {
                return ErrorComparison::TakeLeft;
            } else {
                return ErrorComparison::PreferLeft;
            }
        }

        if b.cost < a.cost {
            if (a.cost - b.cost) * (1 + b.node_count) > MAX_COST_DIFFERENCE {
                return ErrorComparison::TakeRight;
            } else {
                return ErrorComparison::PreferRight;
            }
        }

        if a.dynamic_precedence > b.dynamic_precedence {
            return ErrorComparison::PreferLeft;
        }
        if b.dynamic_precedence > a.dynamic_precedence {
            return ErrorComparison::PreferRight;
        }
        ErrorComparison::None
    }

    fn better_version_exists(&mut self, version: StackVersion, is_in_error: bool, cost: u32) -> bool {
        if let Some(ft) = &self.finished_tree {
            if ft.error_cost() <= cost {
                return true;
            }
        }

        let position = self.stack.position(version);
        let status = ErrorStatus {
            cost,
            is_in_error,
            dynamic_precedence: self.stack.dynamic_precedence(version),
            node_count: self.stack.node_count_since_error(version),
        };

        let n = self.stack.version_count();
        for i in 0..n {
            if i == version || !self.stack.is_active(i) || self.stack.position(i).bytes < position.bytes {
                continue;
            }
            let status_i = self.version_status(i);
            match Self::compare_versions(status, status_i) {
                ErrorComparison::TakeRight => return true,
                ErrorComparison::PreferRight => {
                    if self.stack.can_merge(i, version) {
                        return true;
                    }
                }
                _ => {}
            }
        }

        false
    }

    fn condense_stack(&mut self) -> u32 {
        let mut made_changes = false;
        let mut min_error_cost = u32::MAX;
        let mut i = 0usize;
        while i < self.stack.version_count() {
            // Prune any versions that have been marked for removal.
            if self.stack.is_halted(i) {
                self.stack.remove_version(i);
                continue;
            }

            // Keep track of the minimum error cost of any stack version so
            // that it can be returned.
            let status_i = self.version_status(i);
            if !status_i.is_in_error && status_i.cost < min_error_cost {
                min_error_cost = status_i.cost;
            }

            // Examine each pair of stack versions, removing any versions that
            // are clearly worse than another version. Ensure that the versions
            // are ordered from most promising to least promising.
            let mut j: isize = 0;
            let mut removed_i = false;
            while (j as usize) < i {
                let ju = j as usize;
                let status_j = self.version_status(ju);
                let status_i = self.version_status(i);
                match Self::compare_versions(status_j, status_i) {
                    ErrorComparison::TakeLeft => {
                        made_changes = true;
                        self.stack.remove_version(i);
                        removed_i = true;
                        break;
                    }
                    ErrorComparison::PreferLeft | ErrorComparison::None => {
                        if self.stack.merge(ju, i) {
                            made_changes = true;
                            removed_i = true;
                            break;
                        }
                    }
                    ErrorComparison::PreferRight => {
                        made_changes = true;
                        if self.stack.merge(ju, i) {
                            removed_i = true;
                            break;
                        } else {
                            self.stack.swap_versions(i, ju);
                        }
                    }
                    ErrorComparison::TakeRight => {
                        made_changes = true;
                        self.stack.remove_version(ju);
                        i -= 1;
                        j -= 1;
                    }
                }
                j += 1;
            }
            if removed_i {
                // i now refers to the next version
                continue;
            }
            i += 1;
        }

        // Enforce a hard upper bound on the number of stack versions.
        while self.stack.version_count() > MAX_VERSION_COUNT {
            self.stack.remove_version(MAX_VERSION_COUNT);
            made_changes = true;
        }

        // If the best-performing stack version is currently paused, or all
        // versions are paused, then resume the best paused version and begin
        // the error recovery process. Otherwise, remove the paused versions.
        if self.stack.version_count() > 0 {
            let mut has_unpaused_version = false;
            let mut i = 0;
            let mut n = self.stack.version_count();
            while i < n {
                if self.stack.is_paused(i) {
                    if !has_unpaused_version && self.accept_count < MAX_VERSION_COUNT {
                        log!(self, "resume version:{}", i);
                        min_error_cost = self.stack.error_cost(i);
                        let lookahead = self.stack.resume(i).unwrap();
                        self.handle_error(i, lookahead);
                        has_unpaused_version = true;
                    } else {
                        self.stack.remove_version(i);
                        made_changes = true;
                        n -= 1;
                        continue;
                    }
                } else {
                    has_unpaused_version = true;
                }
                i += 1;
            }
        }

        if made_changes {
            log!(self, "condense");
        }

        min_error_cost
    }

    fn recover_to_state(&mut self, version: StackVersion, depth: u32, goal_state: TSStateId) -> bool {
        let pop = self.stack.pop_count(version, depth);
        let mut previous_version = STACK_VERSION_NONE;

        for slice in pop {
            if slice.version == previous_version {
                continue;
            }

            if self.stack.state(slice.version) != goal_state {
                self.stack.halt(slice.version);
                continue;
            }

            let mut subtrees = slice.subtrees;
            let error_trees = self.stack.pop_error(slice.version);
            if let Some(error_tree) = error_trees.into_iter().next() {
                let error_children = error_tree.children.clone();
                if !error_children.is_empty() {
                    subtrees.splice(0..0, error_children);
                }
            }

            let trailing_extras = remove_trailing_extras(&mut subtrees);

            if !subtrees.is_empty() {
                let error = new_error_node(subtrees, true, &self.language);
                self.stack.push(slice.version, Some(error), false, goal_state);
            }

            for tree in trailing_extras {
                self.stack.push(slice.version, Some(tree), false, goal_state);
            }

            previous_version = slice.version;
        }

        previous_version != STACK_VERSION_NONE
    }

    fn recover(&mut self, version: StackVersion, lookahead: Subtree) {
        let mut did_recover = false;
        let previous_version_count = self.stack.version_count();
        let position = self.stack.position(version);
        let summary = self.stack.get_summary(version);
        let node_count_since_error = self.stack.node_count_since_error(version);
        let current_error_cost = self.stack.error_cost(version);

        // When the parser is in the error state, there are two strategies for recovering with a
        // given lookahead token:
        // 1. Find a previous state on the stack in which that lookahead token would be valid. Then,
        //    create a new stack version that is in that state again. This entails popping all of the
        //    subtrees that have been pushed onto the stack since that previous state, and wrapping
        //    them in an ERROR node.
        // 2. Wrap the lookahead token in an ERROR node, push that ERROR node onto the stack, and
        //    move on to the next lookahead token, remaining in the error state.
        //
        // First, try the strategy 1. Upon entering the error state, the parser recorded a summary
        // of the previous parse states and their depths. Look at each state in the summary, to see
        // if the current lookahead token would be valid in that state.
        if let Some(summary) = &summary {
            if !lookahead.is_error() {
                for entry in summary.iter() {
                    if entry.state == ERROR_STATE {
                        continue;
                    }
                    if entry.position.bytes == position.bytes {
                        continue;
                    }
                    let mut depth = entry.depth;
                    if node_count_since_error > 0 {
                        depth += 1;
                    }

                    // Do not recover in ways that create redundant stack versions.
                    let mut would_merge = false;
                    for j in 0..previous_version_count {
                        if self.stack.state(j) == entry.state && self.stack.position(j).bytes == position.bytes {
                            would_merge = true;
                            break;
                        }
                    }
                    if would_merge {
                        continue;
                    }

                    // Do not recover if the cost of doing so would be too high.
                    let new_cost = current_error_cost
                        + entry.depth * ERROR_COST_PER_SKIPPED_TREE
                        + (position.bytes - entry.position.bytes) * ERROR_COST_PER_SKIPPED_CHAR
                        + (position.extent.row - entry.position.extent.row) * ERROR_COST_PER_SKIPPED_LINE;
                    if self.better_version_exists(version, false, new_cost) {
                        break;
                    }

                    // If the current lookahead token is valid in some previous state, recover to that
                    // state. Then stop looking for further recoveries.
                    if self.language.has_actions(entry.state, lookahead.symbol) {
                        if self.recover_to_state(version, depth, entry.state) {
                            did_recover = true;
                            log!(self, "recover_to_previous state:{}, depth:{}", entry.state, depth);
                            break;
                        }
                    }
                }
            }
        }

        // In the process of attempting to recover, some stack versions may have been created
        // and subsequently halted. Remove these versions.
        let mut i = previous_version_count;
        while i < self.stack.version_count() {
            if !self.stack.is_active(i) {
                log!(self, "removed paused version:{}", i);
                self.stack.remove_version(i);
            } else {
                i += 1;
            }
        }

        // If the parser is still in the error state at the end of the file, just wrap everything
        // in an ERROR node and terminate.
        if lookahead.is_eof() {
            log!(self, "recover_eof");
            let parent = new_error_node(Vec::new(), false, &self.language);
            self.stack.push(version, Some(parent), false, 1);
            self.accept(version, lookahead);
            return;
        }

        // If strategy 1 succeeded, a new stack version will have been created which is able to
        // handle the current lookahead token. Now, in addition, try strategy 2 described above:
        // skip the current lookahead token by wrapping it in an ERROR node.

        // Don't pursue this additional strategy if there are already too many stack versions.
        if did_recover && self.stack.version_count() > MAX_VERSION_COUNT {
            self.stack.halt(version);
            return;
        }

        if did_recover && lookahead.has_external_scanner_state_change {
            self.stack.halt(version);
            return;
        }

        // Do not recover if the cost of doing so would be too high.
        let new_cost = current_error_cost
            + ERROR_COST_PER_SKIPPED_TREE
            + lookahead.total_bytes() * ERROR_COST_PER_SKIPPED_CHAR
            + lookahead.total_size().extent.row * ERROR_COST_PER_SKIPPED_LINE;
        if self.better_version_exists(version, false, new_cost) {
            self.stack.halt(version);
            return;
        }

        // If the current lookahead token is an extra token, mark it as extra. This means it won't
        // be counted in error cost calculations.
        let mut lookahead = lookahead;
        let actions = self.language.actions(1, lookahead.symbol);
        if let Some(ParseAction::Shift { extra: true, .. }) = actions.last() {
            let mut d = (*lookahead).clone();
            d.extra = true;
            lookahead = Rc::new(d);
        }

        // Wrap the lookahead token in an ERROR.
        log!(self, "skip_token symbol:{}", self.tree_name(&lookahead));
        let mut error_repeat = new_node(TS_BUILTIN_SYM_ERROR_REPEAT, vec![lookahead.clone()], 0, &self.language);

        // If other tokens have already been skipped, so there is already an ERROR at the top of the
        // stack, then pop that ERROR off the stack and wrap the two ERRORs together into one larger
        // ERROR.
        if node_count_since_error > 0 {
            let mut pop = self.stack.pop_count(version, 1);

            // If multiple stack versions have merged at this point, just pick one of the errors
            // arbitrarily and discard the rest.
            if pop.len() > 1 {
                let v0 = pop[0].version;
                while self.stack.version_count() > v0 + 1 {
                    self.stack.remove_version(v0 + 1);
                }
                pop.truncate(1);
            }

            let first = pop.into_iter().next().unwrap();
            self.stack.renumber_version(first.version, version);
            let mut subtrees = first.subtrees;
            subtrees.push(Rc::new(error_repeat));
            error_repeat = new_node(TS_BUILTIN_SYM_ERROR_REPEAT, subtrees, 0, &self.language);
        }

        // Push the new ERROR onto the stack.
        self.stack.push(version, Some(Rc::new(error_repeat)), false, ERROR_STATE);
        if lookahead.has_external_tokens {
            self.stack.set_last_external_token(version, last_external_token(&lookahead));
        }

        let mut has_error = true;
        for i in 0..self.stack.version_count() {
            let status = self.version_status(i);
            if !status.is_in_error {
                has_error = false;
                break;
            }
        }
        self.has_error = has_error;
    }

    fn handle_error(&mut self, version: StackVersion, lookahead: Subtree) {
        let previous_version_count = self.stack.version_count();

        // Perform any reductions that can happen in this state, regardless of the lookahead. After
        // skipping one or more invalid tokens, the parser might find a token that would have allowed
        // a reduction to take place.
        self.do_all_potential_reductions(version, 0);
        let version_count = self.stack.version_count();
        let position = self.stack.position(version);

        // Push a discontinuity onto the stack. Merge all of the stack versions that
        // were created in the previous step.
        let mut did_insert_missing_token = false;
        let mut v = version;
        while v < version_count {
            if !did_insert_missing_token {
                let state = self.stack.state(v);
                let token_count = self.language.token_count() as TSSymbol;
                for missing_symbol in 1..token_count {
                    let state_after_missing_symbol = self.language.next_state(state, missing_symbol);
                    if state_after_missing_symbol == 0 || state_after_missing_symbol == state {
                        continue;
                    }

                    if self.language.has_reduce_action(state_after_missing_symbol, lookahead.leaf_symbol()) {
                        // In case the parser is currently outside of any included range, the lexer will
                        // snap to the beginning of the next included range. The missing token's padding
                        // must be assigned to position it within the next included range.
                        self.lexer.reset(position);
                        self.lexer.mark_end();
                        let padding = self.lexer.token_end_position.sub(position);
                        let lookahead_bytes = lookahead.total_bytes() + lookahead.lookahead_bytes;

                        let version_with_missing_tree = self.stack.copy_version(v);
                        let missing_tree = new_missing_leaf(&self.language, missing_symbol, padding, lookahead_bytes);
                        self.stack.push(version_with_missing_tree, Some(missing_tree), false, state_after_missing_symbol);

                        if self.do_all_potential_reductions(version_with_missing_tree, lookahead.leaf_symbol()) {
                            log!(self, "recover_with_missing symbol:{}, state:{}", self.sym_name(missing_symbol), self.stack.state(version_with_missing_tree));
                            did_insert_missing_token = true;
                            break;
                        }
                    }
                }
            }

            self.stack.push(v, None, false, ERROR_STATE);
            v = if v == version { previous_version_count } else { v + 1 };
        }

        for _ in previous_version_count..version_count {
            let did_merge = self.stack.merge(version, previous_version_count);
            debug_assert!(did_merge);
        }

        self.stack.record_summary(version, MAX_SUMMARY_DEPTH);

        // Begin recovery with the current lookahead node, rather than waiting for the
        // next turn of the parse loop. This ensures that the tree accounts for the
        // current lookahead token's "lookahead bytes" value, which describes how far
        // the lexer needed to look ahead beyond the content of the token in order to
        // recognize it.
        self.recover(version, lookahead);
    }

    fn advance(&mut self, version: StackVersion) -> bool {
        let mut state = self.stack.state(version);
        let position = self.stack.position(version).bytes;
        let last_external_token = self.stack.last_external_token(version);

        let mut lookahead: Option<Subtree> = self.get_cached_token(state, position, &last_external_token);
        let mut table_entry = match &lookahead {
            Some(l) => self.language.table_entry(state, l.symbol),
            None => super::language::TableEntry { actions: vec![], is_reusable: false },
        };

        let mut needs_lex = lookahead.is_none();
        loop {
            // Otherwise, re-run the lexer.
            if needs_lex {
                needs_lex = false;
                lookahead = self.lex(version, state);
                if self.has_scanner_error {
                    return false;
                }

                if let Some(l) = &lookahead {
                    self.set_cached_token(position, last_external_token.clone(), l.clone());
                    table_entry = self.language.table_entry(state, l.symbol);
                }
                // When parsing a non-terminal extra, a null lookahead indicates the
                // end of the rule. The reduction is stored in the EOF table entry.
                // After the reduction, the lexer needs to be run again.
                else {
                    table_entry = self.language.table_entry(state, TS_BUILTIN_SYM_END);
                }
            }

            if self.timeout_micros > 0 {
                self.operation_count += 1;
                if self.operation_count >= 100 {
                    self.operation_count = 0;
                    if self.start_time.elapsed().as_micros() as u64 > self.timeout_micros {
                        self.cancelled = true;
                        return false;
                    }
                }
            }

            // Process each parse action for the current lookahead token in
            // the current state. If there are multiple actions, then this is
            // an ambiguous state. REDUCE actions always create a new stack
            // version, whereas SHIFT actions update the existing stack version
            // and terminate this loop.
            let mut last_reduction_version = STACK_VERSION_NONE;
            let action_count = table_entry.actions.len();
            let actions = table_entry.actions.clone();
            for action in actions {
                match action {
                    ParseAction::Shift { state: shift_state, extra, repetition } => {
                        if repetition {
                            break;
                        }
                        let next_state;
                        if extra {
                            next_state = state;
                            log!(self, "shift_extra");
                        } else {
                            next_state = shift_state;
                            log!(self, "shift state:{}", next_state);
                        }
                        let la = lookahead.clone().unwrap();
                        self.shift(version, next_state, la, extra);
                        return true;
                    }
                    ParseAction::Reduce { symbol, child_count, dynamic_precedence, production_id } => {
                        let is_fragile = action_count > 1;
                        let end_of_non_terminal_extra = lookahead.is_none();
                        log!(self, "reduce sym:{}, child_count:{}", self.sym_name(symbol), child_count);
                        let reduction_version = self.reduce(version, symbol, child_count as u32, dynamic_precedence as i32, production_id, is_fragile, end_of_non_terminal_extra);
                        if reduction_version != STACK_VERSION_NONE {
                            last_reduction_version = reduction_version;
                        }
                    }
                    ParseAction::Accept => {
                        log!(self, "accept");
                        let la = lookahead.clone().unwrap();
                        self.accept(version, la);
                        return true;
                    }
                    ParseAction::Recover => {
                        let la = lookahead.clone().unwrap();
                        self.recover(version, la);
                        return true;
                    }
                }
            }

            // If a reduction was performed, then replace the current stack version
            // with one of the stack versions created by a reduction, and continue
            // processing this version of the stack with the same lookahead symbol.
            if last_reduction_version != STACK_VERSION_NONE {
                self.stack.renumber_version(last_reduction_version, version);
                state = self.stack.state(version);

                // At the end of a non-terminal extra rule, the lexer will return a
                // null subtree, because the parser needs to perform a fixed reduction
                // regardless of the lookahead node. After performing that reduction,
                // (and completing the non-terminal extra rule) run the lexer again based
                // on the current parse state.
                match &lookahead {
                    None => needs_lex = true,
                    Some(l) => table_entry = self.language.table_entry(state, l.leaf_symbol()),
                }
                continue;
            }

            // A non-terminal extra rule was reduced and merged into an existing
            // stack version. This version can be discarded.
            let la = match &lookahead {
                None => {
                    self.stack.halt(version);
                    return true;
                }
                Some(l) => l.clone(),
            };

            // If there were no parse actions for the current lookahead token, then
            // it is not valid in this state. If the current lookahead token is a
            // keyword, then switch to treating it as the normal word token if that
            // token is valid in this state.
            let kct = self.language.keyword_capture_token();
            if la.is_keyword && la.symbol != kct && !self.language.is_reserved_word(state, la.symbol) {
                let entry = self.language.table_entry(state, kct);
                if !entry.actions.is_empty() {
                    log!(self, "switch from_keyword:{}, to_word_token:{}", self.tree_name(&la), self.sym_name(kct));
                    let mut d = (*la).clone();
                    set_symbol(&mut d, kct, &self.language);
                    lookahead = Some(Rc::new(d));
                    table_entry = entry;
                    continue;
                }
            }

            // Otherwise, there is definitely an error in this version of the parse stack.
            // Mark this version as paused and continue processing any other stack
            // versions that exist. If some other version of the stack is able to
            // successfully parse the current lookahead token, then this version can
            // simply be removed. But if all versions end up paused, then error recovery
            // is needed.
            log!(self, "detect_error lookahead:{}", self.tree_name(&la));
            self.stack.pause(version, la);
            return true;
        }
    }

    pub fn parse(&mut self) -> Option<Subtree> {
        self.start_time = std::time::Instant::now();
        let mut last_position: u32 = 0;
        let mut version_count;
        loop {
            let mut version = 0;
            loop {
                version_count = self.stack.version_count();
                if version >= version_count {
                    break;
                }
                while self.stack.is_active(version) {
                    log!(
                        self,
                        "process version:{}, version_count:{}, state:{}, row:{}, col:{}",
                        version,
                        self.stack.version_count(),
                        self.stack.state(version),
                        self.stack.position(version).extent.row,
                        self.stack.position(version).extent.column
                    );

                    if !self.advance(version) {
                        return None;
                    }

                    let position = self.stack.position(version).bytes;
                    if position > last_position || (version > 0 && position == last_position) {
                        last_position = position;
                        break;
                    }
                }
                version += 1;
            }

            // After advancing each version of the stack, re-sort the versions by their cost,
            // removing any versions that are no longer worth pursuing.
            let min_error_cost = self.condense_stack();

            // If there's already a finished parse tree that's better than any in-progress version,
            // then terminate parsing. Clear the parse stack to remove any extra references to subtrees
            // within the finished tree, ensuring that these subtrees can be safely mutated in-place
            // for rebalancing.
            if let Some(ft) = &self.finished_tree {
                if ft.error_cost() < min_error_cost {
                    self.stack.clear();
                    break;
                }
            }

            if version_count == 0 {
                break;
            }
        }
        log!(self, "done");
        self.finished_tree.clone()
    }
}
