#![allow(dead_code)]
use super::language::{Language, TSSymbol, TS_BUILTIN_SYM_ERROR};
use super::subtree::{Length, Point, Subtree};

#[derive(Clone, Debug)]
pub struct Node {
    pub symbol: TSSymbol,
    pub grammar_symbol: TSSymbol,
    pub kind: &'static str,
    pub grammar_kind: &'static str,
    pub is_named: bool,
    pub is_extra: bool,
    pub is_missing: bool,
    pub has_error: bool,
    pub start_byte: u32,
    pub end_byte: u32,
    pub start_point: Point,
    pub end_point: Point,
    pub field_id: u16,
    pub field_name: Option<&'static str>,
    pub children: Vec<usize>,
    pub parent: Option<usize>,
    pub parse_state: u16,
    pub index_in_parent: usize,
}

pub struct Tree {
    pub nodes: Vec<Node>,
    pub language: Language,
    pub root_subtree: Subtree,
}

impl Node {
    pub fn is_error(&self) -> bool {
        self.symbol == TS_BUILTIN_SYM_ERROR
    }
}

impl Tree {
    pub fn new(root: Subtree, language: Language) -> Tree {
        let mut tree = Tree { nodes: Vec::new(), language, root_subtree: root.clone() };
        let start = root.padding;
        tree.build_node(&root, start, 0, 0, None);
        tree
    }

    pub fn root(&self) -> usize {
        0
    }

    fn build_node(&mut self, subtree: &Subtree, start: Length, alias: TSSymbol, field_id: u16, parent: Option<usize>) -> usize {
        let symbol = if alias != 0 { alias } else { subtree.symbol };
        let named = if alias != 0 { self.language.symbol_metadata(alias).named } else { subtree.named };
        let end = start.add(subtree.size);
        let id = self.nodes.len();
        let index_in_parent = parent.map_or(0, |p| self.nodes[p].children.len());
        self.nodes.push(Node {
            symbol: self.language.public_symbol(symbol),
            grammar_symbol: subtree.symbol,
            kind: self.language.symbol_name(symbol),
            grammar_kind: self.language.symbol_name(subtree.symbol),
            is_named: named || subtree.symbol == TS_BUILTIN_SYM_ERROR,
            is_extra: subtree.extra,
            is_missing: subtree.is_missing,
            has_error: subtree.error_cost() > 0,
            start_byte: start.bytes,
            end_byte: end.bytes,
            start_point: start.extent,
            end_point: end.extent,
            field_id,
            field_name: if field_id != 0 { self.language.field_name(field_id) } else { None },
            children: Vec::new(),
            parent,
            parse_state: subtree.parse_state,
            index_in_parent,
        });
        if let Some(p) = parent {
            self.nodes[p].children.push(id);
        }
        self.collect_children(id, subtree, start, 0);
        id
    }

    fn collect_children(&mut self, owner: usize, subtree: &Subtree, start: Length, inherited_field: u16) {
        let mut position = start;
        let mut structural_index = 0usize;
        let field_map: Vec<_> = self.language.field_map(subtree.production_id).to_vec();
        for (i, child) in subtree.children.iter().enumerate() {
            let mut alias = 0;
            let child_structural_index = structural_index;
            if !child.extra {
                alias = self.language.alias_at(subtree.production_id, structural_index);
                structural_index += 1;
            }
            if i > 0 {
                position = position.add(child.padding);
            }
            let child_start = position;
            position = position.add(child.size);

            let mut field = 0u16;
            if !child.extra {
                for entry in &field_map {
                    if !entry.inherited && entry.child_index as usize == child_structural_index {
                        field = entry.field_id;
                        break;
                    }
                }
                if field == 0 {
                    field = inherited_field;
                }
            }

            let visible = child.visible || alias != 0;
            if visible {
                self.build_node(child, child_start, alias, field, Some(owner));
            } else if !child.children.is_empty() {
                self.collect_children(owner, child, child_start, field);
            }
        }
    }

    pub fn node(&self, id: usize) -> &Node {
        &self.nodes[id]
    }

    pub fn named_children(&self, id: usize) -> Vec<usize> {
        self.nodes[id].children.iter().copied().filter(|c| self.nodes[*c].is_named).collect()
    }

    pub fn next_sibling(&self, id: usize) -> Option<usize> {
        let p = self.nodes[id].parent?;
        let idx = self.nodes[id].index_in_parent;
        self.nodes[p].children.get(idx + 1).copied()
    }

    pub fn prev_sibling(&self, id: usize) -> Option<usize> {
        let p = self.nodes[id].parent?;
        let idx = self.nodes[id].index_in_parent;
        if idx == 0 {
            None
        } else {
            self.nodes[p].children.get(idx - 1).copied()
        }
    }

    pub fn next_named_sibling(&self, id: usize) -> Option<usize> {
        let mut cur = self.next_sibling(id);
        while let Some(c) = cur {
            if self.nodes[c].is_named {
                return Some(c);
            }
            cur = self.next_sibling(c);
        }
        None
    }

    pub fn prev_named_sibling(&self, id: usize) -> Option<usize> {
        let mut cur = self.prev_sibling(id);
        while let Some(c) = cur {
            if self.nodes[c].is_named {
                return Some(c);
            }
            cur = self.prev_sibling(c);
        }
        None
    }

    pub fn child_by_field_id(&self, id: usize, field: u16) -> Option<usize> {
        self.nodes[id].children.iter().copied().find(|c| self.nodes[*c].field_id == field)
    }

    pub fn children_by_field_id(&self, id: usize, field: u16) -> Vec<usize> {
        self.nodes[id].children.iter().copied().filter(|c| self.nodes[*c].field_id == field).collect()
    }

    /// Render the node as an S-expression like ts_node_string.
    pub fn to_sexp(&self, id: usize) -> String {
        let mut out = String::new();
        self.write_sexp(id, &mut out, true, None);
        out
    }

    fn write_sexp(&self, id: usize, out: &mut String, is_root: bool, field: Option<&str>) {
        let n = &self.nodes[id];
        let visible = n.is_named || is_root;
        if visible {
            if !is_root {
                out.push(' ');
            }
            if let Some(f) = field {
                out.push_str(f);
                out.push_str(": ");
            }
            if n.is_missing {
                if n.is_named {
                    out.push_str(&format!("(MISSING {}", n.kind));
                } else {
                    out.push_str(&format!("(MISSING \"{}\"", n.kind.replace('\\', "\\\\").replace('"', "\\\"")));
                }
            } else if !n.is_named {
                out.push_str(&format!("(\"{}\"", n.kind.replace('\\', "\\\\").replace('"', "\\\"")));
            } else {
                out.push('(');
                out.push_str(n.kind);
            }
        }
        for c in &n.children {
            let cn = &self.nodes[*c];
            if cn.is_named {
                self.write_sexp(*c, out, false, cn.field_name);
            }
        }
        if visible {
            out.push(')');
        }
    }
}
