}

pub fn find_config_file() -> Option<PathBuf> {
    if let Ok(d) = std::env::var("TREE_SITTER_DIR") {
        let p = PathBuf::from(d).join("config.json");
        if p.is_file() {
            return Some(p);
        }
    }
    let xdg = std::env::var("XDG_CONFIG_HOME").map(PathBuf::from).unwrap_or_else(|_| crate::loader::home_dir().join(".config"));
    let p = xdg.join("tree-sitter").join("config.json");
    if p.is_file() {
        return Some(p);
    }
    let legacy = crate::loader::home_dir().join(".tree-sitter").join("config.json");
    if legacy.is_file() {
        return Some(legacy);
    }
    None
}

impl Config {
    pub fn load(path: Option<&Path>) -> Result<Config> {
        let location = match path {
            Some(p) => Some(p.to_path_buf()),
            None => find_config_file(),
        };
        let raw = match &location {
            Some(p) => {
                let text = std::fs::read_to_string(p)?;
                serde_json::from_str(&text)?
            }
            None => serde_json::json!({}),
        };
        let parser_directories = raw
            .get("parser-directories")
            .and_then(|v| v.as_array())
            .map(|a| a.iter().filter_map(|x| x.as_str()).map(|s| PathBuf::from(expand_home(s))).collect())
            .unwrap_or_default();
        let theme = raw.get("theme").cloned();
        Ok(Config { parser_directories, theme, raw, location })
    }
}

fn expand_home(s: &str) -> String {
    if let Some(rest) = s.strip_prefix("~/") {
        format!("{}/{}", crate::loader::home_dir().display(), rest)
    } else {
        s.to_string()
    }
}
