    }

    pub fn find_all_languages(&mut self, config_path: Option<&Path>) -> Result<()> {
        let config = crate::config::Config::load(config_path)?;
        for dir in config.parser_directories {
            if let Ok(entries) = std::fs::read_dir(&dir) {
                let mut paths: Vec<PathBuf> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
                paths.sort();
                for p in paths {
                    let name = p.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                    if name.starts_with("tree-sitter-") && p.is_dir() {
                        let _ = self.find_language_configurations_at_path(&p);
                    }
                }
            }
        }
        Ok(())
    }

    pub fn language_for_config(&mut self, idx: usize) -> Result<Language> {
        let config = self.configs[idx].clone();
        self.load_language_at_path(&config.root_path.join("src"), &config.name)
    }

    pub fn load_language_at_path(&mut self, src_path: &Path, name: &str) -> Result<Language> {
        let lib_name = format!("{}.so", name);
        let lib_dir = cache_dir();
        let lib_path = lib_dir.join(&lib_name);
        if let Some(l) = self.languages.get(&lib_path) {
            return Ok(*l);
        }
        let parser_path = src_path.join("parser.c");
        let mut scanner_path = None;
        for f in ["scanner.c", "scanner.cc", "scanner.cpp"] {
            let p = src_path.join(f);
            if p.exists() {
                scanner_path = Some(p);
                break;
            }
        }
        let needs_recompile = self.force_rebuild || !lib_path.exists() || {
            let lib_mtime = std::fs::metadata(&lib_path).and_then(|m| m.modified()).ok();
            let mut paths = vec![parser_path.clone()];
            if let Some(s) = &scanner_path {
                paths.push(s.clone());
            }
            paths.iter().any(|p| {
                let m = std::fs::metadata(p).and_then(|m| m.modified()).ok();
                match (m, lib_mtime) {
                    (Some(m), Some(l)) => m > l,
                    _ => true,
                }
            })
        };
        if needs_recompile {
            std::fs::create_dir_all(&lib_dir).ok();
            std::fs::create_dir_all(lib_dir.parent().unwrap().join("lock")).ok();
            compile_parser(src_path, &parser_path, scanner_path.as_deref(), &lib_path, self.debug_build)?;
        }
        let fname = format!("tree_sitter_{}", replace_dashes_with_underscores(name));
        let lang = load_language_from_library(&lib_path, &fname).map_err(|e| anyhow!("Error opening dynamic library {}\n\nCaused by:\n    {}", lib_path.display(), e))?;
        self.languages.insert(lib_path, lang);
        Ok(lang)
    }

    pub fn language_for_file_name(&mut self, path: &Path) -> Result<Option<Language>> {
        let file_name = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
        let ext = path.extension().map(|e| e.to_string_lossy().to_string());
        let mut best = None;
        for (i, c) in self.configs.iter().enumerate() {
            for ft in &c.file_types {
                if *ft == file_name || Some(ft.clone()) == ext {
                    best = Some(i);
                    break;
                }
            }
            if best.is_some() {
                break;
            }
        }
        match best {
            Some(i) => Ok(Some(self.language_for_config(i)?)),
            None => Ok(None),
        }
    }

    pub fn config_for_scope(&self, scope: &str) -> Option<usize> {
        self.configs.iter().position(|c| c.scope.as_deref() == Some(scope))
    }

    pub fn config_for_language_name(&self, name: &str) -> Option<usize> {
        self.configs.iter().position(|c| c.name == name)
    }

    /// Select a language for a given file path.
    pub fn select_language(&mut self, path: &Path, current_dir: &Path, scope: Option<&str>, lib_info: Option<(&Path, &str)>) -> Result<(Language, Option<usize>)> {
        if let Some((lib_path, name)) = lib_info {
            let fname = format!("tree_sitter_{}", replace_dashes_with_underscores(name));
            let lang = load_language_from_library(lib_path, &fname).map_err(|e| anyhow!("Error opening dynamic library {}\n\nCaused by:\n    {}", lib_path.display(), e))?;
            return Ok((lang, None));
        }
        if let Some(scope) = scope {
            if let Some(i) = self.config_for_scope(scope) {
                return Ok((self.language_for_config(i)?, Some(i)));
            }
            return Err(anyhow!("Unknown scope '{}'", scope));
        }
        let file_name = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
        let ext = path.extension().map(|e| e.to_string_lossy().to_string());
        for i in 0..self.configs.len() {
            let matches = self.configs[i].file_types.iter().any(|ft| *ft == file_name || Some(ft.clone()) == ext);
            if matches {
                return Ok((self.language_for_config(i)?, Some(i)));
            }
        }
        if let Some(i) = self.current_dir_config {
            return Ok((self.language_for_config(i)?, Some(i)));
        }
        let _ = current_dir;
        // first line regex
        if let Ok(text) = std::fs::read_to_string(path) {
            let first_line = text.lines().next().unwrap_or("");
            for i in 0..self.configs.len() {
                if let Some(re) = &self.configs[i].first_line_regex {
                    if let Ok(r) = regex::Regex::new(re) {
                        if r.is_match(first_line) {
                            return Ok((self.language_for_config(i)?, Some(i)));
                        }
                    }
                }
            }
        }
        Err(anyhow!("No language found"))
    }
}

pub fn compile_parser(src_path: &Path, parser_path: &Path, scanner_path: Option<&Path>, output_path: &Path, debug: bool) -> Result<()> {
    let mut cmd = Command::new("cc");
    if debug {
        cmd.arg("-O0").arg("-g");
    } else {
        cmd.arg("-O2");
    }
    cmd.arg("-fPIC").arg("-shared").arg("-std=c11").arg("-I").arg(src_path).arg("-w");
    cmd.arg(parser_path);
    let mut cxx = false;
    if let Some(s) = scanner_path {
        if s.extension().map_or(false, |e| e == "c") {
            cmd.arg(s);
        } else {
            cxx = true;
        }
    }
    cmd.arg("-o").arg(output_path);
    if cxx {
        // compile C++ scanner separately and link
        let obj = output_path.with_extension("scanner.o");
        let st = Command::new("c++").arg("-fPIC").arg("-c").arg("-O2").arg("-I").arg(src_path).arg(scanner_path.unwrap()).arg("-o").arg(&obj).status()?;
        if !st.success() {
            return Err(anyhow!("Failed to compile scanner"));
        }
        cmd.arg(&obj).arg("-lstdc++");
    }
    let out = cmd.output().context("Failed to execute the C compiler with the following command")?;
    if !out.status.success() {
        return Err(anyhow!(
            "Parser compilation failed.\nStdout: {}\nStderr: {}",
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    Ok(())
}
