use crate::loader::Loader;
use crate::runtime::language::Language;
use crate::runtime::lexer::Encoding;
use crate::runtime::parser::Parser;
use crate::runtime::tree::Tree;
use anyhow::{anyhow, Result};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum OutputFormat {
    Sexp,
    Xml,
    Cst,
    Dot,
    Quiet,
}

pub struct ParseOptions {
    pub output: OutputFormat,
    pub no_ranges: bool,
    pub stat: bool,
    pub time: bool,
    pub quiet: bool,
    pub debug: Option<String>,
    pub encoding: Encoding,
    pub timeout: u64,
    pub json_summary: bool,
    pub edits: Vec<String>,
}

pub struct ParseStat {
    pub file: String,
    pub successful: bool,
    pub start: (u32, u32),
    pub end: (u32, u32),
    pub duration: Duration,
    pub bytes: usize,
}

pub fn parse_source(language: Language, source: &[u8], encoding: Encoding, debug: Option<&str>, timeout: u64) -> (Option<Tree>, Duration) {
    let start = Instant::now();
    let mut parser = Parser::new(language, source.to_vec(), encoding);
    parser.timeout_micros = timeout;
    if let Some(mode) = debug {
        let pretty = mode == "pretty";
        let _ = pretty;
        parser.logger = Some(Box::new(move |s: &str| {
            eprintln!("{}", s);
        }));
    }
    let root = parser.parse();
    let dur = start.elapsed();
    (root.map(|r| Tree::new(r, language)), dur)
}

pub fn write_sexp_tree(out: &mut impl Write, tree: &Tree, no_ranges: bool) -> std::io::Result<()> {
    // Mirrors the cursor-based traversal used by the CLI.
    let mut needs_newline = false;
    fn visit(tree: &Tree, id: usize, depth: usize, out: &mut impl Write, needs_newline: &mut bool, no_ranges: bool) -> std::io::Result<()> {
        let n = tree.node(id);
        if n.is_named {
            if *needs_newline {
                out.write_all(b"\n")?;
            }
            for _ in 0..depth {
                out.write_all(b"  ")?;
            }
            if let Some(f) = n.field_name {
                write!(out, "{}: ", f)?;
            }
            if n.is_missing {
                write!(out, "(MISSING {}", n.kind)?;
            } else {
                write!(out, "({}", n.kind)?;
            }
            if !no_ranges {
                write!(out, " [{}, {}] - [{}, {}]", n.start_point.row, n.start_point.column, n.end_point.row, n.end_point.column)?;
            }
            *needs_newline = true;
        }
        for c in &n.children {
            visit(tree, *c, depth + 1, out, needs_newline, no_ranges)?;
        }
        if n.is_named {
            out.write_all(b")")?;
            *needs_newline = true;
        }
        Ok(())
    }
    visit(tree, tree.root(), 0, out, &mut needs_newline, no_ranges)?;
    out.write_all(b"\n")?;
    Ok(())
}

/// Find the first error or missing node in a tree (pre-order).
pub fn first_error(tree: &Tree) -> Option<usize> {
    fn find(tree: &Tree, id: usize) -> Option<usize> {
        let n = tree.node(id);
        if n.is_error() || n.is_missing {
            return Some(id);
        }
        if !n.has_error && !n.is_error() {
            // still need to search children: has_error covers subtree
        }
        for c in &n.children {
            if let Some(r) = find(tree, *c) {
                return Some(r);
            }
        }
        None
    }
    find(tree, tree.root())
}

pub fn error_description(tree: &Tree, id: usize) -> String {
    let n = tree.node(id);
    if n.is_missing {
        if n.is_named {
            format!("(MISSING {} [{}, {}] - [{}, {}])", n.kind, n.start_point.row, n.start_point.column, n.end_point.row, n.end_point.column)
        } else {
            format!("(MISSING \"{}\" [{}, {}] - [{}, {}])", n.kind.replace('\n', "\\n"), n.start_point.row, n.start_point.column, n.end_point.row, n.end_point.column)
        }
    } else {
        format!("({} [{}, {}] - [{}, {}])", n.kind, n.start_point.row, n.start_point.column, n.end_point.row, n.end_point.column)
    }
}

pub fn parse_file_at_path(language: Language, path: &Path, display_name: &str, opts: &ParseOptions, stats: &mut Vec<ParseStat>, out: &mut impl Write) -> Result<bool> {
    let source = std::fs::read(path).map_err(|e| anyhow!("Error reading source file {:?}: {}", path, e))?;
    let (tree, duration) = parse_source(language, &source, opts.encoding, opts.debug.as_deref(), opts.timeout);
    let tree = match tree {
        Some(t) => t,
        None => {
            writeln!(out, "{:<width$}\tParse: {:>7.2} ms\t(timed out)", display_name, duration.as_secs_f64() * 1000.0, width = 0)?;
            stats.push(ParseStat { file: display_name.to_string(), successful: false, start: (0, 0), end: (0, 0), duration, bytes: source.len() });
            return Ok(false);
        }
    };

    match opts.output {
        OutputFormat::Sexp => write_sexp_tree(out, &tree, opts.no_ranges)?,
        OutputFormat::Cst => super::parse_render::write_cst(out, &tree, &source)?,
        OutputFormat::Xml => super::parse_render::write_xml(out, &tree, &source, display_name)?,
        OutputFormat::Dot => super::parse_render::write_dot(out, &tree)?,
        OutputFormat::Quiet => {}
    }

    let root = tree.node(tree.root());
    let first_err = first_error(&tree);
    let ms = duration.as_secs_f64() * 1000.0;
    let speed = if duration.as_nanos() > 0 { (source.len() as f64 / (duration.as_nanos() as f64 / 1_000_000.0)) as u64 } else { 0 };
    let successful = first_err.is_none();
    if let Some(e) = first_err {
        if !opts.json_summary {
            writeln!(out, "{}\tParse: {:>7.2} ms\t{:>6} bytes/ms\t{}", display_name, ms, speed, error_description(&tree, e))?;
        }
    } else if opts.time && !opts.json_summary {
        writeln!(out, "{}\tParse: {:>7.2} ms\t{:>6} bytes/ms", display_name, ms, speed)?;
    }
    stats.push(ParseStat {
        file: display_name.to_string(),
        successful,
        start: (root.start_point.row, root.start_point.column),
        end: (root.end_point.row, root.end_point.column),
        duration,
        bytes: source.len(),
    });
    Ok(successful)
}

pub fn collect_paths(paths_file: Option<&str>, paths: Vec<String>) -> Result<Vec<String>> {
    let mut result = Vec::new();
    if let Some(pf) = paths_file {
        let text = std::fs::read_to_string(pf)?;
        for line in text.lines() {
            let l = line.trim();
            if !l.is_empty() {
                result.push(l.to_string());
            }
        }
        return Ok(result);
    }
    for p in paths {
        if Path::new(&p).exists() {
            result.push(p);
        } else if p.contains('*') || p.contains('?') || p.contains('[') {
            // glob
            let mut matched = glob_paths(&p);
            matched.sort();
            result.extend(matched);
        } else {
            // nonexistent path
        }
    }
    if result.is_empty() {
        return Err(anyhow!("No files were found at or matched by the provided pathname/glob"));
    }
    Ok(result)
}

fn glob_paths(pattern: &str) -> Vec<String> {
    let re_str = {
        let mut s = String::from("^");
        for c in pattern.chars() {
            match c {
                '*' => s.push_str("[^/]*"),
                '?' => s.push_str("[^/]"),
                '.' | '+' | '(' | ')' | '^' | '$' | '|' | '{' | '}' | '\\' => {
                    s.push('\\');
                    s.push(c);
                }
                c => s.push(c),
            }
        }
        s.push('$');
        s
    };
    let re = match regex::Regex::new(&re_str) {
        Ok(r) => r,
        Err(_) => return vec![],
    };
    let mut out = Vec::new();
    let base = if pattern.starts_with('/') { PathBuf::from("/") } else { PathBuf::from(".") };
    for entry in walk(&base) {
        let s = entry.to_string_lossy().to_string();
        let s = s.strip_prefix("./").unwrap_or(&s).to_string();
        if re.is_match(&s) {
            out.push(s);
        }
    }
    out
}

fn walk(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(entries) = std::fs::read_dir(dir) {
        for e in entries.flatten() {
            let p = e.path();
            if p.is_dir() {
                out.extend(walk(&p));
            } else {
                out.push(p);
            }
        }
    }
    out
}
