    let _ = loader.find_all_languages(config_path.as_deref());

    let output = if m.get_flag("quiet") {
        OutputFormat::Quiet
    } else if m.get_flag("xml") {
        OutputFormat::Xml
    } else if m.get_flag("cst") {
        OutputFormat::Cst
    } else if m.get_flag("dot") {
        OutputFormat::Dot
    } else {
        OutputFormat::Sexp
    };
