        no_ranges: m.get_flag("no_ranges"),
        stat: m.get_flag("stat"),
        time: m.get_flag("time"),
        quiet: m.get_flag("quiet"),
        debug: m.get_one::<String>("debug").cloned(),
        encoding,
        timeout: m.get_one::<u64>("timeout").copied().unwrap_or(0),
        json_summary: m.get_flag("json_summary") || m.get_flag("json"),
        edits: m.get_many::<String>("edits").map(|v| v.cloned().collect()).unwrap_or_default(),
    };
