    let paths = collect_paths(m.get_one::<String>("paths_file").map(|s| s.as_str()), paths)?;
    let lib_path = m.get_one::<String>("lib_path").cloned();
    let lang_name = m.get_one::<String>("lang_name").cloned();
    let scope = m.get_one::<String>("scope").cloned();

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut stats = Vec::new();
    let mut had_error = false;
    for path in &paths {
