        Cursor { tree, stack: vec![tree.root()] }
    }
    pub fn node(&self) -> usize {
        *self.stack.last().unwrap()
    }
    pub fn goto_first_child(&mut self) -> bool {
        let n = self.tree.node(self.node());
        if let Some(c) = n.children.first() {
            self.stack.push(*c);
            true
        } else {
            false
        }
    }
    pub fn goto_next_sibling(&mut self) -> bool {
        if self.stack.len() < 2 {
            return false;
        }
        match self.tree.next_sibling(self.node()) {
            Some(s) => {
                *self.stack.last_mut().unwrap() = s;
                true
            }
            None => false,
        }
    }
    pub fn goto_parent(&mut self) -> bool {
        if self.stack.len() > 1 {
            self.stack.pop();
            true
        } else {
            false
        }
    }
    pub fn field_name(&self) -> Option<&'static str> {
        if self.stack.len() < 2 {
            return None;
        }
        self.tree.node(self.node()).field_name
    }
}

fn paint(color: &str, text: &str) -> String {
    if color.is_empty() {
        text.to_string()
    } else {
        format!("{}{}\x1b[0m", color, text)
    }
}

const NODE_KIND: &str = "\x1b[96m";
const FIELD: &str = "\x1b[34m";
const EXTRA: &str = "\x1b[95m";
const ERROR: &str = "\x1b[31m";
const MISSING: &str = "\x1b[38;2;255;153;51m";
const LITERAL: &str = "\x1b[38;2;219;219;173m";
const NODE_TEXT: &str = "\x1b[38;2;118;118;118m";
const BACKTICK: &str = "\x1b[38;2;101;192;67m";
const ROW: &str = "\x1b[37m";
const ROW_NAMED: &str = "\x1b[96m";
const LINE_FEED: &str = "\x1b[38;2;166;172;181m";

fn digits(n: usize) -> usize {
    if n == 0 {
        1
    } else {
        (n as f64).log10() as usize + 1
    }
}

fn render_range(is_named: bool, is_multiline: bool, has_field: bool, width: usize, sr: u32, sc: u32, er: u32, ec: u32) -> String {
    let color = if is_named && !is_multiline && !has_field { ROW_NAMED } else { ROW };
    let start = format!("{}:{}", sr, sc);
    let end = format!("{}:{}", er, ec);
    paint(color, &format!("{:<w$}- {:<w$}", start, end, w = width))
}

fn escape_invisible(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\0' => out.push_str("\\0"),
            '\\' => out.push_str("\\\\"),
            '\x0b' => out.push_str("\\v"),
            '\x0c' => out.push_str("\\f"),
            c => out.push(c),
        }
    }
    out
}

fn escape_delimiter(s: &str, quote: char) -> String {
    s.replace(quote, &format!("\\{}", quote))
}

fn render_node_text(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c => out.push(c),
        }
    }
    out
}

fn render_line_feed(line: &str) -> String {
    if let Some(stripped) = line.strip_suffix("\r\n") {
        format!("{}{}", render_node_text(stripped), paint(LINE_FEED, "\\r\\n"))
    } else if let Some(stripped) = line.strip_suffix('\n') {
        format!("{}{}", render_node_text(stripped), paint(LINE_FEED, "\\n"))
    } else {
        render_node_text(line)
    }
}

pub fn write_cst(out: &mut impl Write, tree: &Tree, source: &[u8]) -> std::io::Result<()> {
    let lossy = String::from_utf8_lossy(source);
    let total_width = lossy.lines().enumerate().map(|(row, line)| digits(row) + digits(line.len()) + 1).max().unwrap_or(1) + 1;
    let mut cursor = Cursor::new(tree);
    let mut indent_level = 1usize;
    let mut did_visit_children = false;
    let mut in_error = false;
    loop {
        if did_visit_children {
            if cursor.goto_next_sibling() {
                did_visit_children = false;
            } else if cursor.goto_parent() {
                did_visit_children = true;
                indent_level -= 1;
                if !tree.node(cursor.node()).has_error {
                    in_error = false;
                }
            } else {
                break;
            }
        } else {
            cst_render_node(out, &cursor, source, total_width, indent_level, in_error)?;
            if cursor.goto_first_child() {
                did_visit_children = false;
                indent_level += 1;
                if tree.node(cursor.node()).has_error {
                    in_error = true;
                }
            } else {
                did_visit_children = true;
            }
        }
    }
    Ok(())
}

fn cst_render_node(out: &mut impl Write, cursor: &Cursor, source: &[u8], total_width: usize, indent_level: usize, in_error: bool) -> std::io::Result<()> {
    let tree = cursor.tree;
    let id = cursor.node();
    let node = tree.node(id);
    let is_named = node.is_named;
    let field = cursor.field_name();
    write!(out, "{}", render_range(is_named, false, field.is_some(), total_width, node.start_point.row, node.start_point.column, node.end_point.row, node.end_point.column))?;
    write!(out, "{}{}", "  ".repeat(indent_level), if in_error && !node.has_error { " " } else { "" })?;
    if is_named {
        if let Some(f) = field {
            write!(out, "{}", paint(FIELD, &format!("{}: ", f)))?;
        }
        if node.has_error || node.is_error() {
            write!(out, "{}", paint(ERROR, "•"))?;
        }
        let parent_is_extra = node.parent.map_or(false, |p| tree.node(p).is_extra && !tree.node(p).is_error());
        let kind_color = if node.is_error() {
            ERROR
        } else if node.is_extra || parent_is_extra {
            EXTRA
        } else {
            NODE_KIND
        };
        write!(out, "{}", paint(kind_color, node.kind))?;
        if node.children.is_empty() {
            let text = String::from_utf8_lossy(&source[node.start_byte as usize..(node.end_byte as usize).min(source.len())]).to_string();
            write_named_text(out, cursor, &text, total_width, indent_level)?;
        }
    } else if node.is_missing {
        write!(out, "{}: ", paint(MISSING, "MISSING"))?;
        write!(out, "\"{}\"", paint(MISSING, node.kind))?;
    } else {
        write!(out, "{}{}{}", paint(LITERAL, "\""), paint(LITERAL, &escape_invisible(&escape_delimiter(node.kind, '"'))), paint(LITERAL, "\""))?;
    }
    writeln!(out)?;
    Ok(())
}

fn write_named_text(out: &mut impl Write, cursor: &Cursor, source: &str, total_width: usize, indent_level: usize) -> std::io::Result<()> {
    let node = cursor.tree.node(cursor.node());
    let multiline = source.contains('\n');
    for (i, line) in source.split_inclusive('\n').enumerate() {
        if line.is_empty() {
            break;
        }
        let sr = node.start_point.row + i as u32;
        let sc = node.start_point.column;
        let er = sr;
        let ec = line.len() as u32 + if i == 0 { node.start_point.column } else { 0 };
        let formatted = render_line_feed(line);
        if multiline {
            write!(out, "\n{}{}", render_range(true, true, cursor.field_name().is_some(), total_width, sr, sc, er, ec), "  ".repeat(indent_level + 1))?;
        } else {
            write!(out, " ")?;
        }
        write!(out, "{}{}{}", paint(BACKTICK, "`"), paint(NODE_TEXT, &formatted), paint(BACKTICK, "`"))?;
    }
    Ok(())
}

fn html_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
    out
}

pub fn write_xml(out: &mut impl Write, tree: &Tree, source: &[u8], name: &str, is_first: bool, is_last: bool) -> std::io::Result<()> {
    let mut needs_newline = false;
    let mut indent_level = 2usize;
    let mut did_visit_children = false;
    let mut had_named_children = false;
    let mut tags: Vec<&str> = Vec::new();

    if is_first {
        writeln!(out, "<?xml version=\"1.0\"?>")?;
        writeln!(out, "<sources>")?;
    }
    writeln!(out, "  <source name=\"{}\">", name)?;

    let mut cursor = Cursor::new(tree);
    loop {
        let id = cursor.node();
        let node = tree.node(id);
        let is_named = node.is_named;
        if did_visit_children {
            if is_named {
                let tag = tags.pop();
                if had_named_children {
                    for _ in 0..indent_level {
                        out.write_all(b"  ")?;
                    }
                }
                write!(out, "</{}>", tag.unwrap_or(""))?;
                if let Some(parent) = node.parent {
                    if tree.node(parent).children.last() == Some(&id) {
                        out.write_all(b"\n")?;
                    }
                }
                needs_newline = true;
            }
            if cursor.goto_next_sibling() {
                did_visit_children = false;
                had_named_children = false;
            } else if cursor.goto_parent() {
                did_visit_children = true;
                had_named_children = is_named;
                indent_level -= 1;
                if !is_named && needs_newline {
                    out.write_all(b"\n")?;
                    for _ in 0..indent_level {
                        out.write_all(b"  ")?;
                    }
                }
            } else {
                break;
            }
        } else {
            if is_named {
                if needs_newline {
                    out.write_all(b"\n")?;
                }
                for _ in 0..indent_level {
                    out.write_all(b"  ")?;
                }
                write!(out, "<{}", node.kind)?;
                if let Some(f) = cursor.field_name() {
                    write!(out, " field=\"{}\"", f)?;
                }
                write!(out, " srow=\"{}\" scol=\"{}\"", node.start_point.row, node.start_point.column)?;
                write!(out, " erow=\"{}\" ecol=\"{}\"", node.end_point.row, node.end_point.column)?;
                write!(out, ">")?;
                tags.push(node.kind);
                needs_newline = true;
            }
            if cursor.goto_first_child() {
                did_visit_children = false;
                had_named_children = false;
                indent_level += 1;
            } else {
                did_visit_children = true;
                let start = node.start_byte as usize;
                let end = (node.end_byte as usize).min(source.len());
                let value = String::from_utf8_lossy(&source[start.min(end)..end]).to_string();
                if !is_named && needs_newline {
                    out.write_all(b"\n")?;
                    for _ in 0..indent_level {
                        out.write_all(b"  ")?;
                    }
                }
                write!(out, "{}", html_escape(&value))?;
            }
        }
    }
    writeln!(out)?;
    writeln!(out, "  </source>")?;
    if is_last {
        writeln!(out, "</sources>")?;
    }
    Ok(())
}

