#[allow(clippy::too_many_arguments)]
pub fn parse_source_bytes(language: Language, source: &[u8], display_name: &str, opts: &ParseOptions, stats: &mut Vec<ParseStat>, out: &mut impl Write, is_first: bool, is_last: bool) -> Result<bool> {
    let (tree, duration) = parse_source(language, source, opts.encoding, opts.debug.as_deref(), opts.timeout);
    let ms = duration.as_secs_f64() * 1000.0;
    let speed = if duration.as_nanos() > 0 { (source.len() as f64 / (duration.as_nanos() as f64 / 1_000_000.0)) as u64 } else { 0 };
    let tree = match tree {
        Some(t) => t,
        None => {
            writeln!(out, "{}\\tParse: {:>7.2} ms\\t{:>6} bytes/ms\\t(timed out)", display_name, ms, speed)?;
            stats.push(ParseStat { file: display_name.to_string(), successful: false, start: (0, 0), end: (0, 0), duration, bytes: source.len() });
            return Ok(false);
        }
    };

    if !opts.json_summary {
        match opts.output {
            OutputFormat::Sexp => write_sexp_tree(out, &tree, opts.no_ranges)?,
            OutputFormat::Cst => super::parse_render::write_cst(out, &tree, source)?,
            OutputFormat::Xml => super::parse_render::write_xml(out, &tree, source, display_name, is_first, is_last)?,
            OutputFormat::Dot => {
                out.flush()?;
                super::parse_render::dot_panic()
            }
            OutputFormat::Quiet => {}
        }
    }

    let root = tree.node(tree.root());
    let first_err = first_error(&tree);
    let successful = first_err.is_none();
    if let Some(e) = first_err {
        writeln!(out, "{}\\tParse: {:>7.2} ms\\t{:>6} bytes/ms\\t{}", display_name, ms, speed, error_description(&tree, e))?;
    } else if opts.time {
        writeln!(out, "{}\\tParse: {:>7.2} ms\\t{:>6} bytes/ms", display_name, ms, speed)?;
    }
    stats.push(ParseStat {
        file: display_name.to_string(),
        successful,
        start: (root.start_point.row, root.start_point.column),
        end: (root.end_point.row, root.end_point.column),
        duration,
        bytes: source.len(),
    });
    Ok(successful)
}

pub fn write_json_summary(out: &mut impl Write, stats: &[ParseStat], source_count: usize) -> std::io::Result<()> {
    use serde_json::json;
    let summaries: Vec<serde_json::Value> = stats
        .iter()
        .map(|s| {
            json!({
                "file": s.file,
                "successful": s.successful,
                "start": {"row": s.start.0, "column": s.start.1},
                "end": {"row": s.end.0, "column": s.end.1},
                "duration": {"secs": s.duration.as_secs(), "nanos": s.duration.subsec_nanos()},
                "bytes": s.bytes,
            })
        })
        .collect();
    let total: Duration = stats.iter().map(|s| s.duration).sum();
    let v = json!({
        "parse_summaries": summaries,
        "cumulative_stats": {
            "successful_parses": stats.iter().filter(|s| s.successful).count(),
            "total_parses": stats.len(),
            "total_bytes": stats.iter().map(|s| s.bytes).sum::<usize>(),
            "total_duration": {"secs": total.as_secs(), "nanos": total.subsec_nanos()},
        },
        "source_count": source_count,
    });
    writeln!(out, "{}", serde_json::to_string_pretty(&v).unwrap())
}

