{"command":"cat > /workspace/src/commands/test_cmd.rs <<'EOF'
use crate::runtime::language::{Language, TSSymbol};
use crate::runtime::subtree::Subtree;
use anyhow::{anyhow, Result};
use regex::Regex;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug, Default)]
pub struct TestAttributes {
    pub skip: bool,
    pub platform: bool,
    pub fail_fast: bool,
    pub error: bool,
    pub cst: bool,
    pub languages: Vec<String>,
}

#[derive(Clone, Debug)]
pub enum TestEntry {
    Group { name: String, children: Vec<TestEntry>, file_path: Option<PathBuf> },
    Example {
        name: String,
        input: Vec<u8>,
        output: String,
        header_delim_len: usize,
        divider_delim_len: usize,
        has_fields: bool,
        attributes_str: String,
        attributes: TestAttributes,
        file_name: Option<String>,
    },
}

pub struct SimpleTest {
    pub name: String,
    pub input: String,
}

fn header_regex() -> regex::bytes::Regex {
    regex::bytes::RegexBuilder::new(
        r"^(?x)
           (?P<equals>(?:=+){3,})
           (?P<suffix1>[^=\r\n][^\r\n]*)?
           \r?\n
           (?P<test_name_and_markers>(?:([^=\r\n]|\s+:)[^\r\n]*\r?\n)+)
           ===+
           (?P<suffix2>[^=\r\n][^\r\n]*)?\r?\n",
    )
    .multi_line(true)
    .build()
    .unwrap()
}

fn divider_regex() -> regex::bytes::Regex {
    regex::bytes::RegexBuilder::new(r"^(?P<hyphens>(?:-+){3,})(?P<suffix>[^-\r\n][^\r\n]*)?\r?\n").multi_line(true).build().unwrap()
}

pub fn parse_test_content(name: String, content: &str, file_path: Option<PathBuf>) -> TestEntry {
    let header_re = header_regex();
    let divider_re = divider_regex();
    let comment_re = Regex::new(r"(?m)^\s*;.*$").unwrap();
    let whitespace_re = Regex::new(r"\s+").unwrap();
    let sexp_field_re = Regex::new(r" \w+: \(").unwrap();

    let mut children = Vec::new();
    let bytes = content.as_bytes();
    let mut prev_name = String::new();
    let mut prev_attributes_str = String::new();
    let mut prev_header_end = 0;

    let first_suffix = header_re.captures(bytes).and_then(|c| c.name("suffix1")).map(|m| String::from_utf8_lossy(m.as_bytes()).to_string());

    struct Header {
        delim_len: usize,
        range: std::ops::Range<usize>,
        name: Option<String>,
        attributes_str: Option<String>,
        attributes: TestAttributes,
    }

    let mut headers: Vec<Header> = Vec::new();
    for c in header_re.captures_iter(bytes) {
        let header_delim_len = c.name("equals").map_or(80, |m| m.as_bytes().len());
        let suffix1 = c.name("suffix1").map(|m| String::from_utf8_lossy(m.as_bytes()).to_string());
        let suffix2 = c.name("suffix2").map(|m| String::from_utf8_lossy(m.as_bytes()).to_string());
        let (mut skip, mut platform, mut fail_fast, mut error, mut cst, mut languages): (bool, Option<bool>, bool, bool, bool, Vec<String>) = (false, None, false, false, false, vec![]);
        let tnm = c.name("test_name_and_markers").map_or(&b""[..], |m| m.as_bytes());
        let tnm = String::from_utf8_lossy(tnm).to_string();
        let mut test_name = String::new();
        let mut attributes_str = String::new();
        let mut seen_marker = false;
        for line in tnm.split_inclusive('\n').filter(|s| !s.is_empty()) {
            let trimmed_line = line.trim();
            match trimmed_line.split('(').next().unwrap() {
                ":skip" => {
                    seen_marker = true;
                    skip = true;
                }
                ":platform" => {
                    if let Some(platforms) = trimmed_line.strip_prefix(':').and_then(|s| s.strip_prefix("platform(")) {
                        seen_marker = true;
                        platform = Some(platform.unwrap_or(false) || platforms.trim_matches(')') == std::env::consts::OS);
                    }
                }
                ":fail-fast" => {
                    seen_marker = true;
                    fail_fast = true;
                }
                ":error" => {
                    seen_marker = true;
                    error = true;
                }
                ":language" => {
                    if let Some(lang) = trimmed_line.strip_prefix(':').and_then(|s| s.strip_prefix("language(")) {
                        seen_marker = true;
                        languages.push(lang.trim_matches(')').to_string());
                    }
                }
                ":cst" => {
                    seen_marker = true;
                    cst = true;
                }
                _ if !seen_marker => {
                    test_name.push_str(line);
                }
                _ => {}
            }
            attributes_str.push_str(line);
        }
        if skip {
            error = false;
        }
        if languages.is_empty() {
            languages.push(String::new());
        }
        if suffix1 == first_suffix && suffix2 == first_suffix {
            let range = c.get(0).unwrap().range();
            let test_name = if test_name.is_empty() { None } else { Some(test_name.trim_end().to_string()) };
            let attributes_str = if attributes_str.is_empty() { None } else { Some(attributes_str.trim_end().to_string()) };
            headers.push(Header { delim_len: header_delim_len, range, name: test_name, attributes_str, attributes: TestAttributes { skip, platform: platform.unwrap_or(true), fail_fast, error, cst, languages } });
        }
    }
    headers.push(Header { delim_len: 80, range: bytes.len()..bytes.len(), name: None, attributes_str: None, attributes: TestAttributes { platform: true, ..Default::default() } });

    let mut prev_header_len = 80;
    let mut prev_attributes = TestAttributes { platform: true, ..Default::default() };
    for h in headers {
        if prev_header_end > 0 {
            let region = &bytes[prev_header_end..h.range.start];
            let mut best: Option<(usize, std::ops::Range<usize>)> = None;
            for m in divider_re.captures_iter(region) {
                let divider_delim_len = m.name("hyphens").map_or(80, |m| m.as_bytes().len());
                let suffix = m.name("suffix").map(|m| String::from_utf8_lossy(m.as_bytes()).to_string());
                if suffix == first_suffix {
                    let range = m.get(0).unwrap().range();
                    let r = (prev_header_end + range.start)..(prev_header_end + range.end);
                    match &best {
                        Some((_, br)) if br.len() > r.len() => {}
                        _ => best = Some((divider_delim_len, r)),
                    }
                }
            }
            if let Some((divider_delim_len, divider_range)) = best {
                if let Ok(output) = std::str::from_utf8(&bytes[divider_range.end..h.range.start]) {
                    let mut input = bytes[prev_header_end..divider_range.start].to_vec();
                    input.pop();
                    if input.last() == Some(&b'\r') {
                        input.pop();
                    }
                    let (output, has_fields) = if prev_attributes.cst {
                        (output.trim().to_string(), false)
                    } else {
                        let output = comment_re.replace_all(output, "").to_string();
                        let output = whitespace_re.replace_all(output.trim(), " ").to_string();
                        let output = output.replace(" )", ")");
                        let has_fields = sexp_field_re.is_match(&output);
                        (output, has_fields)
                    };
                    let file_name = file_path.as_ref().and_then(|p| p.file_name().map(|n| n.to_string_lossy().to_string()));
                    children.push(TestEntry::Example {
                        name: prev_name.clone(),
                        input,
                        output,
                        header_delim_len: prev_header_len,
                        divider_delim_len,
                        has_fields,
                        attributes_str: prev_attributes_str.clone(),
                        attributes: prev_attributes.clone(),
                        file_name,
                    });
                }
            }
        }
        prev_attributes = h.attributes;
        prev_name = h.name.unwrap_or_default();
        prev_attributes_str = h.attributes_str.unwrap_or_default();
        prev_header_len = h.delim_len;
        prev_header_end = h.range.end;
    }
    TestEntry::Group { name, children, file_path }
}

pub fn parse_tests(path: &Path) -> Result<TestEntry> {
    let name = path.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    if path.is_dir() {
        let mut children = Vec::new();
        let mut entries: Vec<PathBuf> = std::fs::read_dir(path)?.filter_map(|e| e.ok()).map(|e| e.path()).collect();
        entries.sort();
        for entry in entries {
            let hidden = entry.file_name().map_or(false, |n| n.to_string_lossy().starts_with('.'));
            if !hidden {
                children.push(parse_tests(&entry)?);
            }
        }
        Ok(TestEntry::Group { name, children, file_path: None })
    } else {
        let content = std::fs::read_to_string(path)?;
        Ok(parse_test_content(name, &content, Some(path.to_path_buf())))
    }
}

pub fn get_test_by_number(cwd: &Path, number: u32) -> Result<SimpleTest> {
    let corpus = cwd.join("test").join("corpus");
    let entry = parse_tests(&corpus)?;
    let mut n = 0u32;
    fn find(e: &TestEntry, n: &mut u32, target: u32) -> Option<SimpleTest> {
        match e {
            TestEntry::Group { children, .. } => {
                for c in children {
                    if let Some(r) = find(c, n, target) {
                        return Some(r);
                    }
                }
                None
            }
            TestEntry::Example { name, input, .. } => {
                *n += 1;
                if *n == target {
                    Some(SimpleTest { name: name.clone(), input: String::from_utf8_lossy(input).to_string() })
                } else {
                    None
                }
            }
        }
    }
    find(&entry, &mut n, number).ok_or_else(|| anyhow!("Failed to find a test with the number {}.", number))
}

// ---------------- sexp utilities ----------------

fn write_char_to_string(out: &mut String, chr: i32) {
    if chr == -1 {
        out.push_str("INVALID");
    } else if chr == 0 {
        out.push_str("'\\0'");
    } else if chr == '\n' as i32 {
        out.push_str("'\\n'");
    } else if chr == '\t' as i32 {
        out.push_str("'\\t'");
    } else if chr == '\r' as i32 {
        out.push_str("'\\r'");
    } else if chr > 0 && chr < 128 && (0x20..0x7f).contains(&chr) {
        out.push_str(&format!("'{}'", chr as u8 as char));
    } else {
        out.push_str(&format!("{}", chr));
    }
}

pub fn subtree_to_sexp(root: &Subtree, language: &Language) -> String {
    let mut out = String::new();
    write_subtree(root, language, &mut out, false, 0, false, None, true);
    out
}

#[allow(clippy::too_many_arguments)]
fn write_subtree(tree: &Subtree, language: &Language, out: &mut String, include_all: bool, alias_symbol: TSSymbol, alias_is_named: bool, field_name: Option<&str>, is_root: bool) {
    let is_visible = include_all || tree.is_missing || if alias_symbol != 0 { alias_is_named } else { tree.visible && tree.named };
    if is_visible {
        if !is_root {
            out.push(' ');
            if let Some(f) = field_name {
                out.push_str(f);
                out.push_str(": ");
            }
        }
        if tree.is_error() && tree.children.is_empty() && tree.size.bytes > 0 {
            out.push_str("(UNEXPECTED ");
            write_char_to_string(out, tree.lookahead_char);
        } else {
            let symbol = if alias_symbol != 0 { alias_symbol } else { tree.symbol };
            let symbol_name = language.symbol_name(symbol);
            if tree.is_missing {
                out.push_str("(MISSING ");
                if alias_is_named || tree.named {
                    out.push_str(symbol_name);
                } else {
                    out.push('"');
                    out.push_str(symbol_name);
                    out.push('"');
                }
            } else {
                out.push('(');
                out.push_str(symbol_name);
            }
        }
    } else if is_root {
        let symbol = if alias_symbol != 0 { alias_symbol } else { tree.symbol };
        let symbol_name = language.symbol_name(symbol);
        if !tree.children.is_empty() {
            out.push('(');
            out.push_str(symbol_name);
        } else if tree.named {
            out.push_str(&format!("({})", symbol_name));
        } else {
            out.push_str(&format!("(\"{}\")", symbol_name));
        }
    }

    if !tree.children.is_empty() {
        let field_map: Vec<_> = language.field_map(tree.production_id).to_vec();
        let mut structural_child_index = 0usize;
        for child in &tree.children {
            if child.extra {
                write_subtree(child, language, out, include_all, 0, false, None, false);
            } else {
                let subtree_alias_symbol = language.alias_at(tree.production_id, structural_child_index);
                let subtree_alias_is_named = if subtree_alias_symbol != 0 { language.symbol_metadata(subtree_alias_symbol).named } else { false };
                let mut child_field_name = if is_visible { None } else { field_name };
                for entry in &field_map {
                    if !entry.inherited && entry.child_index as usize == structural_child_index {
                        child_field_name = language.field_name(entry.field_id);
                        break;
                    }
                }
                write_subtree(child, language, out, include_all, subtree_alias_symbol, subtree_alias_is_named, child_field_name, false);
                structural_child_index += 1;
            }
        }
    }

    if is_visible {
        out.push(')');
    }
}

pub fn strip_sexp_fields(sexp: &str) -> String {
    let re = Regex::new(r" \w+: \(").unwrap();
    re.replace_all(sexp, " (").to_string()
}

pub fn format_sexp(sexp: &str, initial_indent_level: usize) -> String {
    let mut indent_level = initial_indent_level;
    let mut formatted = String::new();
    let mut has_field = false;

    let chars: Vec<char> = sexp.chars().collect();
    let mut pos = 0usize;
    let mut s = String::with_capacity(sexp.len());
    let mut quote = '\0';
    let mut saw_paren = false;
    let mut did_last = false;

    let mut fetch_next_str = |next: &mut String| -> Option<()> {
        next.clear();
        while pos < chars.len() {
            let c = chars[pos];
            pos += 1;
            if c == '\'' || c == '"' {
                quote = c;
            } else if c == ' ' || (c == ')' && quote != '\0') {
                if pos < chars.len() {
                    let next_c = chars[pos];
                    if next_c == quote {
                        next.push(c);
                        next.push(next_c);
                        pos += 1;
                        quote = '\0';
                        continue;
                    }
                }
                break;
            }
            if c == ')' {
                saw_paren = true;
                break;
            }
            next.push(c);
        }

        if pos >= chars.len() && next.is_empty() {
            if saw_paren {
                saw_paren = false;
                return Some(());
            }
            if !did_last {
                did_last = true;
                return Some(());
            }
            return None;
        }
        Some(())
    };

    while fetch_next_str(&mut s).is_some() {
        if s.is_empty() && indent_level > 0 {
            indent_level -= 1;
            formatted.push(')');
        } else if s.starts_with('(') {
            if has_field {
                has_field = false;
            } else {
                if indent_level > 0 {
                    formatted.push('\n');
                    for _ in 0..indent_level {
                        formatted.push_str("  ");
                    }
                }
                indent_level += 1;
            }

            formatted.push_str(&s);

            if s.starts_with("(MISSING") || s.starts_with("(UNEXPECTED") {
                fetch_next_str(&mut s).unwrap();
                if s.is_empty() {
                    while indent_level > 0 {
                        indent_level -= 1;
                        formatted.push(')');
                    }
                } else {
                    formatted.push(' ');
                    formatted.push_str(&s);
                }
            }
        } else if s.ends_with(':') {
            formatted.push('\n');
            for _ in 0..indent_level {
                formatted.push_str("  ");
            }
            formatted.push_str(&s);
            formatted.push(' ');
            has_field = true;
            indent_level += 1;
        }
    }

    formatted
}

// ---------------- diff ----------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ChangeTag {
    Equal,
    Delete,
    Insert,
}

fn split_lines(s: &str) -> Vec<&str> {
    s.split_inclusive('\n').collect()
}

/// Compute a line diff using the Myers algorithm.
pub fn diff_lines<'a>(old: &'a str, new: &'a str) -> Vec<(ChangeTag, &'a str)> {
    let a = split_lines(old);
    let b = split_lines(new);
    let ops = myers(&a, &b);
    ops.into_iter()
        .map(|(tag, idx)| match tag {
            ChangeTag::Delete | ChangeTag::Equal => (tag, a[idx]),
            ChangeTag::Insert => (tag, b[idx]),
        })
        .collect()
}

fn myers(a: &[&str], b: &[&str]) -> Vec<(ChangeTag, usize)> {
    let mut result = Vec::new();
    // trim common prefix / suffix
    let mut start = 0;
    while start < a.len() && start < b.len() && a[start] == b[start] {
        result.push((ChangeTag::Equal, start));
        start += 1;
    }
    let mut end_a = a.len();
    let mut end_b = b.len();
    let mut suffix = Vec::new();
    while end_a > start && end_b > start && a[end_a - 1] == b[end_b - 1] {
        end_a -= 1;
        end_b -= 1;
        suffix.push((ChangeTag::Equal, end_a));
    }
    let aa = &a[start..end_a];
    let bb = &b[start..end_b];
    let n = aa.len() as isize;
    let m = bb.len() as isize;
    let max = (n + m) as usize;
    let offset = max as isize;
    let mut v = vec![0isize; 2 * max + 2];
    let mut trace: Vec<Vec<isize>> = Vec::new();
    let mut found = false;
    for d in 0..=(max as isize) {
        trace.push(v.clone());
        let mut k = -d;
        while k <= d {
            let idx = (k + offset) as usize;
            let mut x = if k == -d || (k != d && v[idx - 1] < v[idx + 1]) { v[idx + 1] } else { v[idx - 1] + 1 };
            let mut y = x - k;
            while x < n && y < m && aa[x as usize] == bb[y as usize] {
                x += 1;
                y += 1;
            }
            v[idx] = x;
            if x >= n && y >= m {
                found = true;
                break;
            }
            k += 2;
        }
        if found {
            trace.push(v.clone());
            break;
        }
    }
    // backtrack
    let mut ops: Vec<(ChangeTag, usize)> = Vec::new();
    let mut x = n;
    let mut y = m;
    let dmax = trace.len() as isize - 2;
    let mut d = dmax;
    while d >= 0 {
        let v = &trace[d as usize];
        let k = x - y;
        let prev_k = if k == -d || (k != d && v[(k - 1 + offset) as usize] < v[(k + 1 + offset) as usize]) { k + 1 } else { k - 1 };
        let prev_x = v[(prev_k + offset) as usize];
        let prev_y = prev_x - prev_k;
        while x > prev_x && y > prev_y {
            x -= 1;
            y -= 1;
            ops.push((ChangeTag::Equal, x as usize));
        }
        if d > 0 {
            if x == prev_x {
                y -= 1;
                ops.push((ChangeTag::Insert, y as usize));
            } else {
                x -= 1;
                ops.push((ChangeTag::Delete, x as usize));
            }
        }
        x = prev_x;
        y = prev_y;
        d -= 1;
    }
    ops.reverse();
    // regroup: within runs of non-equal ops, put deletes before inserts
    let mut grouped = Vec::new();
    let mut i = 0;
    while i < ops.len() {
        if ops[i].0 == ChangeTag::Equal {
            grouped.push(ops[i]);
            i += 1;
        } else {
            let mut dels = Vec::new();
            let mut ins = Vec::new();
            while i < ops.len() && ops[i].0 != ChangeTag::Equal {
                if ops[i].0 == ChangeTag::Delete {
                    dels.push(ops[i]);
                } else {
                    ins.push(ops[i]);
                }
                i += 1;
            }
            grouped.extend(dels);
            grouped.extend(ins);
        }
    }
    for op in grouped {
        result.push(match op.0 {
            ChangeTag::Equal => (ChangeTag::Equal, op.1 + start),
            ChangeTag::Delete => (ChangeTag::Delete, op.1 + start),
            ChangeTag::Insert => (ChangeTag::Insert, op.1 + start),
        });
    }
    suffix.reverse();
    result.extend(suffix);
    result
}

pub fn print_diff(out: &mut String, actual: &str, expected: &str, use_color: bool) {
    for (tag, line) in diff_lines(actual, expected) {
        let missing_newline = !line.ends_with('\n');
        match tag {
            ChangeTag::Equal => {
                if use_color {
                    out.push_str(line);
                } else {
                    out.push(' ');
                    out.push_str(line);
                }
                if missing_newline {
                    out.push('\n');
                }
            }
            ChangeTag::Insert => {
                if use_color {
                    out.push_str(&format!("\x1b[32m{}\x1b[0m", line));
                } else {
                    out.push('+');
                    out.push_str(line);
                }
                if missing_newline {
                    out.push('\n');
                }
            }
            ChangeTag::Delete => {
                if use_color {
                    out.push_str(&format!("\x1b[31m{}\x1b[0m", line));
                } else {
                    out.push('-');
                    out.push_str(line);
                }
                if missing_newline {
                    out.push('\n');
                }
            }
        }
    }
    out.push('\n');
}
