}

pub struct Failure {
    pub name: String,
    pub actual: String,
    pub expected: String,
}

fn paint(color: &str, s: &str, use_color: bool) -> String {
    if use_color {
        format!("{}{}\x1b[0m", color, s)
    } else {
        s.to_string()
    }
}

const GREEN: &str = "\x1b[32m";
const RED: &str = "\x1b[31m";
const YELLOW: &str = "\x1b[33m";
const MAGENTA: &str = "\x1b[35m";

type CorrectedEntry = (String, String, String, String, usize, usize);

pub fn run_tests(
    out: &mut String,
    entry: &TestEntry,
    opts: &mut TestOptions,
    mut indent_level: u32,
    failures: &mut Vec<Failure>,
    corrected_entries: &mut Vec<CorrectedEntry>,
    has_parse_errors: &mut bool,
) -> Result<bool> {
    match entry {
        TestEntry::Example { name, input, output, header_delim_len, divider_delim_len, has_fields, attributes_str, attributes, .. } => {
            out.push_str(&"  ".repeat(indent_level as usize));

            if attributes.skip {
                out.push_str(&format!("{:>3}. ⌀ {}\n", opts.test_num, paint(YELLOW, name, opts.color)));
                opts.test_num += 1;
                return Ok(true);
            }

            if !attributes.platform {
                out.push_str(&format!("{:>3}. ⌀ {}\n", opts.test_num, paint(MAGENTA, name, opts.color)));
                opts.test_num += 1;
                return Ok(true);
            }

            for (i, language_name) in attributes.languages.iter().enumerate() {
                let language = if !language_name.is_empty() {
                    match opts.languages.iter().find(|(n, _)| n == language_name) {
                        Some((_, l)) => *l,
                        None => return Err(anyhow!("Language not found: {}", language_name)),
                    }
                } else {
                    opts.languages[0].1
                };
                let start = std::time::Instant::now();
                let mut parser = crate::runtime::parser::Parser::new(language, input.clone(), crate::runtime::lexer::Encoding::Utf8);
                let root = parser.parse().unwrap();
                let dur = start.elapsed();
                opts.total_bytes += input.len();
                opts.total_duration += dur;
                opts.stats_total += 1;

                if attributes.error {
                    if root.error_cost() > 0 {
                        out.push_str(&format!("{:>3}. ✓ {}\n", opts.test_num, paint(GREEN, name, opts.color)));
                        opts.stats_successful += 1;
                        if opts.update {
                            let input = String::from_utf8_lossy(input).to_string();
                            let output = format_sexp(output, 0);
                            corrected_entries.push((name.clone(), input, output, attributes_str.clone(), *header_delim_len, *divider_delim_len));
                        }
                    } else {
                        if opts.update {
                            let input = String::from_utf8_lossy(input).to_string();
                            let output = format_sexp(output, 0);
                            corrected_entries.push((name.clone(), input, output, attributes_str.clone(), *header_delim_len, *divider_delim_len));
                        }
                        out.push_str(&format!("{:>3}. ✗ {}\n", opts.test_num, paint(RED, name, opts.color)));
                        failures.push(Failure { name: name.clone(), actual: subtree_to_sexp(&root, &language), expected: "NO ERROR".to_string() });
                    }
                    if attributes.fail_fast {
                        return Ok(false);
                    }
                } else {
                    let mut actual = subtree_to_sexp(&root, &language);
                    if !(opts.show_fields || *has_fields) {
                        actual = strip_sexp_fields(&actual);
                    }

                    if actual == *output {
                        out.push_str(&format!("{:>3}. ✓ {}\n", opts.test_num, paint(GREEN, name, opts.color)));
                        opts.stats_successful += 1;
                        if opts.update {
                            let input = String::from_utf8_lossy(input).to_string();
                            let output = format_sexp(output, 0);
                            corrected_entries.push((name.clone(), input, output, attributes_str.clone(), *header_delim_len, *divider_delim_len));
                        }
                    } else {
                        if opts.update {
                            let input = String::from_utf8_lossy(input).to_string();
                            let expected_output = format_sexp(output, 0);
                            let actual_output = format_sexp(&actual, 0);
                            if actual.contains("ERROR") || actual.contains("MISSING") {
                                *has_parse_errors = true;
                                corrected_entries.push((name.clone(), input, expected_output, attributes_str.clone(), *header_delim_len, *divider_delim_len));
                            } else {
                                corrected_entries.push((name.clone(), input, actual_output, attributes_str.clone(), *header_delim_len, *divider_delim_len));
                            }
                        }
                        out.push_str(&format!("{:>3}. ✗ {}\n", opts.test_num, paint(RED, name, opts.color)));
                        failures.push(Failure { name: name.clone(), actual, expected: output.clone() });
                        if attributes.fail_fast {
                            return Ok(false);
                        }
                    }
                }
                let _ = i;
            }
            opts.test_num += 1;
        }
        TestEntry::Group { name, children, file_path } => {
            if children.is_empty() {
                return Ok(true);
            }

            indent_level += 1;
            let failure_count = failures.len();
            let mut has_printed = false;

            for child in children {
                if let TestEntry::Example { name: cname, input, output, attributes_str, header_delim_len, divider_delim_len, file_name, .. } = child {
                    let matches = {
                        let mut ok = true;
                        if let (Some(tfp), Some(ffn)) = (file_name, &opts.file_name) {
                            if tfp != ffn {
                                ok = false;
                            }
                        }
                        if ok {
                            if let Some(inc) = &opts.include {
                                ok = inc.is_match(cname);
                            } else if let Some(exc) = &opts.exclude {
                                ok = !exc.is_match(cname);
                            }
                        }
                        ok
                    };
                    if !matches {
                        let input = String::from_utf8_lossy(input).to_string();
                        let output = format_sexp(output, 0);
                        corrected_entries.push((cname.clone(), input, output, attributes_str.clone(), *header_delim_len, *divider_delim_len));
                        opts.test_num += 1;
                        continue;
                    }
                }
                if !has_printed && indent_level > 1 {
                    has_printed = true;
                    out.push_str(&format!("{}{}:\n", "  ".repeat((indent_level - 1) as usize), name));
                }
                if !run_tests(out, child, opts, indent_level, failures, corrected_entries, has_parse_errors)? {
                    return Ok(false);
                }
            }

            if let Some(file_path) = file_path {
                if opts.update && failures.len() - failure_count > 0 {
                    write_tests(file_path, corrected_entries)?;
                }
                corrected_entries.clear();
            }
        }
    }
    Ok(true)
}

fn write_tests(file_path: &Path, corrected_entries: &[CorrectedEntry]) -> Result<()> {
    let mut buffer = String::new();
    for (i, (name, input, output, attributes_str, header_delim_len, divider_delim_len)) in corrected_entries.iter().enumerate() {
        if i > 0 {
            buffer.push('\n');
        }
        buffer.push_str(&"=".repeat(*header_delim_len));
        buffer.push('\n');
        buffer.push_str(name);
        buffer.push('\n');
        if !attributes_str.is_empty() {
            // attributes_str includes the name; only write attribute lines
            for line in attributes_str.lines() {
                let t = line.trim();
                if t.starts_with(':') {
                    buffer.push_str(line.trim_end());
                    buffer.push('\n');
                }
            }
        }
        buffer.push_str(&"=".repeat(*header_delim_len));
        buffer.push('\n');
        buffer.push_str(input);
        buffer.push('\n');
        buffer.push_str(&"-".repeat(*divider_delim_len));
        buffer.push('\n');
        if !output.is_empty() {
            buffer.push('\n');
            buffer.push_str(output.trim_start_matches('\n'));
            buffer.push('\n');
        }
    }
    std::fs::write(file_path, buffer)?;
    Ok(())
}

pub fn print_failures(out: &mut String, failures: &[Failure], use_color: bool) {
    if failures.is_empty() {
        return;
    }
    out.push('\n');
    if failures.len() == 1 {
        out.push_str("1 failure:\n");
    } else {
        out.push_str(&format!("{} failures:\n", failures.len()));
    }
    if use_color {
        out.push_str(&format!("\ncorrect / {} / {}\n", paint(GREEN, "expected", true), paint(RED, "unexpected", true)));
    } else {
        out.push_str("\ncorrect / expected / unexpected\n");
    }
    for (i, f) in failures.iter().enumerate() {
        if f.expected == "NO ERROR" {
            out.push_str(&format!("\n  {}. {}:\n\n", i + 1, f.name));
            out.push_str("  Expected an ERROR node, but got:\n");
            out.push_str(&format!("  {}\n", paint(RED, &format_sexp(&f.actual, 2), use_color)));
        } else {
            out.push_str(&format!("\n  {}. {}:\n", i + 1, f.name));
            let actual = format_sexp(&f.actual, 2);
            let expected = format_sexp(&f.expected, 2);
            print_diff(out, &actual, &expected, use_color);
        }
    }
}
