                let name = self.parse_identifier();
                if name.is_empty() {
                    return Err(self.syntax_error(self.pos));
                }
                let id = self.capture_id(name);
                node.captures.push(id);
            } else {
                break;
            }
        }
        Ok(())
    }

    /// Parse one pattern. Returns None if at ')' or ']' (end of list).
    fn parse_pattern(&mut self, predicates: &mut Vec<Predicate>, is_top_level: bool) -> Result<Option<ChildItem>, QueryError> {
        self.skip_ws();
        let c = match self.peek() {
            None => return Err(self.syntax_error(self.pos)),
            Some(c) => c,
        };
        if c == b')' || c == b']' {
            return Ok(None);
        }
        if c == b'.' {
            self.pos += 1;
            return Ok(Some(ChildItem::Anchor));
        }
        let mut node;
        if c == b'[' {
            self.pos += 1;
            let mut alternatives = Vec::new();
            loop {
                self.skip_ws();
                if self.peek() == Some(b']') {
                    self.pos += 1;
                    break;
                }
                match self.parse_pattern(predicates, false)? {
                    Some(ChildItem::Pattern(p)) => alternatives.push(p),
                    Some(ChildItem::Anchor) => return Err(self.syntax_error(self.pos - 1)),
                    None => return Err(self.syntax_error(self.pos)),
                }
            }
            if alternatives.is_empty() {
                return Err(self.syntax_error(self.pos - 1));
            }
            node = PatternNode { kind: PatternKind::Alternation(alternatives), field: None, captures: vec![], quantifier: Quantifier::One };
        } else if c == b'(' {
            let paren_pos = self.pos;
            self.pos += 1;
            self.skip_ws();
            match self.peek() {
                Some(b'(') | Some(b'[') | Some(b'"') | Some(b'.') | Some(b'_') if self.is_group_start() => {
                    // grouped sequence
                    let mut children = Vec::new();
                    loop {
                        self.skip_ws();
                        if self.peek() == Some(b')') {
                            self.pos += 1;
                            break;
                        }
                        if self.peek() == Some(b'(') && self.src.get(self.pos + 1) == Some(&b'#') {
                            self.parse_predicate(predicates)?;
                            continue;
                        }
                        match self.parse_pattern(predicates, false)? {
                            Some(item) => children.push(item),
                            None => return Err(self.syntax_error(self.pos)),
                        }
                    }
                    node = PatternNode { kind: PatternKind::Group(children), field: None, captures: vec![], quantifier: Quantifier::One };
                }
                Some(b'#') => {
                    let _ = paren_pos;
                    return Err(self.syntax_error(self.pos));
                }
                _ => {
                    let name_start = self.pos;
                    let name = self.parse_identifier();
                    if name.is_empty() {
                        return Err(self.syntax_error(self.pos));
                    }
                    let mut supertype = None;
                    let matcher;
                    if name == "_" {
                        matcher = NodeMatcher::Wildcard { named: true };
                    } else if name == "ERROR" {
                        matcher = NodeMatcher::Error;
                    } else if name == "MISSING" {
                        self.skip_ws();
                        let mut inner = None;
                        match self.peek() {
                            Some(b'"') => {
                                let s_start = self.pos + 1;
                                let s = self.parse_string()?;
                                match self.language.symbol_for_name(&s, false) {
                                    Some(sym) => inner = Some((sym, false)),
                                    None => return Err(self.error(QueryErrorKind::NodeType, s_start, format!("\"{}\"", s))),
                                }
                            }
                            Some(c) if is_ident_char(c) => {
                                let s_start = self.pos;
                                let s = self.parse_identifier();
                                match self.language.symbol_for_name(s, true) {
                                    Some(sym) => inner = Some((sym, true)),
                                    None => return Err(self.error(QueryErrorKind::NodeType, s_start, format!("\"{}\"", s))),
                                }
                            }
                            _ => {}
                        }
                        matcher = NodeMatcher::Missing(inner);
                    } else {
                        let mut base_name = name;
                        if let Some(slash) = name.find('/') {
                            let st = &name[..slash];
                            base_name = &name[slash + 1..];
                            match self.language.symbol_for_name(st, true) {
                                Some(sym) => supertype = Some(sym),
                                None => return Err(self.error(QueryErrorKind::NodeType, name_start, format!("\"{}\"", st))),
                            }
                        }
                        let _ = base_name;
                        match self.language.symbol_for_name(name, true) {
                            Some(sym) => matcher = NodeMatcher::Symbol(sym, true),
                            None => return Err(self.error(QueryErrorKind::NodeType, name_start, format!("\"{}\"", name))),
                        }
                    }
                    // children
                    let mut children = Vec::new();
                    let mut negated_fields = Vec::new();
                    loop {
                        self.skip_ws();
                        match self.peek() {
                            Some(b')') => {
                                self.pos += 1;
                                break;
                            }
                            None => return Err(self.syntax_error(self.pos)),
                            Some(b'!') => {
                                self.pos += 1;
                                self.skip_ws();
                                let fstart = self.pos;
                                let fname = self.parse_identifier();
                                match self.language.field_id_for_name(fname) {
                                    Some(id) => negated_fields.push(id),
                                    None => return Err(self.error(QueryErrorKind::Field, fstart, format!("\"{}\"", fname))),
                                }
                            }
                            Some(b'(') if self.src.get(self.pos + 1) == Some(&b'#') => {
                                self.parse_predicate(predicates)?;
                            }
                            _ => match self.parse_pattern(predicates, false)? {
                                Some(item) => children.push(item),
                                None => return Err(self.syntax_error(self.pos)),
                            },
                        }
                    }
                    node = PatternNode { kind: PatternKind::Node { matcher, supertype, children, negated_fields }, field: None, captures: vec![], quantifier: Quantifier::One };
                }
            }
        } else if c == b'"' {
            let s_start = self.pos + 1;
            let s = self.parse_string()?;
            let sym = match self.language.symbol_for_name(&s, false) {
                Some(sym) => sym,
                None => return Err(self.error(QueryErrorKind::NodeType, s_start, format!("\"{}\"", s))),
            };
            node = PatternNode { kind: PatternKind::Node { matcher: NodeMatcher::Symbol(sym, false), supertype: None, children: vec![], negated_fields: vec![] }, field: None, captures: vec![], quantifier: Quantifier::One };
        } else if c == b'_' && !self.src.get(self.pos + 1).map_or(false, |c| is_ident_char(*c)) {
            self.pos += 1;
            node = PatternNode { kind: PatternKind::Node { matcher: NodeMatcher::Wildcard { named: false }, supertype: None, children: vec![], negated_fields: vec![] }, field: None, captures: vec![], quantifier: Quantifier::One };
        } else if is_ident_char(c) && c != b'.' {
            // field name
            let fstart = self.pos;
            let fname = self.parse_identifier();
            self.skip_ws();
            if self.peek() != Some(b':') {
                return Err(self.syntax_error(fstart));
            }
            self.pos += 1;
            let field_id = match self.language.field_id_for_name(fname) {
                Some(id) => id,
                None => return Err(self.error(QueryErrorKind::Field, fstart, format!("\"{}\"", fname))),
            };
            let inner = self.parse_pattern(predicates, false)?;
            match inner {
                Some(ChildItem::Pattern(mut p)) => {
                    p.field = Some(field_id);
                    return Ok(Some(ChildItem::Pattern(p)));
                }
                _ => return Err(self.syntax_error(self.pos)),
            }
        } else if c == b'@' {
            return Err(self.syntax_error(self.pos));
        } else {
            return Err(self.syntax_error(self.pos));
        }
        let _ = is_top_level;
        self.parse_suffixes(&mut node)?;
        Ok(Some(ChildItem::Pattern(node)))
    }

    fn is_group_start(&self) -> bool {
        match self.peek() {
            Some(b'_') => !self.src.get(self.pos + 1).map_or(false, |c| is_ident_char(*c)),
            Some(b'.') => true,
            _ => true,
        }
    }

    fn parse_predicate(&mut self, predicates: &mut Vec<Predicate>) -> Result<(), QueryError> {
        // at '(' '#'
        self.pos += 2;
        let name = self.parse_identifier().to_string();
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b')') => {
                    self.pos += 1;
                    break;
                }
                Some(b'@') => {
                    self.pos += 1;
                    let cstart = self.pos;
                    let cname = self.parse_identifier();
                    match self.capture_names.iter().position(|n| n == cname) {
                        Some(i) => args.push(PredicateArg::Capture(i)),
                        None => return Err(self.error(QueryErrorKind::Capture, cstart, format!("\"{}\"", cname))),
                    }
                }
                Some(b'"') => {
                    let s = self.parse_string()?;
                    args.push(PredicateArg::String(s));
                }
                Some(c) if is_ident_char(c) => {
                    let s = self.parse_identifier().to_string();
                    args.push(PredicateArg::String(s));
                }
                None => return Err(self.syntax_error(self.pos)),
                _ => return Err(self.syntax_error(self.pos)),
            }
        }
        predicates.push(Predicate { name, args });
        Ok(())
    }
}

fn combine(a: Quantifier, b: Quantifier) -> Quantifier {
    use Quantifier::*;
    match (a, b) {
        (One, x) => x,
        (x, One) => x,
        (ZeroOrOne, ZeroOrOne) => ZeroOrOne,
        (OneOrMore, OneOrMore) => OneOrMore,
        _ => ZeroOrMore,
    }
}

impl Query {
    pub fn new(language: Language, source: &str) -> Result<Query, QueryError> {
        let mut capture_names = Vec::new();
        let mut patterns = Vec::new();
        {
            let mut parser = QueryParser { src: source.as_bytes(), text: source, pos: 0, language, capture_names: &mut capture_names };
            loop {
                parser.skip_ws();
                if parser.pos >= parser.src.len() {
                    break;
                }
                let start = parser.pos;
                let mut predicates = Vec::new();
                match parser.parse_pattern(&mut predicates, true)? {
                    Some(ChildItem::Pattern(p)) => {
                        patterns.push(Pattern { root: p, predicates, start_byte: start });
                    }
                    Some(ChildItem::Anchor) => return Err(parser.syntax_error(start)),
                    None => return Err(parser.syntax_error(parser.pos)),
                }
            }
        }
        // validate predicates
        Ok(Query { patterns, capture_names, language, regex_cache: Default::default() })
    }

    pub fn regex(&self, pattern: &str) -> Option<Regex> {
        let mut cache = self.regex_cache.borrow_mut();
        cache.entry(pattern.to_string()).or_insert_with(|| Regex::new(pattern).ok()).clone()
    }
}

// ---------------- matching ----------------

#[derive(Clone, Debug)]
pub struct QueryCapture {
    pub node: usize,
    pub index: usize,
}

#[derive(Clone, Debug)]
pub struct QueryMatch {
    pub pattern_index: usize,
    pub captures: Vec<QueryCapture>,
    pub completion: usize, // pre-order index of completing node
    pub start_depth: usize,
}

struct Matcher<'a> {
    tree: &'a Tree,
    preorder: Vec<usize>,
    depth: Vec<usize>,
}

type Bindings = Vec<(usize, usize)>; // (capture index, node)

struct Partial {
    caps: Bindings,
    last: Option<usize>, // last matched node (preorder)
}

impl<'a> Matcher<'a> {
    fn node_matches(&self, pn: &PatternNode, node: usize, matcher: &NodeMatcher, supertype: Option<TSSymbol>) -> bool {
        let n = self.tree.node(node);
        let ok = match matcher {
            NodeMatcher::Symbol(sym, named) => {
                if n.symbol == *sym && n.is_named == *named {
                    true
                } else {
                    // supertype pattern: node wrapped by hidden supertype
                    n.supertypes.contains(sym)
                }
            }
            NodeMatcher::Wildcard { named } => {
                if *named {
                    n.is_named
                } else {
                    true
                }
            }
            NodeMatcher::Error => n.symbol == TS_BUILTIN_SYM_ERROR,
            NodeMatcher::Missing(inner) => n.is_missing && inner.map_or(true, |(s, named)| n.symbol == s && n.is_named == named),
        };
        if !ok {
            return false;
        }
        if let Some(st) = supertype {
            if !n.supertypes.contains(&st) {
                return false;
            }
        }
        if let Some(f) = pn.field {
            if n.field_id != f {
                return false;
            }
        }
        true
    }

    /// Match a single pattern node against a tree node; returns list of possible bindings.
    fn match_single(&self, pn: &PatternNode, node: usize) -> Vec<Partial> {
        match &pn.kind {
            PatternKind::Node { matcher, supertype, children, negated_fields } => {
                if !self.node_matches(pn, node, matcher, *supertype) {
                    return vec![];
                }
                for f in negated_fields {
                    if self.tree.node(node).children.iter().any(|c| self.tree.node(*c).field_id == *f) {
                        return vec![];
                    }
                }
                let mut base: Bindings = Vec::new();
                for c in &pn.captures {
                    base.push((*c, node));
                }
                let my_pre = self.preorder[node];
                if children.is_empty() {
                    return vec![Partial { caps: base, last: Some(my_pre) }];
                }
                let kids = &self.tree.node(node).children;
                let results = self.match_sequence(children, kids, 0, true, true);
                results
                    .into_iter()
                    .map(|p| {
                        let mut caps = base.clone();
                        caps.extend(p.caps);
                        Partial { caps, last: Some(p.last.map_or(my_pre, |l| l.max(my_pre))) }
                    })
                    .collect()
            }
            PatternKind::Alternation(alts) => {
                let mut out = Vec::new();
                for alt in alts {
                    let mut alt2 = alt.clone();
                    if alt2.field.is_none() {
                        alt2.field = pn.field;
                    }
                    for mut p in self.match_single(&alt2, node) {
                        let mut caps = Vec::new();
                        for c in &pn.captures {
                            caps.push((*c, node));
                        }
                        caps.extend(p.caps);
                        p.caps = caps;
                        out.push(p);
                    }
                }
                out
            }
            PatternKind::Group(_) => vec![],
        }
    }

    /// Match a sequence of child items against a list of sibling nodes, starting at index `start`.
    fn match_sequence(&self, items: &[ChildItem], siblings: &[usize], start: usize, anchor_first: bool, is_child_list: bool) -> Vec<Partial> {
        // Flatten groups and anchors into a list of (pattern, immediately_after_previous, anchored_first)
        let _ = anchor_first;
        let mut out = Vec::new();
        let anchored_start = matches!(items.first(), Some(ChildItem::Anchor));
        let anchored_end = items.len() > 1 && matches!(items.last(), Some(ChildItem::Anchor));
        self.seq_rec(items, 0, siblings, start, None, anchored_start, anchored_end, is_child_list, Vec::new(), &mut out);
        out
    }

    #[allow(clippy::too_many_arguments)]
    fn seq_rec(
        &self,
        items: &[ChildItem],
        item_idx: usize,
        siblings: &[usize],
        pos: usize,
        last: Option<usize>,
        mut immediate: bool,
        anchored_end: bool,
        is_child_list: bool,
        caps: Bindings,
        out: &mut Vec<Partial>,
    ) {
        let mut idx = item_idx;
        while idx < items.len() {
            if let ChildItem::Anchor = items[idx] {
                if idx > 0 {
                    immediate = true;
                }
                idx += 1;
                continue;
            }
            break;
        }
        if idx >= items.len() {
            if anchored_end {
                // all remaining named siblings must be absent
                for s in &siblings[pos..] {
                    if self.tree.node(*s).is_named && !self.tree.node(*s).is_extra {
                        return;
                    }
                }
            }
            out.push(Partial { caps, last });
            return;
        }
        let pn = match &items[idx] {
            ChildItem::Pattern(p) => p,
            _ => unreachable!(),
        };
        let next_idx = idx + 1;

        // Candidate positions for this item
        let candidates: Vec<usize> = if immediate {
            // the next named sibling (skipping anonymous and extras)
            let mut v = Vec::new();
            let mut i = pos;
            while i < siblings.len() {
                let n = self.tree.node(siblings[i]);
                if n.is_named && !n.is_extra {
                    v.push(i);
                    break;
                }
                // anonymous nodes may be matched directly by anonymous patterns
                if !n.is_named {
                    if let PatternKind::Node { matcher: NodeMatcher::Symbol(_, false), .. } = &pn.kind {
                        v.push(i);
                        break;
                    }
                }
                i += 1;
            }
            v
        } else {
            (pos..siblings.len()).collect()
        };

        let quant = pn.quantifier;
        let allow_zero = matches!(quant, Quantifier::ZeroOrOne | Quantifier::ZeroOrMore);
        let repeat = matches!(quant, Quantifier::ZeroOrMore | Quantifier::OneOrMore);

        let mut found_any = false;
        match &pn.kind {
            PatternKind::Group(group_items) => {
                // match group as a subsequence
                for &ci in &candidates {
                    let mut sub = Vec::new();
                    let mut g_items = group_items.clone();
                    if immediate {
                        g_items.insert(0, ChildItem::Anchor);
                    }
                    self.seq_group(&g_items, siblings, ci, &mut sub);
                    for p in sub {
                        found_any = true;
                        let mut c2 = caps.clone();
                        for c in &pn.captures {
                            if let Some((_, n)) = p.caps.first() {
                                c2.push((*c, *n));
                            }
                        }
                        c2.extend(p.caps.clone());
                        let new_last = max_opt(last, p.last);
                        let end_pos = p.end_pos;
                        if repeat {
                            self.repeat_rec(items, idx, siblings, end_pos, new_last, anchored_end, is_child_list, c2.clone(), out);
                        }
                        self.seq_rec(items, next_idx, siblings, end_pos, new_last, false, anchored_end, is_child_list, c2, out);
                    }
                    if immediate {
                        break;
                    }
                }
            }
            _ => {
                for &ci in &candidates {
                    let node = siblings[ci];
                    let results = self.match_single(pn, node);
                    for p in results {
                        found_any = true;
                        let mut c2 = caps.clone();
                        c2.extend(p.caps);
                        let new_last = max_opt(last, p.last);
                        if repeat {
                            self.repeat_rec(items, idx, siblings, ci + 1, new_last, anchored_end, is_child_list, c2.clone(), out);
                        } else {
                            self.seq_rec(items, next_idx, siblings, ci + 1, new_last, false, anchored_end, is_child_list, c2, out);
                        }
                    }
                }
            }
        }
        if allow_zero {
            self.seq_rec(items, next_idx, siblings, pos, last, immediate, anchored_end, is_child_list, caps, out);
        }
        let _ = found_any;
    }

    #[allow(clippy::too_many_arguments)]
    fn repeat_rec(&self, items: &[ChildItem], idx: usize, siblings: &[usize], pos: usize, last: Option<usize>, anchored_end: bool, is_child_list: bool, caps: Bindings, out: &mut Vec<Partial>) {
        // after matching at least once: greedily try to match more, otherwise continue
        let pn = match &items[idx] {
            ChildItem::Pattern(p) => p,
            _ => unreachable!(),
        };
        let mut matched_more = false;
        for ci in pos..siblings.len() {
            let node = siblings[ci];
            let results = self.match_single(pn, node);
            if !results.is_empty() {
                for p in results {
                    let mut c2 = caps.clone();
                    c2.extend(p.caps);
                    let new_last = max_opt(last, p.last);
                    self.repeat_rec(items, idx, siblings, ci + 1, new_last, anchored_end, is_child_list, c2, out);
                }
                matched_more = true;
                break;
            }
            // skip only if the following items can't match here
            let n = self.tree.node(node);
            if n.is_named && !n.is_extra {
                // a named non-matching sibling ends greedy repetition only if the rest matches
            }
        }
        if !matched_more {
            self.seq_rec(items, idx + 1, siblings, pos, last, false, anchored_end, is_child_list, caps, out);
        }
    }

    fn seq_group(&self, items: &[ChildItem], siblings: &[usize], start: usize, out: &mut Vec<GroupPartial>) {
        let mut tmp = Vec::new();
        self.seq_rec_end(items, 0, siblings, start, None, false, Vec::new(), &mut tmp, true);
        out.extend(tmp);
    }

    #[allow(clippy::too_many_arguments)]
    fn seq_rec_end(&self, items: &[ChildItem], item_idx: usize, siblings: &[usize], pos: usize, last: Option<usize>, mut immediate: bool, caps: Bindings, out: &mut Vec<GroupPartial>, first: bool) {
        let mut idx = item_idx;
        while idx < items.len() {
            if let ChildItem::Anchor = items[idx] {
                immediate = true;
                idx += 1;
                continue;
            }
            break;
        }
        if idx >= items.len() {
            out.push(GroupPartial { caps, last, end_pos: pos });
            return;
        }
        let pn = match &items[idx] {
            ChildItem::Pattern(p) => p,
            _ => unreachable!(),
        };
        let candidates: Vec<usize> = if first {
            vec![pos]
        } else if immediate {
            let mut v = Vec::new();
            let mut i = pos;
            while i < siblings.len() {
                let n = self.tree.node(siblings[i]);
                if n.is_named && !n.is_extra {
                    v.push(i);
                    break;
                }
                i += 1;
            }
            v
        } else {
            (pos..siblings.len()).collect()
        };
        let allow_zero = matches!(pn.quantifier, Quantifier::ZeroOrOne | Quantifier::ZeroOrMore);
        for &ci in &candidates {
            if ci >= siblings.len() {
                continue;
            }
            for p in self.match_single(pn, siblings[ci]) {
                let mut c2 = caps.clone();
                c2.extend(p.caps);
                self.seq_rec_end(items, idx + 1, siblings, ci + 1, max_opt(last, p.last), false, c2, out, false);
            }
        }
        if allow_zero {
            self.seq_rec_end(items, idx + 1, siblings, pos, last, immediate, caps, out, first);
        }
    }
}

struct GroupPartial {
    caps: Bindings,
    last: Option<usize>,
    end_pos: usize,
}

impl Partial {
    #[allow(dead_code)]
    fn end_pos(&self) -> usize {
        0
    }
}

trait EndPos {
    fn end_pos(&self) -> usize;
}

fn max_opt(a: Option<usize>, b: Option<usize>) -> Option<usize> {
    match (a, b) {
        (Some(x), Some(y)) => Some(x.max(y)),
        (Some(x), None) => Some(x),
        (None, y) => y,
    }
}

pub struct QueryCursorOptions {
    pub byte_range: Option<(usize, usize)>,
    pub point_range: Option<((u32, u32), (u32, u32))>,
    pub containing_byte_range: Option<(usize, usize)>,
    pub containing_point_range: Option<((u32, u32), (u32, u32))>,
}

pub fn node_text<'b>(tree: &Tree, node: usize, source: &'b [u8]) -> &'b [u8] {
    let n = tree.node(node);
    let s = (n.start_byte as usize).min(source.len());
    let e = (n.end_byte as usize).min(source.len());
    &source[s..e]
}

fn satisfies_predicates(query: &Query, pattern: &Pattern, caps: &[QueryCapture], tree: &Tree, source: &[u8]) -> bool {
    for pred in &pattern.predicates {
        let name = pred.name.as_str();
        let capture_nodes = |idx: usize| -> Vec<usize> { caps.iter().filter(|c| c.index == idx).map(|c| c.node).collect() };
        match name {
            "eq?" | "not-eq?" | "any-eq?" | "any-not-eq?" => {
                if pred.args.len() != 2 {
                    continue;
                }
                let is_positive = name == "eq?" || name == "any-eq?";
                let match_all = name == "eq?" || name == "not-eq?";
                let first = match &pred.args[0] {
                    PredicateArg::Capture(c) => *c,
                    _ => continue,
                };
                let nodes = capture_nodes(first);
                match &pred.args[1] {
                    PredicateArg::Capture(c2) => {
                        let nodes2 = capture_nodes(*c2);
                        let mut iter = nodes.iter().zip(nodes2.iter()).map(|(a, b)| (node_text(tree, *a, source) == node_text(tree, *b, source)) == is_positive);
                        let ok = if match_all { iter.all(|x| x) } else { iter.any(|x| x) };
                        if !ok {
                            return false;
                        }
                    }
                    PredicateArg::String(s) => {
                        let mut iter = nodes.iter().map(|n| (node_text(tree, *n, source) == s.as_bytes()) == is_positive);
                        let ok = if match_all { iter.all(|x| x) } else { iter.any(|x| x) };
                        if !ok {
                            return false;
                        }
                    }
                }
            }
            "match?" | "not-match?" | "any-match?" | "any-not-match?" => {
                if pred.args.len() != 2 {
                    continue;
                }
                let is_positive = name == "match?" || name == "any-match?";
                let match_all = name == "match?" || name == "not-match?";
                let first = match &pred.args[0] {
                    PredicateArg::Capture(c) => *c,
                    _ => continue,
                };
                let re = match &pred.args[1] {
                    PredicateArg::String(s) => match query.regex(s) {
                        Some(r) => r,
                        None => continue,
                    },
                    _ => continue,
                };
                let nodes = capture_nodes(first);
                let mut iter = nodes.iter().map(|n| re.is_match(&String::from_utf8_lossy(node_text(tree, *n, source))) == is_positive);
                let ok = if match_all { iter.all(|x| x) } else { iter.any(|x| x) };
                if !ok {
                    return false;
                }
            }
            "any-of?" | "not-any-of?" => {
                if pred.args.len() < 2 {
                    continue;
                }
                let is_positive = name == "any-of?";
                let first = match &pred.args[0] {
                    PredicateArg::Capture(c) => *c,
                    _ => continue,
                };
                let values: Vec<&str> = pred.args[1..].iter().filter_map(|a| if let PredicateArg::String(s) = a { Some(s.as_str()) } else { None }).collect();
                let nodes = capture_nodes(first);
                for n in nodes {
                    let t = String::from_utf8_lossy(node_text(tree, n, source)).to_string();
                    if values.contains(&t.as_str()) != is_positive {
                        return false;
                    }
                }
            }
            _ => {}
        }
    }
    true
}

pub fn execute_query(query: &Query, tree: &Tree, source: &[u8], opts: &QueryCursorOptions) -> Vec<QueryMatch> {
    // compute preorder and depth
    let mut preorder = vec![0usize; tree.nodes.len()];
    let mut depth = vec![0usize; tree.nodes.len()];
    let mut order = Vec::new();
    let mut stack = vec![(tree.root(), 0usize)];
    while let Some((n, d)) = stack.pop() {
        preorder[n] = order.len();
        depth[n] = d;
        order.push(n);
        for c in tree.node(n).children.iter().rev() {
            stack.push((*c, d + 1));
        }
    }
    let matcher = Matcher { tree, preorder: preorder.clone(), depth: depth.clone() };

    let mut matches: Vec<QueryMatch> = Vec::new();
    for (pi, pattern) in query.patterns.iter().enumerate() {
        match &pattern.root.kind {
            PatternKind::Group(items) => {
                // top-level sibling sequence: match among children of each node (and root alone)
                let mut parents: Vec<Option<usize>> = vec![None];
                parents.extend(order.iter().map(|n| Some(*n)));
                for parent in parents {
                    let siblings: Vec<usize> = match parent {
                        None => vec![tree.root()],
                        Some(p) => tree.node(p).children.clone(),
                    };
                    for start in 0..siblings.len() {
                        let mut out = Vec::new();
                        matcher.seq_group(items, &siblings, start, &mut out);
                        for p in out {
                            let mut caps: Vec<QueryCapture> = Vec::new();
                            for c in &pattern.root.captures {
                                caps.push(QueryCapture { node: siblings[start], index: *c });
                            }
                            caps.extend(p.caps.iter().map(|(i, n)| QueryCapture { node: *n, index: *i }));
                            let completion = p.last.unwrap_or(preorder[siblings[start]]);
                            matches.push(QueryMatch { pattern_index: pi, captures: caps, completion, start_depth: depth[siblings[start]] });
                        }
                    }
                }
            }
            _ => {
                for &n in &order {
                    for p in matcher.match_single(&pattern.root, n) {
                        let caps: Vec<QueryCapture> = p.caps.iter().map(|(i, nd)| QueryCapture { node: *nd, index: *i }).collect();
                        let completion = p.last.unwrap_or(preorder[n]);
                        matches.push(QueryMatch { pattern_index: pi, captures: caps, completion, start_depth: depth[n] });
                    }
                }
            }
        }
    }

    // filter predicates
    matches.retain(|m| satisfies_predicates(query, &query.patterns[m.pattern_index], &m.captures, tree, source));

    // ranges
    if let Some((s, e)) = opts.byte_range {
        matches.retain(|m| m.captures.iter().any(|c| (tree.node(c.node).end_byte as usize) > s && (tree.node(c.node).start_byte as usize) < e) || m.captures.is_empty());
    }
    if let Some(((sr, sc), (er, ec))) = opts.point_range {
        matches.retain(|m| {
            m.captures.iter().any(|c| {
                let n = tree.node(c.node);
                (n.end_point.row, n.end_point.column) > (sr, sc) && (n.start_point.row, n.start_point.column) < (er, ec)
            })
        });
    }
    if let Some((s, e)) = opts.containing_byte_range {
        matches.retain(|m| m.captures.iter().all(|c| (tree.node(c.node).start_byte as usize) >= s && (tree.node(c.node).end_byte as usize) <= e));
    }
    if let Some(((sr, sc), (er, ec))) = opts.containing_point_range {
        matches.retain(|m| {
            m.captures.iter().all(|c| {
                let n = tree.node(c.node);
                (n.start_point.row, n.start_point.column) >= (sr, sc) && (n.end_point.row, n.end_point.column) <= (er, ec)
            })
        });
    }

    matches.sort_by(|a, b| a.completion.cmp(&b.completion).then(a.start_depth.cmp(&b.start_depth)).then(a.pattern_index.cmp(&b.pattern_index)));
    matches
}

/// Return captures in document order (like QueryCursor::captures).
pub fn query_captures(query: &Query, tree: &Tree, source: &[u8], opts: &QueryCursorOptions) -> Vec<(QueryMatch, usize)> {
    let matches = execute_query(query, tree, source, opts);
    let mut out: Vec<(usize, usize, QueryMatch, usize)> = Vec::new();
    for (mi, m) in matches.iter().enumerate() {
        for (ci, _) in m.captures.iter().enumerate() {
            out.push((mi, ci, m.clone(), ci));
        }
    }
    out.sort_by(|a, b| {
        let na = tree.node(a.2.captures[a.3].node);
        let nb = tree.node(b.2.captures[b.3].node);
        na.start_byte
            .cmp(&nb.start_byte)
            .then(a.2.pattern_index.cmp(&b.2.pattern_index))
            .then(a.0.cmp(&b.0))
            .then(a.1.cmp(&b.1))
    });
    out.into_iter().map(|(_, _, m, ci)| (m, ci)).collect()
}
