impl<'a> QueryBuilder<'a> {
    fn capture_id(&mut self, name: &str) -> usize {
        if let Some(i) = self.capture_names.iter().position(|n| n == name) {
            i
        } else {
            self.capture_names.push(name.to_string());
            self.capture_names.len() - 1
        }
    }

    fn parse_string_literal(&mut self) -> Result<String, (QueryErrorKind, usize, Option<String>)> {
        // at '"'
        let start = self.stream.pos;
        self.stream.advance();
        let mut out = Vec::new();
        let mut is_escaped = false;
        loop {
            if self.stream.at_end() {
                return Err((QueryErrorKind::Syntax, start, None));
            }
            let c = self.stream.next();
            if is_escaped {
                is_escaped = false;
                match c {
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
                    b'0' => out.push(0),
                    _ => out.push(c),
                }
                self.stream.advance();
            } else if c == b'\\' {
                is_escaped = true;
                self.stream.advance();
            } else if c == b'"' {
                self.stream.advance();
                break;
            } else if c == b'\n' {
                return Err((QueryErrorKind::Syntax, self.stream.pos, None));
            } else {
                out.push(c);
                self.stream.advance();
            }
        }
        Ok(String::from_utf8_lossy(&out).to_string())
    }

    fn parse_predicate(&mut self) -> Result<(), (QueryErrorKind, usize, Option<String>)> {
        // at the predicate name (after '#')
        if !self.stream.is_ident_start() {
            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
        }
        let name = self.stream.scan_identifier().to_string();
        self.stream.skip_whitespace();
        let mut args = Vec::new();
        loop {
            if self.stream.next() == b')' {
                self.stream.advance();
                self.stream.skip_whitespace();
                break;
            } else if self.stream.next() == b'@' {
                self.stream.advance();
                if !self.stream.is_ident_start() {
                    return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                }
                let cstart = self.stream.pos;
                let cname = self.stream.scan_identifier();
                match self.capture_names.iter().position(|n| n == cname) {
                    Some(i) => args.push(PredicateArg::Capture(i)),
                    None => return Err((QueryErrorKind::Capture, cstart, Some(format!("\"{}\"", cname)))),
                }
            } else if self.stream.next() == b'"' {
                let s = self.parse_string_literal()?;
                args.push(PredicateArg::String(s));
            } else if self.stream.is_ident_start() {
                let s = self.stream.scan_identifier().to_string();
                args.push(PredicateArg::String(s));
            } else {
                return Err((QueryErrorKind::Syntax, self.stream.pos, None));
            }
            self.stream.skip_whitespace();
        }
        self.predicates.push(Predicate { name, args });
        Ok(())
    }

    fn parse_pattern(&mut self, depth: u16, is_immediate: bool) -> PResult {
        if self.stream.at_end() {
            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
        }
        if self.stream.next() == b')' || self.stream.next() == b']' {
            return Ok(ParseResult::ParentDone);
        }

        let starting_step_index = self.steps.len();

        if self.stream.next() == b'[' {
            self.stream.advance();
            self.stream.skip_whitespace();
            let mut branch_step_indices = Vec::new();
            loop {
                let start_index = self.steps.len();
                match self.parse_pattern(depth, is_immediate)? {
                    ParseResult::ParentDone => {
                        if self.stream.next() == b']' && !branch_step_indices.is_empty() {
                            self.stream.advance();
                            break;
                        }
                        return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                    }
                    ParseResult::Ok => {}
                }
                branch_step_indices.push(start_index);
                self.steps.push(QueryStep::new(0, depth, false));
            }
            self.steps.pop();
            for i in 0..branch_step_indices.len() - 1 {
                let step_index = branch_step_indices[i];
                let next_step_index = branch_step_indices[i + 1];
                let len = self.steps.len();
                self.steps[step_index].alternative_index = next_step_index;
                let end_step = &mut self.steps[next_step_index - 1];
                end_step.alternative_index = len;
                end_step.is_dead_end = true;
            }
        } else if self.stream.next() == b'(' {
            self.stream.advance();
            self.stream.skip_whitespace();

            if self.stream.next() == b'(' || self.stream.next() == b'"' || self.stream.next() == b'[' {
                let mut child_is_immediate = is_immediate;
                loop {
                    if self.stream.next() == b'.' {
                        child_is_immediate = true;
                        self.stream.advance();
                        self.stream.skip_whitespace();
                    }
                    match self.parse_pattern(depth, child_is_immediate)? {
                        ParseResult::ParentDone => {
                            if self.stream.next() == b')' {
                                self.stream.advance();
                                break;
                            }
                            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                        }
                        ParseResult::Ok => {}
                    }
                    child_is_immediate = false;
                }
            } else if self.stream.next() == b'.' || self.stream.next() == b'#' {
                self.stream.advance();
                self.parse_predicate()?;
                return Ok(ParseResult::Ok);
            } else {
                let mut symbol;
                let mut is_missing = false;
                let node_name_start = self.stream.pos;
                if self.stream.is_ident_start() {
                    let node_name = self.stream.scan_identifier();
                    if node_name == "_" {
                        symbol = WILDCARD_SYMBOL;
                    } else if node_name == "MISSING" {
                        is_missing = true;
                        self.stream.skip_whitespace();
                        if self.stream.is_ident_start() {
                            let mstart = self.stream.pos;
                            let mname = self.stream.scan_identifier();
                            match self.language.symbol_for_name(mname, true) {
                                Some(s) => symbol = s,
                                None => return Err((QueryErrorKind::NodeType, mstart, Some(format!("\"{}\"", mname)))),
                            }
                        } else if self.stream.next() == b'"' {
                            let sstart = self.stream.pos;
                            let s = self.parse_string_literal()?;
                            match self.language.symbol_for_name(&s, false) {
                                Some(sym) => symbol = sym,
                                None => return Err((QueryErrorKind::NodeType, sstart + 1, Some(format!("\"{}\"", s)))),
                            }
                        } else if self.stream.next() == b')' {
                            symbol = WILDCARD_SYMBOL;
                        } else {
                            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                        }
                    } else {
                        match self.language.symbol_for_name(node_name, true) {
                            Some(s) => symbol = s,
                            None => {
                                if node_name == "ERROR" {
                                    symbol = TS_BUILTIN_SYM_ERROR;
                                } else {
                                    return Err((QueryErrorKind::NodeType, node_name_start, Some(format!("\"{}\"", node_name))));
                                }
                            }
                        }
                    }
                } else {
                    return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                }

                let mut step = QueryStep::new(symbol, depth, is_immediate);
                if symbol != WILDCARD_SYMBOL && symbol != TS_BUILTIN_SYM_ERROR && self.language.symbol_metadata(symbol).supertype {
                    step.supertype_symbol = step.symbol;
                    step.symbol = WILDCARD_SYMBOL;
                }
                if is_missing {
                    step.is_missing = true;
                }
                if symbol == WILDCARD_SYMBOL {
                    step.is_named = true;
                }
                self.steps.push(step);
                let step_idx = self.steps.len() - 1;

                if self.stream.next() == b'/' {
                    if self.steps[step_idx].supertype_symbol == 0 {
                        return Err((QueryErrorKind::Structure, node_name_start.saturating_sub(1), None));
                    }
                    self.stream.advance();
                    let sub_start = self.stream.pos;
                    let sub;
                    if self.stream.is_ident_start() {
                        let n = self.stream.scan_identifier();
                        sub = self.language.symbol_for_name(n, true);
                        if sub.is_none() {
                            return Err((QueryErrorKind::NodeType, sub_start, Some(format!("\"{}\"", n))));
                        }
                    } else if self.stream.next() == b'"' {
                        let s = self.parse_string_literal()?;
                        sub = self.language.symbol_for_name(&s, false);
                        if sub.is_none() {
                            return Err((QueryErrorKind::NodeType, sub_start, Some(format!("\"{}\"", s))));
                        }
                    } else {
                        return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                    }
                    self.steps[step_idx].symbol = sub.unwrap();
                    if self.language.abi_version() >= 15 {
                        let subtypes = self.language.subtypes(self.steps[step_idx].supertype_symbol);
                        if !subtypes.contains(&self.steps[step_idx].symbol) {
                            return Err((QueryErrorKind::Structure, node_name_start.saturating_sub(1), None));
                        }
                    }
                }

                self.stream.skip_whitespace();

                let mut child_is_immediate = false;
                let mut last_child_step_index = 0usize;
                let mut negated: Vec<u16> = Vec::new();
                loop {
                    if self.stream.next() == b'!' {
                        self.stream.advance();
                        self.stream.skip_whitespace();
                        if !self.stream.is_ident_start() {
                            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                        }
                        let fstart = self.stream.pos;
                        let fname = self.stream.scan_identifier();
                        self.stream.skip_whitespace();
                        match self.language.field_id_for_name(fname) {
                            Some(id) => {
                                if negated.len() < 8 {
                                    negated.push(id);
                                }
                            }
                            None => return Err((QueryErrorKind::Field, fstart, Some(format!("\"{}\"", fname)))),
                        }
                        continue;
                    }

                    if self.stream.next() == b'.' {
                        child_is_immediate = true;
                        self.stream.advance();
                        self.stream.skip_whitespace();
                    }

                    let step_index = self.steps.len();
                    match self.parse_pattern(depth + 1, child_is_immediate)? {
                        ParseResult::ParentDone => {
                            if self.stream.next() == b')' {
                                if child_is_immediate {
                                    if last_child_step_index == 0 {
                                        return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                                    }
                                    self.steps[last_child_step_index].is_last_child = true;
                                }
                                if !negated.is_empty() {
                                    negated.sort_unstable();
                                    self.steps[starting_step_index].negated_fields = negated.clone();
                                }
                                self.stream.advance();
                                break;
                            }
                            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                        }
                        ParseResult::Ok => {}
                    }
                    if self.steps.len() > step_index {
                        last_child_step_index = step_index;
                    }
                    child_is_immediate = false;
                }
            }
        } else if self.stream.next() == b'_' && !self.stream.src.get(self.stream.pos + 1).map_or(false, |c| is_ident_char(*c)) {
            self.stream.advance();
            self.stream.skip_whitespace();
            self.steps.push(QueryStep::new(WILDCARD_SYMBOL, depth, is_immediate));
        } else if self.stream.next() == b'"' {
            let string_start = self.stream.pos;
            let s = self.parse_string_literal()?;
            match self.language.symbol_for_name(&s, false) {
                Some(sym) => self.steps.push(QueryStep::new(sym, depth, is_immediate)),
                None => return Err((QueryErrorKind::NodeType, string_start + 1, Some(format!("\"{}\"", s)))),
            }
        } else if self.stream.is_ident_start() {
            let field_start = self.stream.pos;
            let field_name = self.stream.scan_identifier();
            self.stream.skip_whitespace();
            if self.stream.next() != b':' {
                return Err((QueryErrorKind::Syntax, field_start, None));
            }
            self.stream.advance();
            self.stream.skip_whitespace();
            match self.parse_pattern(depth, is_immediate)? {
                ParseResult::ParentDone => return Err((QueryErrorKind::Syntax, self.stream.pos, None)),
                ParseResult::Ok => {}
            }
            let field_id = match self.language.field_id_for_name(field_name) {
                Some(id) => id,
                None => return Err((QueryErrorKind::Field, field_start, Some(format!("\"{}\"", field_name)))),
            };
            let mut step_index = starting_step_index;
            loop {
                self.steps[step_index].field = field_id;
                let alt = self.steps[step_index].alternative_index;
                if alt != NONE && alt > step_index && alt < self.steps.len() {
                    step_index = alt;
                } else {
                    break;
                }
            }
        } else {
            return Err((QueryErrorKind::Syntax, self.stream.pos, None));
        }

        self.stream.skip_whitespace();

        // Parse suffixes modifiers for this pattern
        loop {
            if self.stream.next() == b'+' {
                self.stream.advance();
                self.stream.skip_whitespace();
                let mut repeat_step = QueryStep::new(WILDCARD_SYMBOL, depth, false);
                repeat_step.alternative_index = starting_step_index;
                repeat_step.is_pass_through = true;
                repeat_step.alternative_is_immediate = true;
                self.steps.push(repeat_step);
            } else if self.stream.next() == b'*' {
                self.stream.advance();
                self.stream.skip_whitespace();
                let mut repeat_step = QueryStep::new(WILDCARD_SYMBOL, depth, false);
                repeat_step.alternative_index = starting_step_index;
                repeat_step.is_pass_through = true;
                repeat_step.alternative_is_immediate = true;
                self.steps.push(repeat_step);
                let len = self.steps.len();
                let mut si = starting_step_index;
                while self.steps[si].alternative_index != NONE && self.steps[si].alternative_index < len - 1 {
                    si = self.steps[si].alternative_index;
                }
                self.steps[si].alternative_index = len;
            } else if self.stream.next() == b'?' {
                self.stream.advance();
                self.stream.skip_whitespace();
                let len = self.steps.len();
                let mut si = starting_step_index;
                while self.steps[si].alternative_index != NONE && self.steps[si].alternative_index < len {
                    si = self.steps[si].alternative_index;
                }
                self.steps[si].alternative_index = len;
            } else if self.stream.next() == b'@' {
                self.stream.advance();
                if !self.stream.is_ident_start() {
                    return Err((QueryErrorKind::Syntax, self.stream.pos, None));
                }
                let name = self.stream.scan_identifier().to_string();
                self.stream.skip_whitespace();
                let capture_id = self.capture_id(&name);
                let mut step_index = starting_step_index;
                loop {
                    if self.steps[step_index].capture_ids.len() < 3 {
                        self.steps[step_index].capture_ids.push(capture_id);
                    }
                    let alt = self.steps[step_index].alternative_index;
                    if alt != NONE && alt > step_index && alt < self.steps.len() {
                        step_index = alt;
                    } else {
                        break;
                    }
                }
            } else {
                break;
            }
        }

        Ok(ParseResult::Ok)
    }
}

impl Query {
    pub fn new(language: Language, source: &str) -> Result<Query, QueryError> {
        let mut builder = QueryBuilder { language, steps: Vec::new(), capture_names: Vec::new(), stream: Stream { src: source.as_bytes(), text: source, pos: 0 }, predicates: Vec::new() };
        let mut patterns: Vec<QueryPattern> = Vec::new();
        let mut pattern_map: Vec<PatternEntry> = Vec::new();
        let mut wildcard_root_pattern_count = 0usize;

        let make_error = |kind: QueryErrorKind, offset: usize, message: Option<String>| -> QueryError {
            let offset = offset.min(source.len());
            let before = &source[..offset];
            let row = before.matches('\n').count();
            let line_start = before.rfind('\n').map_or(0, |i| i + 1);
            let column = offset - line_start;
            let message = match message {
                Some(m) => m,
                None => {
                    if kind == QueryErrorKind::Syntax || kind == QueryErrorKind::Structure {
                        if offset >= source.len() {
                            "Unexpected EOF".to_string()
                        } else {
                            let line_end = source[offset..].find('\n').map_or(source.len(), |i| offset + i);
                            format!("{}\n{}^", &source[line_start..line_end], " ".repeat(offset - line_start))
                        }
                    } else {
                        String::new()
                    }
                }
            };
            QueryError { row, column, offset, kind, message }
        };

        builder.stream.skip_whitespace();
        while !builder.stream.at_end() {
            let pattern_index = patterns.len();
            let start_step_index = builder.steps.len();
            let start_byte = builder.stream.pos;
            builder.predicates.clear();
            match builder.parse_pattern(0, false) {
                Ok(ParseResult::Ok) => {}
                Ok(ParseResult::ParentDone) => return Err(make_error(QueryErrorKind::Syntax, builder.stream.pos, None)),
                Err((kind, offset, msg)) => return Err(make_error(kind, offset, msg)),
            }
            builder.steps.push(QueryStep::new(WILDCARD_SYMBOL, PATTERN_DONE_MARKER, false));
            let steps_end = builder.steps.len();

            // A pattern consisting solely of predicates is invalid.
            if steps_end - 1 == start_step_index {
                return Err(make_error(QueryErrorKind::Syntax, start_byte, None));
            }

            patterns.push(QueryPattern { steps_start: start_step_index, steps_end, predicates: builder.predicates.clone(), start_byte });

            // Maintain a map that can look up patterns for a given root symbol.
            let mut start_step_index = start_step_index;
            let mut wildcard_root_alternative_index = NONE;
            loop {
                let mut step_idx = start_step_index;
                {
                    let step = &builder.steps[step_idx];
                    if step.symbol == WILDCARD_SYMBOL && step.depth == 0 && step.field == 0 {
                        let second = &builder.steps[step_idx + 1];
                        if second.symbol != WILDCARD_SYMBOL && second.depth == 1 && !second.is_immediate {
                            wildcard_root_alternative_index = step.alternative_index;
                            start_step_index += 1;
                            step_idx = start_step_index;
                        }
                    }
                }
                let start_depth = builder.steps[step_idx].depth;
                let mut is_rooted = start_depth == 0;
                for si in (step_idx + 1)..builder.steps.len() {
                    let cs = &builder.steps[si];
                    if cs.is_dead_end {
                        break;
                    }
                    if cs.depth == start_depth {
                        is_rooted = false;
                        break;
                    }
                }
                let symbol = builder.steps[step_idx].symbol;
                let entry = PatternEntry { step_index: start_step_index, pattern_index, is_rooted };
                // insert sorted by symbol then pattern index
                let mut index = pattern_map.partition_point(|e| builder.steps[e.step_index].symbol < symbol);
                while index < pattern_map.len() {
                    let e = &pattern_map[index];
                    if builder.steps[e.step_index].symbol == symbol && e.pattern_index < pattern_index {
                        index += 1;
                    } else {
                        break;
                    }
                }
                pattern_map.insert(index, entry);
                if symbol == WILDCARD_SYMBOL {
                    wildcard_root_pattern_count += 1;
                }

                let alt = builder.steps[step_idx].alternative_index;
                if alt != NONE {
                    start_step_index = alt;
                } else if wildcard_root_alternative_index != NONE {
                    start_step_index = wildcard_root_alternative_index;
                    wildcard_root_alternative_index = NONE;
                } else {
                    break;
                }
            }
            builder.stream.skip_whitespace();
        }

        // Compute contains_captures for each step.
        let n = builder.steps.len();
        for i in 0..n {
            if builder.steps[i].depth == PATTERN_DONE_MARKER {
                continue;
            }
            let d = builder.steps[i].depth;
            let mut contains = !builder.steps[i].capture_ids.is_empty();
            let mut j = i + 1;
            while !contains && j < n {
                let s = &builder.steps[j];
                if s.depth == PATTERN_DONE_MARKER || s.depth <= d {
                    break;
                }
                if !s.capture_ids.is_empty() {
                    contains = true;
                }
                j += 1;
            }
            builder.steps[i].contains_captures = contains;
        }

        let pattern_count = patterns.len();
        Ok(Query {
            steps: builder.steps,
            patterns,
            capture_names: builder.capture_names,
            language,
            pattern_map,
            wildcard_root_pattern_count,
            regex_cache: Default::default(),
            disabled_patterns: vec![false; pattern_count],
        })
    }

    pub fn regex(&self, pattern: &str) -> Option<Regex> {
        let mut cache = self.regex_cache.borrow_mut();
        cache.entry(pattern.to_string()).or_insert_with(|| Regex::new(pattern).ok()).clone()
    }

    pub fn pattern_index_for_step(&self, step: usize) -> usize {
        self.patterns.iter().position(|p| step >= p.steps_start && step < p.steps_end).unwrap_or(0)
    }

    fn step_is_fallible(&self, step_index: usize) -> bool {
        if step_index + 1 >= self.steps.len() {
            return false;
        }
        let step = &self.steps[step_index];
        let next_step = &self.steps[step_index + 1];
        next_step.depth != PATTERN_DONE_MARKER && next_step.depth > step.depth
    }
}

// ---------------- execution ----------------

#[derive(Clone, Debug)]
pub struct QueryCapture {
    pub node: usize,
    pub index: usize,
}

#[derive(Clone, Debug)]
pub struct QueryMatch {
    pub pattern_index: usize,
    pub captures: Vec<QueryCapture>,
    pub id: usize,
}

#[derive(Clone, Debug)]
struct QueryState {
    id: usize,
    captures: Vec<QueryCapture>,
    start_depth: u32,
    step_index: usize,
    pattern_index: usize,
    seeking_immediate_match: bool,
    has_in_progress_alternatives: bool,
    dead: bool,
    needs_parent: bool,
}

pub struct QueryCursorOptions {
    pub byte_range: Option<(usize, usize)>,
    pub point_range: Option<((u32, u32), (u32, u32))>,
    pub containing_byte_range: Option<(usize, usize)>,
    pub containing_point_range: Option<((u32, u32), (u32, u32))>,
}

impl Default for QueryCursorOptions {
    fn default() -> Self {
        QueryCursorOptions { byte_range: None, point_range: None, containing_byte_range: None, containing_point_range: None }
    }
}

fn compare_nodes(tree: &Tree, left: usize, right: usize) -> i32 {
    if left != right {
        let l = tree.node(left);
        let r = tree.node(right);
        if l.start_byte < r.start_byte {
            return -1;
        }
        if l.start_byte > r.start_byte {
            return 1;
        }
        if l.end_byte > r.end_byte {
            return -1;
        }
        if l.end_byte < r.end_byte {
            return 1;
        }
    }
    0
}

fn compare_captures(tree: &Tree, left: &[QueryCapture], right: &[QueryCapture]) -> (bool, bool) {
    let mut left_contains_right = true;
    let mut right_contains_left = true;
    let mut i = 0;
    let mut j = 0;
    loop {
        if i < left.len() {
            if j < right.len() {
                let l = &left[i];
                let r = &right[j];
                if l.node == r.node && l.index == r.index {
                    i += 1;
                    j += 1;
                } else {
                    match compare_nodes(tree, l.node, r.node) {
                        -1 => {
                            right_contains_left = false;
                            i += 1;
                        }
                        1 => {
                            left_contains_right = false;
                            j += 1;
                        }
                        _ => {
                            right_contains_left = false;
                            left_contains_right = false;
                            i += 1;
                            j += 1;
                        }
                    }
                }
            } else {
                right_contains_left = false;
                break;
            }
        } else {
            if j < right.len() {
                left_contains_right = false;
            }
            break;
        }
    }
    (left_contains_right, right_contains_left)
}

struct Cursor<'a> {
    query: &'a Query,
    tree: &'a Tree,
    states: Vec<QueryState>,
    finished: Vec<QueryState>,
    depth: u32,
    next_state_id: usize,
    opts: &'a QueryCursorOptions,
}

impl<'a> Cursor<'a> {
    fn add_state(&mut self, pattern: &PatternEntry) {
        let step = &self.query.steps[pattern.step_index];
        let start_depth = self.depth - step.depth as u32;
        let mut index = self.states.len();
        while index > 0 {
            let prev = &self.states[index - 1];
            if prev.start_depth < start_depth {
                break;
            }
            if prev.start_depth == start_depth {
                if prev.pattern_index == pattern.pattern_index && prev.step_index == pattern.step_index {
                    return;
                }
                if prev.pattern_index <= pattern.pattern_index {
                    break;
                }
            }
            index -= 1;
        }
        self.states.insert(
            index,
            QueryState {
                id: usize::MAX,
                captures: Vec::new(),
                start_depth,
                step_index: pattern.step_index,
                pattern_index: pattern.pattern_index,
                seeking_immediate_match: true,
                has_in_progress_alternatives: false,
                dead: false,
                needs_parent: step.depth == 1,
            },
        );
    }

    fn node_intersects_range(&self, node: usize) -> bool {
        let n = self.tree.node(node);
        if let Some((s, e)) = self.opts.byte_range {
            if !((n.end_byte as usize) > s && (n.start_byte as usize) < e) {
                return false;
            }
        }
        if let Some((s, e)) = self.opts.point_range {
            let ns = (n.start_point.row, n.start_point.column);
            let ne = (n.end_point.row, n.end_point.column);
            if !(ne > s && ns < e) {
                return false;
            }
        }
        true
    }

    fn enter(&mut self, node: usize, parent: Option<usize>, has_later_siblings: bool, has_later_named_siblings: bool) {
        let tree = self.tree;
        let n = tree.node(node);
        let symbol = n.symbol;
        let is_named = n.is_named;
        let is_missing = n.is_missing;
        let field_id = n.field_id;
        let supertypes = n.supertypes.clone();
        let node_is_error = symbol == TS_BUILTIN_SYM_ERROR;
        let parent_is_error = parent.map_or(false, |p| tree.node(p).symbol == TS_BUILTIN_SYM_ERROR);
        let node_intersects_range = self.node_intersects_range(node);
        let parent_intersects_range = parent.map_or(true, |p| self.node_intersects_range(p));
        // can_have_later_siblings_with_this_field: approximated by inspecting later siblings
        let can_have_later_siblings_with_this_field = match parent {
            Some(p) if field_id != 0 => {
                let sibs = &tree.node(p).children;
                let idx = n.index_in_parent;
                sibs[idx + 1..].iter().any(|s| tree.node(*s).field_id == field_id)
            }
            _ => false,
        };

        // Add new states for any patterns whose root node is a wildcard.
        if !node_is_error {
            for i in 0..self.query.wildcard_root_pattern_count {
                let pattern = self.query.pattern_map[i].clone();
                let step = &self.query.steps[pattern.step_index];
                if self.depth < step.depth as u32 {
                    continue;
                }
                if (if pattern.is_rooted { node_intersects_range } else { parent_intersects_range && !parent_is_error })
                    && (step.field == 0 || field_id == step.field)
                    && (step.supertype_symbol == 0 || !supertypes.is_empty())
                {
                    self.add_state(&pattern);
                }
            }
        }

        // Add new states for any patterns whose root node matches this node.
        let first = self.query.pattern_map.partition_point(|e| self.query.steps[e.step_index].symbol < symbol);
        let mut i = first;
        while i < self.query.pattern_map.len() {
            let pattern = self.query.pattern_map[i].clone();
            let step = &self.query.steps[pattern.step_index];
            if step.symbol != symbol {
                break;
            }
            if symbol != WILDCARD_SYMBOL && self.depth >= step.depth as u32 {
                if (if pattern.is_rooted { node_intersects_range } else { parent_intersects_range && !parent_is_error }) && (step.field == 0 || field_id == step.field) {
                    self.add_state(&pattern);
                }
            }
            i += 1;
        }

        // Update all of the in-progress states with current node.
        let mut j = 0usize;
        while j < self.states.len() {
            let mut copy_count = 0usize;
            let state_step_index = self.states[j].step_index;
            let step = self.query.steps[state_step_index].clone();
            self.states[j].has_in_progress_alternatives = false;

            if self.states[j].start_depth + step.depth as u32 != self.depth {
                j += 1;
                continue;
            }

            let mut node_does_match = if step.symbol == WILDCARD_SYMBOL {
                if step.is_missing {
                    is_missing
                } else {
                    !node_is_error && (is_named || !step.is_named)
                }
            } else {
                symbol == step.symbol && (!step.is_missing || is_missing)
            };
            let mut later_sibling_can_match = has_later_siblings;
            if (step.is_immediate && is_named) || self.states[j].seeking_immediate_match {
                later_sibling_can_match = false;
            }
            if step.is_last_child && has_later_named_siblings {
                node_does_match = false;
            }
            if step.supertype_symbol != 0 && !supertypes.contains(&step.supertype_symbol) {
                node_does_match = false;
            }
            if step.field != 0 {
                if step.field == field_id {
                    if !can_have_later_siblings_with_this_field {
                        later_sibling_can_match = false;
                    }
                } else {
                    node_does_match = false;
                }
            }
            if !step.negated_fields.is_empty() {
                for f in &step.negated_fields {
                    if tree.child_by_field_id(node, *f).is_some() {
                        node_does_match = false;
                        break;
                    }
                }
            }

            if !node_does_match {
                if !later_sibling_can_match {
                    self.states.remove(j);
                    continue;
                }
                j += 1;
                continue;
            }

            // Some patterns can match their root node in multiple ways, capturing different
            // children. If this pattern step could match later children within the same
            // parent, then this query state cannot simply be updated in place. It must be
            // split into two states: one that matches this node, and one which skips over
            // this node, to preserve the possibility of matching later siblings.
            if later_sibling_can_match && (step.contains_captures || self.query.step_is_fallible(state_step_index)) {
                let copy = self.states[j].clone();
                self.states.insert(j + 1, QueryState { captures: copy.captures.clone(), ..copy });
                copy_count += 1;
            }

            // If this pattern started with a wildcard, such that the pattern map
            // actually points to the *second* step of the pattern, then check
            // that the node has a parent, and capture the parent node if necessary.
            if self.states[j].needs_parent {
                match parent {
                    None => self.states[j].dead = true,
                    Some(p) => {
                        self.states[j].needs_parent = false;
                        let mut skipped = state_step_index;
                        loop {
                            skipped -= 1;
                            let s = &self.query.steps[skipped];
                            if !(s.is_dead_end || s.is_pass_through || s.depth > 0) {
                                break;
                            }
                        }
                        let ids = self.query.steps[skipped].capture_ids.clone();
                        for id in ids {
                            self.states[j].captures.push(QueryCapture { node: p, index: id });
                        }
                    }
                }
            }

            // If the current node is captured in this pattern, add it to the capture list.
            if !self.states[j].dead {
                for id in &step.capture_ids {
                    self.states[j].captures.push(QueryCapture { node, index: *id });
                }
            }

            if self.states[j].dead {
                self.states.remove(j);
                continue;
            }

            // Advance this state to the next step of its pattern.
            self.states[j].step_index += 1;
            let next_step = &self.query.steps[self.states[j].step_index];
            self.states[j].seeking_immediate_match = step.symbol == WILDCARD_SYMBOL && !step.is_named && next_step.is_immediate;

            // If this state's next step has an alternative step, then copy the state in order
            // to pursue both alternatives. The alternative step itself may have an alternative,
            // so this is an interactive process.
            let mut end_index = j + 1;
            let mut k = j;
            while k < end_index {
                let child_step_index = self.states[k].step_index;
                let child_step = &self.query.steps[child_step_index];
                if child_step.alternative_index != NONE {
                    if child_step.is_dead_end {
                        self.states[k].step_index = child_step.alternative_index;
                        continue;
                    }
                    let alt = child_step.alternative_index;
                    let alt_imm = child_step.alternative_is_immediate;
                    if child_step.is_pass_through {
                        self.states[k].step_index += 1;
                    }
                    let mut copy = self.states[k].clone();
                    copy.step_index = alt;
                    if alt_imm {
                        copy.seeking_immediate_match = true;
                    }
                    self.states.insert(k + 1, copy);
                    end_index += 1;
                    copy_count += 1;
                    if child_step.is_pass_through {
                        // re-process the advanced state at index k
                        continue;
                    }
                }
                k += 1;
            }
            j += 1 + copy_count;
        }

        self.post_process();
    }

    fn post_process(&mut self) {
        let mut j = 0usize;
        while j < self.states.len() {
            if self.states[j].dead {
                self.states.remove(j);
                continue;
            }

            // Enforce the longest-match criteria.
            let mut did_remove = false;
            let mut k = j + 1;
            while k < self.states.len() {
                if self.states[k].start_depth != self.states[j].start_depth || self.states[k].pattern_index != self.states[j].pattern_index {
                    break;
                }
                let (left_contains_right, right_contains_left) = compare_captures(self.tree, &self.states[j].captures, &self.states[k].captures);
                if left_contains_right {
                    if self.states[j].step_index == self.states[k].step_index {
                        self.states.remove(k);
                        continue;
                    }
                    self.states[k].has_in_progress_alternatives = true;
                }
                if right_contains_left {
                    if self.states[j].step_index == self.states[k].step_index {
                        self.states.remove(j);
                        did_remove = true;
                        break;
                    }
                    self.states[j].has_in_progress_alternatives = true;
                }
                k += 1;
            }

            if did_remove {
                continue;
            }

            // If the state is at the end of its pattern, remove it from the list
            // of in-progress states and add it to the list of finished states.
            let next_step = &self.query.steps[self.states[j].step_index];
            if next_step.depth == PATTERN_DONE_MARKER {
                if self.states[j].has_in_progress_alternatives {
                    // defer finishing pattern
                } else {
                    let mut s = self.states.remove(j);
                    s.id = self.next_state_id;
                    self.next_state_id += 1;
                    self.finished.push(s);
                    continue;
                }
            }
            j += 1;
        }
    }

    fn leave(&mut self) {
        let mut i = 0;
        while i < self.states.len() {
            let step = &self.query.steps[self.states[i].step_index];
            if step.depth == PATTERN_DONE_MARKER && (self.states[i].start_depth > self.depth || self.depth == 0) {
                let mut s = self.states.remove(i);
                s.id = self.next_state_id;
                self.next_state_id += 1;
                self.finished.push(s);
            } else if step.depth != PATTERN_DONE_MARKER && self.states[i].start_depth + step.depth as u32 > self.depth {
                self.states.remove(i);
            } else {
                i += 1;
            }
        }
    }

    fn walk(&mut self, node: usize, parent: Option<usize>, has_later_siblings: bool, has_later_named_siblings: bool) {
        self.enter(node, parent, has_later_siblings, has_later_named_siblings);
        let children = self.tree.node(node).children.clone();
        if !children.is_empty() {
            self.depth += 1;
            for (i, c) in children.iter().enumerate() {
                let later = i + 1 < children.len();
                let later_named = children[i + 1..].iter().any(|s| self.tree.node(*s).is_named);
                self.walk(*c, Some(node), later, later_named);
            }
            self.depth -= 1;
        }
        self.leave();
    }
}

pub fn node_text<'b>(tree: &Tree, node: usize, source: &'b [u8]) -> &'b [u8] {
    let n = tree.node(node);
    let s = (n.start_byte as usize).min(source.len());
    let e = (n.end_byte as usize).min(source.len());
    &source[s..e]
}

fn satisfies_predicates(query: &Query, pattern: &QueryPattern, caps: &[QueryCapture], tree: &Tree, source: &[u8]) -> bool {
    for pred in &pattern.predicates {
        let name = pred.name.as_str();
        let capture_nodes = |idx: usize| -> Vec<usize> { caps.iter().filter(|c| c.index == idx).map(|c| c.node).collect() };
        match name {
            "eq?" | "not-eq?" | "any-eq?" | "any-not-eq?" => {
                if pred.args.len() != 2 {
                    continue;
                }
                let is_positive = name == "eq?" || name == "any-eq?";
                let match_all = name == "eq?" || name == "not-eq?";
                let first = match &pred.args[0] {
                    PredicateArg::Capture(c) => *c,
                    _ => continue,
                };
                let nodes = capture_nodes(first);
                match &pred.args[1] {
                    PredicateArg::Capture(c2) => {
                        let nodes2 = capture_nodes(*c2);
                        let mut iter = nodes.iter().zip(nodes2.iter()).map(|(a, b)| (node_text(tree, *a, source) == node_text(tree, *b, source)) == is_positive);
                        let ok = if match_all { iter.all(|x| x) } else { iter.any(|x| x) };
                        if !ok {
                            return false;
                        }
                    }
                    PredicateArg::String(s) => {
                        let mut iter = nodes.iter().map(|n| (node_text(tree, *n, source) == s.as_bytes()) == is_positive);
                        let ok = if match_all { iter.all(|x| x) } else { iter.any(|x| x) };
                        if !ok {
                            return false;
                        }
                    }
                }
            }
            "match?" | "not-match?" | "any-match?" | "any-not-match?" => {
                if pred.args.len() != 2 {
                    continue;
                }
                let is_positive = name == "match?" || name == "any-match?";
                let match_all = name == "match?" || name == "not-match?";
                let first = match &pred.args[0] {
                    PredicateArg::Capture(c) => *c,
                    _ => continue,
                };
                let re = match &pred.args[1] {
                    PredicateArg::String(s) => match query.regex(s) {
                        Some(r) => r,
                        None => continue,
                    },
                    _ => continue,
                };
                let nodes = capture_nodes(first);
                let mut iter = nodes.iter().map(|n| re.is_match(&String::from_utf8_lossy(node_text(tree, *n, source))) == is_positive);
                let ok = if match_all { iter.all(|x| x) } else { iter.any(|x| x) };
                if !ok {
                    return false;
                }
            }
            "any-of?" | "not-any-of?" => {
                if pred.args.len() < 2 {
                    continue;
                }
                let is_positive = name == "any-of?";
                let first = match &pred.args[0] {
                    PredicateArg::Capture(c) => *c,
                    _ => continue,
                };
                let values: Vec<&str> = pred.args[1..].iter().filter_map(|a| if let PredicateArg::String(s) = a { Some(s.as_str()) } else { None }).collect();
                let nodes = capture_nodes(first);
                for n in nodes {
                    let t = String::from_utf8_lossy(node_text(tree, n, source)).to_string();
                    if values.contains(&t.as_str()) != is_positive {
                        return false;
                    }
                }
            }
            _ => {}
        }
    }
    true
}

/// Run the query and return all matches (with predicates applied) in the order
/// that a query cursor would return them.
pub fn execute_query(query: &Query, tree: &Tree, source: &[u8], opts: &QueryCursorOptions) -> Vec<QueryMatch> {
    let mut cursor = Cursor { query, tree, states: Vec::new(), finished: Vec::new(), depth: 0, next_state_id: 0, opts };
    cursor.walk(tree.root(), None, false, false);
    let mut result = Vec::new();
    for s in cursor.finished {
        if query.disabled_patterns.get(s.pattern_index).copied().unwrap_or(false) {
            continue;
        }
        if !satisfies_predicates(query, &query.patterns[s.pattern_index], &s.captures, tree, source) {
            continue;
        }
        if let Some((cs, ce)) = opts.containing_byte_range {
            if !s.captures.iter().all(|c| (tree.node(c.node).start_byte as usize) >= cs && (tree.node(c.node).end_byte as usize) <= ce) {
                continue;
            }
        }
        if let Some((cs, ce)) = opts.containing_point_range {
            if !s.captures.iter().all(|c| {
                let n = tree.node(c.node);
                (n.start_point.row, n.start_point.column) >= cs && (n.end_point.row, n.end_point.column) <= ce
            }) {
                continue;
            }
        }
        result.push(QueryMatch { pattern_index: s.pattern_index, captures: s.captures, id: s.id });
    }
    result
}

/// Return captures in the order a query cursor's `captures()` would yield them.
pub fn query_captures(query: &Query, tree: &Tree, source: &[u8], opts: &QueryCursorOptions) -> Vec<(QueryMatch, usize)> {
    let matches = execute_query(query, tree, source, opts);
    let mut consumed = vec![0usize; matches.len()];
    let mut out = Vec::new();
    loop {
        let mut best: Option<usize> = None;
        let mut best_byte = u32::MAX;
        let mut best_pattern = usize::MAX;
        for (i, m) in matches.iter().enumerate() {
            if consumed[i] >= m.captures.len() {
                continue;
            }
            let node = m.captures[consumed[i]].node;
            let sb = tree.node(node).start_byte;
            if sb < best_byte || (sb == best_byte && m.pattern_index < best_pattern) {
                best = Some(i);
                best_byte = sb;
                best_pattern = m.pattern_index;
            }
        }
        match best {
            Some(i) => {
                out.push((matches[i].clone(), consumed[i]));
                consumed[i] += 1;
            }
            None => break,
        }
    }
    out
}
