pub fn ansi256_to_rgb(n: u8) -> (u8, u8, u8) {
    const BASIC: [(u8, u8, u8); 16] = [
        (0, 0, 0),
        (128, 0, 0),
        (0, 128, 0),
        (128, 128, 0),
        (0, 0, 128),
        (128, 0, 128),
        (0, 128, 128),
        (192, 192, 192),
        (128, 128, 128),
        (255, 0, 0),
        (0, 255, 0),
        (255, 255, 0),
        (0, 0, 255),
        (255, 0, 255),
        (0, 255, 255),
        (255, 255, 255),
    ];
    if n < 16 {
        return BASIC[n as usize];
    }
    if n < 232 {
        let i = n - 16;
        let levels = [0u8, 95, 135, 175, 215, 255];
        return (levels[(i / 36) as usize], levels[((i % 36) / 6) as usize], levels[(i % 6) as usize]);
    }
    let g = 8 + 10 * (n - 232);
    (g, g, g)
}

fn parse_color(v: &serde_json::Value) -> Option<Color> {
    match v {
        serde_json::Value::Number(n) => n.as_u64().map(|n| Color::Ansi256(n as u8)),
        serde_json::Value::String(s) => match s.to_lowercase().as_str() {
            "black" => Some(Color::Ansi(0)),
            "blue" => Some(Color::Ansi(4)),
            "cyan" => Some(Color::Ansi(6)),
            "green" => Some(Color::Ansi(2)),
            "purple" => Some(Color::Ansi(5)),
            "red" => Some(Color::Ansi(1)),
            "white" => Some(Color::Ansi(7)),
            "yellow" => Some(Color::Ansi(3)),
            s => {
                let h = s.strip_prefix('#')?;
                if h.len() == 6 {
                    let r = u8::from_str_radix(&h[0..2], 16).ok()?;
                    let g = u8::from_str_radix(&h[2..4], 16).ok()?;
                    let b = u8::from_str_radix(&h[4..6], 16).ok()?;
                    Some(Color::Rgb(r, g, b))
                } else {
                    None
                }
            }
        },
        _ => None,
    }
}

fn style_to_css(style: &Style) -> String {
    let mut result = String::new();
    if style.underline {
        result.push_str("text-decoration: underline;");
    }
    if style.bold {
        result.push_str("font-weight: bold;");
    }
    if style.italic {
        result.push_str("font-style: italic;");
    }
    if let Some(c) = style.color {
        match c {
            Color::Ansi(n) => {
                let names = ["black", "red", "green", "yellow", "blue", "purple", "cyan", "white"];
                result.push_str(&format!("color: {}", names[n as usize]));
            }
            Color::Ansi256(n) => {
                let (r, g, b) = ansi256_to_rgb(n);
                result.push_str(&format!("color: #{:02x}{:02x}{:02x}", r, g, b));
            }
            Color::Rgb(r, g, b) => result.push_str(&format!("color: #{:02x}{:02x}{:02x}", r, g, b)),
        }
    }
    result
}

impl Style {
    pub fn ansi_prefix(&self) -> String {
        let mut s = String::new();
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
        }
        if let Some(c) = self.color {
            match c {
                Color::Ansi(n) => s.push_str(&format!("\x1b[{}m", 30 + n)),
                Color::Ansi256(n) => s.push_str(&format!("\x1b[38;5;{}m", n)),
                Color::Rgb(r, g, b) => s.push_str(&format!("\x1b[38;2;{};{};{}m", r, g, b)),
            }
        }
        s
    }
    pub fn is_plain(&self) -> bool {
        !self.bold && !self.italic && !self.underline && self.color.is_none()
    }
}

impl Theme {
    pub fn from_json(v: &serde_json::Value) -> Theme {
        let mut styles = Vec::new();
        let mut highlight_names = Vec::new();
        if let serde_json::Value::Object(map) = v {
            for (name, value) in map {
                let mut style = Style::default();
                if let serde_json::Value::Object(entries) = value {
                    for (prop, val) in entries {
                        match prop.as_str() {
                            "bold" => {
                                if val == &serde_json::Value::Bool(true) {
                                    style.bold = true;
                                }
                            }
                            "italic" => {
                                if val == &serde_json::Value::Bool(true) {
                                    style.italic = true;
                                }
                            }
                            "underline" => {
                                if val == &serde_json::Value::Bool(true) {
                                    style.underline = true;
                                }
                            }
                            "color" => {
                                if let Some(c) = parse_color(val) {
                                    style.color = Some(c);
                                }
                            }
                            _ => {}
                        }
                    }
                    style.css = Some(style_to_css(&style));
                } else if let Some(c) = parse_color(value) {
                    style.color = Some(c);
                    style.css = Some(style_to_css(&style));
                } else {
                    style.css = None;
                }
                styles.push(style);
                highlight_names.push(name.clone());
            }
        }
        Theme { styles, highlight_names }
    }

    pub fn default_theme() -> Theme {
        let v: serde_json::Value = serde_json::from_str(DEFAULT_THEME_JSON).unwrap();
        Theme::from_json(&v)
    }
}

pub struct HighlightConfiguration {
    pub query: Query,
    pub locals_pattern_index: usize,
    pub highlights_pattern_index: usize,
    pub highlight_indices: Vec<Option<usize>>,
    pub non_local_variable_patterns: Vec<bool>,
    pub injection_content_capture_index: Option<usize>,
    pub injection_language_capture_index: Option<usize>,
    pub local_def_capture_index: Option<usize>,
    pub local_def_value_capture_index: Option<usize>,
    pub local_ref_capture_index: Option<usize>,
    pub local_scope_capture_index: Option<usize>,
    pub language_name: String,
}

impl HighlightConfiguration {
    pub fn new(language: crate::runtime::language::Language, name: &str, highlights: &str, injections: &str, locals: &str) -> Result<HighlightConfiguration, crate::runtime::query::QueryError> {
        let mut source = String::new();
        source.push_str(injections);
        let locals_offset = source.len();
        source.push_str(locals);
        let highlights_offset = source.len();
        source.push_str(highlights);
        let mut query = Query::new(language, &source)?;
        let mut locals_pattern_index = 0;
        let mut highlights_pattern_index = 0;
        for p in &query.patterns {
            if p.start_byte < highlights_offset {
                highlights_pattern_index += 1;
                if p.start_byte < locals_offset {
                    locals_pattern_index += 1;
                }
            }
        }
        // disable combined injection patterns
        for i in 0..locals_pattern_index {
            if query.patterns[i].predicates.iter().any(|p| p.name == "set!" && matches!(p.args.first(), Some(PredicateArg::String(s)) if s == "injection.combined")) {
                query.disabled_patterns[i] = true;
            }
        }
        let non_local_variable_patterns = query
            .patterns
            .iter()
            .map(|p| p.predicates.iter().any(|pr| pr.name == "is-not?" && matches!(pr.args.first(), Some(PredicateArg::String(s)) if s == "local")))
            .collect();
        let find = |n: &str| query.capture_names.iter().position(|c| c == n);
        let injection_content_capture_index = find("injection.content");
        let injection_language_capture_index = find("injection.language");
        let local_def_capture_index = find("local.definition");
        let local_def_value_capture_index = find("local.definition-value");
        let local_ref_capture_index = find("local.reference");
        let local_scope_capture_index = find("local.scope");
        let n = query.capture_names.len();
        Ok(HighlightConfiguration {
            query,
            locals_pattern_index,
            highlights_pattern_index,
            highlight_indices: vec![None; n],
            non_local_variable_patterns,
            injection_content_capture_index,
            injection_language_capture_index,
            local_def_capture_index,
            local_def_value_capture_index,
            local_ref_capture_index,
            local_scope_capture_index,
            language_name: name.to_string(),
        })
    }

    pub fn configure(&mut self, recognized_names: &[String]) {
        self.highlight_indices = self
            .query
            .capture_names
            .iter()
            .map(|capture_name| {
                let capture_parts: Vec<&str> = capture_name.split('.').collect();
                let mut best_index = None;
                let mut best_match_len = 0;
                for (i, recognized_name) in recognized_names.iter().enumerate() {
                    let mut len = 0;
                    let mut matches = true;
                    for part in recognized_name.split('.') {
                        len += 1;
                        if !capture_parts.contains(&part) {
                            matches = false;
                            break;
                        }
                    }
                    if matches && len > best_match_len {
                        best_index = Some(i);
                        best_match_len = len;
                    }
                }
                best_index
            })
            .collect();
    }
}

#[derive(Clone, Debug)]
pub enum HighlightEvent {
    Source { start: usize, end: usize },
    HighlightStart(usize),
    HighlightEnd,
}

struct LocalDef {
    name: String,
    value_range: (usize, usize),
    highlight: Option<usize>,
}

struct LocalScope {
    inherits: bool,
    range: (usize, usize),
    local_defs: Vec<LocalDef>,
}

/// Compute highlight events for a single-layer document.
pub fn highlight(config: &HighlightConfiguration, tree: &Tree, source: &[u8]) -> Vec<HighlightEvent> {
    let captures = query_captures(&config.query, tree, source, &QueryCursorOptions::default());
    let mut removed: HashSet<usize> = HashSet::new();
    let mut events = Vec::new();
    let mut byte_offset = 0usize;
    let mut highlight_end_stack: Vec<usize> = Vec::new();
    let mut scope_stack: Vec<LocalScope> = vec![LocalScope { inherits: false, range: (0, usize::MAX), local_defs: Vec::new() }];
    let mut last_highlight_range: Option<(usize, usize)> = None;
    let mut idx = 0usize;

    let emit = |events: &mut Vec<HighlightEvent>, byte_offset: &mut usize, offset: usize, event: Option<HighlightEvent>| {
        if *byte_offset < offset {
            events.push(HighlightEvent::Source { start: *byte_offset, end: offset });
            *byte_offset = offset;
        }
        if let Some(e) = event {
            events.push(e);
        }
    };

    // skip captures belonging to removed matches
    let next_valid = |idx: &mut usize, removed: &HashSet<usize>| {
        while *idx < captures.len() && removed.contains(&captures[*idx].0.id) {
            *idx += 1;
        }
    };

    loop {
        next_valid(&mut idx, &removed);
        if idx >= captures.len() {
            if let Some(end_byte) = highlight_end_stack.pop() {
                emit(&mut events, &mut byte_offset, end_byte, Some(HighlightEvent::HighlightEnd));
                continue;
            }
            emit(&mut events, &mut byte_offset, source.len(), None);
            break;
        }
        let (ref m0, ci0) = captures[idx];
        let node0 = m0.captures[ci0].node;
        let range = (tree.node(node0).start_byte as usize, tree.node(node0).end_byte as usize);
        if let Some(&end_byte) = highlight_end_stack.last() {
            if end_byte <= range.0 {
                highlight_end_stack.pop();
                emit(&mut events, &mut byte_offset, end_byte, Some(HighlightEvent::HighlightEnd));
                continue;
            }
        }

        let mut match_: QueryMatch = captures[idx].0.clone();
        let mut capture_index = captures[idx].1;
        idx += 1;
        let mut capture = match_.captures[capture_index].clone();

        // Injections are not supported yet: skip injection patterns.
        if match_.pattern_index < config.locals_pattern_index {
            removed.insert(match_.id);
            continue;
        }

        while range.0 > scope_stack.last().unwrap().range.1 {
            scope_stack.pop();
        }

        let mut reference_highlight: Option<Option<usize>> = None;
        let mut definition_def: Option<(usize, usize)> = None; // (scope index, def index)
        let mut handled_locals = false;
        while match_.pattern_index < config.highlights_pattern_index {
            if Some(capture.index) == config.local_scope_capture_index {
                definition_def = None;
                let mut scope = LocalScope { inherits: true, range, local_defs: Vec::new() };
                for p in &config.query.patterns[match_.pattern_index].predicates {
                    if p.name == "set!" {
                        if let Some(PredicateArg::String(k)) = p.args.first() {
                            if k == "local.scope-inherits" {
                                scope.inherits = match p.args.get(1) {
                                    Some(PredicateArg::String(v)) => v == "true",
                                    _ => true,
                                };
                            }
                        }
                    }
                }
                scope_stack.push(scope);
            } else if Some(capture.index) == config.local_def_capture_index {
                reference_highlight = None;
                let mut value_range = (0, 0);
                for c in &match_.captures {
                    if Some(c.index) == config.local_def_value_capture_index {
                        let n = tree.node(c.node);
                        value_range = (n.start_byte as usize, n.end_byte as usize);
                    }
                }
                let name = String::from_utf8_lossy(&source[range.0..range.1]).to_string();
                let si = scope_stack.len() - 1;
                scope_stack[si].local_defs.push(LocalDef { name, value_range, highlight: None });
                definition_def = Some((si, scope_stack[si].local_defs.len() - 1));
            } else if Some(capture.index) == config.local_ref_capture_index && definition_def.is_none() {
                definition_def = None;
                let name = String::from_utf8_lossy(&source[range.0..range.1]).to_string();
                for scope in scope_stack.iter().rev() {
                    if let Some(h) = scope.local_defs.iter().rev().find_map(|def| if def.name == name && range.0 >= def.value_range.1 { Some(def.highlight) } else { None }) {
                        reference_highlight = Some(h);
                        break;
                    }
                    if !scope.inherits {
                        break;
                    }
                }
            }

            next_valid(&mut idx, &removed);
            if idx < captures.len() {
                let (ref nm, nci) = captures[idx];
                if nm.captures[nci].node == capture.node {
                    capture = nm.captures[nci].clone();
                    match_ = nm.clone();
                    capture_index = nci;
                    idx += 1;
                    continue;
                }
            }
            handled_locals = true;
            break;
        }
        if handled_locals {
            continue;
        }
        let _ = capture_index;

        if let Some((ls, le)) = last_highlight_range {
            if range.0 == ls && range.1 == le {
                // same range at a shallower layer depth is never the case for a single layer
            }
        }

        // Once a highlighting pattern is found for the current node, keep iterating over
        // any later highlighting patterns that also match this node and set the match to it.
        loop {
            next_valid(&mut idx, &removed);
            if idx >= captures.len() {
                break;
            }
            let (ref nm, nci) = captures[idx];
            if nm.captures[nci].node == capture.node {
                let following = nm.clone();
                idx += 1;
                let is_local = definition_def.is_some() || matches!(reference_highlight, Some(Some(_)));
                if is_local && config.non_local_variable_patterns[following.pattern_index] {
                    continue;
                }
                removed.insert(match_.id);
                capture = following.captures[nci].clone();
                match_ = following;
            } else {
                break;
            }
        }

        let current_highlight = config.highlight_indices[capture.index];
        if let Some((si, di)) = definition_def {
            scope_stack[si].local_defs[di].highlight = current_highlight;
        }
        let ref_h = match reference_highlight {
            Some(Some(h)) => Some(h),
            _ => None,
        };
        if let Some(h) = ref_h.or(current_highlight) {
            last_highlight_range = Some(range);
            highlight_end_stack.push(range.1);
            emit(&mut events, &mut byte_offset, range.0, Some(HighlightEvent::HighlightStart(h)));
        }
    }
    events
}

pub fn render_ansi(events: &[HighlightEvent], source: &[u8], theme: &Theme, out: &mut Vec<u8>) {
    let mut style_stack: Vec<Option<usize>> = vec![None];
    for e in events {
        match e {
            HighlightEvent::HighlightStart(h) => style_stack.push(Some(*h)),
            HighlightEvent::HighlightEnd => {
                style_stack.pop();
            }
            HighlightEvent::Source { start, end } => {
                let style = style_stack.last().unwrap().map(|h| &theme.styles[h]);
                let plain = style.map_or(true, |s| s.is_plain());
                if !plain {
                    out.extend_from_slice(style.unwrap().ansi_prefix().as_bytes());
                }
                out.extend_from_slice(&source[*start..*end]);
                if !plain {
                    out.extend_from_slice(b"\x1b[0m");
                }
            }
        }
    }
}

pub struct HtmlRenderer {
    pub html: Vec<u8>,
    pub line_offsets: Vec<u32>,
}

impl HtmlRenderer {
    pub fn new() -> HtmlRenderer {
        HtmlRenderer { html: Vec::new(), line_offsets: vec![0] }
    }

    pub fn render(&mut self, events: &[HighlightEvent], source: &[u8], attr: &dyn Fn(usize, &mut Vec<u8>)) {
        let mut highlights: Vec<usize> = Vec::new();
        for e in events {
            match e {
                HighlightEvent::HighlightStart(h) => {
                    highlights.push(*h);
                    self.start_highlight(*h, attr);
                }
                HighlightEvent::HighlightEnd => {
                    highlights.pop();
                    self.html.extend_from_slice(b"</span>");
                }
                HighlightEvent::Source { start, end } => {
                    self.add_text(&source[*start..*end], &highlights, attr);
                }
            }
        }
        if self.html.last() != Some(&b'\n') {
            self.html.push(b'\n');
        }
        if self.line_offsets.last() == Some(&(self.html.len() as u32)) {
            self.line_offsets.pop();
        }
    }

    pub fn lines(&self) -> Vec<String> {
        let mut out = Vec::new();
        for (i, start) in self.line_offsets.iter().enumerate() {
            let s = *start as usize;
            let e = if i + 1 == self.line_offsets.len() { self.html.len() } else { self.line_offsets[i + 1] as usize };
            out.push(String::from_utf8_lossy(&self.html[s..e]).to_string());
        }
        out
    }

    fn start_highlight(&mut self, h: usize, attr: &dyn Fn(usize, &mut Vec<u8>)) {
        self.html.extend_from_slice(b"<span ");
        attr(h, &mut self.html);
        self.html.extend_from_slice(b">");
    }

    fn add_text(&mut self, src: &[u8], highlights: &[usize], attr: &dyn Fn(usize, &mut Vec<u8>)) {
        let text = String::from_utf8_lossy(src).to_string();
        let mut last_char_was_cr = false;
        for c in text.bytes() {
            if c == b'\r' {
                last_char_was_cr = true;
                continue;
            }
            if last_char_was_cr {
                if c != b'\n' {
                    // lone carriage return
                }
                last_char_was_cr = false;
            }
            if c == b'\n' {
                for _ in highlights {
                    self.html.extend_from_slice(b"</span>");
                }
                self.html.push(c);
                self.line_offsets.push(self.html.len() as u32);
                for h in highlights {
                    self.start_highlight(*h, attr);
                }
            } else {
                match c {
                    b'>' => self.html.extend_from_slice(b"&gt;"),
                    b'<' => self.html.extend_from_slice(b"&lt;"),
                    b'&' => self.html.extend_from_slice(b"&amp;"),
                    b'\'' => self.html.extend_from_slice(b"&#39;"),
                    b'"' => self.html.extend_from_slice(b"&quot;"),
                    _ => self.html.push(c),
                }
            }
        }
    }
}

