fn read_query_files(paths: &[std::path::PathBuf]) -> Result<String> {
    let mut s = String::new();
    for p in paths {
        if let Ok(t) = std::fs::read_to_string(p) {
            s.push_str(&t);
        }
    }
    Ok(s)
}

fn run_highlight(m: &clap::ArgMatches) -> Result<i32> {
    use std::io::Write;
    let cwd = std::env::current_dir()?;
    let mut loader = loader::Loader::new();
    loader.force_rebuild = m.get_flag("rebuild") || m.get_one::<String>("grammar_path").is_some();
    let grammar_path = m.get_one::<String>("grammar_path").map(std::path::PathBuf::from).unwrap_or_else(|| cwd.clone());
    let ids = loader.find_language_configurations_at_path(&grammar_path)?;
    let config_path = m.get_one::<String>("config_path").map(std::path::PathBuf::from);
    let _ = loader.find_all_languages(config_path.as_deref());
    let _ = ids;
    let config = config::Config::load(config_path.as_deref()).ok();
    let theme = match config.as_ref().and_then(|c| c.theme.clone()) {
        Some(t) => highlight::Theme::from_json(&t),
        None => highlight::Theme::default_theme(),
    };
    let html_mode = m.get_flag("html");
    let css_classes = m.get_flag("css_classes");
    let quiet = m.get_flag("quiet");
    let scope = m.get_one::<String>("scope").cloned();
    let raw_paths: Vec<String> = m.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default();
    let paths_file = m.get_one::<String>("paths_file").cloned();
    let query_paths: Option<Vec<String>> = m.get_many::<String>("query_paths").map(|v| v.cloned().collect());

    let mut inputs: Vec<(String, Vec<u8>)> = Vec::new();
    if let Some(n) = m.get_one::<u32>("test_number") {
        let t = commands::test_cmd::get_test_by_number(&cwd, *n)?;
        inputs.push((t.name.clone(), t.input.into_bytes()));
    } else if raw_paths.is_empty() && paths_file.is_none() {
        let mut input = Vec::new();
        std::io::Read::read_to_end(&mut std::io::stdin(), &mut input)?;
        inputs.push(("stdin".to_string(), input));
    } else {
        for p in commands::parse_cmd::collect_paths(paths_file.as_deref(), raw_paths)? {
            let data = std::fs::read(&p).map_err(|e| anyhow::Error::new(e).context(format!("Error reading {:?}", p)))?;
            inputs.push((p, data));
        }
    }

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut warned_highlights = false;
    for (path, source) in inputs {
        let cfg_idx = if let Some(sc) = &scope {
            match loader.config_for_scope(sc) {
                Some(i) => Some(i),
                None => return Err(anyhow::anyhow!("Unknown scope '{}'", sc)),
            }
        } else {
            let p = std::path::Path::new(&path);
            let file_name = p.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
            let ext = p.extension().map(|e| e.to_string_lossy().to_string());
            (0..loader.configs.len()).find(|i| loader.configs[*i].file_types.iter().any(|ft| *ft == file_name || Some(ft.clone()) == ext))
        };
        let idx = match cfg_idx {
            Some(i) => i,
            None => {
                out.flush()?;
                no_language_warning(&path, config_path.as_deref());
                continue;
            }
        };
        let lc = loader.configs[idx].clone();
        if !lc.explicit_highlights && !warned_highlights && query_paths.is_none() {
            warned_highlights = true;
            out.flush()?;
            eprintln!("\\x1b[33mWarning:\\x1b[0m You should add a `highlights` entry pointing to the highlights.scm path in the `tree-sitter` object in the grammar's tree-sitter.json file. See more here: https://tree-sitter.github.io/tree-sitter/3-syntax-highlighting#query-paths");
        }
        let highlight_paths: Vec<std::path::PathBuf> = match &query_paths {
            Some(qp) => qp.iter().map(std::path::PathBuf::from).collect(),
            None => lc.highlights.clone(),
        };
        if highlight_paths.is_empty() || !highlight_paths.iter().any(|p| p.exists()) {
            out.flush()?;
            eprintln!("\\x1b[33mWarning:\\x1b[0m No syntax highlighting config found for path {}", path);
            continue;
        }
        let lang = loader.language_for_config(idx)?;
        let highlights_src = read_query_files(&highlight_paths)?;
        let injections_src = read_query_files(&lc.injections)?;
        let locals_src = read_query_files(&lc.locals)?;
        let mut hconfig = match highlight::HighlightConfiguration::new(lang, &lc.name, &highlights_src, &injections_src, &locals_src) {
            Ok(c) => c,
            Err(e) => {
                out.flush()?;
                return Err(anyhow::Error::new(e).context("Failed to load highlight queries"));
            }
        };
        hconfig.configure(&theme.highlight_names);
        let start = std::time::Instant::now();
        let (tree, _) = commands::parse_cmd::parse_source(lang, &source, runtime::lexer::Encoding::Utf8, None, 0);
        let tree = match tree {
            Some(t) => t,
            None => continue,
        };
        let events = highlight::highlight(&hconfig, &tree, &source);
        if html_mode {
            if !quiet {
                writeln!(out, "{}", highlight::HTML_HEAD_HEADER)?;
                writeln!(out, "  <style>")?;
                for (i, name) in theme.highlight_names.iter().enumerate() {
                    if let Some(css) = &theme.styles[i].css {
                        writeln!(out, "    .{} {{ {}; }}", name, css)?;
                    }
                }
                writeln!(out, "  </style>")?;
                writeln!(out, "{}", highlight::HTML_BODY_HEADER)?;
            }
            let mut renderer = highlight::HtmlRenderer::new();
            let names = theme.highlight_names.clone();
            let styles = theme.styles.clone();
            let attr = move |h: usize, buf: &mut Vec<u8>| {
                if css_classes {
                    buf.extend_from_slice(b"class='");
                    buf.extend_from_slice(names[h].replace('.', " ").as_bytes());
                    buf.extend_from_slice(b"'");
                } else if let Some(css) = &styles[h].css {
                    buf.extend_from_slice(b"style='");
                    buf.extend_from_slice(css.as_bytes());
                    buf.extend_from_slice(b"'");
                }
            };
            renderer.render(&events, &source, &attr);
            if !quiet {
                writeln!(out, "<table>")?;
                for (i, line) in renderer.lines().iter().enumerate() {
                    writeln!(out, "<tr><td class=line-number>{}</td><td class=line>{}</td></tr>", i + 1, line)?;
                }
                writeln!(out, "</table>")?;
                writeln!(out, "{}", highlight::HTML_FOOTER)?;
            }
        } else {
            let mut buf = Vec::new();
            highlight::render_ansi(&events, &source, &theme, &mut buf);
            out.write_all(&buf)?;
        }
        if m.get_flag("time") {
            out.flush()?;
            eprintln!("Time: {}ms", start.elapsed().as_millis());
        }
    }
    out.flush()?;
    Ok(0)
}

