use clap::{Arg, ArgAction, Command, ValueHint};

fn arg_type(arg: &Arg) -> &'static str {
    match arg.get_value_hint() {
        ValueHint::AnyPath | ValueHint::FilePath | ValueHint::DirPath | ValueHint::ExecutablePath => "path",
        _ => "string",
    }
}

fn help_text(arg: &Arg) -> String {
    arg.get_help().map(|h| h.to_string().replace('\n', " ")).unwrap_or_default()
}

fn line(spec: String, help: &str) -> String {
    if spec.len() >= 26 {
        format!("    {} # {}\n", spec, help)
    } else {
        format!("    {:<26}# {}\n", spec, help)
    }
}

fn takes_value(arg: &Arg) -> bool {
    matches!(arg.get_action(), ArgAction::Set | ArgAction::Append)
}

fn gen_command(cmd: &Command, path: &str, is_root: bool, out: &mut String) {
    // possible-value completers
    for arg in cmd.get_arguments() {
        if arg.is_positional() {
            continue;
        }
        let pvs = arg.get_possible_values();
        if !pvs.is_empty() && takes_value(arg) {
            out.push_str(&format!("  def \"nu-complete {} {}\" [] {{\n", path, arg.get_id()));
            let vals: Vec<String> = pvs.iter().map(|v| format!("\"{}\"", v.get_name())).collect();
            out.push_str(&format!("    [ {} ]\n", vals.join(" ")));
            out.push_str("  }\n\n");
        }
    }
    if let Some(about) = cmd.get_about() {
        out.push_str(&format!("  # {}\n", about));
    }
    if is_root {
        out.push_str(&format!("  export extern {} [\n", path));
    } else {
        out.push_str(&format!("  export extern \"{}\" [\n", path));
    }
    for arg in cmd.get_arguments() {
        if arg.is_positional() {
            continue;
        }
        let long = match arg.get_long() {
            Some(l) => l,
            None => continue,
        };
        let mut spec = format!("--{}", long);
        if let Some(s) = arg.get_short() {
            spec.push_str(&format!("({})", s));
        }
        if takes_value(arg) {
            spec.push_str(": ");
            spec.push_str(arg_type(arg));
            if !arg.get_possible_values().is_empty() {
                spec.push_str(&format!("@\"nu-complete {} {}\"", path, arg.get_id()));
            }
        }
        out.push_str(&line(spec, &help_text(arg)));
    }
    for arg in cmd.get_arguments() {
        if !arg.is_positional() {
            continue;
        }
        let multiple = arg.get_num_args().map_or(false, |n| n.max_values() > 1);
        let mut spec = String::new();
        if multiple {
            spec.push_str("...");
        }
        spec.push_str(arg.get_id().as_str());
        if !arg.is_required_set() && !multiple {
            spec.push('?');
        }
        spec.push_str(": ");
        spec.push_str(arg_type(arg));
        out.push_str(&line(spec, &help_text(arg)));
    }
    out.push_str("  ]\n\n");
    for sub in cmd.get_subcommands() {
        gen_command(sub, &format!("{} {}", path, sub.get_name()), false, out);
    }
}

pub fn generate(cmd: &mut Command, bin: &str) -> String {
    cmd.build();
    let mut out = String::from("module completions {\n\n");
    gen_command(cmd, bin, true, &mut out);
    out.push_str("}\n\nexport use completions *\n");
    out
}
