use crate::runtime::query::{execute_query, PredicateArg, Query, QueryCursorOptions};
use crate::runtime::subtree::Point;
use crate::runtime::tree::Tree;
use regex::Regex;
use std::collections::HashMap;

pub struct PatternInfo {
    docs_adjacent_capture: Option<usize>,
    local_scope_inherits: bool,
    name_must_be_non_local: bool,
