        let mut capture_map = HashMap::new();
        let mut doc_capture_index = None;
        let mut name_capture_index = None;
        let mut ignore_capture_index = None;
        let mut local_scope_capture_index = None;
        let mut local_definition_capture_index = None;
        for (i, name) in query.capture_names.iter().enumerate() {
            match name.as_str() {
                "name" => name_capture_index = Some(i),
                "ignore" => ignore_capture_index = Some(i),
                "doc" => doc_capture_index = Some(i),
                "local.scope" => local_scope_capture_index = Some(i),
                "local.definition" => local_definition_capture_index = Some(i),
                "local.reference" | "" => {}
                _ => {
                    let mut is_definition = false;
                    let kind = if let Some(k) = name.strip_prefix("definition.") {
                        is_definition = true;
                        k
                    } else if let Some(k) = name.strip_prefix("reference.") {
                        k
                    } else {
                        continue;
                    };
                    let id = match syntax_type_names.iter().position(|n| n == kind) {
                        Some(id) => id,
                        None => {
                            syntax_type_names.push(kind.to_string());
                            syntax_type_names.len() - 1
                        }
                    };
                    capture_map.insert(i, (id, is_definition));
                }
            }
        }
        let mut pattern_info = Vec::new();
        for p in &query.patterns {
            let mut info = PatternInfo { docs_adjacent_capture: None, local_scope_inherits: true, name_must_be_non_local: false, doc_strip_regex: None };
            for pred in &p.predicates {
                match pred.name.as_str() {
                    "strip!" => {
                        if let (Some(PredicateArg::Capture(c)), Some(PredicateArg::String(re))) = (pred.args.first(), pred.args.get(1)) {
                            if Some(*c) == doc_capture_index {
                                info.doc_strip_regex = Regex::new(re).ok();
                            }
                        }
                    }
                    "select-adjacent!" => {
                        if let (Some(PredicateArg::Capture(c1)), Some(PredicateArg::Capture(c2))) = (pred.args.first(), pred.args.get(1)) {
                            if Some(*c1) == doc_capture_index {
