                            if k == "local.scope-inherits" {
                                info.local_scope_inherits = match v {
                                    Some(PredicateArg::String(s)) => s == "true",
                                    _ => true,
                                };
                            }
                        }
                    }
                    _ => {}
                }
            }
            pattern_info.push(info);
        }
        Ok(TagsConfiguration {
            query,
            syntax_type_names,
            capture_map,
            doc_capture_index,
            name_capture_index,
            ignore_capture_index,
            local_scope_capture_index,
            local_definition_capture_index,
            tags_pattern_index,
            pattern_info,
        })
    }
}

fn line_range(text: &[u8], start_byte: usize, start_point: Point, max_line_len: usize) -> (usize, usize) {
    let mut line_start_byte = start_byte - start_point.column as usize;
    while line_start_byte < text.len() && text[line_start_byte].is_ascii_whitespace() {
        line_start_byte += 1;
    }
    let max_line_len = max_line_len.min(text.len() - line_start_byte);
    let after = &text[line_start_byte..line_start_byte + max_line_len];
    let line_len = if let Some(len) = after.iter().position(|b| *b == b'\n') {
        len
    } else if let Err(e) = std::str::from_utf8(after) {
        e.valid_up_to()
    } else {
        max_line_len
    };
    let mut line_end_byte = line_start_byte + line_len;
    while line_end_byte > line_start_byte && text[line_end_byte - 1].is_ascii_whitespace() {
        line_end_byte -= 1;
    }
    (line_start_byte, line_end_byte)
}

struct LocalScope<'a> {
    range: (usize, usize),
    inherits: bool,
    local_defs: Vec<&'a [u8]>,
}

pub fn generate_tags(config: &TagsConfiguration, tree: &Tree, source: &[u8]) -> Vec<Tag> {
    let matches = execute_query(&config.query, tree, source, &QueryCursorOptions::default());
    let mut scopes: Vec<LocalScope> = vec![LocalScope { range: (0, source.len()), inherits: false, local_defs: Vec::new() }];
    let mut tag_queue: Vec<(Tag, usize)> = Vec::new();
    let mut out = Vec::new();
    let mut prev_line: Option<(Point, (usize, usize))> = None;
    let mut mi = 0;
    loop {
        if let Some(last) = tag_queue.last() {
            if tag_queue.len() > 1 && tag_queue[0].0.name_range.1 < last.0.name_range.0 {
                let tag = tag_queue.remove(0).0;
                if !tag.ignored {
                    out.push(tag);
                }
                continue;
            }
        }
        if mi < matches.len() {
            let mat = &matches[mi];
            mi += 1;
            let info = &config.pattern_info[mat.pattern_index];
            if mat.pattern_index < config.tags_pattern_index {
                for capture in &mat.captures {
                    let n = tree.node(capture.node);
                    let range = (n.start_byte as usize, n.end_byte as usize);
                    if Some(capture.index) == config.local_scope_capture_index {
                        scopes.push(LocalScope { range, inherits: info.local_scope_inherits, local_defs: Vec::new() });
                    } else if Some(capture.index) == config.local_definition_capture_index {
                        if let Some(scope) = scopes.iter_mut().rev().find(|s| s.range.0 <= range.0 && s.range.1 >= range.1) {
                            scope.local_defs.push(&source[range.0..range.1]);
                        }
                    }
                }
                continue;
            }
            let mut name_node = None;
            let mut doc_nodes = Vec::new();
            let mut tag_node = None;
            let mut syntax_type_id = 0;
            let mut is_definition = false;
            let mut docs_adjacent_node = None;
            let mut is_ignored = false;
            for capture in &mat.captures {
                let index = Some(capture.index);
                if index == info.docs_adjacent_capture {
                    docs_adjacent_node = Some(capture.node);
                }
                if index == config.ignore_capture_index {
                    is_ignored = true;
                    name_node = Some(capture.node);
                }
                if index == config.name_capture_index {
                    name_node = Some(capture.node);
                } else if index == config.doc_capture_index {
                    doc_nodes.push(capture.node);
                }
                if let Some((id, def)) = config.capture_map.get(&capture.index) {
                    tag_node = Some(capture.node);
                    syntax_type_id = *id;
                    is_definition = *def;
                }
            }
            let name_node = match name_node {
                Some(n) => n,
                None => continue,
            };
            let nn = tree.node(name_node);
            let name_range = (nn.start_byte as usize, nn.end_byte as usize);
            let tag;
            if let Some(tag_node) = tag_node {
                if nn.has_error {
                    continue;
                }
                if info.name_must_be_non_local {
                    let mut is_local = false;
                    for scope in scopes.iter().rev() {
                        if scope.range.0 <= name_range.0 && scope.range.1 >= name_range.1 {
                            if scope.local_defs.iter().any(|d| *d == &source[name_range.0..name_range.1]) {
                                is_local = true;
                                break;
                            }
                            if !scope.inherits {
                                break;
                            }
                        }
                    }
                    if is_local {
                        continue;
                    }
                }
                let mut docs_start_index = 0;
                if let (Some(adj), false) = (docs_adjacent_node, doc_nodes.is_empty()) {
                    docs_start_index = doc_nodes.len();
                    let mut start_row = tree.node(adj).start_point.row;
                    while docs_start_index > 0 {
                        let d = tree.node(doc_nodes[docs_start_index - 1]);
                        if d.end_point.row + 1 >= start_row {
                            docs_start_index -= 1;
                            start_row = d.start_point.row;
                        } else {
                            break;
                        }
                    }
                }
                let mut docs: Option<String> = None;
                for dn in &doc_nodes[docs_start_index..] {
                    let n = tree.node(*dn);
                    if let Ok(content) = std::str::from_utf8(&source[n.start_byte as usize..n.end_byte as usize]) {
                        let content = match &info.doc_strip_regex {
                            Some(r) => r.replace_all(content, "").to_string(),
                            None => content.to_string(),
                        };
                        match &mut docs {
                            None => docs = Some(content),
                            Some(d) => {
                                d.push('\n');
                                d.push_str(&content);
                            }
                        }
                    }
                }
                let tn = tree.node(tag_node);
                let range = ((tn.start_byte as usize).min(name_range.0), (tn.end_byte as usize).max(name_range.1));
                let span = (nn.start_point, nn.end_point);
                let lr = match &prev_line {
                    Some((pos, lr)) if pos.row == span.0.row => *lr,
                    _ => line_range(source, name_range.0, span.0, 180),
                };
                prev_line = Some((span.1, lr));
                tag = Tag { range, name_range, line_range: lr, span, docs, is_definition, syntax_type_id, ignored: false };
            } else if is_ignored {
                tag = Tag { range: name_range, name_range, line_range: (0, 0), span: (Point::default(), Point::default()), docs: None, is_definition: false, syntax_type_id: 0, ignored: true };
            } else {
                continue;
            }
            let key = (tag.name_range.1, tag.name_range.0);
            match tag_queue.binary_search_by_key(&key, |(t, _)| (t.name_range.1, t.name_range.0)) {
                Ok(i) => {
                    if tag_queue[i].1 > mat.pattern_index {
                        tag_queue[i] = (tag, mat.pattern_index);
                    }
                }
                Err(i) => tag_queue.insert(i, (tag, mat.pattern_index)),
            }
        } else if !tag_queue.is_empty() {
            let tag = tag_queue.remove(0).0;
            if !tag.ignored {
                out.push(tag);
            }
        } else {
            break;
        }
    }
    out
}
